  ('Ss12000SyncRuns', '{INTEGRATIONER}', '{INTEGRATIONER}', '{}', '{}'),
  ('StaffingPolicies', '{PLANERING}', '{PLANERING}', '{PLANERING}', '{}'),
  ('StudentEnrollments', '{}', '{}', '{}', '{}'),
  ('StudentGroupMembers', '{PLANERING}', '{PLANERING}', '{PLANERING}', '{}'),
  ('StudentGroups', '{PLANERING}', '{PLANERING}', '{PLANERING}', '{}'),
  ('Subjects', '{PLANERING}', '{PLANERING}', '{PLANERING}', '{}'),
  ('SubstituteAvailabilities', '{DRIFT}', '{DRIFT}', '{DRIFT}', '{}'),
  ('SubstitutePoolMembers', '{DRIFT}', '{DRIFT}', '{DRIFT}', '{}'),
  ('SupervisionAreas', '{PLANERING}', '{PLANERING}', '{PLANERING}', '{}'),
  ('SupervisionCovers', '{DRIFT}', '{DRIFT}', '{DRIFT}', '{}'),
  ('SupervisionShifts', '{PLANERING}', '{PLANERING}', '{PLANERING}', '{}'),
  ('TeacherAbsenceCovers', '{DRIFT}', '{DRIFT}', '{DRIFT}', '{}'),
  ('TeacherAbsenceReasons', '{DRIFT}', '{DRIFT}', '{DRIFT}', '{}'),
  ('TeacherAbsences', '{DRIFT}', '{DRIFT}', '{DRIFT}', '{}'),
  ('TeacherDuties', '{PLANERING}', '{PLANERING}', '{PLANERING}', '{}'),
  ('TeacherDutySlots', '{PLANERING}', '{}', '{PLANERING}', '{}'),
  ('TeacherEmploymentLogs', '{}', '{}', '{}', '{}'),
  ('TeacherEmploymentPeriods', '{DECIDES}', '{DECIDES}', '{DECIDES}', '{}'),
  ('TeacherEmployments', '{DECIDES}', '{DECIDES}', '{DECIDES}', '{}'),
  ('TeacherPublicLabels', '{PUBLICERING}', '{PUBLICERING}', '{PUBLICERING}', '{}'),
  ('TeacherSubjectQualifications', '{PLANERING}', '{PLANERING}', '{PLANERING}', '{}'),
  ('TeacherWorkRules', '{PLANERING}', '{PLANERING}', '{PLANERING}', '{}'),
  ('TeachingBlocks', '{PLANERING}', '{PLANERING}', '{PLANERING}', '{}'),
  ('TeachingRequirementShares', '{PLANERING}', '{PLANERING}', '{PLANERING}', '{}'),
  ('TeachingRequirements', '{PLANERING}', '{PLANERING}', '{PLANERING}', '{}'),
  ('TimetablePublications', '{PUBLICERING}', '{}', '{}', '{}'),
  ('TimplanCredits', '{DRIFT}', '{DRIFT}', '{DRIFT}', '{}'),
  ('TimplanStatementPublications', '{PUBLICERING}', '{PUBLICERING}', '{PUBLICERING}', '{}'),
  ('TimplanStatements', '{PUBLICERING}', '{PUBLICERING}', '{PUBLICERING}', '{}'),
  ('UserRoleChanges', '{}', '{}', '{}', '{}'),
  ('Users', '{PERSONAL}', '{PERSONAL,PLANERING}', '{PERSONAL}', '{}');
-- END GENERATED: area matrix

DO $$
DECLARE
  -- The fourth column says how the school is named (Flera skolor per
  -- inloggning, 20261204090000): not at all, or, for a login with a row at
  -- school A as well, by PostgREST's header or the gateway's setting. Those
  -- two hold the other profile at school A, so a helper that answered for
  -- every row of the login would show here as the wrong profile's cells.
  principals constant text[][] := ARRAY[
    ['00000000-0000-4000-8000-000000000105', 'FULL', 'false', ''],
    ['00000000-0000-4000-8000-000000000106', 'REKTOR', 'false', ''],
    ['00000000-0000-4000-8000-000000000107', 'SCHEMALAGGARE', 'false', ''],
    ['00000000-0000-4000-8000-000000000108', 'EXPEDITION', 'false', ''],
    ['00000000-0000-4000-8000-000000000109', 'SCHEMALAGGARE', 'true', ''],
    ['00000000-0000-4000-8000-000000000110', 'EXPEDITION', 'true', ''],
    ['00000000-0000-4000-8000-000000000115', 'LASARE', 'false', ''],
    ['00000000-0000-4000-8000-000000000116', 'LASARE', 'true', ''],
    ['fe000000-0000-4000-8000-000000000240', 'LASARE', 'false', 'header'],
    ['fe000000-0000-4000-8000-000000000241', 'FULL', 'false', 'setting']];
  i integer;
  m uuid;
  pr record;
  g record;
  key_col text;
  pick text;
  ins_cols text;
  upd_col text;
  n bigint;
  st text;
  msg text;
  outcome text;
  refusal text;
  holds boolean;
  expected bigint;
  cmd text;
  gate_list text[];
  full_seen jsonb := '{}';
  wrong text[] := '{}';
  cells integer := 0;
BEGIN
  IF (SELECT count(*) FROM area_gates) < 70
     OR (SELECT count(*) FROM area_profiles) <> cardinality(enum_range(NULL::"AdminProfile")) THEN
    RAISE EXCEPTION 'matrix: the generated rows are missing (% tables, % profiles)',
      (SELECT count(*) FROM area_gates), (SELECT count(*) FROM area_profiles);
  END IF;

  FOR i IN 1 .. array_length(principals, 1) LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', principals[i][1])::text, true);
    PERFORM set_config('request.headers',
      CASE principals[i][4] WHEN 'header' THEN json_build_object('x-school-id', m)::text ELSE '' END, true);
    PERFORM set_config('app.chosen_school_id', CASE principals[i][4] WHEN 'setting' THEN m::text ELSE '' END, true);
    IF i = 1 THEN
      m := app.current_school_id();
      IF m IS NULL OR (SELECT slug FROM "Schools" WHERE id = m) IS DISTINCT FROM 'rls-roller-school' THEN
        RAISE EXCEPTION 'matrix: the full administrator is not in rls-roller-school; fixtures did not run';
      END IF;
    END IF;
    SELECT u."adminProfile"::text AS profile, u."hrRead" AS hr INTO pr
      FROM "Users" u WHERE u.id = app.current_user_id();
    IF app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' OR app.current_school_id() IS DISTINCT FROM m
       OR pr.profile IS DISTINCT FROM principals[i][2] OR pr.hr::text IS DISTINCT FROM principals[i][3] THEN
      RAISE EXCEPTION 'matrix: % resolved as % % % in %, expected % with HR-läs %', principals[i][1],
        app.current_user_role(), pr.profile, pr.hr, app.current_school_id(), principals[i][2], principals[i][3];
    END IF;

    FOR g IN SELECT * FROM area_gates ORDER BY tbl LOOP
      key_col := CASE g.tbl WHEN 'Schools' THEN 'id' ELSE 'schoolId' END;
      pick := format('(SELECT ctid FROM %I WHERE %I = %L%s LIMIT 1)', g.tbl, key_col, m,
                     CASE g.tbl WHEN 'Users' THEN ' AND role = ''STUDENT''' ELSE '' END);
      SELECT string_agg(quote_ident(a.attname), ', ' ORDER BY a.attnum) INTO ins_cols
        FROM pg_attribute a
       WHERE a.attrelid = format('public.%I', g.tbl)::regclass AND a.attnum > 0 AND NOT a.attisdropped
         AND has_column_privilege(format('public.%I', g.tbl), a.attname, 'INSERT');
      SELECT quote_ident(a.attname) INTO upd_col
        FROM pg_attribute a
       WHERE a.attrelid = format('public.%I', g.tbl)::regclass AND a.attnum > 0 AND NOT a.attisdropped
         AND has_column_privilege(format('public.%I', g.tbl), a.attname, 'UPDATE')
       ORDER BY (a.attname = key_col) DESC, a.attnum LIMIT 1;

      -- Read.
      EXECUTE format('SELECT count(*) FROM %I WHERE %I = $1', g.tbl, key_col) INTO n USING m;
      IF i = 1 THEN
        IF n = 0 THEN
          wrong := wrong || format('%s: FULL reads no row (the fixtures planted none?)', g.tbl);
        END IF;
        full_seen := full_seen || jsonb_build_object(g.tbl || ':read', n);
      ELSE
        -- A table with readers of its own (the läslogg) is read by those
        -- profiles and by nobody else; every other table by every profile.
        SELECT cardinality(g.rd) = 0 OR bool_or(CASE gl WHEN 'DECIDES' THEN p.decides ELSE gl = ANY (p.writes) END)
          INTO holds
          FROM area_profiles p LEFT JOIN unnest(g.rd) gl ON true
         WHERE p.profile = principals[i][2];
        expected := 0;
        IF holds THEN
          expected := (full_seen ->> (g.tbl || ':read'))::bigint;
        END IF;
        IF n IS DISTINCT FROM expected THEN
          wrong := wrong || format('%s %s%s reads %s rows of %s, FULL %s, readers %s', principals[i][2],
                                   CASE principals[i][3] WHEN 'true' THEN '+HR ' ELSE '' END, g.tbl, n, g.tbl,
                                   full_seen ->> (g.tbl || ':read'), g.rd);
        END IF;
      END IF;
      cells := cells + 1;

      FOREACH cmd IN ARRAY ARRAY['insert', 'update', 'delete'] LOOP
        outcome := NULL;
        BEGIN
          IF cmd = 'insert' THEN
            IF ins_cols IS NULL THEN
              outcome := 'denied';
            ELSE
              EXECUTE format('INSERT INTO %I (%s) SELECT %s FROM %I WHERE ctid = %s', g.tbl, ins_cols, ins_cols, g.tbl, pick);
              GET DIAGNOSTICS n = ROW_COUNT;
              outcome := CASE WHEN n = 1 THEN 'admitted' ELSE 'none' END;
            END IF;
          ELSIF cmd = 'update' THEN
            IF upd_col IS NULL THEN
              outcome := 'denied';
            ELSE
              EXECUTE format('UPDATE %I SET %s = %s WHERE ctid = %s', g.tbl, upd_col, upd_col, pick);
              GET DIAGNOSTICS n = ROW_COUNT;
              outcome := CASE WHEN n = 1 THEN 'admitted' ELSE 'none' END;
            END IF;
          ELSE
            EXECUTE format('DELETE FROM %I WHERE ctid = %s', g.tbl, pick);
            GET DIAGNOSTICS n = ROW_COUNT;
            outcome := CASE WHEN n = 1 THEN 'admitted' ELSE 'none' END;
          END IF;
          RAISE EXCEPTION USING ERRCODE = 'ZM116';
        EXCEPTION
          WHEN SQLSTATE 'ZM116' THEN NULL;
          WHEN unique_violation OR foreign_key_violation THEN
            outcome := 'admitted';
          WHEN insufficient_privilege THEN
            GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
            outcome := CASE WHEN msg LIKE '%row-level security%' THEN 'refused' ELSE 'denied' END;
          WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, msg = MESSAGE_TEXT;
            outcome := 'error ' || st || ' ' || left(msg, 80);
        END;

        gate_list := CASE cmd WHEN 'insert' THEN g.ins WHEN 'update' THEN g.upd ELSE g.del END;
        IF i = 1 THEN
          full_seen := full_seen || jsonb_build_object(g.tbl || ':' || cmd, outcome);
          IF cardinality(gate_list) > 0 AND outcome <> 'admitted' THEN
            wrong := wrong || format('FULL may %s %s but met %s', cmd, g.tbl, outcome);
          ELSIF cardinality(gate_list) = 0 AND outcome = 'admitted' THEN
            wrong := wrong || format('FULL may not %s %s, no gate says so, but was admitted', cmd, g.tbl);
          END IF;
        ELSIF cardinality(gate_list) = 0 THEN
          IF outcome IS DISTINCT FROM full_seen ->> (g.tbl || ':' || cmd) THEN
            wrong := wrong || format('%s %s met %s on %s, FULL met %s', principals[i][2], cmd, outcome, g.tbl,
                                     full_seen ->> (g.tbl || ':' || cmd));
          END IF;
        ELSE
          -- A delete's arm has only USING, so a refused delete finds no row.
          refusal := CASE cmd WHEN 'delete' THEN 'none' ELSE 'refused' END;
          SELECT bool_or(CASE gl WHEN 'DECIDES' THEN p.decides ELSE gl = ANY (p.writes) END) INTO holds
            FROM area_profiles p, unnest(gate_list) gl
           WHERE p.profile = principals[i][2];
          IF holds AND outcome <> 'admitted' THEN
            wrong := wrong || format('%s may %s %s (%s) but met %s', principals[i][2], cmd, g.tbl,
                                     array_to_string(gate_list, '|'), outcome);
          ELSIF NOT holds AND outcome <> refusal THEN
            wrong := wrong || format('%s may not %s %s (%s) but met %s', principals[i][2], cmd, g.tbl,
                                     array_to_string(gate_list, '|'), outcome);
          END IF;
        END IF;
        cells := cells + 1;
      END LOOP;
    END LOOP;
  END LOOP;

  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'matrix: % of % cells wrong: %', cardinality(wrong), cells, array_to_string(wrong, '; ');
  END IF;
  RAISE NOTICE 'matrix: % cells, % administrators × % tables × read, insert, update, delete', cells,
    array_length(principals, 1),
    (SELECT count(*) FROM area_gates);
END $$;

-- ---------------------------------------------------------------------------
-- Section 106: armarna säger samma sak som matrisen (Roller i skolan).
--
-- The catalogue half of section 116, against the same generated rows:
--   a. the tables are the same set: every table with an arm that names
--      SCHOOL_ADMIN or asks the area or the decisions is in the list, and
--      every listed table has one;
--   b. each command's arms ask exactly the command's gates, by name;
--   c. an update arm's USING never asks the area, so a row lock for a read
--      keeps working for every administrator (20261110100000);
--   d. no write arm admits an administrator without asking, which is the
--      migration's own closing guard, here for a branch that adds an arm
--      after it.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  bad text;
BEGIN
  SELECT string_agg(t, ', ' ORDER BY t) INTO bad FROM (
    (SELECT DISTINCT tablename AS t FROM pg_policies
      WHERE schemaname = 'public'
        AND (coalesce(qual, '') || coalesce(with_check, '')) ~ 'SCHOOL_ADMIN|current_user_may|current_user_decides'
     EXCEPT SELECT tbl FROM area_gates)
    UNION ALL
    (SELECT tbl FROM area_gates
     EXCEPT SELECT DISTINCT tablename FROM pg_policies
      WHERE schemaname = 'public'
        AND (coalesce(qual, '') || coalesce(with_check, '')) ~ 'SCHOOL_ADMIN|current_user_may|current_user_decides')
  ) x;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'arms: the tables with an administrator''s arm and src/auth/admin-areas.ts differ: %', bad;
  END IF;

  WITH asked AS (
    SELECT p.tablename AS tbl, c.cmd,
           coalesce(array_agg(DISTINCT g.gate ORDER BY g.gate) FILTER (WHERE g.gate IS NOT NULL), '{}') AS gates
      FROM pg_policies p
     CROSS JOIN unnest(ARRAY['INSERT', 'UPDATE', 'DELETE']) c(cmd)
      LEFT JOIN LATERAL (
        SELECT m[1] AS gate FROM regexp_matches(
                 CASE WHEN c.cmd = 'DELETE' THEN coalesce(p.qual, '') ELSE coalesce(p.with_check, p.qual, '') END,
                 'current_user_may\(''(\w+)''', 'g') m
        UNION ALL
        SELECT 'DECIDES' WHERE (CASE WHEN c.cmd = 'DELETE' THEN coalesce(p.qual, '') ELSE coalesce(p.with_check, p.qual, '') END)
                               LIKE '%current_user_decides()%'
      ) g ON true
     WHERE p.schemaname = 'public' AND p.cmd IN (c.cmd, 'ALL')
       AND (coalesce(p.qual, '') || coalesce(p.with_check, '')) LIKE '%SCHOOL_ADMIN%'
     GROUP BY p.tablename, c.cmd
  ), expected AS (
    SELECT tbl, 'INSERT' AS cmd, (SELECT coalesce(array_agg(x ORDER BY x), '{}') FROM unnest(ins) x) AS gates FROM area_gates
    UNION ALL SELECT tbl, 'UPDATE', (SELECT coalesce(array_agg(x ORDER BY x), '{}') FROM unnest(upd) x) FROM area_gates
    UNION ALL SELECT tbl, 'DELETE', (SELECT coalesce(array_agg(x ORDER BY x), '{}') FROM unnest(del) x) FROM area_gates
  )
  SELECT string_agg(format('%s %s asks %s, the matrix says %s', e.tbl, e.cmd, coalesce(a.gates, '{}'), e.gates), '; ')
    INTO bad
    FROM expected e LEFT JOIN asked a ON a.tbl = e.tbl AND a.cmd = e.cmd
   WHERE coalesce(a.gates, '{}') IS DISTINCT FROM e.gates
     -- A command neither API role is granted (TeacherDutySlots' UPDATE: a
     -- link is deleted and made again) is nobody's, whatever its arm says.
     AND NOT (e.gates = '{}'
              AND NOT has_table_privilege('app_authenticated', format('public.%I', e.tbl), e.cmd)
              AND NOT has_table_privilege('authenticated', format('public.%I', e.tbl), e.cmd));
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'arms: %', bad;
  END IF;

  -- A read arm asks the area or the decisions exactly where the table names
  -- its readers (the läslogg), and nowhere else: reading is every
  -- administrator's.
  SELECT string_agg(format('%s.%s', p.tablename, p.policyname), ', ') INTO bad
    FROM pg_policies p JOIN area_gates g ON g.tbl = p.tablename
   WHERE p.schemaname = 'public' AND p.cmd = 'SELECT'
     AND coalesce(p.qual, '') LIKE '%SCHOOL_ADMIN%'
     AND (coalesce(p.qual, '') ~ 'current_user_may|current_user_decides') IS DISTINCT FROM (cardinality(g.rd) > 0);
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'arms: these read arms ask, or fail to ask, what the matrix says about the table''s readers: %', bad;
  END IF;

  SELECT string_agg(format('%s.%s', tablename, policyname), ', ') INTO bad
    FROM pg_policies
   WHERE schemaname = 'public' AND cmd = 'UPDATE'
     AND coalesce(qual, '') LIKE '%SCHOOL_ADMIN%'
     AND coalesce(qual, '') ~ 'current_user_may|current_user_decides';
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'arms: an update arm asks the area in USING, which hands a row lock zero rows: %', bad;
  END IF;

  SELECT string_agg(format('%s.%s', tablename, policyname), ', ') INTO bad
    FROM pg_policies
   WHERE schemaname = 'public' AND cmd <> 'SELECT'
     AND (coalesce(qual, '') || coalesce(with_check, '')) LIKE '%SCHOOL_ADMIN%'
     AND NOT CASE cmd
           WHEN 'DELETE' THEN coalesce(qual, '') ~ 'current_user_(may|decides)\('
           WHEN 'ALL' THEN coalesce(qual, '') ~ 'current_user_(may|decides)\('
                           AND coalesce(with_check, qual, '') ~ 'current_user_(may|decides)\('
           ELSE coalesce(with_check, '') ~ 'current_user_(may|decides)\('
         END;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'arms: these admit an administrator''s write without asking: %', bad;
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 107: app.current_user_may och app.current_user_decides
-- (20261110090000).
--
-- Every principal of the matrix school, a teacher, a pupil, a guardian and
-- the primary school's deactivated administrator, against every area: an
-- active administrator reads every area and writes those of their profile;
-- nobody else reads or writes any; a NULL area is nothing, a NULL for write
-- is a write. Only FULL and REKTOR decide. The two functions run as their
-- owner with a fixed search_path, as every identity helper does.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  rec record;
  a "AdminArea";
  admin boolean;
  writes "AdminArea"[];
  wrong text[] := '{}';
BEGIN
  FOR rec IN SELECT * FROM (VALUES
      ('00000000-0000-4000-8000-000000000105', 'FULL'),
      ('00000000-0000-4000-8000-000000000106', 'REKTOR'),
      ('00000000-0000-4000-8000-000000000107', 'SCHEMALAGGARE'),
      ('00000000-0000-4000-8000-000000000108', 'EXPEDITION'),
      ('00000000-0000-4000-8000-000000000110', 'EXPEDITION'),
      ('00000000-0000-4000-8000-000000000115', 'LASARE'),
      ('00000000-0000-4000-8000-000000000116', 'LASARE'),
      ('00000000-0000-4000-8000-000000000111', 'TEACHER'),
      ('00000000-0000-4000-8000-000000000112', 'STUDENT'),
      ('00000000-0000-4000-8000-000000000113', 'GUARDIAN'),
      ('00000000-0000-4000-8000-000000000003', 'DEACTIVATED')) v(sub, who)
  LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', rec.sub)::text, true);
    admin := rec.who IN ('FULL', 'REKTOR', 'SCHEMALAGGARE', 'EXPEDITION', 'LASARE');
    writes := CASE WHEN admin THEN app.admin_profile_writes(rec.who::"AdminProfile") ELSE '{}' END;
    FOREACH a IN ARRAY enum_range(NULL::"AdminArea") LOOP
      IF app.current_user_may(a, false) IS DISTINCT FROM admin THEN
        wrong := wrong || format('%s reads %s: %s', rec.who, a, app.current_user_may(a, false));
      END IF;
      IF app.current_user_may(a, true) IS DISTINCT FROM (a = ANY (writes)) THEN
        wrong := wrong || format('%s writes %s: %s', rec.who, a, app.current_user_may(a, true));
      END IF;
      IF app.current_user_may(a, NULL) IS DISTINCT FROM app.current_user_may(a, true) THEN
        wrong := wrong || format('%s: a NULL write is not a write on %s', rec.who, a);
      END IF;
    END LOOP;
    IF app.current_user_may(NULL, false) OR app.current_user_may(NULL, true) THEN
      wrong := wrong || format('%s may do something with no area at all', rec.who);
    END IF;
    IF app.current_user_decides() IS DISTINCT FROM (rec.who IN ('FULL', 'REKTOR')) THEN
      wrong := wrong || format('%s decides: %s', rec.who, app.current_user_decides());
    END IF;
  END LOOP;
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'functions: %', array_to_string(wrong, '; ');
  END IF;

  IF (SELECT count(*) FROM pg_proc p
       WHERE p.pronamespace = 'app'::regnamespace
         AND p.proname IN ('current_user_may', 'current_user_decides')
         AND p.prosecdef
         AND EXISTS (SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%')) <> 2 THEN
    RAISE EXCEPTION 'functions: the area functions are not SECURITY DEFINER with a fixed search_path';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 108: rektor beslutar vem som är administratör, och varje ändring
-- loggas (Users_administrators_are_decided, Users_role_changes_are_logged).
--
-- The expedition writes the roster but makes nobody an administrator,
-- changes no role, and touches no administrator's row. Rektor does all of
-- it; each change of role, profile or HR-läs leaves one row with rektor as
-- the actor, and a name change leaves none. The profile follows the role:
-- an administrator written without one is FULL, HR-läs goes with a
-- deciding profile, and both go when somebody stops being an
-- administrator. Nobody writes the log but the trigger; every
-- administrator reads it, a teacher does not.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  m uuid;
  teacher uuid;
  planner uuid;
  rektor uuid;
  newcomer uuid;
  n bigint;
  row_ record;
BEGIN
  -- The expedition.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000108')::text, true);
  m := app.current_school_id();
  IF m IS NULL OR (SELECT slug FROM "Schools" WHERE id = m) IS DISTINCT FROM 'rls-roller-school' THEN
    RAISE EXCEPTION 'decisions: the expedition is not in rls-roller-school; fixtures did not run';
  END IF;
  teacher := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000111');
  planner := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000107');
  rektor := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000106');

  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "updatedAt")
  VALUES (m, 'roller-ny-larare@example.invalid', 'Ny', 'Lärare', 'TEACHER', gen_random_uuid(), now());
  UPDATE "Users" SET phone = '070-108' WHERE id = teacher;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'decisions: the expedition could not write a teacher''s phone'; END IF;

  BEGIN
    INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "adminProfile", "authId", "updatedAt")
    VALUES (m, 'roller-ny-admin@example.invalid', 'Ny', 'Admin', 'SCHOOL_ADMIN', 'EXPEDITION', gen_random_uuid(), now());
    RAISE EXCEPTION 'decisions: the expedition made an administrator';
  EXCEPTION WHEN SQLSTATE 'AR403' THEN NULL;
  END;
  BEGIN
    UPDATE "Users" SET role = 'SCHOOL_ADMIN' WHERE id = teacher;
    RAISE EXCEPTION 'decisions: the expedition made a teacher an administrator';
  EXCEPTION WHEN SQLSTATE 'AR403' THEN NULL;
  END;
  BEGIN
    UPDATE "Users" SET role = 'STUDENT' WHERE id = teacher;
    RAISE EXCEPTION 'decisions: the expedition changed a teacher''s role';
  EXCEPTION WHEN SQLSTATE 'AR403' THEN NULL;
  END;
  BEGIN
    UPDATE "Users" SET "firstName" = 'Bytt' WHERE id = planner;
    RAISE EXCEPTION 'decisions: the expedition renamed an administrator';
  EXCEPTION WHEN SQLSTATE 'AR403' THEN NULL;
  END;
  BEGIN
    UPDATE "Users" SET "hrRead" = true WHERE id = planner;
    RAISE EXCEPTION 'decisions: the expedition gave HR-läs';
  EXCEPTION WHEN SQLSTATE 'AR403' THEN NULL;
  END;
  BEGIN
    DELETE FROM "Users" WHERE id = planner;
    RAISE EXCEPTION 'decisions: the expedition removed an administrator';
  EXCEPTION WHEN SQLSTATE 'AR403' THEN NULL;
  END;
  IF (SELECT "firstName" FROM "Users" WHERE id = planner) IS DISTINCT FROM 'Roller' THEN
    RAISE EXCEPTION 'decisions: a refused write changed the planner''s row';
  END IF;

  -- Rektor.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000106')::text, true);
  n := (SELECT count(*) FROM "UserRoleChanges" WHERE "userId" = teacher);
  UPDATE "Users" SET role = 'SCHOOL_ADMIN', "adminProfile" = 'SCHEMALAGGARE', "hrRead" = true WHERE id = teacher;
  SELECT * INTO row_ FROM "UserRoleChanges" WHERE "userId" = teacher ORDER BY "createdAt" DESC LIMIT 1;
  IF (SELECT count(*) FROM "UserRoleChanges" WHERE "userId" = teacher) <> n + 1
     OR (row_."fromRole", row_."toRole", row_."fromProfile", row_."toProfile", row_."fromHrRead", row_."toHrRead", row_."actorId")
        IS DISTINCT FROM ('TEACHER'::"UserRole", 'SCHOOL_ADMIN'::"UserRole", NULL::"AdminProfile",
                          'SCHEMALAGGARE'::"AdminProfile", false, true, rektor) THEN
    RAISE EXCEPTION 'decisions: rektor''s promotion was logged as %', row_;
  END IF;
  UPDATE "Users" SET "firstName" = 'Omdöpt' WHERE id = teacher;
  IF (SELECT count(*) FROM "UserRoleChanges" WHERE "userId" = teacher) <> n + 1 THEN
    RAISE EXCEPTION 'decisions: a name change was logged as a role change';
  END IF;
  UPDATE "Users" SET "adminProfile" = 'REKTOR' WHERE id = teacher;
  IF (SELECT "hrRead" FROM "Users" WHERE id = teacher) THEN
    RAISE EXCEPTION 'decisions: a rektor kept HR-läs, which is the narrow profiles''';
  END IF;
  UPDATE "Users" SET role = 'TEACHER' WHERE id = teacher;
  IF (SELECT ("adminProfile", "hrRead") FROM "Users" WHERE id = teacher) IS DISTINCT FROM (NULL::"AdminProfile", false) THEN
    RAISE EXCEPTION 'decisions: a teacher kept an administrator''s profile';
  END IF;
  IF (SELECT count(*) FROM "UserRoleChanges" WHERE "userId" = teacher) <> n + 3 THEN
    RAISE EXCEPTION 'decisions: % rows logged for three changes', (SELECT count(*) FROM "UserRoleChanges" WHERE "userId" = teacher) - n;
  END IF;
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "updatedAt")
  VALUES (m, 'roller-rektors-nya@example.invalid', 'Rektors', 'Nya', 'SCHOOL_ADMIN', gen_random_uuid(), now())
  RETURNING id INTO newcomer;
  IF (SELECT "adminProfile" FROM "Users" WHERE id = newcomer) IS DISTINCT FROM 'FULL' THEN
    RAISE EXCEPTION 'decisions: an administrator written without a profile is not FULL';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "UserRoleChanges" WHERE "userId" = newcomer AND "fromRole" IS NULL AND "toProfile" = 'FULL' AND "actorId" = rektor) THEN
    RAISE EXCEPTION 'decisions: a new administrator was not logged';
  END IF;

  -- The log is the trigger's.
  BEGIN
    INSERT INTO "UserRoleChanges" ("schoolId", "userId", "toRole", "toHrRead") VALUES (m, teacher, 'SCHOOL_ADMIN', false);
    RAISE EXCEPTION 'decisions: the API wrote the log';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    DELETE FROM "UserRoleChanges" WHERE "userId" = teacher;
    RAISE EXCEPTION 'decisions: the API erased the log';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000108')::text, true);
  IF (SELECT count(*) FROM "UserRoleChanges" WHERE "userId" = teacher) <> n + 3 THEN
    RAISE EXCEPTION 'decisions: the expedition does not read the log rektor wrote';
  END IF;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000111')::text, true);
  IF (SELECT count(*) FROM "UserRoleChanges") <> 0 THEN
    RAISE EXCEPTION 'decisions: a teacher reads the role log';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 109: utan personal flyttar en administratör bara en elev mellan
-- klasser (Users_class_moves_are_narrow, 20261110100000).
--
-- The planner writes planering, not the roster: Aktivera moves pupils into
-- next year's classes, and that update is the planner's, but not a pupil's
-- name, not a teacher's class, not a new person and not a removal. The
-- expedition, who writes the roster, renames the pupil.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  m uuid;
  pupil uuid;
  teacher uuid;
  next_class uuid;
  n bigint;
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
  m := app.current_school_id();
  pupil := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000112');
  teacher := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000111');
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, "gradeLevel", "updatedAt")
  SELECT m, "academicYearId", 'Roller 7B', 7, now() FROM "StudentGroups" WHERE name = 'Roller 7A' AND "schoolId" = m
  RETURNING id INTO next_class;

  UPDATE "Users" SET "studentGroupId" = next_class, "updatedAt" = now() WHERE id = pupil;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'class move: the planner could not move a pupil (% rows)', n; END IF;

  BEGIN
    UPDATE "Users" SET "firstName" = 'Bytt' WHERE id = pupil;
    RAISE EXCEPTION 'class move: the planner renamed a pupil';
  EXCEPTION WHEN SQLSTATE 'AR403' THEN NULL;
  END;
  BEGIN
    UPDATE "Users" SET phone = '070-107' WHERE id = teacher;
    RAISE EXCEPTION 'class move: the planner wrote a teacher''s row';
  EXCEPTION WHEN SQLSTATE 'AR403' THEN NULL;
  END;
  BEGIN
    INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "updatedAt")
    VALUES (m, 'roller-planerarens@example.invalid', 'Ny', 'Elev', 'STUDENT', gen_random_uuid(), now());
    RAISE EXCEPTION 'class move: the planner added a person';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  DELETE FROM "Users" WHERE id = pupil;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'class move: the planner removed a pupil'; END IF;

  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000108')::text, true);
  UPDATE "Users" SET "firstName" = 'Expeditionens' WHERE id = pupil;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'class move: the expedition could not rename a pupil'; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 110: varje profil kan låsa raderna gatewayen låser
-- (20261110100000).
--
-- Postgres applies an UPDATE arm's USING to SELECT ... FOR UPDATE and FOR
-- SHARE, and the gateway locks a teacher's Users row (an uppdrag, a
-- behörighet), the posts (the timplansposter), the läsår (a lov) and the
-- plans (a subject's removal) in work that is not those tables' area. Every
-- profile must get the row; zero would be a silent wrong answer mid-term.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  sub text;
  n bigint;
  wrong text[] := '{}';
BEGIN
  FOREACH sub IN ARRAY ARRAY['00000000-0000-4000-8000-000000000105', '00000000-0000-4000-8000-000000000106',
                             '00000000-0000-4000-8000-000000000107', '00000000-0000-4000-8000-000000000108']
  LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', sub)::text, true);
    SELECT count(*) INTO n FROM (SELECT 1 FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000111' FOR NO KEY UPDATE) x;
    IF n <> 1 THEN wrong := wrong || format('%s locks %s Users rows', sub, n); END IF;
    SELECT count(*) INTO n FROM (SELECT 1 FROM "TeacherEmployments" WHERE "schoolId" = app.current_school_id() FOR NO KEY UPDATE) x;
    IF n <> 1 THEN wrong := wrong || format('%s locks %s posts', sub, n); END IF;
    SELECT count(*) INTO n FROM (SELECT 1 FROM "AcademicYears" WHERE "schoolId" = app.current_school_id() FOR SHARE) x;
    IF n <> 1 THEN wrong := wrong || format('%s locks %s läsår', sub, n); END IF;
    SELECT count(*) INTO n FROM (SELECT 1 FROM "LocalTimplans" WHERE "schoolId" = app.current_school_id() FOR SHARE) x;
    IF n <> 1 THEN wrong := wrong || format('%s locks %s plans', sub, n); END IF;
    SELECT count(*) INTO n FROM (SELECT 1 FROM "TeachingRequirements" WHERE "schoolId" = app.current_school_id() FOR NO KEY UPDATE) x;
    IF n <> 1 THEN wrong := wrong || format('%s locks %s requirements', sub, n); END IF;
  END LOOP;
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'locks: %', array_to_string(wrong, '; ');
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 111: en annans tjänst % nås bara genom gatewayen (20261110100000).
--
-- Through PostgREST's role (authenticated) every administrator, rektor and
-- full and HR-läs included, reads no colleague's post or its log: the
-- administrators' arms are the API role's alone since 20261028090000, and
-- the split keeps that. The teacher reads their own (section 129's read).
-- Through the API's role (app_authenticated) a planner without HR-läs reads
-- the row, whose percentages the gateway leaves out, and the API keeps its
-- privileges to write the posts.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  rel text;
  p text;
  bad text[] := '{}';
BEGIN
  FOREACH rel IN ARRAY ARRAY['public."TeacherEmployments"', 'public."TeacherEmploymentLogs"'] LOOP
    IF NOT has_table_privilege('app_authenticated', rel, 'SELECT') THEN bad := bad || format('the API cannot read %s', rel); END IF;
  END LOOP;
  FOREACH p IN ARRAY ARRAY['INSERT', 'UPDATE', 'DELETE'] LOOP
    IF NOT has_table_privilege('app_authenticated', 'public."TeacherEmployments"', p) THEN
      bad := bad || format('the API cannot %s a post', p);
    END IF;
  END LOOP;
  IF cardinality(bad) > 0 THEN
    RAISE EXCEPTION 'hr: %', array_to_string(bad, '; ');
  END IF;
END $$;

BEGIN;
DO $$
DECLARE
  who text;
  posts bigint;
  logs bigint;
  bad text[] := '{}';
BEGIN
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000000105', '00000000-0000-4000-8000-000000000106',
                             '00000000-0000-4000-8000-000000000107', '00000000-0000-4000-8000-000000000108',
                             '00000000-0000-4000-8000-000000000109', '00000000-0000-4000-8000-000000000110',
                             '00000000-0000-4000-8000-000000000111'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    IF (SELECT slug FROM "Schools" WHERE id = app.current_school_id()) IS DISTINCT FROM 'rls-roller-school' THEN
      RAISE EXCEPTION 'hr: % is not in rls-roller-school; fixtures did not run', who;
    END IF;
    SET LOCAL ROLE authenticated;
    SELECT count(*) INTO posts FROM "TeacherEmployments" WHERE "userId" IS DISTINCT FROM app.current_user_id();
    SELECT count(*) INTO logs FROM "TeacherEmploymentLogs" WHERE "userId" IS DISTINCT FROM app.current_user_id();
    IF posts + logs > 0 THEN
      bad := bad || format('%s reads %s posts and %s log rows of others through PostgREST', who, posts, logs);
    END IF;
    IF who LIKE '%111' THEN
      SELECT count(*) INTO posts FROM "TeacherEmployments";
      SELECT count(*) INTO logs FROM "TeacherEmploymentLogs";
      IF posts = 0 OR logs = 0 THEN
        bad := bad || format('the teacher reads %s of their own posts and %s of their log rows through PostgREST', posts, logs);
      END IF;
    END IF;
    SET LOCAL ROLE app_authenticated;
    IF who LIKE '%107' THEN
      SELECT count(*) INTO posts FROM "TeacherEmployments";
      IF posts = 0 THEN bad := bad || 'the planner reads no post through the API'; END IF;
    END IF;
  END LOOP;
  IF cardinality(bad) > 0 THEN
    RAISE EXCEPTION 'hr: %', array_to_string(bad, '; ');
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 112: integrationernas hemligheter och SS12000-id är
-- integrationer (20261110100000).
--
-- The three SECURITY DEFINER functions that write the integrations' secrets
-- run past every arm, so they ask the area themselves; a planner is refused
-- (SS403), a full administrator passes the question. Reading whether a
-- secret is set stays every administrator's. A row's SS12000 id, which only
-- an administrator's sync writes, is integrationer's too.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  src uuid;
  ikey uuid;
  grp uuid;
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
  src := (SELECT id FROM "Ss12000Sources" WHERE "schoolId" = app.current_school_id() LIMIT 1);
  ikey := (SELECT id FROM "IntegrationApiKeys" WHERE "schoolId" = app.current_school_id() LIMIT 1);
  grp := (SELECT id FROM "StudentGroups" WHERE "schoolId" = app.current_school_id() AND name = 'Roller 7A');
  IF src IS NULL OR ikey IS NULL OR grp IS NULL THEN
    RAISE EXCEPTION 'secrets: the matrix school has no source, key or class; fixtures did not run';
  END IF;

  BEGIN
    PERFORM app.ss12000_set_source_secret(src, 'BEARER_TOKEN', '\x00'::bytea, '\x000000000000000000000000'::bytea,
                                          '\x00000000000000000000000000000000'::bytea, 'a1b2c3d4');
    RAISE EXCEPTION 'secrets: the planner set a source secret';
  EXCEPTION WHEN SQLSTATE 'SS403' THEN NULL;
  END;
  BEGIN
    PERFORM app.ss12000_clear_source_secrets(src, ARRAY['BEARER_TOKEN']::"Ss12000SecretKind"[]);
    RAISE EXCEPTION 'secrets: the planner cleared a source secret';
  EXCEPTION WHEN SQLSTATE 'SS403' THEN NULL;
  END;
  BEGIN
    PERFORM app.integration_key_set_webhook_secret(ikey, '\x00'::bytea, '\x000000000000000000000000'::bytea,
                                                   '\x00000000000000000000000000000000'::bytea, 'a1b2c3d4');
    RAISE EXCEPTION 'secrets: the planner set a signing secret';
  EXCEPTION WHEN SQLSTATE 'SS403' THEN NULL;
  END;
  -- Reading presence is every administrator's.
  PERFORM app.ss12000_source_secret_presence(src);
  BEGIN
    UPDATE "StudentGroups" SET "ss12000Id" = gen_random_uuid() WHERE id = grp;
    RAISE EXCEPTION 'secrets: the planner linked a class to the source';
  EXCEPTION WHEN SQLSTATE 'SS403' THEN NULL;
  END;

  -- A full administrator: the same calls, with the same (valid) bytes, pass.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  PERFORM app.ss12000_set_source_secret(src, 'BEARER_TOKEN', '\x00'::bytea, '\x000000000000000000000000'::bytea,
                                        '\x00000000000000000000000000000000'::bytea, 'a1b2c3d4');
  IF app.ss12000_clear_source_secrets(src, ARRAY['BEARER_TOKEN']::"Ss12000SecretKind"[]) <> 1 THEN
    RAISE EXCEPTION 'secrets: a full administrator''s secret was not there to clear';
  END IF;
  PERFORM app.integration_key_set_webhook_secret(ikey, '\x00'::bytea, '\x000000000000000000000000'::bytea,
                                                 '\x00000000000000000000000000000000'::bytea, 'a1b2c3d4');
  UPDATE "StudentGroups" SET "ss12000Id" = gen_random_uuid() WHERE id = grp;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 113: att dela tjänst % med integrationerna är ett beslut
-- (StaffingPolicies_sharing_is_decided, 20261110100000).
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  n bigint;
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
  UPDATE "StaffingPolicies" SET "fullTimeTeachingMinutesPerWeek" = 1000 WHERE "schoolId" = app.current_school_id();
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'sharing: the planner could not set the riktmärke'; END IF;
  BEGIN
    UPDATE "StaffingPolicies" SET "shareEmploymentWithIntegrations" = true WHERE "schoolId" = app.current_school_id();
    RAISE EXCEPTION 'sharing: the planner shared tjänst %% with the integrations';
  EXCEPTION WHEN SQLSTATE 'AR403' THEN NULL;
  END;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000106')::text, true);
  UPDATE "StaffingPolicies" SET "shareEmploymentWithIntegrations" = true WHERE "schoolId" = app.current_school_id();
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'sharing: rektor could not share'; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 114: de nya objekten börjar som nya objekt ska (20261110090000,
-- 20261110100000).
--
-- UserRoleChanges: row security on, the API reads and writes nothing,
-- PostgREST's role and anon hold nothing, service_role reads (20261016130000),
-- MAINTAIN for nobody on Postgres 17. The trigger functions are no API
-- role's to call; the two policy functions are every role's that evaluates a
-- policy; the writers' school function is the API's alone. Users carries its
-- two CHECKs, validated.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  rel regclass := 'public."UserRoleChanges"';
  maintain text[] := CASE WHEN current_setting('server_version_num')::int >= 170000 THEN ARRAY['MAINTAIN'] ELSE '{}' END;
  r text;
  p text;
  fn text;
  bad text[] := '{}';
BEGIN
  IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = rel) THEN
    bad := bad || 'UserRoleChanges has row security off'::text;
  END IF;
  FOREACH r IN ARRAY ARRAY['app_authenticated', 'authenticated', 'anon', 'service_role'] LOOP
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
    FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] || maintain LOOP
      IF has_table_privilege(r, rel, p) IS DISTINCT FROM (p = 'SELECT' AND r IN ('app_authenticated', 'service_role')) THEN
        bad := bad || format('%s %s %s', r, p, has_table_privilege(r, rel, p));
      END IF;
    END LOOP;
  END LOOP;

  FOREACH fn IN ARRAY ARRAY['app.users_profile_follows_the_role()', 'app.users_administrators_are_decided()',
                            'app.users_role_changes_are_logged()', 'app.users_class_moves_are_narrow()',
                            'app.staffing_policies_sharing_is_decided()'] LOOP
    FOREACH r IN ARRAY ARRAY['app_authenticated', 'authenticated', 'anon', 'service_role'] LOOP
      CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
      IF has_function_privilege(r, fn, 'EXECUTE') THEN bad := bad || format('%s may call %s', r, fn); END IF;
    END LOOP;
  END LOOP;
  FOREACH fn IN ARRAY ARRAY['app.current_user_may("AdminArea", boolean)', 'app.current_user_decides()'] LOOP
    FOREACH r IN ARRAY ARRAY['app_authenticated', 'authenticated'] LOOP
      IF NOT has_function_privilege(r, fn, 'EXECUTE') THEN bad := bad || format('%s may not call %s', r, fn); END IF;
    END LOOP;
  END LOOP;
  IF NOT has_function_privilege('app_authenticated', 'app.ss12000_admin_writer_school()', 'EXECUTE') THEN
    bad := bad || 'the API may not call app.ss12000_admin_writer_school()'::text;
  END IF;
  FOREACH r IN ARRAY ARRAY['authenticated', 'anon', 'service_role'] LOOP
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
    IF has_function_privilege(r, 'app.ss12000_admin_writer_school()', 'EXECUTE') THEN
      bad := bad || format('%s may call app.ss12000_admin_writer_school()', r);
    END IF;
  END LOOP;

  IF (SELECT count(*) FROM pg_constraint
       WHERE conrelid = 'public."Users"'::regclass AND contype = 'c' AND convalidated
         AND conname IN ('Users_a_profile_is_an_administrators', 'Users_hr_read_is_a_narrow_administrators')) <> 2 THEN
    bad := bad || 'Users lacks a validated profile CHECK'::text;
  END IF;
  IF cardinality(bad) > 0 THEN
    RAISE EXCEPTION 'new objects: %', array_to_string(bad, '; ');
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Section 115: en avaktiverad administratör skriver inget område och
-- beslutar inget (20261110090000).
--
-- The primary school's deactivated administrator, a FULL one: the identity
-- helpers already give nobody, and the area functions answer false for
-- every area and decide nothing, so no arm and no trigger lets them through.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', :'inactive_auth_id')::text, true);
DO $$
DECLARE
  a "AdminArea";
BEGIN
  FOREACH a IN ARRAY enum_range(NULL::"AdminArea") LOOP
    IF app.current_user_may(a, false) OR app.current_user_may(a, true) THEN
      RAISE EXCEPTION 'deactivated: may read or write %', a;
    END IF;
  END LOOP;
  IF app.current_user_decides() THEN
    RAISE EXCEPTION 'deactivated: still decides';
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Section 144: en tjänsts anställningsform och karriärtjänst är tjänstens
-- (20261111090000).
--
-- In the läslogg school. Through the API's role the admin writes teacher
-- 122's anställningsform, förstelärare and lektor shares. The table refuses
-- a share outside 1–100 whole per cent, and the two shares together above
-- the post, each by its own named CHECK (prisma-errors.ts turns each name
-- into a 400), and an anställningsform that is not one of the two. The
-- version the write makes carries the three in its history, the note still
-- out. Teacher 122 reads the three on their own post, directly and through
-- the API; teacher 126 reads nothing of 122's post either way, as 129 holds
-- for the row.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000121')::text, true);
SET LOCAL ROLE app_authenticated;
DO $$
DECLARE
  teacher uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000122');
  post uuid;
  refused text;
  attempt record;
  logged jsonb;
BEGIN
  SELECT id INTO post FROM "TeacherEmployments" WHERE "userId" = teacher;
  IF post IS NULL THEN RAISE EXCEPTION 'career: teacher 122 has no post to write'; END IF;

  UPDATE "TeacherEmployments"
     SET "employmentForm" = 'VISSTID', "firstTeacherPercent" = 20, "lecturerPercent" = 80, note = 'rls144 anteckning'
   WHERE id = post;
  IF NOT FOUND THEN RAISE EXCEPTION 'career: the admin could not write the post through the API'; END IF;

  FOR attempt IN
    SELECT * FROM (VALUES
      ('"firstTeacherPercent" = 0', 'TeacherEmployments_firstTeacherPercent_check'),
      -- Above 100 is above the post too, and PostgreSQL checks by name.
      ('"firstTeacherPercent" = 101', 'TeacherEmployments_career_share_check'),
      ('"firstTeacherPercent" = -1, "lecturerPercent" = NULL', 'TeacherEmployments_firstTeacherPercent_check'),
      ('"lecturerPercent" = 0', 'TeacherEmployments_lecturerPercent_check'),
      ('"lecturerPercent" = 81', 'TeacherEmployments_career_share_check'),
      ('"firstTeacherPercent" = 100, "lecturerPercent" = 1', 'TeacherEmployments_career_share_check')
    ) AS t(assignment, constraint_name)
  LOOP
    BEGIN
      EXECUTE format('UPDATE "TeacherEmployments" SET %s WHERE id = $1', attempt.assignment) USING post;
      RAISE EXCEPTION 'career: % was written', attempt.assignment;
    EXCEPTION WHEN check_violation THEN
      GET STACKED DIAGNOSTICS refused = CONSTRAINT_NAME;
      IF refused IS DISTINCT FROM attempt.constraint_name THEN
        RAISE EXCEPTION 'career: % was refused by %, not %', attempt.assignment, refused, attempt.constraint_name;
      END IF;
    END;
  END LOOP;
  BEGIN
    UPDATE "TeacherEmployments" SET "employmentForm" = 'LEDIG' WHERE id = post;
    RAISE EXCEPTION 'career: an anställningsform outside the two was written';
  EXCEPTION WHEN invalid_text_representation THEN NULL;
  END;

  SELECT after INTO logged FROM "TeacherEmploymentLogs"
   WHERE "entityId" = post ORDER BY version DESC LIMIT 1;
  IF logged->>'employmentForm' IS DISTINCT FROM 'VISSTID'
     OR (logged->>'firstTeacherPercent')::int IS DISTINCT FROM 20
     OR (logged->>'lecturerPercent')::int IS DISTINCT FROM 80 THEN
    RAISE EXCEPTION 'career: the version holds %', logged;
  END IF;
  IF logged ? 'note' OR NOT (logged->>'noteChanged')::boolean THEN
    RAISE EXCEPTION 'career: the version carries the note or does not say it changed: %', logged;
  END IF;
END $$;

SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000122')::text, true);
DO $$
DECLARE
  via text;
  got text;
BEGIN
  FOREACH via IN ARRAY ARRAY['authenticated', 'app_authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    SELECT string_agg(coalesce("employmentForm"::text, '-') || ' ' || coalesce("firstTeacherPercent"::text, '-')
                      || ' ' || coalesce("lecturerPercent"::text, '-'), ',')
      INTO got FROM "TeacherEmployments" WHERE "userId" = app.current_user_id();
    IF got IS DISTINCT FROM 'VISSTID 20 80' THEN
      RAISE EXCEPTION 'career: as % teacher 122 reads % of their own post', via, got;
    END IF;
  END LOOP;
END $$;

SET LOCAL ROLE app_authenticated;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000126')::text, true);
DO $$
DECLARE
  via text;
  n bigint;
BEGIN
  FOREACH via IN ARRAY ARRAY['authenticated', 'app_authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    SELECT count(*) INTO n FROM "TeacherEmployments" WHERE "firstTeacherPercent" IS NOT NULL OR "employmentForm" IS NOT NULL;
    IF n <> 0 THEN RAISE EXCEPTION 'career: as % teacher 126 reads % colleague''s anställningsform or share', via, n; END IF;
    SELECT count(*) INTO n FROM "TeacherEmploymentLogs"
     WHERE "userId" <> app.current_user_id();
    IF n <> 0 THEN RAISE EXCEPTION 'career: as % teacher 126 reads % versions of a colleague''s post', via, n; END IF;
  END LOOP;
END $$;
SET LOCAL ROLE app_authenticated;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 145: kalenderprenumeration, katalogen (20261112091000).
--
-- The feed's door, the person's three (create, revoke, audience_on) and the
-- admin's count are SECURITY DEFINER with a pinned search_path and the API's
-- role's alone. The builders and the family's label rule run as their caller
-- and are nobody's to call, nor are the triggers' functions.
-- CalendarFeeds has row security and one arm, the owner's SELECT for the
-- API's role; the API's role holds SELECT and nothing else, PostgREST's role
-- and anon nothing. The settings', the people's and the links' triggers are
-- in place, the family's staff and the pupil's builder ask the one label
-- rule, the CHECKs hold, a person has one live feed per week by a unique
-- index (the functions revoke the old first, so only the index says it of
-- every writer), and the read log has its CALENDAR way.
-- ---------------------------------------------------------------------------

DO $$
DECLARE fn text; r text; priv text; c text;
BEGIN
  FOREACH fn IN ARRAY ARRAY['app.calendar_feed(text)', 'app.calendar_feed_create(uuid, text, text)', 'app.calendar_feed_revoke(uuid)',
                            'app.calendar_feed_counts()', 'app.calendar_feed_audience_on()'] LOOP
    IF NOT (SELECT prosecdef FROM pg_proc WHERE oid = fn::regprocedure) THEN RAISE EXCEPTION 'feed: % is not SECURITY DEFINER', fn; END IF;
    IF NOT coalesce((SELECT 'search_path="public", "pg_temp"' = ANY (proconfig) OR 'search_path=public, pg_temp' = ANY (proconfig)
                       FROM pg_proc WHERE oid = fn::regprocedure), false) THEN
      RAISE EXCEPTION 'feed: % has no pinned search_path', fn;
    END IF;
    IF NOT has_function_privilege('app_authenticated', fn, 'EXECUTE') THEN RAISE EXCEPTION 'feed: the API may not call %', fn; END IF;
    FOREACH r IN ARRAY ARRAY['anon', 'authenticated', 'service_role'] LOOP
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) AND has_function_privilege(r, fn, 'EXECUTE') THEN
        RAISE EXCEPTION 'feed: % may call %', r, fn;
      END IF;
    END LOOP;
  END LOOP;
  FOREACH fn IN ARRAY ARRAY['app.calendar_feed_teacher_lessons(uuid, uuid, date, date, text)',
                            'app.calendar_feed_pupil_lessons(uuid, uuid, date, date, text, "TeacherDisplay")',
                            'app.calendar_feed_breaks(uuid, integer, boolean, date, date)',
                            'app.family_lesson_labels(uuid, "TeacherDisplay", uuid[])'] LOOP
    IF (SELECT prosecdef FROM pg_proc WHERE oid = fn::regprocedure) THEN RAISE EXCEPTION 'feed: % runs as its owner', fn; END IF;
  END LOOP;
  -- The triggers' functions write the feeds as their owner, and the family's
  -- staff, replaced to ask the label rule, is still a door of its own.
  FOREACH fn IN ARRAY ARRAY['app.calendar_feeds_follow_the_school()', 'app.calendar_feeds_follow_the_person()',
                            'app.family_lesson_staff(uuid[])'] LOOP
    IF NOT (SELECT prosecdef FROM pg_proc WHERE oid = fn::regprocedure) THEN RAISE EXCEPTION 'feed: % is not SECURITY DEFINER', fn; END IF;
    IF NOT coalesce((SELECT 'search_path="public", "pg_temp"' = ANY (proconfig) OR 'search_path=public, pg_temp' = ANY (proconfig)
                       FROM pg_proc WHERE oid = fn::regprocedure), false) THEN
      RAISE EXCEPTION 'feed: % has no pinned search_path', fn;
    END IF;
  END LOOP;
  IF NOT has_function_privilege('app_authenticated', 'app.family_lesson_staff(uuid[])', 'EXECUTE') THEN
    RAISE EXCEPTION 'feed: the API may no longer ask the family''s staff';
  END IF;
  FOREACH fn IN ARRAY ARRAY['app.calendar_feed_teacher_lessons(uuid, uuid, date, date, text)',
                            'app.calendar_feed_pupil_lessons(uuid, uuid, date, date, text, "TeacherDisplay")',
                            'app.calendar_feed_breaks(uuid, integer, boolean, date, date)',
                            'app.family_lesson_labels(uuid, "TeacherDisplay", uuid[])',
                            'app.calendar_feeds_follow_the_school()',
                            'app.calendar_feeds_follow_the_person()'] LOOP
    FOREACH r IN ARRAY ARRAY['app_authenticated', 'anon', 'authenticated', 'service_role'] LOOP
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) AND has_function_privilege(r, fn, 'EXECUTE') THEN
        RAISE EXCEPTION 'feed: % may call %', r, fn;
      END IF;
    END LOOP;
  END LOOP;

  IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = '"CalendarFeeds"'::regclass) THEN
    RAISE EXCEPTION 'feed: CalendarFeeds has no row security';
  END IF;
  IF (SELECT array_agg(p.polname::text || ':' || p.polcmd::text || ':' || r.rolname::text ORDER BY p.polname, r.rolname)
        FROM pg_policy p, unnest(p.polroles) AS pr(oid) JOIN pg_roles r ON r.oid = pr.oid
       WHERE p.polrelid = '"CalendarFeeds"'::regclass) IS DISTINCT FROM ARRAY['calendar_feeds_owner_select:r:app_authenticated'] THEN
    RAISE EXCEPTION 'feed: CalendarFeeds'' arms are %', (SELECT array_agg(polname) FROM pg_policy WHERE polrelid = '"CalendarFeeds"'::regclass);
  END IF;
  IF NOT has_table_privilege('app_authenticated', '"CalendarFeeds"', 'SELECT') THEN RAISE EXCEPTION 'feed: the API may not read its feeds'; END IF;
  FOREACH priv IN ARRAY ARRAY['INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
    IF has_table_privilege('app_authenticated', '"CalendarFeeds"', priv) THEN RAISE EXCEPTION 'feed: the API holds % on CalendarFeeds', priv; END IF;
  END LOOP;
  FOREACH r IN ARRAY ARRAY['authenticated', 'anon'] LOOP
    FOREACH priv IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE'] LOOP
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) AND has_table_privilege(r, '"CalendarFeeds"', priv) THEN
        RAISE EXCEPTION 'feed: % holds % on CalendarFeeds', r, priv;
      END IF;
    END LOOP;
  END LOOP;

  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = '"PublicationSettings"'::regclass
                    AND tgname = 'PublicationSettings_calendar_feeds_follow' AND tgenabled = 'O') THEN
    RAISE EXCEPTION 'feed: the settings do not take their feeds with them';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = '"Users"'::regclass
                    AND tgname = 'Users_calendar_feeds_follow' AND tgenabled = 'O')
     OR NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = '"GuardianStudents"'::regclass
                    AND tgname = 'GuardianStudents_calendar_feeds_follow' AND tgenabled = 'O') THEN
    RAISE EXCEPTION 'feed: a person or a link does not take their feeds with them';
  END IF;
  IF NOT coalesce((SELECT i.indisunique
                          AND pg_get_indexdef(i.indexrelid) LIKE '%("userId", COALESCE("studentId", "userId"))%'
                          AND pg_get_expr(i.indpred, i.indrelid) = '("revokedAt" IS NULL)'
                     FROM pg_index i WHERE i.indexrelid = '"CalendarFeeds_one_live_feed_per_week"'::regclass), false) THEN
    RAISE EXCEPTION 'feed: one live feed per week is not a unique index of the live feeds';
  END IF;
  FOREACH fn IN ARRAY ARRAY['app.family_lesson_staff(uuid[])', 'app.calendar_feed_pupil_lessons(uuid, uuid, date, date, text, "TeacherDisplay")'] LOOP
    IF (SELECT prosrc FROM pg_proc WHERE oid = fn::regprocedure) NOT LIKE '%app.family_lesson_labels(%' THEN
      RAISE EXCEPTION 'feed: % names teachers without the family''s rule', fn;
    END IF;
  END LOOP;
  FOREACH c IN ARRAY ARRAY['CalendarFeeds_token_is_a_sha256', 'CalendarFeeds_locale_is_known', 'CalendarFeeds_whose_week',
                           'CalendarFeeds_only_a_guardian_is_recorded'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = '"CalendarFeeds"'::regclass AND conname = c AND convalidated) THEN
      RAISE EXCEPTION 'feed: % is not in place', c;
    END IF;
  END LOOP;
  IF NOT EXISTS (SELECT 1 FROM pg_enum e JOIN pg_type t ON t.oid = e.enumtypid
                  WHERE t.typname = 'PersonalDataAccessChannel' AND e.enumlabel = 'CALENDAR') THEN
    RAISE EXCEPTION 'feed: the read log has no CALENDAR way';
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Section 146: vem som gör en prenumeration (app.calendar_feed_create,
-- _revoke, _counts, _audience_on).
--
-- In the ledighet school, with every audience off nobody makes a feed and
-- nobody's audience is on; with only the teachers' on, a pupil's and a
-- guardian's are still off. With them on: the admin and a teacher make their
-- own week's, a pupil theirs, the guardian each of their children's — and
-- nobody anything else (a teacher a pupil's, a pupil another's, the guardian
-- none of their own or a stranger's, even one another guardian has); a
-- deactivated teacher makes nothing. A second feed
-- of a week revokes the first. Each person reads and revokes their own
-- feeds only; the admin counts the school's live feeds per audience and
-- nobody else does. An address that is no sha256 is refused by the CHECK.
-- PostgREST's role neither calls the functions nor reads the table, and the
-- API's role writes nothing past them.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000950')::text, true);
CREATE FUNCTION pg_temp.rls146_as(sub text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', sub)::text, true);
END $$;
DO $$
DECLARE
  school uuid := app.current_school_id();
  ella uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000956');
  gustav uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000957');
  frida uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000958');
  r jsonb; first_ella uuid; ellas_own uuid; n integer;
BEGIN
  INSERT INTO "PublicationSettings" ("schoolId") VALUES (school) ON CONFLICT ("schoolId") DO NOTHING;
  r := app.calendar_feed_create(NULL, repeat('1', 64), 'sv');
  IF r ->> 'refused' IS DISTINCT FROM 'AUDIENCE_OFF' THEN RAISE EXCEPTION 'feed: the admin made a feed with every audience off: %', r; END IF;
  IF app.calendar_feed_audience_on() THEN RAISE EXCEPTION 'feed: the admin''s audience reads as on'; END IF;
  -- The teachers' on, and only theirs: a pupil's and a guardian's stay off.
  UPDATE "PublicationSettings" SET "calendarFeedTeachers" = true WHERE "schoolId" = school;
  PERFORM pg_temp.rls146_as('00000000-0000-4000-8000-000000000956');
  IF app.calendar_feed_audience_on() OR app.calendar_feed_create(NULL, repeat('1', 64), 'sv') ->> 'refused' IS DISTINCT FROM 'AUDIENCE_OFF' THEN
    RAISE EXCEPTION 'feed: a pupil''s audience is on with only the teachers''';
  END IF;
  PERFORM pg_temp.rls146_as('00000000-0000-4000-8000-000000000955');
  IF app.calendar_feed_audience_on() OR app.calendar_feed_create(ella, repeat('1', 64), 'sv') ->> 'refused' IS DISTINCT FROM 'AUDIENCE_OFF' THEN
    RAISE EXCEPTION 'feed: a guardian''s audience is on with only the teachers''';
  END IF;
  PERFORM pg_temp.rls146_as('00000000-0000-4000-8000-000000000950');
  UPDATE "PublicationSettings" SET "calendarFeedTeachers" = true, "calendarFeedStudents" = true, "calendarFeedGuardians" = true
   WHERE "schoolId" = school;
  -- Gustav has a guardian, though not this one.
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "isActive", "updatedAt")
  VALUES (school, 'rls146-otto@example.invalid', 'Otto', 'Vårdnadshavare', 'GUARDIAN', '00000000-0000-4000-8000-000000001461', true, now());
  INSERT INTO "GuardianStudents" ("schoolId", "guardianId", "studentId")
  SELECT school, id, gustav FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000001461';

  -- The admin: their own week, as a teacher's, and no pupil's.
  IF NOT app.calendar_feed_audience_on() THEN RAISE EXCEPTION 'feed: the admin''s audience reads as off'; END IF;
  r := app.calendar_feed_create(NULL, repeat('1', 64), 'sv');
  IF r #>> '{feed,audience}' IS DISTINCT FROM 'TEACHER' OR r #>> '{feed,studentId}' IS NOT NULL THEN RAISE EXCEPTION 'feed: the admin made %', r; END IF;
  IF app.calendar_feed_create(ella, repeat('2', 64), 'sv') ->> 'refused' IS DISTINCT FROM 'NOT_YOURS' THEN
    RAISE EXCEPTION 'feed: the admin made a pupil''s feed';
  END IF;

  -- A teacher: their own, in English when asked, and no pupil's.
  PERFORM pg_temp.rls146_as('00000000-0000-4000-8000-000000000951');
  r := app.calendar_feed_create(NULL, repeat('3', 64), 'en');
  IF r #>> '{feed,audience}' IS DISTINCT FROM 'TEACHER' OR r #>> '{feed,locale}' IS DISTINCT FROM 'en' THEN RAISE EXCEPTION 'feed: the teacher made %', r; END IF;
  IF app.calendar_feed_create(ella, repeat('4', 64), 'sv') ->> 'refused' IS DISTINCT FROM 'NOT_YOURS' THEN
    RAISE EXCEPTION 'feed: a teacher made a pupil''s feed';
  END IF;

  -- A pupil: their own (asked by none or by their own id), and nobody else's.
  PERFORM pg_temp.rls146_as('00000000-0000-4000-8000-000000000956');
  r := app.calendar_feed_create(NULL, repeat('5', 64), 'de');
  IF r #>> '{feed,audience}' IS DISTINCT FROM 'STUDENT' OR r #>> '{feed,studentId}' IS DISTINCT FROM ella::text
     OR r #>> '{feed,locale}' IS DISTINCT FROM 'sv' THEN
    RAISE EXCEPTION 'feed: the pupil made %', r;
  END IF;
  ellas_own := (r #>> '{feed,id}')::uuid;
  IF app.calendar_feed_create(gustav, repeat('6', 64), 'sv') ->> 'refused' IS DISTINCT FROM 'NOT_YOURS' THEN
    RAISE EXCEPTION 'feed: a pupil made another pupil''s feed';
  END IF;

  -- The guardian: each child's, and no stranger's and no week of their own.
  PERFORM pg_temp.rls146_as('00000000-0000-4000-8000-000000000955');
  r := app.calendar_feed_create(ella, repeat('7', 64), 'sv');
  IF r #>> '{feed,audience}' IS DISTINCT FROM 'GUARDIAN' OR r #>> '{feed,studentId}' IS DISTINCT FROM ella::text THEN
    RAISE EXCEPTION 'feed: the guardian made %', r;
  END IF;
  first_ella := (r #>> '{feed,id}')::uuid;
  IF app.calendar_feed_create(frida, repeat('8', 64), 'sv') ? 'refused' THEN RAISE EXCEPTION 'feed: the guardian made no feed of Frida'; END IF;
  IF app.calendar_feed_create(gustav, repeat('9', 64), 'sv') ->> 'refused' IS DISTINCT FROM 'NOT_YOURS'
     OR app.calendar_feed_create(NULL, repeat('9', 64), 'sv') ->> 'refused' IS DISTINCT FROM 'NOT_YOURS' THEN
    RAISE EXCEPTION 'feed: the guardian made a stranger''s feed, or one of their own';
  END IF;
  -- A second of Ella's revokes the first: one live feed per week.
  r := app.calendar_feed_create(ella, repeat('a', 64), 'sv');
  IF (SELECT "revokedAt" FROM "CalendarFeeds" WHERE id = first_ella) IS NULL THEN RAISE EXCEPTION 'feed: the first feed of Ella lives on'; END IF;
  SELECT count(*) INTO n FROM "CalendarFeeds" WHERE "revokedAt" IS NULL;
  IF n <> 2 THEN RAISE EXCEPTION 'feed: the guardian has % live feeds (Ella''s new one, Frida''s)', n; END IF;
  -- Their own rows only: Ella's own feed is not theirs to read or revoke.
  IF EXISTS (SELECT 1 FROM "CalendarFeeds" WHERE id = ellas_own) OR (SELECT count(*) FROM "CalendarFeeds") <> 3 THEN
    RAISE EXCEPTION 'feed: the guardian reads feeds that are not theirs';
  END IF;
  IF app.calendar_feed_revoke(ellas_own) THEN RAISE EXCEPTION 'feed: the guardian revoked the pupil''s own feed'; END IF;
  IF NOT app.calendar_feed_revoke((r #>> '{feed,id}')::uuid) THEN RAISE EXCEPTION 'feed: the guardian could not revoke their own'; END IF;
  IF app.calendar_feed_revoke((r #>> '{feed,id}')::uuid) THEN RAISE EXCEPTION 'feed: a revoked feed was revoked again'; END IF;
  IF EXISTS (SELECT 1 FROM app.calendar_feed_counts()) THEN RAISE EXCEPTION 'feed: a guardian counts the school''s feeds'; END IF;
  BEGIN
    PERFORM app.calendar_feed_create(frida, 'not a hash', 'sv');
    RAISE EXCEPTION 'feed: an address that is no sha256 was stored';
  EXCEPTION WHEN check_violation THEN NULL;
  END;

  -- Erik has left: no principal, no feed.
  PERFORM pg_temp.rls146_as('00000000-0000-4000-8000-000000000959');
  IF app.calendar_feed_create(NULL, repeat('b', 64), 'sv') ->> 'refused' IS DISTINCT FROM 'NO_PRINCIPAL' THEN
    RAISE EXCEPTION 'feed: a deactivated teacher made a feed';
  END IF;

  -- The admin counts: two teachers' weeks, one pupil's, one child's (Frida's).
  PERFORM pg_temp.rls146_as('00000000-0000-4000-8000-000000000950');
  IF (SELECT string_agg(audience::text || '=' || live, ',' ORDER BY audience) FROM app.calendar_feed_counts())
     IS DISTINCT FROM 'TEACHER=2,STUDENT=1,GUARDIAN=1' THEN
    RAISE EXCEPTION 'feed: the admin counts %', (SELECT string_agg(audience::text || '=' || live, ',') FROM app.calendar_feed_counts());
  END IF;
  BEGIN
    INSERT INTO "CalendarFeeds" ("schoolId", "userId", audience, "tokenHash") SELECT school, id, 'TEACHER', repeat('c', 64)
      FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000950';
    RAISE EXCEPTION 'feed: the API wrote a feed past the functions';
  EXCEPTION WHEN insufficient_privilege THEN
    -- The grant's refusal, not a policy's (which is the same SQLSTATE).
    IF SQLERRM NOT LIKE 'permission denied%' THEN RAISE; END IF;
  END;
END $$;
SET LOCAL ROLE authenticated;
DO $$
BEGIN
  BEGIN
    PERFORM count(*) FROM "CalendarFeeds";
    RAISE EXCEPTION 'feed: PostgREST''s role reads the feeds';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    PERFORM app.calendar_feed_create(NULL, repeat('d', 64), 'sv');
    RAISE EXCEPTION 'feed: PostgREST''s role makes feeds';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
END $$;
SET LOCAL ROLE app_authenticated;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 147: skolan stänger av, och en prenumeration slutar med det den
-- gjordes för (the settings', the people's and the links' triggers).
--
-- Switching an audience off revokes that audience's live feeds and no
-- other's, in the same statement; switching it on again revives none. A
-- revoked feed answers nothing at the door. The school's settings row
-- deleted revokes all of its feeds. A teacher made admin keeps their feed,
-- one made a guardian loses it; a guardian's link to one child deleted ends
-- that child's feed and not the other's; a pupil deactivated ends their own
-- feed and every guardian's of them, and reactivated revives neither.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000950')::text, true);
CREATE FUNCTION pg_temp.rls147_as(sub text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', sub)::text, true);
END $$;
CREATE FUNCTION pg_temp.rls147_live() RETURNS text LANGUAGE plpgsql AS $$
DECLARE claims text := current_setting('request.jwt.claims', true); got text;
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000950')::text, true);
  SELECT string_agg(audience::text || '=' || live, ',' ORDER BY audience) INTO got FROM app.calendar_feed_counts();
  PERFORM set_config('request.jwt.claims', coalesce(claims, ''), true);
  RETURN coalesce(got, '');
END $$;
DO $$
DECLARE
  school uuid := app.current_school_id();
  ella uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000956');
BEGIN
  INSERT INTO "PublicationSettings" ("schoolId") VALUES (school) ON CONFLICT ("schoolId") DO NOTHING;
  UPDATE "PublicationSettings" SET "calendarFeedTeachers" = true, "calendarFeedStudents" = true, "calendarFeedGuardians" = true
   WHERE "schoolId" = school;
  PERFORM pg_temp.rls147_as('00000000-0000-4000-8000-000000000951');
  PERFORM app.calendar_feed_create(NULL, repeat('1', 64), 'sv');
  PERFORM pg_temp.rls147_as('00000000-0000-4000-8000-000000000956');
  PERFORM app.calendar_feed_create(NULL, repeat('2', 64), 'sv');
  PERFORM pg_temp.rls147_as('00000000-0000-4000-8000-000000000955');
  PERFORM app.calendar_feed_create(ella, repeat('3', 64), 'sv');
  IF pg_temp.rls147_live() IS DISTINCT FROM 'TEACHER=1,STUDENT=1,GUARDIAN=1' THEN RAISE EXCEPTION 'feed: live before: %', pg_temp.rls147_live(); END IF;

  PERFORM pg_temp.rls147_as('00000000-0000-4000-8000-000000000950');
  UPDATE "PublicationSettings" SET "calendarFeedStudents" = false WHERE "schoolId" = school;
  IF pg_temp.rls147_live() IS DISTINCT FROM 'TEACHER=1,GUARDIAN=1' THEN RAISE EXCEPTION 'feed: pupils off leaves %', pg_temp.rls147_live(); END IF;
  UPDATE "PublicationSettings" SET "calendarFeedTeachers" = false WHERE "schoolId" = school;
  IF pg_temp.rls147_live() IS DISTINCT FROM 'GUARDIAN=1' THEN RAISE EXCEPTION 'feed: teachers off leaves %', pg_temp.rls147_live(); END IF;
  -- On again: the revoked stay revoked, and their addresses answer nothing.
  UPDATE "PublicationSettings" SET "calendarFeedTeachers" = true, "calendarFeedStudents" = true WHERE "schoolId" = school;
  IF pg_temp.rls147_live() IS DISTINCT FROM 'GUARDIAN=1' THEN RAISE EXCEPTION 'feed: switching on revived %', pg_temp.rls147_live(); END IF;
  PERFORM set_config('request.jwt.claims', '', true);
  IF app.calendar_feed(repeat('1', 64)) IS NOT NULL OR app.calendar_feed(repeat('2', 64)) IS NOT NULL THEN
    RAISE EXCEPTION 'feed: a feed revoked by its audience answers';
  END IF;
  IF app.calendar_feed(repeat('3', 64)) IS NULL THEN RAISE EXCEPTION 'feed: the guardian''s feed stopped with the others'; END IF;
  PERFORM pg_temp.rls147_as('00000000-0000-4000-8000-000000000950');
  UPDATE "PublicationSettings" SET "calendarFeedGuardians" = false WHERE "schoolId" = school;
  PERFORM set_config('request.jwt.claims', '', true);
  IF app.calendar_feed(repeat('3', 64)) IS NOT NULL THEN RAISE EXCEPTION 'feed: the guardian''s feed answers with guardians off'; END IF;

  -- The settings row deleted: every feed of the school, whatever its audience.
  PERFORM pg_temp.rls147_as('00000000-0000-4000-8000-000000000950');
  UPDATE "PublicationSettings" SET "calendarFeedTeachers" = true, "calendarFeedStudents" = true, "calendarFeedGuardians" = true
   WHERE "schoolId" = school;
  PERFORM pg_temp.rls147_as('00000000-0000-4000-8000-000000000951');
  PERFORM app.calendar_feed_create(NULL, repeat('4', 64), 'sv');
  PERFORM pg_temp.rls147_as('00000000-0000-4000-8000-000000000955');
  PERFORM app.calendar_feed_create(ella, repeat('5', 64), 'sv');
  IF pg_temp.rls147_live() IS DISTINCT FROM 'TEACHER=1,GUARDIAN=1' THEN RAISE EXCEPTION 'feed: live before the delete: %', pg_temp.rls147_live(); END IF;
  PERFORM pg_temp.rls147_as('00000000-0000-4000-8000-000000000950');
  DELETE FROM "PublicationSettings" WHERE "schoolId" = school;
  IF pg_temp.rls147_live() IS DISTINCT FROM '' THEN RAISE EXCEPTION 'feed: the deleted settings leave %', pg_temp.rls147_live(); END IF;
END $$;
ROLLBACK;

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000950')::text, true);
CREATE FUNCTION pg_temp.rls147_as(sub text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', sub)::text, true);
END $$;
-- The door as a calendar asks it: no principal, the claims put back after.
CREATE FUNCTION pg_temp.rls147_answers(hash text) RETURNS boolean LANGUAGE plpgsql AS $$
DECLARE claims text := current_setting('request.jwt.claims', true); got jsonb;
BEGIN
  PERFORM set_config('request.jwt.claims', '', true);
  got := app.calendar_feed(hash);
  PERFORM set_config('request.jwt.claims', coalesce(claims, ''), true);
  RETURN got IS NOT NULL;
END $$;
DO $$
DECLARE
  school uuid := app.current_school_id();
  ella uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000956');
  frida uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000958');
  guardian uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000955');
  hash text;
BEGIN
  INSERT INTO "PublicationSettings" ("schoolId") VALUES (school) ON CONFLICT ("schoolId") DO NOTHING;
  UPDATE "PublicationSettings" SET "calendarFeedTeachers" = true, "calendarFeedStudents" = true, "calendarFeedGuardians" = true
   WHERE "schoolId" = school;
  -- Anna's (1), Bertil's (2), Ella's own (3), the guardian's of Ella (4) and of Frida (5).
  PERFORM pg_temp.rls147_as('00000000-0000-4000-8000-000000000951');
  PERFORM app.calendar_feed_create(NULL, repeat('1', 64), 'sv');
  PERFORM pg_temp.rls147_as('00000000-0000-4000-8000-000000000952');
  PERFORM app.calendar_feed_create(NULL, repeat('2', 64), 'sv');
  PERFORM pg_temp.rls147_as('00000000-0000-4000-8000-000000000956');
  PERFORM app.calendar_feed_create(NULL, repeat('3', 64), 'sv');
  PERFORM pg_temp.rls147_as('00000000-0000-4000-8000-000000000955');
  PERFORM app.calendar_feed_create(ella, repeat('4', 64), 'sv');
  PERFORM app.calendar_feed_create(frida, repeat('5', 64), 'sv');
  PERFORM pg_temp.rls147_as('00000000-0000-4000-8000-000000000950');
  FOREACH hash IN ARRAY ARRAY['1', '2', '3', '4', '5'] LOOP
    IF NOT pg_temp.rls147_answers(repeat(hash, 64)) THEN RAISE EXCEPTION 'feed: feed % answers nothing before the people change', hash; END IF;
  END LOOP;

  -- Each change, and then its undoing: an address the change ended stays
  -- ended, which only a revocation makes so (the door alone would answer
  -- again once the person is what the feed was made for).
  -- Anna made admin: still a teacher's week.
  UPDATE "Users" SET role = 'SCHOOL_ADMIN' WHERE "authId" = '00000000-0000-4000-8000-000000000951';
  IF NOT pg_temp.rls147_answers(repeat('1', 64)) THEN RAISE EXCEPTION 'feed: a teacher made admin lost their feed'; END IF;
  -- Bertil made a guardian, and a teacher again.
  UPDATE "Users" SET role = 'GUARDIAN' WHERE "authId" = '00000000-0000-4000-8000-000000000952';
  UPDATE "Users" SET role = 'TEACHER' WHERE "authId" = '00000000-0000-4000-8000-000000000952';
  IF pg_temp.rls147_answers(repeat('2', 64)) THEN RAISE EXCEPTION 'feed: a teacher''s feed outlived their being a guardian'; END IF;
  -- The guardian's link to Frida deleted, and made again: Frida's feed ends, Ella's does not.
  DELETE FROM "GuardianStudents" WHERE "guardianId" = guardian AND "studentId" = frida;
  INSERT INTO "GuardianStudents" ("schoolId", "guardianId", "studentId") VALUES (school, guardian, frida);
  IF pg_temp.rls147_answers(repeat('5', 64)) THEN RAISE EXCEPTION 'feed: a guardian''s feed outlived the link to the child'; END IF;
  IF NOT pg_temp.rls147_answers(repeat('4', 64)) THEN RAISE EXCEPTION 'feed: one child''s link took the other child''s feed'; END IF;
  -- Ella deactivated, and back: her own and her guardian's feed end, and stay ended.
  UPDATE "Users" SET "isActive" = false WHERE id = ella;
  UPDATE "Users" SET "isActive" = true WHERE id = ella;
  IF pg_temp.rls147_answers(repeat('3', 64)) OR pg_temp.rls147_answers(repeat('4', 64)) THEN
    RAISE EXCEPTION 'feed: a pupil''s week outlived their leaving';
  END IF;
  IF (SELECT string_agg(audience::text || '=' || live, ',' ORDER BY audience) FROM app.calendar_feed_counts()) IS DISTINCT FROM 'TEACHER=1' THEN
    RAISE EXCEPTION 'feed: after the people changed the admin counts %',
      (SELECT string_agg(audience::text || '=' || live, ',' ORDER BY audience) FROM app.calendar_feed_counts());
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 148: vad en prenumeration visar (app.calendar_feed).
--
-- The ledighet school's week from tomorrow (the school's), published: a 9A lesson Anna
-- leads with Bertil, David (protected) and Erik (who left) beside her, Tyska 9
-- its extra group; Ella's Spanska group's
-- lessons (Cecilia's; one cancelled, one Bertil covers); a lesson Ella and
-- Gustav are named on; Frida's Tyska; Spanska last Monday, the day before
-- it, and a year and a day ahead; a studiedag for all, prao for åk 9, a day
-- for åk 8 and one for åk 10–12. Asked with no principal, as a calendar asks:
--
--   * Anna's feed is the lessons she is on, the 9A lesson with its groups,
--     room and Bertil (never David, never Erik), the named lesson naming no
--     pupil, and the whole school's studiedag; Bertil's marks the lesson he
--     covers; each lesson's version is its row's updatedAt (a fixed day
--     long ago, so the clock cannot pass for it), and the feed's scope (the
--     entries' UIDs) Anna's own id;
--   * Ella's own feed and her guardian's are her Spanska lessons from last
--     Monday on (Cecilia named as the school names teachers; the cancelled
--     and the covered ones naming nobody, the covered one marked) and the
--     named lesson; not 9A's (her class history names 9A from 2095 on), not
--     Frida's Tyska, nothing outside the window; the studiedag and her
--     year's prao, not åk 8's day nor åk 10–12's. Both feeds' scope is
--     Ella. No other pupil's name anywhere. By signature, Cecilia is her
--     signature; naming nobody, nobody;
--   * the guardian's feed is written once a school day to the read log, as
--     a read of Ella's schedule by the guardian through the calendar; a
--     teacher's and a pupil's are not; the feed is marked used; and the
--     guardian opening Ella's week in the app after it is still written;
--   * a guardian's feed of a child with no lesson in the window (Tom, in no
--     class) answers an empty week and writes no read-log row;
--   * nothing answers for a revoked feed, an unknown address, a teacher
--     deactivated, a guardian no longer the child's, a child deactivated;
--     and PostgREST's role cannot ask. (That the door ends a live feed it
--     refuses needs the triggers off: the adapter probe, kf-f.)
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000950')::text, true);
CREATE FUNCTION pg_temp.rls148_as(sub text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', sub)::text, true);
END $$;
-- The school's day, which the door counts from (not the server's, which is
-- UTC: around midnight they are two days).
CREATE FUNCTION pg_temp.rls148_today() RETURNS date LANGUAGE sql AS $$ SELECT (now() AT TIME ZONE 'Europe/Stockholm')::date $$;
-- The door as a calendar asks it: no principal, the claims put back after.
CREATE FUNCTION pg_temp.rls148_feed(hash text) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE claims text := current_setting('request.jwt.claims', true); got jsonb;
BEGIN
  PERFORM set_config('request.jwt.claims', '', true);
  got := app.calendar_feed(hash);
  PERFORM set_config('request.jwt.claims', coalesce(claims, ''), true);
  RETURN got;
END $$;
-- "subject@offset" per lesson, in the feed's order, offset in days from tomorrow.
CREATE FUNCTION pg_temp.rls148_lessons(doc jsonb) RETURNS text LANGUAGE sql AS $$
  SELECT string_agg((l ->> 'subject') || '@' || ((l ->> 'date')::date - (pg_temp.rls148_today() + 1)), ',' ORDER BY l ->> 'start', l ->> 'id')
    FROM jsonb_array_elements(doc -> 'lessons') l
$$;
CREATE FUNCTION pg_temp.rls148_lesson(doc jsonb, subject text, offset_days integer) RETURNS jsonb LANGUAGE sql AS $$
  SELECT l FROM jsonb_array_elements(doc -> 'lessons') l
   WHERE l ->> 'subject' = subject AND (l ->> 'date')::date = pg_temp.rls148_today() + 1 + offset_days
$$;
CREATE FUNCTION pg_temp.rls148_breaks(doc jsonb) RETURNS text LANGUAGE sql AS $$
  SELECT string_agg(b ->> 'name', ',' ORDER BY b ->> 'from') FROM jsonb_array_elements(doc -> 'breaks') b
$$;

DO $$
DECLARE
  school uuid := app.current_school_id();
  y uuid := (SELECT id FROM "AcademicYears" WHERE "schoolId" = app.current_school_id() ORDER BY "startDate" LIMIT 1);
  d0 date := pg_temp.rls148_today() + 1;
  monday date := (pg_temp.rls148_today() - 7) - (extract(isodow FROM pg_temp.rls148_today() - 7)::int - 1);
  g9a uuid := (SELECT id FROM "StudentGroups" WHERE "schoolId" = app.current_school_id() AND name = '9A');
  g9b uuid := (SELECT id FROM "StudentGroups" WHERE "schoolId" = app.current_school_id() AND name = '9B');
  anna uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000951');
  bertil uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000952');
  cecilia uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000953');
  david uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000954');
  ella uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000956');
  gustav uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000957');
  frida uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000958');
  room uuid; spanska uuid; tyska uuid; s_hem uuid; s_sp uuid; s_namn uuid; s_ty uuid; lesson uuid;
BEGIN
  INSERT INTO "PublicationSettings" ("schoolId") VALUES (school) ON CONFLICT ("schoolId") DO NOTHING;
  UPDATE "PublicationSettings" SET "calendarFeedTeachers" = true, "calendarFeedStudents" = true, "calendarFeedGuardians" = true,
         "publicTeacherDisplay" = 'NAME' WHERE "schoolId" = school;
  INSERT INTO "TeacherPublicLabels" ("userId", "schoolId", hidden) VALUES (david, school, true);
  INSERT INTO "Rooms" ("schoolId", name, "updatedAt") VALUES (school, 'rls148 Sal', now()) RETURNING id INTO room;
  INSERT INTO "Subjects" ("schoolId", name, "updatedAt") VALUES (school, 'rls148 Hem', now()) RETURNING id INTO s_hem;
  INSERT INTO "Subjects" ("schoolId", name, "updatedAt") VALUES (school, 'rls148 Spanska', now()) RETURNING id INTO s_sp;
  INSERT INTO "Subjects" ("schoolId", name, "updatedAt") VALUES (school, 'rls148 Namn', now()) RETURNING id INTO s_namn;
  INSERT INTO "Subjects" ("schoolId", name, "updatedAt") VALUES (school, 'rls148 Tyska', now()) RETURNING id INTO s_ty;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "updatedAt") VALUES (school, y, 'rls148 Spanska 9', 'TEACHING_GROUP', now())
  RETURNING id INTO spanska;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "updatedAt") VALUES (school, y, 'rls148 Tyska 9', 'TEACHING_GROUP', now())
  RETURNING id INTO tyska;
  INSERT INTO "StudentGroupMembers" ("schoolId", "studentGroupId", "studentId") VALUES (school, spanska, ella), (school, tyska, frida);

  -- 9A, Anna leading, Bertil and David beside her.
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", "roomId", date, "startsAt", "endsAt", "updatedAt")
  -- Changed long ago: its version is that moment, not the time of the ask.
  VALUES (school, s_hem, g9a, room, d0, (d0 + time '08:00') AT TIME ZONE 'Europe/Stockholm', (d0 + time '09:00') AT TIME ZONE 'Europe/Stockholm',
          timestamptz '2026-01-02 03:04:05+00')
  RETURNING id INTO lesson;
  INSERT INTO "CalendarLessonTeachers" ("schoolId", "calendarLessonId", "teacherId", role)
  VALUES (school, lesson, anna, 'LEAD'), (school, lesson, bertil, 'ASSISTANT'), (school, lesson, david, 'ASSISTANT'),
         (school, lesson, (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000959'), 'ASSISTANT');
  INSERT INTO "CalendarLessonGroups" ("schoolId", "calendarLessonId", "studentGroupId") VALUES (school, lesson, tyska);
  -- Spanska: held, cancelled, covered; and last Monday, the day before it, a year and a day on.
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", "updatedAt")
  VALUES (school, s_sp, spanska, d0, (d0 + time '10:00') AT TIME ZONE 'Europe/Stockholm', (d0 + time '11:00') AT TIME ZONE 'Europe/Stockholm',
          timestamptz '2026-01-02 03:04:05+00')
  RETURNING id INTO lesson;
  INSERT INTO "CalendarLessonTeachers" ("schoolId", "calendarLessonId", "teacherId", role) VALUES (school, lesson, cecilia, 'LEAD');
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", status, "updatedAt")
  VALUES (school, s_sp, spanska, d0 + 1, (d0 + 1 + time '10:00') AT TIME ZONE 'Europe/Stockholm', (d0 + 1 + time '11:00') AT TIME ZONE 'Europe/Stockholm', 'CANCELLED', now())
  RETURNING id INTO lesson;
  INSERT INTO "CalendarLessonTeachers" ("schoolId", "calendarLessonId", "teacherId", role) VALUES (school, lesson, cecilia, 'LEAD');
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", "updatedAt")
  VALUES (school, s_sp, spanska, d0 + 2, (d0 + 2 + time '10:00') AT TIME ZONE 'Europe/Stockholm', (d0 + 2 + time '11:00') AT TIME ZONE 'Europe/Stockholm', now())
  RETURNING id INTO lesson;
  INSERT INTO "CalendarLessonTeachers" ("schoolId", "calendarLessonId", "teacherId", role) VALUES (school, lesson, bertil, 'SUBSTITUTE');
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", "updatedAt")
  VALUES (school, s_sp, spanska, monday, (monday + time '09:00') AT TIME ZONE 'Europe/Stockholm', (monday + time '10:00') AT TIME ZONE 'Europe/Stockholm', now()),
         (school, s_sp, spanska, monday - 1, (monday - 1 + time '09:00') AT TIME ZONE 'Europe/Stockholm', (monday - 1 + time '10:00') AT TIME ZONE 'Europe/Stockholm', now()),
         (school, s_sp, spanska, pg_temp.rls148_today() + 366, (pg_temp.rls148_today() + 366 + time '09:00') AT TIME ZONE 'Europe/Stockholm',
          (pg_temp.rls148_today() + 366 + time '10:00') AT TIME ZONE 'Europe/Stockholm', now());
  -- Named: Ella and Gustav, Anna leading.
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", "updatedAt")
  VALUES (school, s_namn, g9b, d0, (d0 + time '13:00') AT TIME ZONE 'Europe/Stockholm', (d0 + time '14:00') AT TIME ZONE 'Europe/Stockholm', now())
  RETURNING id INTO lesson;
  INSERT INTO "CalendarLessonTeachers" ("schoolId", "calendarLessonId", "teacherId", role) VALUES (school, lesson, anna, 'LEAD');
  INSERT INTO "CalendarLessonStudents" ("schoolId", "calendarLessonId", "studentId") VALUES (school, lesson, ella), (school, lesson, gustav);
  -- Frida's Tyska.
  INSERT INTO "CalendarLessons" ("schoolId", "subjectId", "studentGroupId", date, "startsAt", "endsAt", "updatedAt")
  VALUES (school, s_ty, tyska, d0, (d0 + time '11:00') AT TIME ZONE 'Europe/Stockholm', (d0 + time '12:00') AT TIME ZONE 'Europe/Stockholm', now())
  RETURNING id INTO lesson;
  INSERT INTO "CalendarLessonTeachers" ("schoolId", "calendarLessonId", "teacherId", role) VALUES (school, lesson, cecilia, 'LEAD');
  -- The days off.
  INSERT INTO "SchoolBreaks" ("schoolId", "academicYearId", name, kind, "startDate", "endDate", "updatedAt")
  VALUES (school, y, 'rls148 Studiedag', 'STAFF_DAY', d0 + 3, d0 + 3, now());
  INSERT INTO "SchoolBreaks" ("schoolId", "academicYearId", name, "startDate", "endDate", "minGradeLevel", "maxGradeLevel", "updatedAt")
  VALUES (school, y, 'rls148 Prao', d0 + 4, d0 + 5, 9, 9, now()), (school, y, 'rls148 Åk 8', d0 + 6, d0 + 6, 8, 8, now()),
         (school, y, 'rls148 Gymnasiet', d0 + 6, d0 + 6, 10, 12, now());

  -- The feeds: Anna's (b), Bertil's (c), Ella's own (d), the guardian's of Ella (e) and of Frida (f).
  PERFORM pg_temp.rls148_as('00000000-0000-4000-8000-000000000951');
  PERFORM app.calendar_feed_create(NULL, repeat('b', 64), 'sv');
  PERFORM pg_temp.rls148_as('00000000-0000-4000-8000-000000000952');
  PERFORM app.calendar_feed_create(NULL, repeat('c', 64), 'sv');
  PERFORM pg_temp.rls148_as('00000000-0000-4000-8000-000000000956');
  PERFORM app.calendar_feed_create(NULL, repeat('d', 64), 'sv');
  PERFORM pg_temp.rls148_as('00000000-0000-4000-8000-000000000955');
  PERFORM app.calendar_feed_create(ella, repeat('e', 64), 'sv');
  PERFORM app.calendar_feed_create(frida, repeat('f', 64), 'sv');
  PERFORM pg_temp.rls148_as('00000000-0000-4000-8000-000000000950');
  -- Tom, the guardian's third child, in no class and no group: no lesson to show.
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "isActive", "updatedAt")
  VALUES (school, 'rls148-tom@example.invalid', 'Tom', 'Elev', 'STUDENT', '00000000-0000-4000-8000-000000001481', true, now());
  INSERT INTO "GuardianStudents" ("schoolId", "guardianId", "studentId")
  SELECT school, g.id, t.id FROM "Users" g, "Users" t
   WHERE g."authId" = '00000000-0000-4000-8000-000000000955' AND t."authId" = '00000000-0000-4000-8000-000000001481';
  PERFORM pg_temp.rls148_as('00000000-0000-4000-8000-000000000955');
  PERFORM app.calendar_feed_create((SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000001481'), repeat('a', 64), 'sv');
  PERFORM pg_temp.rls148_as('00000000-0000-4000-8000-000000000950');
  PERFORM set_config('app.test_rls148_ella', ella::text, true);
  PERFORM set_config('app.test_rls148_cecilia', cecilia::text, true);
  PERFORM set_config('app.test_rls148_year', y::text, true);
END $$;

DO $$
DECLARE doc jsonb; one jsonb; got text; ella uuid := current_setting('app.test_rls148_ella')::uuid; guardian uuid;
BEGIN
  -- Anna: the lessons she is on, her colleague named and David not, no pupil anywhere, the whole school's day.
  doc := pg_temp.rls148_feed(repeat('b', 64));
  IF doc ->> 'audience' IS DISTINCT FROM 'TEACHER' OR doc ->> 'title' IS DISTINCT FROM 'Anna Mentor'
     OR doc ->> 'timezone' IS DISTINCT FROM 'Europe/Stockholm' OR doc ->> 'school' IS DISTINCT FROM 'RLS Ledighet' THEN
    RAISE EXCEPTION 'feed: Anna''s feed reads %', doc - 'lessons' - 'breaks';
  END IF;
  IF pg_temp.rls148_lessons(doc) IS DISTINCT FROM 'rls148 Hem@0,rls148 Namn@0' THEN RAISE EXCEPTION 'feed: Anna''s lessons are %', pg_temp.rls148_lessons(doc); END IF;
  one := pg_temp.rls148_lesson(doc, 'rls148 Hem', 0);
  IF one -> 'groups' IS DISTINCT FROM '["9A", "rls148 Tyska 9"]'::jsonb OR one -> 'teachers' IS DISTINCT FROM '["Bertil Mentor"]'::jsonb
     OR one ->> 'room' IS DISTINCT FROM 'rls148 Sal' OR (one ->> 'substitute')::boolean OR (one ->> 'cancelled')::boolean
     OR one ->> 'start' IS DISTINCT FROM to_char(pg_temp.rls148_today() + 1, 'YYYYMMDD') || 'T080000' THEN
    RAISE EXCEPTION 'feed: Anna''s 9A lesson reads %', one;
  END IF;
  IF doc::text LIKE '%Gustav%' OR doc::text LIKE '%Ella%' OR doc::text LIKE '%David%' OR doc::text LIKE '%Erik%' THEN
    RAISE EXCEPTION 'feed: Anna''s feed names a pupil, David or Erik';
  END IF;
  IF doc ->> 'scope' IS DISTINCT FROM (SELECT id::text FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000951')
     OR one ->> 'version' IS DISTINCT FROM '20260102T030405Z' THEN
    RAISE EXCEPTION 'feed: Anna''s scope is % and her 9A lesson''s version %', doc ->> 'scope', one ->> 'version';
  END IF;
  IF pg_temp.rls148_breaks(doc) IS DISTINCT FROM 'rls148 Studiedag' THEN RAISE EXCEPTION 'feed: Anna''s days off are %', pg_temp.rls148_breaks(doc); END IF;
  -- Bertil: beside Anna in 9A (David not named), covering Spanska.
  doc := pg_temp.rls148_feed(repeat('c', 64));
  IF pg_temp.rls148_lessons(doc) IS DISTINCT FROM 'rls148 Hem@0,rls148 Spanska@2' THEN RAISE EXCEPTION 'feed: Bertil''s lessons are %', pg_temp.rls148_lessons(doc); END IF;
  IF pg_temp.rls148_lesson(doc, 'rls148 Hem', 0) -> 'teachers' IS DISTINCT FROM '["Anna Mentor"]'::jsonb
     OR NOT (pg_temp.rls148_lesson(doc, 'rls148 Spanska', 2) ->> 'substitute')::boolean THEN
    RAISE EXCEPTION 'feed: Bertil''s feed reads %', doc -> 'lessons';
  END IF;

  -- Ella's own, and her guardian's: the same week of hers.
  FOREACH got IN ARRAY ARRAY[repeat('d', 64), repeat('e', 64)] LOOP
    doc := pg_temp.rls148_feed(got);
    IF pg_temp.rls148_lessons(doc) IS DISTINCT FROM
       format('rls148 Spanska@%s,rls148 Spanska@0,rls148 Namn@0,rls148 Spanska@1,rls148 Spanska@2', (date_trunc('week', (pg_temp.rls148_today() - 7)::timestamp)::date) - (pg_temp.rls148_today() + 1)) THEN
      RAISE EXCEPTION 'feed: Ella''s week (%) is %', got, pg_temp.rls148_lessons(doc);
    END IF;
    IF pg_temp.rls148_lesson(doc, 'rls148 Spanska', 0) -> 'teachers' IS DISTINCT FROM '["Cecilia Mentor"]'::jsonb
       OR pg_temp.rls148_lesson(doc, 'rls148 Namn', 0) -> 'teachers' IS DISTINCT FROM '["Anna Mentor"]'::jsonb THEN
      RAISE EXCEPTION 'feed: Ella''s teachers read %', doc -> 'lessons';
    END IF;
    one := pg_temp.rls148_lesson(doc, 'rls148 Spanska', 1);
    IF NOT (one ->> 'cancelled')::boolean OR one -> 'teachers' IS DISTINCT FROM '[]'::jsonb OR (one ->> 'substitute')::boolean THEN
      RAISE EXCEPTION 'feed: Ella''s cancelled lesson reads %', one;
    END IF;
    one := pg_temp.rls148_lesson(doc, 'rls148 Spanska', 2);
    IF NOT (one ->> 'substitute')::boolean OR one -> 'teachers' IS DISTINCT FROM '[]'::jsonb THEN
      RAISE EXCEPTION 'feed: Ella''s covered lesson reads %', one;
    END IF;
    IF pg_temp.rls148_breaks(doc) IS DISTINCT FROM 'rls148 Studiedag,rls148 Prao' THEN RAISE EXCEPTION 'feed: Ella''s days off are %', pg_temp.rls148_breaks(doc); END IF;
    IF doc ->> 'scope' IS DISTINCT FROM ella::text THEN RAISE EXCEPTION 'feed: Ella''s week (%) is scoped %', got, doc ->> 'scope'; END IF;
    IF pg_temp.rls148_lesson(doc, 'rls148 Spanska', 0) ->> 'version' IS DISTINCT FROM '20260102T030405Z' THEN
      RAISE EXCEPTION 'feed: Ella''s Spanska''s version is %', pg_temp.rls148_lesson(doc, 'rls148 Spanska', 0) ->> 'version';
    END IF;
    IF doc::text LIKE '%Gustav%' OR doc::text LIKE '%Frida%' OR doc::text LIKE '%Tyska%' OR doc::text LIKE '%David%' THEN
      RAISE EXCEPTION 'feed: Ella''s week names another pupil, Frida''s lesson or David';
    END IF;
  END LOOP;
  IF pg_temp.rls148_feed(repeat('d', 64)) ->> 'title' IS DISTINCT FROM 'Ella Elev' OR pg_temp.rls148_feed(repeat('d', 64)) ->> 'audience' IS DISTINCT FROM 'STUDENT'
     OR pg_temp.rls148_feed(repeat('e', 64)) ->> 'title' IS DISTINCT FROM 'Ella' OR pg_temp.rls148_feed(repeat('e', 64)) ->> 'audience' IS DISTINCT FROM 'GUARDIAN' THEN
    RAISE EXCEPTION 'feed: Ella''s feeds are titled wrong';
  END IF;
  -- Frida's: her Tyska, and 9A's lesson Tyska is the extra group of; none of Ella's.
  IF pg_temp.rls148_lessons(pg_temp.rls148_feed(repeat('f', 64))) IS DISTINCT FROM 'rls148 Hem@0,rls148 Tyska@0' THEN
    RAISE EXCEPTION 'feed: Frida''s week is %', pg_temp.rls148_lessons(pg_temp.rls148_feed(repeat('f', 64)));
  END IF;

  -- Tom's: an empty week, asked, and nothing of his read.
  doc := pg_temp.rls148_feed(repeat('a', 64));
  IF doc IS NULL OR doc -> 'lessons' IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION 'feed: Tom''s week reads %', doc; END IF;
  -- The read log: the guardian's two feeds that showed a lesson, once each today, and no other's.
  SELECT id INTO guardian FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000955';
  IF (SELECT count(*) FROM "PersonalDataAccess" WHERE channel = 'CALENDAR') <> 2
     OR NOT EXISTS (SELECT 1 FROM "PersonalDataAccess" WHERE channel = 'CALENDAR' AND "actorId" = guardian AND "actorRole" = 'GUARDIAN'
                     AND kind = 'SCHEDULE' AND "subjectIds" = ARRAY[ella] AND "readSize" = 1 AND "apiKeyId" IS NULL) THEN
    RAISE EXCEPTION 'feed: the read log holds %', (SELECT jsonb_agg(to_jsonb(a) - 'id' - 'at') FROM "PersonalDataAccess" a WHERE channel = 'CALENDAR');
  END IF;
  -- The guardian opens Ella's week in the app minutes after the calendar
  -- fetched it: another read, by another way, and written.
  PERFORM pg_temp.rls148_as('00000000-0000-4000-8000-000000000955');
  IF app.personal_data_read('SCHEDULE', 'APP', ARRAY[ella]) <> 1 THEN
    RAISE EXCEPTION 'feed: the calendar''s row hides the guardian''s read in the app';
  END IF;
  IF app.personal_data_read('SCHEDULE', 'APP', ARRAY[ella]) <> 0 THEN
    RAISE EXCEPTION 'feed: the app''s own quarter-hour no longer holds';
  END IF;
  PERFORM pg_temp.rls148_as('00000000-0000-4000-8000-000000000950');

  -- By signature, Cecilia is hers; naming nobody, nobody.
  INSERT INTO "TeacherEmployments" ("schoolId", "userId", "academicYearId", "employmentPercent", signature, "updatedAt")
  VALUES (app.current_school_id(), current_setting('app.test_rls148_cecilia')::uuid, current_setting('app.test_rls148_year')::uuid, 100, 'CEME', now());
  UPDATE "PublicationSettings" SET "publicTeacherDisplay" = 'SIGNATURE' WHERE "schoolId" = app.current_school_id();
  IF pg_temp.rls148_lesson(pg_temp.rls148_feed(repeat('e', 64)), 'rls148 Spanska', 0) -> 'teachers' IS DISTINCT FROM '["CEME"]'::jsonb THEN
    RAISE EXCEPTION 'feed: by signature Ella''s Spanska reads %', pg_temp.rls148_lesson(pg_temp.rls148_feed(repeat('e', 64)), 'rls148 Spanska', 0);
  END IF;
  UPDATE "PublicationSettings" SET "publicTeacherDisplay" = 'NONE' WHERE "schoolId" = app.current_school_id();
  IF pg_temp.rls148_lesson(pg_temp.rls148_feed(repeat('e', 64)), 'rls148 Spanska', 0) -> 'teachers' IS DISTINCT FROM '[]'::jsonb THEN
    RAISE EXCEPTION 'feed: naming nobody, Ella''s Spanska names someone';
  END IF;
  -- Asked again the same day: still one row per feed.
  IF (SELECT count(*) FROM "PersonalDataAccess" WHERE channel = 'CALENDAR') <> 2 THEN
    RAISE EXCEPTION 'feed: the guardian''s feed is written more than once a day';
  END IF;
  PERFORM pg_temp.rls148_as('00000000-0000-4000-8000-000000000955');
  IF EXISTS (SELECT 1 FROM "CalendarFeeds" WHERE "revokedAt" IS NULL AND "lastUsedAt" IS NULL) THEN
    RAISE EXCEPTION 'feed: an asked feed is not marked used';
  END IF;
  PERFORM pg_temp.rls148_as('00000000-0000-4000-8000-000000000950');

  -- Nothing for what is not a live feed of a person still theirs.
  IF pg_temp.rls148_feed(repeat('0', 64)) IS NOT NULL THEN RAISE EXCEPTION 'feed: an unknown address answers'; END IF;
  DELETE FROM "GuardianStudents" WHERE "guardianId" = guardian AND "studentId" = (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000958');
  IF pg_temp.rls148_feed(repeat('f', 64)) IS NOT NULL THEN RAISE EXCEPTION 'feed: a guardian no longer Frida''s reads her week'; END IF;
  UPDATE "Users" SET "isActive" = false WHERE "authId" = '00000000-0000-4000-8000-000000000951';
  IF pg_temp.rls148_feed(repeat('b', 64)) IS NOT NULL THEN RAISE EXCEPTION 'feed: a deactivated teacher''s feed answers'; END IF;
  UPDATE "Users" SET "isActive" = false WHERE id = ella;
  IF pg_temp.rls148_feed(repeat('e', 64)) IS NOT NULL OR pg_temp.rls148_feed(repeat('d', 64)) IS NOT NULL THEN
    RAISE EXCEPTION 'feed: a deactivated pupil''s week answers';
  END IF;
  PERFORM pg_temp.rls148_as('00000000-0000-4000-8000-000000000952');
  PERFORM app.calendar_feed_revoke((SELECT id FROM "CalendarFeeds" WHERE "revokedAt" IS NULL LIMIT 1));
  IF pg_temp.rls148_feed(repeat('c', 64)) IS NOT NULL THEN RAISE EXCEPTION 'feed: a revoked feed answers'; END IF;
END $$;
SET LOCAL ROLE authenticated;
DO $$
BEGIN
  PERFORM app.calendar_feed(repeat('c', 64));
  RAISE EXCEPTION 'feed: PostgREST''s role asks the feed''s door';
EXCEPTION WHEN insufficient_privilege THEN NULL;
END $$;
SET LOCAL ROLE app_authenticated;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 150: halvklassernas regler står i katalogen (20261113090000).
--
-- What sections 151-153 prove by acting, read from the catalogue, where a
-- later migration that loosens one shows up even on a path no section walks:
-- the four functions are SECURITY DEFINER with a pinned search_path, owned
-- by the migration owner and executed by no API role; each trigger fires
-- when and on the columns the migration says; a half's class is a composite
-- tenant key that deletes the half with the class; one half per class is a
-- partial unique index; and the publish check warns until a school says
-- otherwise.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  fn text;
  f oid;
  cols text[];
  r record;
  idx record;
  fk record;
  col record;
BEGIN
  FOREACH fn IN ARRAY ARRAY[
    'app.student_groups_half_is_of_a_class()',
    'app.student_group_members_half_of()',
    'app.student_group_members_in_the_class()',
    'app.users_leave_the_old_class_halves()'
  ] LOOP
    f := fn::regprocedure;
    IF has_function_privilege('app_authenticated', f, 'EXECUTE')
       OR has_function_privilege('authenticated', f, 'EXECUTE')
       OR has_function_privilege('anon', f, 'EXECUTE') THEN
      RAISE EXCEPTION 'halves catalogue: an API role may execute %', fn;
    END IF;
    IF NOT (SELECT prosecdef FROM pg_proc WHERE oid = f) THEN
      RAISE EXCEPTION 'halves catalogue: % is not SECURITY DEFINER', fn;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_proc WHERE oid = f AND proconfig @> ARRAY['search_path=public, pg_temp']) THEN
      RAISE EXCEPTION 'halves catalogue: % has no pinned search_path (%)', fn, (SELECT proconfig FROM pg_proc WHERE oid = f);
    END IF;
    IF (SELECT proowner FROM pg_proc WHERE oid = f) IN (SELECT oid FROM pg_roles
         WHERE rolname IN ('app_authenticated', 'authenticated', 'anon')) THEN
      RAISE EXCEPTION 'halves catalogue: % is owned by an API role', fn;
    END IF;
  END LOOP;

  -- name, table, function, ROW|BEFORE|INSERT|DELETE|UPDATE bits (1|2|4|8|16), columns
  FOR r IN SELECT * FROM (VALUES
    ('StudentGroups_half_is_of_a_class', '"StudentGroups"', 'app.student_groups_half_is_of_a_class()', 1 | 4 | 16,
     ARRAY['academicYearId', 'halfOfId', 'kind']),
    ('StudentGroupMembers_half_of', '"StudentGroupMembers"', 'app.student_group_members_half_of()', 1 | 2 | 4 | 16,
     ARRAY['halfOfId', 'schoolId', 'studentGroupId']),
    ('StudentGroupMembers_in_the_class', '"StudentGroupMembers"', 'app.student_group_members_in_the_class()', 1 | 4 | 16,
     ARRAY['halfOfId', 'studentGroupId', 'studentId']),
    ('Users_leave_the_old_class_halves', '"Users"', 'app.users_leave_the_old_class_halves()', 1 | 16,
     ARRAY['studentGroupId'])
  ) AS t(name, tbl, fn, bits, cols) LOOP
    SELECT array_agg(a.attname::text ORDER BY a.attname) INTO cols
      FROM pg_trigger t
      JOIN pg_attribute a ON a.attrelid = t.tgrelid AND a.attnum = ANY (t.tgattr)
     WHERE t.tgrelid = r.tbl::regclass AND t.tgname = r.name AND t.tgfoid = r.fn::regprocedure
       AND (t.tgtype & (1 | 2 | 4 | 8 | 16)) = r.bits AND t.tgenabled = 'O';
    IF cols IS DISTINCT FROM r.cols THEN
      RAISE EXCEPTION 'halves catalogue: % fires on % (expected %, as bits %)', r.name, cols, r.cols, r.bits;
    END IF;
  END LOOP;

  SELECT c.confdeltype AS del,
         ARRAY(SELECT a.attname::text FROM unnest(c.conkey) WITH ORDINALITY k(n, o)
                 JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.n ORDER BY k.o) AS here,
         ARRAY(SELECT a.attname::text FROM unnest(c.confkey) WITH ORDINALITY k(n, o)
                 JOIN pg_attribute a ON a.attrelid = c.confrelid AND a.attnum = k.n ORDER BY k.o) AS there,
         c.confrelid::regclass::text AS target
    INTO fk FROM pg_constraint c WHERE c.conname = 'StudentGroups_halfOfId_schoolId_fkey';
  IF fk.del IS DISTINCT FROM 'c' OR fk.here IS DISTINCT FROM ARRAY['halfOfId', 'schoolId']
     OR fk.there IS DISTINCT FROM ARRAY['id', 'schoolId'] OR fk.target <> '"StudentGroups"' THEN
    RAISE EXCEPTION 'halves catalogue: a half''s class key is %', row_to_json(fk);
  END IF;

  SELECT i.indisunique AS uniq, pg_get_expr(i.indpred, i.indrelid) AS pred,
         ARRAY(SELECT a.attname::text FROM unnest(i.indkey) WITH ORDINALITY k(n, o)
                 JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k.n ORDER BY k.o) AS cols
    INTO idx FROM pg_index i WHERE i.indexrelid = '"StudentGroupMembers_one_half_per_class"'::regclass;
  IF NOT idx.uniq OR idx.cols IS DISTINCT FROM ARRAY['halfOfId', 'studentId']
     OR idx.pred IS DISTINCT FROM '("halfOfId" IS NOT NULL)' THEN
    RAISE EXCEPTION 'halves catalogue: one half per class is %', row_to_json(idx);
  END IF;

  SELECT a.attnotnull AS notnull, pg_get_expr(d.adbin, d.adrelid) AS dflt INTO col
    FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
   WHERE a.attrelid = '"PublicationSettings"'::regclass AND a.attname = 'gateEmptyHalf';
  IF NOT col.notnull OR col.dflt IS DISTINCT FROM '''WARN''::"PublishGateMode"' THEN
    RAISE EXCEPTION 'halves catalogue: gateEmptyHalf is %', row_to_json(col);
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Section 151: en halva är en undervisningsgrupp av en klass i sitt eget
-- läsår, och förblir det (SQLSTATE HC409).
--
-- Every way a half can stop being one is refused with HC409, the reason
-- token first and only the written row's id in DETAIL — through both API
-- roles, because PostgREST's may write StudentGroups under the admin's arm
-- and meets no DTO. A half naming another school's class is the composite
-- key's 23503, never an HC409 that would describe school B's row. A half of
-- a class of its own year is let in, and deleting the class takes it along.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', :'admin_auth_id')::text, true);
SELECT set_config('app.test_group_b', :'group_b', true);

-- 'sqlstate|message|detail' of a statement's refusal, or 'none'.
CREATE FUNCTION pg_temp.rls151_refusal(statement text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE st text; msg text; det text;
BEGIN
  EXECUTE statement;
  RETURN 'none';
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, msg = MESSAGE_TEXT, det = PG_EXCEPTION_DETAIL;
  RETURN st || '|' || msg || '|' || coalesce(det, '');
END $$;

DO $$
DECLARE
  school uuid := app.current_school_id();
  year uuid;
  later uuid;
  cls uuid; other_cls uuid; tg uuid; half uuid; plain uuid; fresh uuid;
  via text;
  got text;
  c record;
BEGIN
  IF app.current_user_role() <> 'SCHOOL_ADMIN' THEN
    RAISE EXCEPTION 'halves: expected to be acting as an admin, am %', app.current_user_role();
  END IF;
  SELECT id INTO year FROM "AcademicYears" WHERE "schoolId" = school ORDER BY "isActive" DESC, id LIMIT 1;
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (school, 'RLS151 senare år', DATE '2095-08-15', DATE '2096-06-10', false, now()) RETURNING id INTO later;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "updatedAt")
  VALUES (school, year, 'RLS151 7A', 'CLASS', 7, now()) RETURNING id INTO cls;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "updatedAt")
  VALUES (school, year, 'RLS151 7B', 'CLASS', 7, now()) RETURNING id INTO other_cls;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "updatedAt")
  VALUES (school, year, 'RLS151 Ma7', 'TEACHING_GROUP', now()) RETURNING id INTO tg;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "halfOfId", "updatedAt")
  VALUES (school, year, 'RLS151 7A:1', 'TEACHING_GROUP', 7, cls, now()) RETURNING id INTO half;
  IF half IS NULL THEN RAISE EXCEPTION 'halves: a half of a class of its own year was refused'; END IF;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "updatedAt")
  VALUES (school, year, 'RLS151 Sv7', 'TEACHING_GROUP', now()) RETURNING id INTO plain;

  FOREACH via IN ARRAY ARRAY['app_authenticated', 'authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    IF current_user <> via THEN RAISE EXCEPTION 'halves: running as %, not %', current_user, via; END IF;
    FOR c IN SELECT * FROM (VALUES
      ('a half of a teaching group', 'HALF_OF_NOT_A_CLASS', true,
       format('INSERT INTO "StudentGroups" (id, "schoolId", "academicYearId", name, kind, "halfOfId", "updatedAt")
               VALUES (%%L, %L, %L, ''RLS151 x'', ''TEACHING_GROUP'', %L, now())', school, year, tg)),
      ('a half that is a class', 'HALF_NOT_A_TEACHING_GROUP', true,
       format('INSERT INTO "StudentGroups" (id, "schoolId", "academicYearId", name, kind, "halfOfId", "updatedAt")
               VALUES (%%L, %L, %L, ''RLS151 x'', ''CLASS'', %L, now())', school, year, cls)),
      ('a half in another year than its class', 'HALF_IN_OTHER_YEAR', true,
       format('INSERT INTO "StudentGroups" (id, "schoolId", "academicYearId", name, kind, "halfOfId", "updatedAt")
               VALUES (%%L, %L, %L, ''RLS151 x'', ''TEACHING_GROUP'', %L, now())', school, later, cls)),
      ('a half moved to another class', 'HALF_LINK_IS_FIXED', false,
       format('UPDATE "StudentGroups" SET "halfOfId" = %L WHERE id = %L', other_cls, half)),
      ('a half let go of its class', 'HALF_LINK_IS_FIXED', false,
       format('UPDATE "StudentGroups" SET "halfOfId" = NULL WHERE id = %L', half)),
      ('a teaching group made a half after the fact', 'HALF_LINK_IS_FIXED', false,
       format('UPDATE "StudentGroups" SET "halfOfId" = %L WHERE id = %L', cls, plain)),
      ('a half turned into a class', 'HALF_NOT_A_TEACHING_GROUP', false,
       format('UPDATE "StudentGroups" SET kind = ''CLASS'' WHERE id = %L', half)),
      ('a half moved to another year', 'HALF_IN_OTHER_YEAR', false,
       format('UPDATE "StudentGroups" SET "academicYearId" = %L WHERE id = %L', later, half)),
      ('a class with halves turned into a teaching group', 'CLASS_HAS_HALVES', false,
       format('UPDATE "StudentGroups" SET kind = ''TEACHING_GROUP'' WHERE id = %L', cls)),
      ('a class with halves moved to another year', 'CLASS_HAS_HALVES', false,
       format('UPDATE "StudentGroups" SET "academicYearId" = %L WHERE id = %L', later, cls))
    ) AS t(what, token, inserts, statement) LOOP
      fresh := gen_random_uuid();
      got := pg_temp.rls151_refusal(CASE WHEN c.inserts THEN format(c.statement, fresh) ELSE c.statement END);
      IF split_part(got, '|', 1) <> 'HC409' OR split_part(got, '|', 2) NOT LIKE c.token || ': %' THEN
        RAISE EXCEPTION 'halves: % as % was answered "%", expected %', c.what, via, got, c.token;
      END IF;
      IF split_part(got, '|', 3) <> format('studentGroupId=%s',
           CASE WHEN c.inserts THEN fresh WHEN c.token = 'CLASS_HAS_HALVES' THEN cls
                WHEN c.what LIKE 'a teaching group%' THEN plain ELSE half END) THEN
        RAISE EXCEPTION 'halves: % as % has the detail "%"', c.what, via, split_part(got, '|', 3);
      END IF;
    END LOOP;

    -- Another school's class: the key's refusal, and nothing of school B's.
    got := pg_temp.rls151_refusal(format(
      'INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "halfOfId", "updatedAt")
       VALUES (%L, %L, ''RLS151 x'', ''TEACHING_GROUP'', %L, now())', school, year, current_setting('app.test_group_b')));
    IF split_part(got, '|', 1) <> '23503' THEN
      RAISE EXCEPTION 'halves: a half of another school''s class as % was answered "%"', via, got;
    END IF;
    IF got LIKE '%RLS Fixture Class%' THEN
      RAISE EXCEPTION 'halves: the refusal names school B''s class: %', got;
    END IF;

    -- Its own half: refused as itself by the CHECK, before any key.
    fresh := gen_random_uuid();
    got := pg_temp.rls151_refusal(format(
      'INSERT INTO "StudentGroups" (id, "schoolId", "academicYearId", name, kind, "halfOfId", "updatedAt")
       VALUES (%L, %L, %L, ''RLS151 x'', ''TEACHING_GROUP'', %L, now())', fresh, school, year, fresh));
    IF split_part(got, '|', 1) <> '23514' THEN
      RAISE EXCEPTION 'halves: a group that is its own half as % was answered "%"', via, got;
    END IF;
  END LOOP;
  SET LOCAL ROLE app_authenticated;

  -- What a class with halves may still do: be renamed, change grade.
  UPDATE "StudentGroups" SET name = 'RLS151 7A ny', "gradeLevel" = 8 WHERE id = cls;
  IF NOT FOUND THEN RAISE EXCEPTION 'halves: a class with halves could not be renamed'; END IF;
  UPDATE "StudentGroups" SET name = 'RLS151 7A ny:1' WHERE id = half;
  IF NOT FOUND THEN RAISE EXCEPTION 'halves: a half could not be renamed'; END IF;

  -- Deleting the class deletes its half.
  DELETE FROM "StudentGroups" WHERE id = cls;
  IF EXISTS (SELECT 1 FROM "StudentGroups" WHERE id = half) THEN
    RAISE EXCEPTION 'halves: deleting the class left its half';
  END IF;
END $$;
ROLLBACK;


-- ---------------------------------------------------------------------------
-- Section 152: en elev står i en halva av sin egen klass, och i högst en.
--
-- StudentGroupMembers."halfOfId" is the group's own, whatever the writer
-- sends; a second half of the same class is the unique index's 23505, named;
-- a pupil of another class, or of none, is HC409 HALF_MEMBER_NOT_IN_CLASS
-- with only the membership's id. Next year's half takes the pupils of its
-- class's predecessor (rollover, before activation) and nobody else's. A
-- membership moved off a half carries no class, so the pupil may then join
-- the other half.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', :'admin_auth_id')::text, true);

-- 'sqlstate|message|detail|constraint' of a membership's refusal, or 'none'.
CREATE FUNCTION pg_temp.rls152_place(member uuid, grp uuid, pupil uuid) RETURNS text LANGUAGE plpgsql AS $$
DECLARE st text; msg text; det text; con text;
BEGIN
  INSERT INTO "StudentGroupMembers" (id, "schoolId", "studentGroupId", "studentId")
  VALUES (member, app.current_school_id(), grp, pupil);
  RETURN 'none';
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, msg = MESSAGE_TEXT, det = PG_EXCEPTION_DETAIL, con = CONSTRAINT_NAME;
  RETURN st || '|' || msg || '|' || coalesce(det, '') || '|' || coalesce(con, '');
END $$;

DO $$
DECLARE
  school uuid := app.current_school_id();
  y1 uuid; y2 uuid;
  a uuid; b uuid; a1 uuid; a2 uuid; nxt uuid; n1 uuid; tg uuid;
  p uuid; q uuid; r uuid;
  m uuid;
  pupil uuid;
  got text;
BEGIN
  IF app.current_user_role() <> 'SCHOOL_ADMIN' THEN
    RAISE EXCEPTION 'half members: expected to be acting as an admin, am %', app.current_user_role();
  END IF;
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (school, 'RLS152 år 1', DATE '2095-08-15', DATE '2096-06-10', false, now()) RETURNING id INTO y1;
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "predecessorId", "updatedAt")
  VALUES (school, 'RLS152 år 2', DATE '2096-08-15', DATE '2097-06-10', false, y1, now()) RETURNING id INTO y2;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "updatedAt")
  VALUES (school, y1, 'RLS152 7A', 'CLASS', 7, now()) RETURNING id INTO a;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "updatedAt")
  VALUES (school, y1, 'RLS152 7B', 'CLASS', 7, now()) RETURNING id INTO b;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "halfOfId", "updatedAt")
  VALUES (school, y1, 'RLS152 7A:1', 'TEACHING_GROUP', 7, a, now()) RETURNING id INTO a1;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "halfOfId", "updatedAt")
  VALUES (school, y1, 'RLS152 7A:2', 'TEACHING_GROUP', 7, a, now()) RETURNING id INTO a2;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "updatedAt")
  VALUES (school, y1, 'RLS152 Ma7', 'TEACHING_GROUP', now()) RETURNING id INTO tg;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "predecessorId", "updatedAt")
  VALUES (school, y2, 'RLS152 8A', 'CLASS', 8, a, now()) RETURNING id INTO nxt;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "halfOfId", "updatedAt")
  VALUES (school, y2, 'RLS152 8A:1', 'TEACHING_GROUP', 8, nxt, now()) RETURNING id INTO n1;
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "isActive", "updatedAt", "studentGroupId")
  VALUES (school, 'rls152-p@example.invalid', 'RLS152', 'P', 'STUDENT', gen_random_uuid(), true, now(), a) RETURNING id INTO p;
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "isActive", "updatedAt", "studentGroupId")
  VALUES (school, 'rls152-q@example.invalid', 'RLS152', 'Q', 'STUDENT', gen_random_uuid(), true, now(), b) RETURNING id INTO q;
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "isActive", "updatedAt")
  VALUES (school, 'rls152-r@example.invalid', 'RLS152', 'R', 'STUDENT', gen_random_uuid(), true, now()) RETURNING id INTO r;

  -- The class is the group's, not the writer's.
  INSERT INTO "StudentGroupMembers" ("schoolId", "studentGroupId", "studentId", "halfOfId")
  VALUES (school, a1, p, b) RETURNING id INTO m;
  IF (SELECT "halfOfId" FROM "StudentGroupMembers" WHERE id = m) IS DISTINCT FROM a THEN
    RAISE EXCEPTION 'half members: the writer''s class was kept: %', (SELECT "halfOfId" FROM "StudentGroupMembers" WHERE id = m);
  END IF;
  UPDATE "StudentGroupMembers" SET "halfOfId" = NULL WHERE id = m;
  IF (SELECT "halfOfId" FROM "StudentGroupMembers" WHERE id = m) IS DISTINCT FROM a THEN
    RAISE EXCEPTION 'half members: a writer cleared a membership''s class';
  END IF;
  INSERT INTO "StudentGroupMembers" ("schoolId", "studentGroupId", "studentId", "halfOfId") VALUES (school, tg, q, a);
  IF (SELECT "halfOfId" FROM "StudentGroupMembers" WHERE "studentGroupId" = tg AND "studentId" = q) IS NOT NULL THEN
    RAISE EXCEPTION 'half members: a teaching group''s membership took the writer''s class';
  END IF;

  -- The other half of the same class: the index, by name.
  got := pg_temp.rls152_place(gen_random_uuid(), a2, p);
  IF split_part(got, '|', 1) <> '23505' OR split_part(got, '|', 4) <> 'StudentGroupMembers_one_half_per_class' THEN
    RAISE EXCEPTION 'half members: the second half of a class was answered "%"', got;
  END IF;

  -- A pupil of another class, or of none: refused, with the membership's id alone.
  FOREACH pupil IN ARRAY ARRAY[q, r] LOOP
    m := gen_random_uuid();
    got := pg_temp.rls152_place(m, a1, pupil);
    IF split_part(got, '|', 1) <> 'HC409' OR split_part(got, '|', 2) NOT LIKE 'HALF_MEMBER_NOT_IN_CLASS: %'
       OR split_part(got, '|', 3) <> format('studentGroupMemberId=%s', m) THEN
      RAISE EXCEPTION 'half members: a pupil outside the class was answered "%"', got;
    END IF;
  END LOOP;
  -- Nor moved into a half by changing the membership's pupil or group.
  BEGIN
    UPDATE "StudentGroupMembers" SET "studentId" = q WHERE "studentGroupId" = a1 AND "studentId" = p;
    RAISE EXCEPTION 'half members: a membership was handed to a pupil of another class';
  EXCEPTION WHEN SQLSTATE 'HC409' THEN NULL;
  END;
  BEGIN
    UPDATE "StudentGroupMembers" SET "studentGroupId" = a1 WHERE "studentGroupId" = tg AND "studentId" = q;
    RAISE EXCEPTION 'half members: a teaching group''s membership was moved into another class''s half';
  EXCEPTION WHEN SQLSTATE 'HC409' THEN NULL;
  END;

  -- Next year's half: the predecessor class's pupils, before activation, and nobody else.
  got := pg_temp.rls152_place(gen_random_uuid(), n1, p);
  IF got <> 'none' THEN RAISE EXCEPTION 'half members: 7A''s pupil could not be placed in 8A:1 before activation: %', got; END IF;
  got := pg_temp.rls152_place(gen_random_uuid(), n1, q);
  IF split_part(got, '|', 1) <> 'HC409' THEN
    RAISE EXCEPTION 'half members: 7B''s pupil was answered "%" for 8A:1', got;
  END IF;

  -- Moved off the half, the membership has no class, and the other half is free.
  DELETE FROM "StudentGroupMembers" WHERE "studentGroupId" = tg AND "studentId" = q;
  UPDATE "StudentGroupMembers" SET "studentGroupId" = tg WHERE "studentGroupId" = a1 AND "studentId" = p;
  IF (SELECT "halfOfId" FROM "StudentGroupMembers" WHERE "studentGroupId" = tg AND "studentId" = p) IS NOT NULL THEN
    RAISE EXCEPTION 'half members: a membership moved off a half kept its class';
  END IF;
  got := pg_temp.rls152_place(gen_random_uuid(), a2, p);
  IF got <> 'none' THEN RAISE EXCEPTION 'half members: the other half stayed closed after the move: %', got; END IF;

  -- Deleting the class takes its halves and their memberships, and leaves
  -- its pupils with no class: so in none of next year's 8A's halves either,
  -- whichever of the two SET NULL actions (the pupils' class, 8A's link)
  -- the database ran first.
  DELETE FROM "StudentGroups" WHERE id = a;
  IF EXISTS (SELECT 1 FROM "StudentGroupMembers" WHERE "studentGroupId" IN (a1, a2)) THEN
    RAISE EXCEPTION 'half members: deleting the class left its halves'' memberships';
  END IF;
  IF EXISTS (SELECT 1 FROM "StudentGroupMembers" WHERE "studentGroupId" = n1 AND "studentId" = p) THEN
    RAISE EXCEPTION 'half members: a pupil whose class was deleted is still placed in next year''s half';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 153: en elev som byter klass lämnar halvor hen inte längre hör
-- till, men inte förra läsårets.
--
-- The Users trigger re-judges a moved pupil's halves by the member trigger's
-- rule: a half whose class is neither the new class nor its predecessor is
-- left. For both writers of a home class — the admin through the gateway and
-- the SS12000 sync principal, which may not DELETE a membership itself (the
-- trigger is SECURITY DEFINER for it); PostgREST's role moves nobody. Before
-- activation: 7A -> 7B, 7A -> no class and 7A -> next year's 8B each leave
-- 7A:1 and next year's 8A:1. Except history: once next year is active (as
-- activation makes it before moving anyone), 7A -> 8A keeps 7A:1 and 8A:1,
-- and a graduate's 7A -> no class keeps 7A:1. Only the moved pupil's rows go.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', :'admin_auth_id')::text, true);

DO $$
DECLARE
  school uuid := app.current_school_id();
  y1 uuid; y2 uuid;
  a uuid; b uuid; a1 uuid; nxt uuid; nxt_b uuid; n1 uuid; tg uuid;
  pupils uuid[] := '{}';
  pupil uuid;
  i int;
BEGIN
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (school, 'RLS153 år 1', DATE '2095-08-15', DATE '2096-06-10', false, now()) RETURNING id INTO y1;
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "predecessorId", "updatedAt")
  VALUES (school, 'RLS153 år 2', DATE '2096-08-15', DATE '2097-06-10', false, y1, now()) RETURNING id INTO y2;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "updatedAt")
  VALUES (school, y1, 'RLS153 7A', 'CLASS', 7, now()) RETURNING id INTO a;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "updatedAt")
  VALUES (school, y1, 'RLS153 7B', 'CLASS', 7, now()) RETURNING id INTO b;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "halfOfId", "updatedAt")
  VALUES (school, y1, 'RLS153 7A:1', 'TEACHING_GROUP', 7, a, now()) RETURNING id INTO a1;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "updatedAt")
  VALUES (school, y1, 'RLS153 Ma7', 'TEACHING_GROUP', now()) RETURNING id INTO tg;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "predecessorId", "updatedAt")
  VALUES (school, y2, 'RLS153 8A', 'CLASS', 8, a, now()) RETURNING id INTO nxt;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "predecessorId", "updatedAt")
  VALUES (school, y2, 'RLS153 8B', 'CLASS', 8, b, now()) RETURNING id INTO nxt_b;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "halfOfId", "updatedAt")
  VALUES (school, y2, 'RLS153 8A:1', 'TEACHING_GROUP', 8, nxt, now()) RETURNING id INTO n1;
  -- Seven pupils of 7A, each in 7A:1, 8A:1 and Ma7.
  FOR i IN 1..7 LOOP
    INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "isActive", "updatedAt", "studentGroupId")
    VALUES (school, format('rls153-%s@example.invalid', i), 'RLS153', i::text, 'STUDENT', gen_random_uuid(), true, now(), a)
    RETURNING id INTO pupil;
    pupils := pupils || pupil;
    INSERT INTO "StudentGroupMembers" ("schoolId", "studentGroupId", "studentId")
    VALUES (school, a1, pupil), (school, n1, pupil), (school, tg, pupil);
  END LOOP;
  PERFORM set_config('app.test_rls153', json_build_object('a', a, 'b', b, 'nxt', nxt, 'nxt_b', nxt_b, 'y2', y2,
    'pupils', pupils)::text, true);
END $$;

-- 'halves,other groups' a pupil is in.
CREATE FUNCTION pg_temp.rls153_in(pupil uuid) RETURNS text LANGUAGE sql AS $$
  SELECT count(*) FILTER (WHERE "halfOfId" IS NOT NULL) || ',' || count(*) FILTER (WHERE "halfOfId" IS NULL)
    FROM "StudentGroupMembers" WHERE "studentId" = pupil
$$;

DO $$
DECLARE
  t jsonb := current_setting('app.test_rls153')::jsonb;
  p uuid[] := ARRAY(SELECT jsonb_array_elements_text(t -> 'pupils')::uuid);
  claims text := current_setting('request.jwt.claims');
BEGIN
  -- PostgREST's role has no arm that writes Users: nobody moves, nothing goes.
  SET LOCAL ROLE authenticated;
  UPDATE "Users" SET "studentGroupId" = (t ->> 'b')::uuid WHERE id = p[1];
  IF FOUND THEN RAISE EXCEPTION 'class change: PostgREST''s role moved a pupil'; END IF;
  SET LOCAL ROLE app_authenticated;
  IF pg_temp.rls153_in(p[1]) <> '2,1' THEN
    RAISE EXCEPTION 'class change: a move that never happened left the pupil in %', pg_temp.rls153_in(p[1]);
  END IF;

  -- The admin: 7A -> 7B within the läsår.
  UPDATE "Users" SET "studentGroupId" = (t ->> 'b')::uuid WHERE id = p[1];
  IF NOT FOUND THEN RAISE EXCEPTION 'class change: the admin could not move a pupil'; END IF;
  IF pg_temp.rls153_in(p[1]) <> '0,1' THEN
    RAISE EXCEPTION 'class change: moved to 7B by the admin, the pupil is in % (halves, other groups); expected 0,1',
      pg_temp.rls153_in(p[1]);
  END IF;

  -- The sync principal, with no claims: the same move, and the same cleanup.
  PERFORM set_config('app.sync_school_id', app.current_school_id()::text, true);
  PERFORM set_config('request.jwt.claims', '', true);
  UPDATE "Users" SET "studentGroupId" = (t ->> 'b')::uuid WHERE id = p[2];
  IF NOT FOUND THEN RAISE EXCEPTION 'class change: the sync principal could not move a pupil'; END IF;
  BEGIN
    DELETE FROM "StudentGroupMembers" WHERE "studentId" = p[7];
    IF FOUND THEN RAISE EXCEPTION 'class change: the sync principal deleted a membership itself'; END IF;
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  PERFORM set_config('app.sync_school_id', '', true);
  PERFORM set_config('request.jwt.claims', claims, true);
  IF pg_temp.rls153_in(p[2]) <> '0,1' THEN
    RAISE EXCEPTION 'class change: moved to 7B by the sync, the pupil is in %', pg_temp.rls153_in(p[2]);
  END IF;

  -- 7A -> no class.
  UPDATE "Users" SET "studentGroupId" = NULL WHERE id = p[3];
  IF pg_temp.rls153_in(p[3]) <> '0,1' THEN
    RAISE EXCEPTION 'class change: out of any class, the pupil is in %', pg_temp.rls153_in(p[3]);
  END IF;

  -- 7A -> next year's 8B before activation: not 7A's any more, and not going to 8A.
  UPDATE "Users" SET "studentGroupId" = (t ->> 'nxt_b')::uuid WHERE id = p[4];
  IF pg_temp.rls153_in(p[4]) <> '0,1' THEN
    RAISE EXCEPTION 'class change: moved straight into next year''s 8B, the pupil is in %', pg_temp.rls153_in(p[4]);
  END IF;

  -- Not the moved pupils': untouched, and a write that keeps the class changes nothing.
  UPDATE "Users" SET "studentGroupId" = (t ->> 'a')::uuid, "firstName" = 'RLS153 x' WHERE id = p[7];
  IF pg_temp.rls153_in(p[7]) <> '2,1' THEN
    RAISE EXCEPTION 'class change: a classmate who did not move, or kept the class, is in %', pg_temp.rls153_in(p[7]);
  END IF;

  -- Activation: next year is made active first, then the pupils move.
  UPDATE "AcademicYears" SET "isActive" = false WHERE "schoolId" = app.current_school_id() AND "isActive";
  UPDATE "AcademicYears" SET "isActive" = true WHERE id = (t ->> 'y2')::uuid;
  UPDATE "Users" SET "studentGroupId" = (t ->> 'nxt')::uuid WHERE id = p[5];
  IF pg_temp.rls153_in(p[5]) <> '2,1' THEN
    RAISE EXCEPTION 'class change: moved by activation into 8A, the pupil is in %; expected last year''s 7A:1 and 8A:1',
      pg_temp.rls153_in(p[5]);
  END IF;
  -- A graduate out of any class keeps 7A:1, which is history, and leaves 8A:1.
  UPDATE "Users" SET "studentGroupId" = NULL WHERE id = p[6];
  IF pg_temp.rls153_in(p[6]) <> '1,1'
     OR NOT EXISTS (SELECT 1 FROM "StudentGroupMembers" m JOIN "StudentGroups" g ON g.id = m."studentGroupId"
                     WHERE m."studentId" = p[6] AND g."halfOfId" = (t ->> 'a')::uuid) THEN
    RAISE EXCEPTION 'class change: a graduate is in %; expected 7A:1 kept as history', pg_temp.rls153_in(p[6]);
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 154: halvorna och profilerna (Roller i skolan).
--
-- Halves are StudentGroups and placements StudentGroupMembers, both PLANERING
-- (TABLE_WRITE_GATES): in the matrix school a schemaläggare places a pupil, an
-- expedition (DRIFT, PERSONAL) can neither split a class nor place nor take a
-- pupil out of a half. But the expedition moves a pupil to another class
-- (Users, PERSONAL), and the pupil then leaves the old class's half all the
-- same: the class-change cleanup is SECURITY DEFINER, so a placement never
-- outlives the class change a profile without PLANERING made.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);

-- 'sqlstate' of a statement's refusal, or 'none'.
CREATE FUNCTION pg_temp.rls154_refusal(statement text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE st text;
BEGIN
  EXECUTE statement;
  RETURN 'none';
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE;
  RETURN st;
END $$;

-- FULL: 7A split in halves, a second class, the first pupil placed.
DO $$
DECLARE
  school uuid := app.current_school_id();
  a uuid; yr uuid; b uuid; h1 uuid; h2 uuid; p1 uuid; p2 uuid;
BEGIN
  IF app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' OR NOT app.current_user_may('PLANERING', true) THEN
    RAISE EXCEPTION 'halves and profiles: expected the matrix school''s FULL administrator';
  END IF;
  SELECT id, "academicYearId" INTO a, yr FROM "StudentGroups" WHERE "schoolId" = school AND name = 'Roller 7A';
  SELECT id INTO p1 FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000112';
  SELECT id INTO p2 FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000114';
  IF a IS NULL OR p1 IS NULL OR p2 IS NULL THEN
    RAISE EXCEPTION 'halves and profiles: the matrix school''s 7A or its pupils are missing; fixtures did not run';
  END IF;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "updatedAt")
  VALUES (school, yr, 'RLS154 7B', 'CLASS', 7, now()) RETURNING id INTO b;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "halfOfId", "updatedAt")
  VALUES (school, yr, 'RLS154 7A:1', 'TEACHING_GROUP', 7, a, now()) RETURNING id INTO h1;
  INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "halfOfId", "updatedAt")
  VALUES (school, yr, 'RLS154 7A:2', 'TEACHING_GROUP', 7, a, now()) RETURNING id INTO h2;
  INSERT INTO "StudentGroupMembers" ("schoolId", "studentGroupId", "studentId") VALUES (school, h1, p1);
  PERFORM set_config('app.test_rls154', json_build_object('school', school, 'yr', yr, 'a', a, 'b', b,
    'h1', h1, 'h2', h2, 'p1', p1, 'p2', p2)::text, true);
END $$;

-- The schemaläggare (PLANERING) places the second pupil.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
DO $$
DECLARE
  t jsonb := current_setting('app.test_rls154')::jsonb;
BEGIN
  IF NOT app.current_user_may('PLANERING', true) THEN
    RAISE EXCEPTION 'halves and profiles: the schemaläggare does not write PLANERING';
  END IF;
  INSERT INTO "StudentGroupMembers" ("schoolId", "studentGroupId", "studentId")
  VALUES ((t ->> 'school')::uuid, (t ->> 'h2')::uuid, (t ->> 'p2')::uuid);
  IF NOT EXISTS (SELECT 1 FROM "StudentGroupMembers" WHERE "studentGroupId" = (t ->> 'h2')::uuid AND "studentId" = (t ->> 'p2')::uuid) THEN
    RAISE EXCEPTION 'halves and profiles: the schemaläggare could not place a pupil';
  END IF;
END $$;

-- The expedition (DRIFT, PERSONAL): no split, no placement, no removal.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000108')::text, true);
DO $$
DECLARE
  t jsonb := current_setting('app.test_rls154')::jsonb;
  got text;
  n int;
BEGIN
  IF app.current_user_may('PLANERING', true) OR NOT app.current_user_may('PERSONAL', true) THEN
    RAISE EXCEPTION 'halves and profiles: expected the expedition (PERSONAL, not PLANERING)';
  END IF;
  got := pg_temp.rls154_refusal(format(
    'INSERT INTO "StudentGroups" ("schoolId", "academicYearId", name, kind, "gradeLevel", "halfOfId", "updatedAt")
     VALUES (%L, %L, ''RLS154 7B:1'', ''TEACHING_GROUP'', 7, %L, now())', t ->> 'school', t ->> 'yr', t ->> 'b'));
  IF got <> '42501' THEN RAISE EXCEPTION 'halves and profiles: the expedition split a class (%)', got; END IF;
  got := pg_temp.rls154_refusal(format(
    'INSERT INTO "StudentGroupMembers" ("schoolId", "studentGroupId", "studentId") VALUES (%L, %L, %L)',
    t ->> 'school', t ->> 'h1', t ->> 'p2'));
  IF got <> '42501' THEN RAISE EXCEPTION 'halves and profiles: the expedition placed a pupil (%)', got; END IF;
  DELETE FROM "StudentGroupMembers" WHERE "studentGroupId" = (t ->> 'h2')::uuid;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'halves and profiles: the expedition took % pupil(s) out of a half', n; END IF;

  -- But moves the first pupil to 7B, and the pupil leaves 7A:1 with it.
  UPDATE "Users" SET "studentGroupId" = (t ->> 'b')::uuid WHERE id = (t ->> 'p1')::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'halves and profiles: the expedition could not move a pupil'; END IF;
  IF EXISTS (SELECT 1 FROM "StudentGroupMembers" WHERE "studentGroupId" = (t ->> 'h1')::uuid AND "studentId" = (t ->> 'p1')::uuid) THEN
    RAISE EXCEPTION 'halves and profiles: a pupil the expedition moved is still placed in the old class''s half';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "StudentGroupMembers" WHERE "studentGroupId" = (t ->> 'h2')::uuid AND "studentId" = (t ->> 'p2')::uuid) THEN
    RAISE EXCEPTION 'halves and profiles: the move took a pupil who stayed out of a half';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 155: SS12000-närvaro, katalogen (20261114090000).
--
-- The school's decision (AttendanceSharingDecisions): row security on;
-- exactly the admin's SELECT and INSERT, TO app_authenticated; PostgREST's
-- authenticated and anon hold nothing; service_role SELECT and nothing else;
-- the API SELECT and INSERT of schoolId, shares and reference only (who and
-- when are the database's), no UPDATE, DELETE, TRUNCATE, REFERENCES or
-- TRIGGER, and no API role MAINTAIN on 17. No arm of AttendanceRecords or
-- AbsenceReports names the service principal: the integration reads them
-- through app.ss12000_attendances and app.ss12000_absences, which are the
-- API's alone, run as their owner, and answer exactly the emitted columns.
-- The versions' and tombstones' service arms ask app.service_reads_attendance
-- for the two resources. Every other function is nobody's to call, except
-- that question, which is the API's; the fifteen triggers are in place (a
-- linked pupil's rows stamped again at commit, deferred), and the CHECKs
-- know the two resources (and the pupils' rows of each) and the scopes.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  r text;
  p text;
  n bigint;
  fn text;
  def text;
BEGIN
  IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = '"AttendanceSharingDecisions"'::regclass) THEN
    RAISE EXCEPTION 'attendance sharing: row security is off';
  END IF;
  SELECT count(*) INTO n FROM pg_policies WHERE schemaname = 'public' AND tablename = 'AttendanceSharingDecisions';
  IF n <> 2
     OR NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'AttendanceSharingDecisions'
                      AND policyname = 'attendance_sharing_decisions_admin_select' AND cmd = 'SELECT' AND roles = '{app_authenticated}')
     OR NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'AttendanceSharingDecisions'
                      AND policyname = 'attendance_sharing_decisions_admin_insert' AND cmd = 'INSERT' AND roles = '{app_authenticated}') THEN
    RAISE EXCEPTION 'attendance sharing: the arms are not the admin''s SELECT and INSERT, TO app_authenticated';
  END IF;
  FOREACH r IN ARRAY ARRAY['authenticated', 'anon'] LOOP
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
    FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
      IF has_table_privilege(r, '"AttendanceSharingDecisions"', p) THEN RAISE EXCEPTION 'attendance sharing: % holds %', r, p; END IF;
    END LOOP;
    IF has_any_column_privilege(r, '"AttendanceSharingDecisions"', 'INSERT') THEN RAISE EXCEPTION 'attendance sharing: % may insert a column', r; END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
    FOREACH p IN ARRAY ARRAY['INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
      IF has_table_privilege('service_role', '"AttendanceSharingDecisions"', p) THEN RAISE EXCEPTION 'attendance sharing: service_role holds %', p; END IF;
    END LOOP;
  END IF;
  IF NOT has_table_privilege('app_authenticated', '"AttendanceSharingDecisions"', 'SELECT') THEN
    RAISE EXCEPTION 'attendance sharing: the API cannot read the decisions';
  END IF;
  FOREACH p IN ARRAY ARRAY['INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
    IF has_table_privilege('app_authenticated', '"AttendanceSharingDecisions"', p) THEN RAISE EXCEPTION 'attendance sharing: the API holds % on the whole table', p; END IF;
  END LOOP;
  FOREACH p IN ARRAY ARRAY['schoolId', 'shares', 'reference'] LOOP
    IF NOT has_column_privilege('app_authenticated', '"AttendanceSharingDecisions"', p, 'INSERT') THEN
      RAISE EXCEPTION 'attendance sharing: the API cannot insert %', p;
    END IF;
  END LOOP;
  FOREACH p IN ARRAY ARRAY['id', 'decidedById', 'decidedAt', 'xid', 'committedAt'] LOOP
    IF has_column_privilege('app_authenticated', '"AttendanceSharingDecisions"', p, 'INSERT') THEN
      RAISE EXCEPTION 'attendance sharing: the API may write %, which is the database''s', p;
    END IF;
  END LOOP;
  IF current_setting('server_version_num')::int >= 170000 THEN
    FOREACH r IN ARRAY ARRAY['authenticated', 'app_authenticated', 'service_role', 'anon'] LOOP
      CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
      IF has_table_privilege(r, '"AttendanceSharingDecisions"', 'MAINTAIN') THEN RAISE EXCEPTION 'attendance sharing: % holds MAINTAIN', r; END IF;
    END LOOP;
  END IF;

  -- No arm of the two tables is the service principal's.
  SELECT count(*) INTO n FROM pg_policies
   WHERE schemaname = 'public' AND tablename IN ('AttendanceRecords', 'AbsenceReports')
     AND (policyname LIKE '%service%' OR coalesce(qual, '') LIKE '%service%' OR coalesce(with_check, '') LIKE '%service%');
  IF n <> 0 THEN RAISE EXCEPTION 'attendance sharing: % arms of AttendanceRecords or AbsenceReports name the service principal', n; END IF;

  -- The versions' and tombstones' service arms ask the question for the two resources.
  -- Versions while the school shares; tombstones once it has ever shared.
  FOREACH p IN ARRAY ARRAY['Ss12000EntityVersions:ss12000_entity_versions_service_select:service_reads_attendance',
                           'Ss12000Tombstones:ss12000_tombstones_service_select:service_reads_attendance_removals'] LOOP
    SELECT qual INTO def FROM pg_policies WHERE schemaname = 'public' AND tablename = split_part(p, ':', 1) AND policyname = split_part(p, ':', 2);
    IF def IS NULL
       OR def NOT LIKE '%app.' || split_part(p, ':', 3) || '(''attendances.read''::text)%'
       OR def NOT LIKE '%app.' || split_part(p, ':', 3) || '(''absences.read''::text)%' THEN
      RAISE EXCEPTION 'attendance sharing: % does not keep Attendance and Absence to a key that may read them: %', p, def;
    END IF;
  END LOOP;

  -- The functions: nobody's but the questions and the two reads, which are the API's.
  FOREACH fn IN ARRAY ARRAY[
    'app.attendance_sharing_decisions_are_stamped()', 'app.attendance_sharing_decisions_are_append_only()',
    'app.attendance_shared(uuid)', 'app.attendance_shared_since(uuid)', 'app.attendance_ever_shared(uuid)',
    'app.absence_reports_granted_leave_is_decided()', 'app.ss12000_emitted_years(uuid)',
    'app.ss12000_attendance_emitted(uuid, uuid[])', 'app.ss12000_absence_emitted(uuid, uuid[])',
    'app.ss12000_v_attendance()', 'app.ss12000_v_absences()', 'app.ss12000_v_attendance_pupils()',
    'app.ss12000_v_attendance_lessons()', 'app.ss12000_v_absence_timezone()', 'app.ss12000_v_attendance_years()',
    'app.ss12000_notifies(text[], text[], uuid)', 'app.ss12000_notifies_removals(text[], text[], uuid)',
    'app.attendance_run_xid(uuid)', 'app.attendance_stopped_since(uuid)',
    'app.ss12000_may_have_left(uuid, text, uuid[], timestamptz[])',
    'app.attendance_recorded_as_shared(uuid)', 'app.attendance_removals_ordered(uuid)',
    'app.ss12000_attendance_pupils_stamped()', 'app.attendance_sharing_decisions_are_committed()'
  ] LOOP
    FOREACH r IN ARRAY ARRAY['app_authenticated', 'authenticated', 'anon', 'service_role'] LOOP
      CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
      IF has_function_privilege(r, fn, 'EXECUTE') THEN RAISE EXCEPTION 'attendance sharing: % may execute %', r, fn; END IF;
    END LOOP;
    IF NOT (SELECT prosecdef FROM pg_proc WHERE oid = fn::regprocedure) THEN RAISE EXCEPTION 'attendance sharing: % runs as its caller', fn; END IF;
  END LOOP;
  FOREACH fn IN ARRAY ARRAY[
    'app.service_reads_attendance(text)',
    'app.service_reads_attendance_removals(text)',
    'app.ss12000_attendances(uuid[], uuid[], uuid[], uuid[], timestamptz, timestamptz, timestamptz, timestamptz, uuid, integer)',
    'app.ss12000_absences(uuid[], uuid[])'
  ] LOOP
    IF NOT has_function_privilege('app_authenticated', fn, 'EXECUTE') THEN RAISE EXCEPTION 'attendance sharing: the API may not call %', fn; END IF;
    FOREACH r IN ARRAY ARRAY['authenticated', 'anon', 'service_role'] LOOP
      CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
      IF has_function_privilege(r, fn, 'EXECUTE') THEN RAISE EXCEPTION 'attendance sharing: % may call %', r, fn; END IF;
    END LOOP;
    IF NOT (SELECT prosecdef FROM pg_proc WHERE oid = fn::regprocedure) THEN RAISE EXCEPTION 'attendance sharing: % runs as its caller', fn; END IF;
  END LOOP;
  -- The two reads answer the emitted columns and nothing else: no note, no
  -- reporter, no recordedAt, no absence type.
  IF pg_get_function_result('app.ss12000_attendances(uuid[], uuid[], uuid[], uuid[], timestamptz, timestamptz, timestamptz, timestamptz, uuid, integer)'::regprocedure)
     IS DISTINCT FROM 'TABLE(id uuid, "calendarLessonId" uuid, "studentId" uuid, status text, "createdAt" timestamp with time zone, '
                      '"startsAt" timestamp with time zone, "endsAt" timestamp with time zone, "studentGroupId" uuid, '
                      '"versionCreatedAt" timestamp with time zone, "versionModifiedAt" timestamp with time zone)' THEN
    RAISE EXCEPTION 'attendance sharing: app.ss12000_attendances answers %',
      pg_get_function_result('app.ss12000_attendances(uuid[], uuid[], uuid[], uuid[], timestamptz, timestamptz, timestamptz, timestamptz, uuid, integer)'::regprocedure);
  END IF;
  IF pg_get_function_result('app.ss12000_absences(uuid[], uuid[])'::regprocedure)
     IS DISTINCT FROM 'TABLE(id uuid, "studentId" uuid, date text, "startTime" text, "endTime" text, "grantedLeave" boolean, "createdAt" timestamp with time zone, '
                      '"versionCreatedAt" timestamp with time zone, "versionModifiedAt" timestamp with time zone)' THEN
    RAISE EXCEPTION 'attendance sharing: app.ss12000_absences answers %', pg_get_function_result('app.ss12000_absences(uuid[], uuid[])'::regprocedure);
  END IF;

  SELECT count(*) INTO n FROM pg_trigger
   WHERE NOT tgisinternal AND (
         (tgrelid = '"AttendanceSharingDecisions"'::regclass AND tgname IN (
            'AttendanceSharingDecisions_stamped', 'AttendanceSharingDecisions_committed', 'AttendanceSharingDecisions_append_only',
            'AttendanceSharingDecisions_no_truncate'))
      OR (tgrelid = '"AbsenceReports"'::regclass AND tgname IN (
            'AbsenceReports_granted_leave_is_decided', 'AbsenceReports_ss12000_versions_ins',
            'AbsenceReports_ss12000_versions_upd', 'AbsenceReports_ss12000_versions_del'))
      OR (tgrelid = '"AttendanceRecords"'::regclass AND tgname IN (
            'AttendanceRecords_ss12000_versions_ins', 'AttendanceRecords_ss12000_versions_upd', 'AttendanceRecords_ss12000_versions_del'))
      OR (tgrelid = '"Users"'::regclass AND tgname IN ('Users_ss12000_attendance_upd', 'Users_ss12000_attendance_pupils_stamped'))
      OR (tgrelid = '"CalendarLessons"'::regclass AND tgname = 'CalendarLessons_ss12000_attendance_upd')
      OR (tgrelid = '"Schools"'::regclass AND tgname = 'Schools_ss12000_attendance_upd')
      OR (tgrelid = '"AcademicYears"'::regclass AND tgname = 'AcademicYears_ss12000_attendance_upd'));
  IF n <> 16 THEN RAISE EXCEPTION 'attendance sharing: % of the sixteen triggers are in place', n; END IF;
  -- A decision is stamped again as it commits, when it took effect.
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = '"AttendanceSharingDecisions"'::regclass AND tgname = 'AttendanceSharingDecisions_committed'
                    AND tgdeferrable AND tginitdeferred AND tgenabled = 'O') THEN
    RAISE EXCEPTION 'attendance sharing: AttendanceSharingDecisions_committed is not deferred until commit';
  END IF;
  -- A linked pupil's rows are stamped again as the transaction commits.
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = '"Users"'::regclass AND tgname = 'Users_ss12000_attendance_pupils_stamped'
                    AND tgdeferrable AND tginitdeferred AND tgenabled = 'O') THEN
    RAISE EXCEPTION 'attendance sharing: Users_ss12000_attendance_pupils_stamped is not deferred until commit';
  END IF;

  -- The CHECKs know the two resources and the two scopes.
  FOREACH fn IN ARRAY ARRAY['Ss12000EntityVersions_resource_is_emitted', 'Ss12000Tombstones_resource_is_emitted',
                            'Ss12000Subscriptions_resourceTypes_are_emitted', 'IntegrationApiKeys_scopes_are_known'] LOOP
    SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conname = fn;
    IF def IS NULL OR NOT (SELECT convalidated FROM pg_constraint WHERE conname = fn) THEN
      RAISE EXCEPTION 'attendance sharing: % is missing or not validated', fn;
    END IF;
    IF fn = 'IntegrationApiKeys_scopes_are_known' THEN
      IF def NOT LIKE '%attendances.read%' OR def NOT LIKE '%absences.read%' THEN RAISE EXCEPTION 'attendance sharing: % does not know the scopes', fn; END IF;
    ELSIF def NOT LIKE '%Attendance%' OR def NOT LIKE '%Absence%' THEN
      RAISE EXCEPTION 'attendance sharing: % does not know the resources', fn;
    END IF;
  END LOOP;
  -- A pupil's rows (linked or back: all their records moved at once) are
  -- versions too, kept to a key that may read the resource like the records'.
  SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conname = 'Ss12000EntityVersions_resource_is_emitted';
  IF def NOT LIKE '%AttendancePupil%' OR def NOT LIKE '%AbsencePupil%' THEN
    RAISE EXCEPTION 'attendance sharing: the versions do not know the pupils'' rows: %', def;
  END IF;
  SELECT qual INTO def FROM pg_policies WHERE schemaname = 'public' AND tablename = 'Ss12000EntityVersions' AND policyname = 'ss12000_entity_versions_service_select';
  IF def NOT LIKE '%AttendancePupil%' OR def NOT LIKE '%AbsencePupil%' THEN
    RAISE EXCEPTION 'attendance sharing: the versions'' arm does not keep the pupils'' rows to the scope: %', def;
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Section 156: integrationen läser närvaron och frånvaron bara genom
-- leverantörens två funktioner, bara hos en skola som delar den, med en egen
-- nyckel som har omfånget, och bara den skolans (app.ss12000_attendances,
-- app.ss12000_absences).
--
-- Directly, under the service principal, the two tables are empty to every
-- key, shared or not (pg_temp.nv156_reads asserts it at every call). Through
-- the functions: a school that has not decided answers its key with both
-- scopes nothing. The sharing school: its own key reads its own rows and no
-- other school's; a key of one school named with the other reads nothing,
-- and so does the service principal without a key (v1). Once the first
-- school decides, its key reads what its scope says, function by function,
-- and only the attendance it emits: next year's lesson's is not, and a pupil
-- who leaves is gone from both at once. A key without the scope and a
-- revoked key read nothing; the filters narrow and the keyset pages; the
-- service principal writes nothing; PostgREST's role may not call them; and
-- when the school stops, nothing again.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000150')::text, true);
SELECT set_config('app.test_nv_school', app.current_school_id()::text, true);
SELECT set_config('app.test_nv_full', (SELECT id FROM "IntegrationApiKeys" WHERE name = 'NV hel')::text, true);
SELECT set_config('app.test_nv_narrow', (SELECT id FROM "IntegrationApiKeys" WHERE name = 'NV utan')::text, true);
SELECT set_config('app.test_nv_revoked', (SELECT id FROM "IntegrationApiKeys" WHERE name = 'NV återkallad')::text, true);
SELECT set_config('app.test_nv_absences', (SELECT id FROM "IntegrationApiKeys" WHERE name = 'NV frånvaro')::text, true);
SELECT set_config('app.test_nv_pupil', (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000153')::text, true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000155')::text, true);
SELECT set_config('app.test_nv_shares', app.current_school_id()::text, true);
SELECT set_config('app.test_nv_shares_key', (SELECT id FROM "IntegrationApiKeys" WHERE name = 'ND hel')::text, true);
SELECT set_config('request.jwt.claims', '', true);
CREATE FUNCTION pg_temp.nv156_as(p_school text, p_key text) RETURNS void
LANGUAGE plpgsql AS $$
BEGIN
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM set_config('app.service_school_id', p_school, true);
  PERFORM set_config('app.service_key_id', p_key, true);
END
$$;
CREATE FUNCTION pg_temp.nv156_reads(p_school text, p_key text) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE a bigint; b bigint; da bigint; db bigint;
BEGIN
  PERFORM pg_temp.nv156_as(p_school, p_key);
  SELECT count(*) INTO da FROM "AttendanceRecords";
  SELECT count(*) INTO db FROM "AbsenceReports";
  SELECT count(*) INTO a FROM app.ss12000_attendances(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
  SELECT count(*) INTO b FROM app.ss12000_absences(NULL, NULL);
  PERFORM pg_temp.nv156_as('', '');
  IF da + db <> 0 THEN
    RAISE EXCEPTION 'attendance sharing: the service principal read % attendance and % absence rows directly', da, db;
  END IF;
  RETURN a || '/' || b;
END
$$;
DO $$
DECLARE
  s1 text := current_setting('app.test_nv_school');
  s2 text := current_setting('app.test_nv_shares');
  mine text := current_setting('app.test_nv_full');
  theirs text := current_setting('app.test_nv_shares_key');
  got text;
BEGIN
  IF s1 = '' OR s2 = '' OR mine = '' OR theirs = '' THEN RAISE EXCEPTION 'attendance sharing: the fixtures are missing'; END IF;
  got := pg_temp.nv156_reads(s1, mine);
  IF got <> '0/0' THEN RAISE EXCEPTION 'attendance sharing: a school that has not decided gave its key %', got; END IF;
  got := pg_temp.nv156_reads(s2, theirs);
  IF got <> '1/1' THEN RAISE EXCEPTION 'attendance sharing: the sharing school''s key read %, not its own row of each', got; END IF;
  got := pg_temp.nv156_reads(s2, mine);
  IF got <> '0/0' THEN RAISE EXCEPTION 'attendance sharing: another school''s key read the sharing school: %', got; END IF;
  got := pg_temp.nv156_reads(s1, theirs);
  IF got <> '0/0' THEN RAISE EXCEPTION 'attendance sharing: the sharing school''s key read another school: %', got; END IF;
  got := pg_temp.nv156_reads(s2, '');
  IF got <> '0/0' THEN RAISE EXCEPTION 'attendance sharing: the service principal without a key read %', got; END IF;
END $$;

-- The first school decides, as its administrator.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000150')::text, true);
WITH d AS (
  INSERT INTO "AttendanceSharingDecisions" ("schoolId", shares, reference) VALUES (app.current_school_id(), true, 'RLS 156') RETURNING "decidedAt"
)
SELECT set_config('app.test_nv_since', d."decidedAt"::text, true) FROM d;
SELECT set_config('request.jwt.claims', '', true);
DO $$
DECLARE
  s1 text := current_setting('app.test_nv_school');
  mine text := current_setting('app.test_nv_full');
  pupil uuid := current_setting('app.test_nv_pupil')::uuid;
  got text;
  n bigint;
  first uuid;
  lesson uuid;
  granted record;
BEGIN
  -- This year's two; next year's lesson's attendance is not emitted.
  got := pg_temp.nv156_reads(s1, mine);
  IF got <> '2/2' THEN RAISE EXCEPTION 'attendance sharing: the key with both scopes read %, not the school''s 2 and 2', got; END IF;
  got := pg_temp.nv156_reads(s1, current_setting('app.test_nv_absences'));
  IF got <> '0/2' THEN RAISE EXCEPTION 'attendance sharing: an absences.read key read %', got; END IF;
  got := pg_temp.nv156_reads(s1, current_setting('app.test_nv_narrow'));
  IF got <> '0/0' THEN RAISE EXCEPTION 'attendance sharing: a key without the scopes read %', got; END IF;
  got := pg_temp.nv156_reads(s1, current_setting('app.test_nv_revoked'));
  IF got <> '0/0' THEN RAISE EXCEPTION 'attendance sharing: a revoked key read %', got; END IF;

  -- The filters narrow, the keyset pages, the bounds are the version's or the creation's.
  PERFORM pg_temp.nv156_as(s1, mine);
  SELECT a.id, a."calendarLessonId" INTO first, lesson
    FROM app.ss12000_attendances(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1) a;
  SELECT count(*) INTO n FROM app.ss12000_attendances(NULL, NULL, ARRAY[pupil], NULL, NULL, NULL, NULL, NULL, NULL, NULL);
  IF n <> 1 THEN RAISE EXCEPTION 'attendance sharing: the pupil filter answered % rows', n; END IF;
  SELECT count(*) INTO n FROM app.ss12000_attendances(NULL, ARRAY[lesson], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
  IF n <> 2 THEN RAISE EXCEPTION 'attendance sharing: the lesson filter answered % rows', n; END IF;
  SELECT count(*) INTO n FROM app.ss12000_attendances(ARRAY[first], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
  IF n <> 1 THEN RAISE EXCEPTION 'attendance sharing: the id filter answered % rows', n; END IF;
  SELECT count(*) INTO n FROM app.ss12000_attendances(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, first, NULL);
  IF n <> 1 THEN RAISE EXCEPTION 'attendance sharing: the page after the first answered % rows, not the other one', n; END IF;
  SELECT count(*) INTO n FROM app.ss12000_attendances(NULL, NULL, NULL, NULL, NULL, NULL, NULL, now() + interval '1 day', NULL, NULL);
  IF n <> 0 THEN RAISE EXCEPTION 'attendance sharing: % rows were modified after tomorrow', n; END IF;
  SELECT count(*) INTO n FROM app.ss12000_attendances(NULL, NULL, NULL, NULL, now() - interval '1 year', NULL, NULL, NULL, NULL, NULL);
  IF n <> 0 THEN RAISE EXCEPTION 'attendance sharing: % rows were created a year ago', n; END IF;
  SELECT count(*) INTO n FROM app.ss12000_absences(NULL, ARRAY[pupil]);
  IF n <> 1 THEN RAISE EXCEPTION 'attendance sharing: the pupil''s absences are % rows', n; END IF;
  -- The granted leave's day as the gateway reads it: the date and no times, as text.
  SELECT * INTO granted FROM app.ss12000_absences(NULL, NULL) a WHERE a."grantedLeave";
  IF granted.date IS DISTINCT FROM to_char(current_date + 5, 'YYYY-MM-DD') OR granted."startTime" IS NOT NULL OR granted."endTime" IS NOT NULL THEN
    RAISE EXCEPTION 'attendance sharing: the granted leave reads as % % %', granted.date, granted."startTime", granted."endTime";
  END IF;
  -- Written before the school shared, so no version: each reads as modified
  -- the moment it started sharing, and an incremental read from before that
  -- moment reads them all, one from after it none.
  SELECT count(*) INTO n FROM app.ss12000_attendances(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL) a
   WHERE a."versionModifiedAt" IS DISTINCT FROM current_setting('app.test_nv_since')::timestamptz;
  SELECT n + count(*) INTO n FROM app.ss12000_absences(NULL, NULL) a
   WHERE a."versionModifiedAt" IS DISTINCT FROM current_setting('app.test_nv_since')::timestamptz;
  IF n <> 0 THEN RAISE EXCEPTION 'attendance sharing: % rows do not read as modified when the school started sharing', n; END IF;
  SELECT count(*) INTO n FROM app.ss12000_attendances(NULL, NULL, NULL, NULL, NULL, NULL, NULL,
                                                       current_setting('app.test_nv_since')::timestamptz - interval '1 day', NULL, NULL);
  IF n <> 2 THEN RAISE EXCEPTION 'attendance sharing: a read from before the school started sharing answered % rows, not all 2', n; END IF;
  SELECT count(*) INTO n FROM app.ss12000_attendances(NULL, NULL, NULL, NULL, NULL, NULL, NULL,
                                                       current_setting('app.test_nv_since')::timestamptz, NULL, NULL);
  IF n <> 0 THEN RAISE EXCEPTION 'attendance sharing: a read from the moment the school started sharing answered % unchanged rows', n; END IF;
  SELECT count(*) INTO n FROM app.ss12000_attendances(NULL, NULL, NULL, NULL, NULL, NULL,
                                                       current_setting('app.test_nv_since')::timestamptz - interval '1 day', NULL, NULL, NULL);
  IF n <> 0 THEN RAISE EXCEPTION 'attendance sharing: % rows read as modified before the school started sharing', n; END IF;

  -- The service principal writes nothing here.
  UPDATE "AttendanceRecords" SET status = 'ABSENT';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'attendance sharing: the integration updated % attendance rows', n; END IF;
  DELETE FROM "AbsenceReports";
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'attendance sharing: the integration removed % absences', n; END IF;
  PERFORM pg_temp.nv156_as('', '');

  -- A pupil who leaves is gone from both at once.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000150')::text, true);
  UPDATE "Users" SET "isActive" = false WHERE id = pupil;
  got := pg_temp.nv156_reads(s1, mine);
  IF got <> '1/1' THEN RAISE EXCEPTION 'attendance sharing: with the pupil gone the key read %', got; END IF;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000150')::text, true);
  UPDATE "Users" SET "isActive" = true WHERE id = pupil;
  PERFORM set_config('request.jwt.claims', '', true);
END $$;
-- A second decision to share in a row (a new reference) is not a new
-- beginning: nothing reads as modified again.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000150')::text, true);
INSERT INTO "AttendanceSharingDecisions" ("schoolId", shares, reference) VALUES (app.current_school_id(), true, 'RLS 156, ny referens');
SELECT set_config('request.jwt.claims', '', true);
DO $$
DECLARE n bigint;
BEGIN
  PERFORM pg_temp.nv156_as(current_setting('app.test_nv_school'), current_setting('app.test_nv_full'));
  SELECT count(*) INTO n FROM app.ss12000_absences(NULL, NULL) a
   WHERE a."versionModifiedAt" IS DISTINCT FROM current_setting('app.test_nv_since')::timestamptz;
  PERFORM pg_temp.nv156_as('', '');
  IF n <> 0 THEN RAISE EXCEPTION 'attendance sharing: a second decision to share moved % absences', n; END IF;
END $$;
-- PostgREST's role, with the same settings: the functions are not its.
SELECT pg_temp.nv156_as(current_setting('app.test_nv_school'), current_setting('app.test_nv_full'));
SET LOCAL ROLE authenticated;
DO $$
DECLARE n bigint;
BEGIN
  IF current_user <> 'authenticated' THEN RAISE EXCEPTION 'attendance sharing: could not act as authenticated'; END IF;
  SELECT (SELECT count(*) FROM "AttendanceRecords") + (SELECT count(*) FROM "AbsenceReports") INTO n;
  IF n <> 0 THEN RAISE EXCEPTION 'attendance sharing: PostgREST''s role read % rows through the integration''s settings', n; END IF;
  BEGIN
    PERFORM count(*) FROM app.ss12000_attendances(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
    RAISE EXCEPTION 'attendance sharing: PostgREST''s role called the attendance read';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    PERFORM count(*) FROM app.ss12000_absences(NULL, NULL);
    RAISE EXCEPTION 'attendance sharing: PostgREST''s role called the absence read';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
END $$;
SET LOCAL ROLE app_authenticated;
SELECT pg_temp.nv156_as('', '');
-- The school stops sharing: nothing again, from the next statement.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000150')::text, true);
INSERT INTO "AttendanceSharingDecisions" ("schoolId", shares) VALUES (app.current_school_id(), false);
SELECT set_config('request.jwt.claims', '', true);
DO $$
DECLARE got text;
BEGIN
  got := pg_temp.nv156_reads(current_setting('app.test_nv_school'), current_setting('app.test_nv_full'));
  IF got <> '0/0' THEN RAISE EXCEPTION 'attendance sharing: a school that stopped sharing gave its key %', got; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 157: bara ett beslut om ledighet skriver en beviljad ledighet
-- (AbsenceReports.grantedLeave, app.absence_reports_granted_leave_is_decided).
--
-- A guardian and a pupil file their absences as before, but one that says it
-- is a granted leave is refused (NV403) whatever its note; a teacher's goes
-- no further than RLS; the administrator writes it and may mark a report as
-- one. The note decides nothing: a guardian's "Approved leave" stays false.
-- The administrator's insert in the decision's shape without the column (an
-- API deployed before the migration's code) is the decision's all the same.
-- And a reported span ends after it starts (AbsenceReports_ends_after_it_starts).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000150')::text, true);
SELECT set_config('app.test_nv_pupil', (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000153')::text, true);
SELECT set_config('app.test_nv_guardian', (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000152')::text, true);
SELECT set_config('app.test_nv_teacher', (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000151')::text, true);
DO $$
DECLARE
  pupil uuid := current_setting('app.test_nv_pupil')::uuid;
  guardian uuid := current_setting('app.test_nv_guardian')::uuid;
  teacher uuid := current_setting('app.test_nv_teacher')::uuid;
  admin uuid := app.current_user_id();
  school uuid := app.current_school_id();
  reported uuid;
  marked boolean;
  n bigint;
BEGIN
  -- The guardian.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000152')::text, true);
  BEGIN
    INSERT INTO "AbsenceReports" ("schoolId", "studentId", "reportedById", date, type, note, "grantedLeave")
    VALUES (school, pupil, guardian, current_date + 20, 'OTHER', 'Approved leave', true);
    RAISE EXCEPTION 'granted leave: a guardian filed a granted leave';
  EXCEPTION WHEN SQLSTATE 'NV403' THEN NULL;
  END;
  INSERT INTO "AbsenceReports" ("schoolId", "studentId", "reportedById", date, type, note)
  VALUES (school, pupil, guardian, current_date + 20, 'OTHER', 'Approved leave');
  -- The pupil.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000153')::text, true);
  BEGIN
    INSERT INTO "AbsenceReports" ("schoolId", "studentId", "reportedById", date, type, "grantedLeave")
    VALUES (school, pupil, pupil, current_date + 21, 'OTHER', true);
    RAISE EXCEPTION 'granted leave: a pupil filed their own granted leave';
  EXCEPTION WHEN SQLSTATE 'NV403' THEN NULL;
  END;
  -- A teacher who decided nothing: RLS, not the guard, says no.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000151')::text, true);
  BEGIN
    INSERT INTO "AbsenceReports" ("schoolId", "studentId", "reportedById", date, type, note, "grantedLeave")
    VALUES (school, pupil, teacher, current_date + 22, 'OTHER', 'Approved leave', true);
    RAISE EXCEPTION 'granted leave: a teacher wrote a granted leave without a decision';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  -- The administrator.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000150')::text, true);
  INSERT INTO "AbsenceReports" ("schoolId", "studentId", "reportedById", date, type, "grantedLeave")
  VALUES (school, pupil, admin, current_date + 23, 'OTHER', true);
  SELECT count(*) INTO n FROM "AbsenceReports" WHERE "studentId" = pupil AND date = current_date + 20 AND "grantedLeave";
  IF n <> 0 THEN RAISE EXCEPTION 'granted leave: a guardian''s note made a granted leave'; END IF;
  SELECT id INTO reported FROM "AbsenceReports" WHERE "studentId" = pupil AND date = current_date + 20;
  UPDATE "AbsenceReports" SET "grantedLeave" = true WHERE id = reported;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'granted leave: the administrator could not mark a report as a granted leave'; END IF;
  -- The decision's shape, without the column.
  INSERT INTO "AbsenceReports" ("schoolId", "studentId", "reportedById", date, type, note)
  VALUES (school, pupil, admin, current_date + 24, 'OTHER', 'Approved leave') RETURNING "grantedLeave" INTO marked;
  IF NOT marked THEN RAISE EXCEPTION 'granted leave: the administrator''s leave day without the column is not a granted leave'; END IF;
  INSERT INTO "AbsenceReports" ("schoolId", "studentId", "reportedById", date, type, note)
  VALUES (school, pupil, admin, current_date + 25, 'SICK', 'Approved leave') RETURNING "grantedLeave" INTO marked;
  IF marked THEN RAISE EXCEPTION 'granted leave: a sick day became a granted leave by its note'; END IF;
  -- A span that ends before it starts, or as it starts.
  FOREACH n IN ARRAY ARRAY[0, 1] LOOP
    BEGIN
      INSERT INTO "AbsenceReports" ("schoolId", "studentId", "reportedById", date, "startTime", "endTime", type)
      VALUES (school, pupil, admin, current_date + 26, time '10:00', time '10:00' - n * interval '2 hours', 'APPOINTMENT');
      RAISE EXCEPTION 'granted leave: an absence that does not end after it starts was stored';
    EXCEPTION WHEN check_violation THEN NULL;
    END;
  END LOOP;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 158: skolans beslut fattas av administratören, stämplas av
-- databasen och ändras aldrig (AttendanceSharingDecisions).
--
-- The administrator (full, by the fixtures; that only rektor and full may,
-- every other profile refused, is the role matrix's, section 116) inserts a
-- decision, and who and when are stamped from the claims and the clock,
-- whatever is sent (the API may not even name those columns); no API role
-- updates, removes or truncates one; a decision
-- for another school is refused, and none is seen. Teachers, guardians and
-- pupils neither read nor write a decision, and PostgREST's role nothing.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000155')::text, true);
SELECT set_config('app.test_nv_shares', app.current_school_id()::text, true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000150')::text, true);
DO $$
DECLARE
  school uuid := app.current_school_id();
  other uuid := current_setting('app.test_nv_shares')::uuid;
  row "AttendanceSharingDecisions"%ROWTYPE;
  n bigint;
  who text;
BEGIN
  SELECT count(*) INTO n FROM "AttendanceSharingDecisions";
  IF n <> 0 THEN RAISE EXCEPTION 'decisions: the administrator reads % decisions of another school', n; END IF;
  INSERT INTO "AttendanceSharingDecisions" ("schoolId", shares, reference) VALUES (school, true, 'RLS 158') RETURNING * INTO row;
  IF row."decidedById" IS DISTINCT FROM app.current_user_id() OR row."decidedAt" IS NULL THEN
    RAISE EXCEPTION 'decisions: the decision was not stamped with its decider (%)', row."decidedById";
  END IF;
  BEGIN
    INSERT INTO "AttendanceSharingDecisions" ("schoolId", shares, "decidedById") VALUES (school, true, app.current_user_id());
    RAISE EXCEPTION 'decisions: the API named the decider';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    UPDATE "AttendanceSharingDecisions" SET shares = false;
    RAISE EXCEPTION 'decisions: a decision was changed';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    DELETE FROM "AttendanceSharingDecisions";
    RAISE EXCEPTION 'decisions: a decision was removed';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    TRUNCATE "AttendanceSharingDecisions";
    RAISE EXCEPTION 'decisions: the decisions were truncated';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  IF other IS NOT NULL THEN
    BEGIN
      INSERT INTO "AttendanceSharingDecisions" ("schoolId", shares) VALUES (other, false);
      RAISE EXCEPTION 'decisions: the administrator decided for another school';
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
  END IF;
  SELECT count(*) INTO n FROM "AttendanceSharingDecisions";
  IF n <> 1 THEN RAISE EXCEPTION 'decisions: the administrator reads % decisions, not their own one', n; END IF;
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000000151', '00000000-0000-4000-8000-000000000152', '00000000-0000-4000-8000-000000000153'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    SELECT count(*) INTO n FROM "AttendanceSharingDecisions";
    IF n <> 0 THEN RAISE EXCEPTION 'decisions: % (%) reads the decision', who, app.current_user_role(); END IF;
    BEGIN
      INSERT INTO "AttendanceSharingDecisions" ("schoolId", shares) VALUES (school, false);
      RAISE EXCEPTION 'decisions: % (%) decided', who, app.current_user_role();
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
  END LOOP;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000150')::text, true);
END $$;
SET LOCAL ROLE authenticated;
DO $$
BEGIN
  PERFORM 1 FROM "AttendanceSharingDecisions";
  RAISE EXCEPTION 'decisions: PostgREST''s role reads the decisions';
EXCEPTION WHEN insufficient_privilege THEN NULL;
END $$;
SET LOCAL ROLE app_authenticated;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 159: leverantören följer närvaron och frånvaron: en ändrad status,
-- lektionens tider, en beviljad ledighet, en elev som kopplas till källan och
-- ett läsår som aktiveras flyttar meta.modified, en anteckning gör det inte;
-- en borttagen post, en borttagen lektion och en elev som slutar begravs, och
-- nästa års borttagna lektion begravs aldrig. När skolan har slutat dela
-- begravs en borttagen post ändå och visas för nyckeln med omfånget (inte
-- för en utan), men inte en post som skapades under uppehållet och togs bort
-- under det, och en elev som slutar under uppehållet tar med sig det hen
-- hade före det, inte det som rapporterades under det; inget versioneras,
-- och när skolan delar igen läses det som skrevs under tiden som ändrat då
-- (20261114090000).
--
-- The school decides first: versions are written only while it shares, and
-- tombstones once it ever has, of what may have left (the probe holds a
-- school that never shared to writing nothing, as the owner; here the
-- versions of a school that does not share are not even visible). The
-- section is one transaction, whose now() is before every decision in it,
-- so a row "created while the school has stopped" is planted with
-- createdAt = clock_timestamp(). Read back
-- as the service principal of the school with its key (the versions' and
-- tombstones' own arm), and a key without the scope, or with only the other
-- one, sees no Attendance version. Everything in one transaction, so "moved"
-- is "now carries this transaction's xid", and every such check first asserts
-- there is a version at all. A linked or returning pupil moves the pupil's
-- own rows ('AttendancePupil', 'AbsencePupil'), not each record's version.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000150')::text, true);
SELECT set_config('app.test_nv_school', app.current_school_id()::text, true);
SELECT set_config('app.test_nv_pupil', (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000153')::text, true);
SELECT set_config('app.test_nv_classmate', (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000154')::text, true);
SELECT set_config('app.test_nv_full', (SELECT id FROM "IntegrationApiKeys" WHERE name = 'NV hel')::text, true);
SELECT set_config('app.test_nv_narrow', (SELECT id FROM "IntegrationApiKeys" WHERE name = 'NV utan')::text, true);
SELECT set_config('app.test_nv_absences', (SELECT id FROM "IntegrationApiKeys" WHERE name = 'NV frånvaro')::text, true);
SELECT set_config('app.test_nv_this_year', (SELECT id FROM "AcademicYears" WHERE name = 'Närvaro i år')::text, true);
SELECT set_config('app.test_nv_next_year', (SELECT id FROM "AcademicYears" WHERE name = 'Närvaro nästa år')::text, true);
-- A third pupil, reported sick before the school shares and left alone
-- after (the other two are relinked, and leave and come back): an absence
-- with no version that existed while the school shared.
INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "isActive", "studentGroupId", "updatedAt")
SELECT "schoolId", 'narvaro-tredje@example.invalid', 'Närvaro', 'Tredje', 'STUDENT', '00000000-0000-4000-8000-000000000157', true, "studentGroupId", now()
  FROM "Users" WHERE id = current_setting('app.test_nv_classmate')::uuid;
INSERT INTO "AbsenceReports" ("schoolId", "studentId", "reportedById", date, type, note)
SELECT u."schoolId", u.id, app.current_user_id(), current_date + 10, 'SICK', 'rls159 före'
  FROM "Users" u WHERE u.email = 'narvaro-tredje@example.invalid';
INSERT INTO "AttendanceSharingDecisions" ("schoolId", shares, reference) VALUES (app.current_school_id(), true, 'RLS 159');
CREATE FUNCTION pg_temp.nv159_xid(p_resource text, p_id uuid, p_key text DEFAULT NULL) RETURNS xid8
LANGUAGE plpgsql AS $$
DECLARE claims text := current_setting('request.jwt.claims', true); x xid8;
BEGIN
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM set_config('app.service_school_id', current_setting('app.test_nv_school'), true);
  PERFORM set_config('app.service_key_id', coalesce(p_key, current_setting('app.test_nv_full')), true);
  SELECT v."xid" INTO x FROM "Ss12000EntityVersions" v WHERE v.resource = p_resource AND v."entityId" = p_id;
  PERFORM set_config('app.service_school_id', '', true);
  PERFORM set_config('app.service_key_id', '', true);
  PERFORM set_config('request.jwt.claims', claims, true);
  RETURN x;
END
$$;
CREATE FUNCTION pg_temp.nv159_buried(p_resource text, p_id uuid, p_key text DEFAULT NULL) RETURNS boolean
LANGUAGE plpgsql AS $$
DECLARE claims text := current_setting('request.jwt.claims', true); found boolean;
BEGIN
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM set_config('app.service_school_id', current_setting('app.test_nv_school'), true);
  PERFORM set_config('app.service_key_id', coalesce(p_key, current_setting('app.test_nv_full')), true);
  SELECT EXISTS (SELECT 1 FROM "Ss12000Tombstones" t WHERE t.resource = p_resource AND t."emittedId" = p_id) INTO found;
  PERFORM set_config('app.service_school_id', '', true);
  PERFORM set_config('app.service_key_id', '', true);
  PERFORM set_config('request.jwt.claims', claims, true);
  RETURN found;
END
$$;
CREATE FUNCTION pg_temp.nv159_moved(p_resource text, p_id uuid) RETURNS boolean
LANGUAGE plpgsql AS $$
DECLARE x xid8 := pg_temp.nv159_xid(p_resource, p_id);
BEGIN
  RETURN x IS NOT NULL AND x = pg_current_xact_id();
END
$$;
-- meta.modified of an attendance as the provider reads it.
CREATE FUNCTION pg_temp.nv159_modified(p_id uuid) RETURNS timestamptz
LANGUAGE plpgsql AS $$
DECLARE claims text := current_setting('request.jwt.claims', true); m timestamptz;
BEGIN
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM set_config('app.service_school_id', current_setting('app.test_nv_school'), true);
  PERFORM set_config('app.service_key_id', current_setting('app.test_nv_full'), true);
  SELECT a."versionModifiedAt" INTO m FROM app.ss12000_attendances(ARRAY[p_id], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL) a;
  PERFORM set_config('app.service_school_id', '', true);
  PERFORM set_config('app.service_key_id', '', true);
  PERFORM set_config('request.jwt.claims', claims, true);
  RETURN m;
END
$$;
DO $$
DECLARE
  school uuid := current_setting('app.test_nv_school')::uuid;
  pupil uuid := current_setting('app.test_nv_pupil')::uuid;
  classmate uuid := current_setting('app.test_nv_classmate')::uuid;
  resumed timestamptz;
  present uuid;
  absent uuid;
  ahead uuid;
  sick uuid;
  granted uuid;
  lesson uuid;
  later uuid;
  fresh uuid;
  absent_lesson uuid;
  raced uuid;
  withdrawn uuid;
  quiet uuid;
  unseen uuid;
  planted uuid;
BEGIN
  SELECT a.id, a."calendarLessonId" INTO present, lesson FROM "AttendanceRecords" a
    JOIN "CalendarLessons" l ON l.id = a."calendarLessonId" WHERE a."studentId" = pupil AND l.date < current_date;
  SELECT a.id, a."calendarLessonId" INTO absent, absent_lesson FROM "AttendanceRecords" a WHERE a."studentId" = classmate;
  SELECT a.id, a."calendarLessonId" INTO ahead, later FROM "AttendanceRecords" a
    JOIN "CalendarLessons" l ON l.id = a."calendarLessonId" WHERE a."studentId" = pupil AND l.date > current_date;
  SELECT id INTO sick FROM "AbsenceReports" WHERE "studentId" = pupil;
  SELECT id INTO granted FROM "AbsenceReports" WHERE "studentId" = classmate;
  SELECT id INTO planted FROM "AbsenceReports" WHERE note = 'rls159 före';
  IF present IS NULL OR absent IS NULL OR ahead IS NULL OR sick IS NULL OR granted IS NULL OR planted IS NULL THEN
    RAISE EXCEPTION 'attendance versions: the fixtures are missing';
  END IF;
  -- Planted before the school shared: none has a version, and none was handed out.
  IF pg_temp.nv159_xid('Attendance', present) IS NOT NULL OR pg_temp.nv159_xid('Absence', sick) IS NOT NULL
     OR pg_temp.nv159_xid('Absence', planted) IS NOT NULL THEN
    RAISE EXCEPTION 'attendance versions: a row written before the school shared has a version';
  END IF;

  -- Written now: an insert is versioned and its removal buried. Every insert
  -- is versioned, next year's too (meta.modified never before meta.created),
  -- but next year's removal is not buried: it never left.
  INSERT INTO "AbsenceReports" ("schoolId", "studentId", "reportedById", date, type)
  VALUES (school, classmate, app.current_user_id(), current_date + 6, 'SICK') RETURNING id INTO fresh;
  IF NOT pg_temp.nv159_moved('Absence', fresh) THEN RAISE EXCEPTION 'attendance versions: a new absence was not recorded'; END IF;
  DELETE FROM "AbsenceReports" WHERE id = fresh;
  IF NOT pg_temp.nv159_buried('Absence', fresh) THEN RAISE EXCEPTION 'attendance versions: a removed absence was not buried'; END IF;
  INSERT INTO "AttendanceRecords" ("schoolId", "calendarLessonId", "studentId", status, "updatedAt")
  VALUES (school, later, classmate, 'PRESENT', now()) RETURNING id INTO fresh;
  IF NOT pg_temp.nv159_moved('Attendance', fresh) THEN
    RAISE EXCEPTION 'attendance versions: an insert at a sharing school was not versioned';
  END IF;
  DELETE FROM "AttendanceRecords" WHERE id = fresh;
  IF pg_temp.nv159_buried('Attendance', fresh) THEN
    RAISE EXCEPTION 'attendance versions: an attendance of next year''s lesson was buried';
  END IF;

  -- A note moves nothing; a status does.
  UPDATE "AttendanceRecords" SET note = 'rls159 annan anteckning' WHERE id = absent;
  IF pg_temp.nv159_xid('Attendance', absent) IS NOT NULL THEN RAISE EXCEPTION 'attendance versions: a note moved an attendance'; END IF;
  UPDATE "AttendanceRecords" SET status = 'EXCUSED' WHERE id = absent;
  IF NOT pg_temp.nv159_moved('Attendance', absent) THEN RAISE EXCEPTION 'attendance versions: a status did not move an attendance'; END IF;
  -- The lesson's times are the minutes of every attendance of it.
  UPDATE "CalendarLessons" SET "endsAt" = "endsAt" + interval '5 minutes' WHERE id = lesson;
  IF NOT pg_temp.nv159_moved('Attendance', present) THEN RAISE EXCEPTION 'attendance versions: the lesson''s times did not move its attendance'; END IF;
  -- Only a key that may read attendance sees its version.
  IF pg_temp.nv159_xid('Attendance', present, current_setting('app.test_nv_narrow')) IS NOT NULL
     OR pg_temp.nv159_xid('Attendance', present, current_setting('app.test_nv_absences')) IS NOT NULL THEN
    RAISE EXCEPTION 'attendance versions: a key without attendances.read sees an attendance''s version';
  END IF;
  -- A report marked as a granted leave is another type.
  IF pg_temp.nv159_xid('Absence', sick) IS NOT NULL THEN RAISE EXCEPTION 'attendance versions: the absence moved before anything changed'; END IF;
  UPDATE "AbsenceReports" SET "grantedLeave" = true WHERE id = sick;
  IF NOT pg_temp.nv159_moved('Absence', sick) THEN RAISE EXCEPTION 'attendance versions: grantedLeave did not move the absence'; END IF;
  IF pg_temp.nv159_xid('Absence', sick, current_setting('app.test_nv_absences')) IS NULL
     OR pg_temp.nv159_xid('Absence', sick, current_setting('app.test_nv_narrow')) IS NOT NULL THEN
    RAISE EXCEPTION 'attendance versions: the absence''s version is not exactly the absences.read key''s';
  END IF;
  -- A pupil linked to the source is emitted under another id: the pupil's own
  -- rows move (every record of theirs reads as modified then), and no
  -- record's version, which a register save writes and an apply must not hold.
  IF pg_temp.nv159_xid('Absence', granted) IS NOT NULL OR pg_temp.nv159_xid('AbsencePupil', classmate) IS NOT NULL THEN
    RAISE EXCEPTION 'attendance versions: the granted leave moved before anything changed';
  END IF;
  UPDATE "Users" SET "ss12000Id" = gen_random_uuid() WHERE id = classmate;
  IF NOT pg_temp.nv159_moved('AbsencePupil', classmate) OR NOT pg_temp.nv159_moved('AttendancePupil', classmate) THEN
    RAISE EXCEPTION 'attendance versions: linking the pupil did not move their rows';
  END IF;
  IF pg_temp.nv159_xid('Absence', granted) IS NOT NULL THEN
    RAISE EXCEPTION 'attendance versions: linking the pupil wrote a version of each record';
  END IF;
  -- The pupil's rows are each resource's: kept to a key that may read it.
  IF pg_temp.nv159_xid('AbsencePupil', classmate, current_setting('app.test_nv_narrow')) IS NOT NULL
     OR pg_temp.nv159_xid('AttendancePupil', classmate, current_setting('app.test_nv_absences')) IS NOT NULL
     OR pg_temp.nv159_xid('AbsencePupil', classmate, current_setting('app.test_nv_absences')) IS NULL THEN
    RAISE EXCEPTION 'attendance versions: a pupil''s rows are not exactly their scope''s';
  END IF;

  -- A year activated: its lessons' attendance is emitted from now on, and
  -- versioned (next year's planted row had none). Deactivating this year
  -- first makes nothing newly emitted; activating next year does.
  IF pg_temp.nv159_xid('Attendance', ahead) IS NOT NULL THEN RAISE EXCEPTION 'attendance versions: next year''s planted attendance has a version'; END IF;
  UPDATE "AcademicYears" SET "isActive" = false WHERE id = current_setting('app.test_nv_this_year')::uuid;
  IF pg_temp.nv159_xid('Attendance', ahead) IS NOT NULL THEN RAISE EXCEPTION 'attendance versions: a year left active moved next year''s attendance'; END IF;
  UPDATE "AcademicYears" SET "isActive" = true WHERE id = current_setting('app.test_nv_next_year')::uuid;
  IF NOT pg_temp.nv159_moved('Attendance', ahead) THEN RAISE EXCEPTION 'attendance versions: activating its year did not record an attendance'; END IF;
  UPDATE "AcademicYears" SET "isActive" = false WHERE id = current_setting('app.test_nv_next_year')::uuid;
  UPDATE "AcademicYears" SET "isActive" = true WHERE id = current_setting('app.test_nv_this_year')::uuid;

  -- Removed: buried. Next year's: never buried.
  DELETE FROM "AttendanceRecords" WHERE id IN (absent, ahead);
  IF NOT pg_temp.nv159_buried('Attendance', absent) THEN RAISE EXCEPTION 'attendance versions: a removed attendance was not buried'; END IF;
  IF pg_temp.nv159_buried('Attendance', ahead) THEN RAISE EXCEPTION 'attendance versions: next year''s attendance was buried'; END IF;
  -- Only a key that may read attendance learns of its removal.
  IF pg_temp.nv159_buried('Attendance', absent, current_setting('app.test_nv_narrow'))
     OR pg_temp.nv159_buried('Attendance', absent, current_setting('app.test_nv_absences')) THEN
    RAISE EXCEPTION 'attendance versions: a key without attendances.read sees an attendance''s tombstone';
  END IF;

  -- A pupil who leaves takes their attendance and absences with them, and brings them back.
  UPDATE "Users" SET "isActive" = false WHERE id = pupil;
  IF NOT pg_temp.nv159_buried('Attendance', present) OR NOT pg_temp.nv159_buried('Absence', sick) THEN
    RAISE EXCEPTION 'attendance versions: a pupil who left left their attendance or absence unburied';
  END IF;
  UPDATE "Users" SET "isActive" = true WHERE id = pupil;
  IF pg_temp.nv159_buried('Attendance', present) OR pg_temp.nv159_buried('Absence', sick) THEN
    RAISE EXCEPTION 'attendance versions: a pupil who came back stayed buried';
  END IF;
  IF NOT pg_temp.nv159_moved('AttendancePupil', pupil) OR NOT pg_temp.nv159_moved('AbsencePupil', pupil) THEN
    RAISE EXCEPTION 'attendance versions: a pupil who came back brought no version';
  END IF;

  -- A row whose transaction began after the coming decision to stop read the
  -- clock, and committed before the decision did: it saw the school share,
  -- so it has a version, and its createdAt is after the stop began (planted
  -- ahead here).
  INSERT INTO "AbsenceReports" ("schoolId", "studentId", "reportedById", date, type, "createdAt")
  VALUES (school, classmate, app.current_user_id(), current_date + 7, 'SICK', clock_timestamp() + interval '1 hour')
  RETURNING id INTO raced;

  -- The school stops. Meanwhile a removal is still buried (it has shared:
  -- the integration may hold the row), and nothing is versioned. When it
  -- shares again the tombstone is there to be told, and the row written
  -- meanwhile reads as modified at the moment it started again.
  INSERT INTO "AttendanceSharingDecisions" ("schoolId", shares) VALUES (school, false);
  -- What was never handed out is told to nobody: an absence and an
  -- attendance created while the school has stopped, and removed meanwhile.
  -- A second decision not to share in a row (a new reference) is not a new
  -- beginning: the stop began at the first.
  INSERT INTO "AbsenceReports" ("schoolId", "studentId", "reportedById", date, type, "createdAt")
  VALUES (school, pupil, app.current_user_id(), current_date + 8, 'SICK', clock_timestamp()) RETURNING id INTO withdrawn;
  INSERT INTO "AttendanceSharingDecisions" ("schoolId", shares, reference) VALUES (school, false, 'RLS 159 igen');
  DELETE FROM "AbsenceReports" WHERE id = withdrawn;
  IF pg_temp.nv159_buried('Absence', withdrawn) THEN
    RAISE EXCEPTION 'attendance versions: an absence created and removed while the school had stopped is told';
  END IF;
  INSERT INTO "AttendanceRecords" ("schoolId", "calendarLessonId", "studentId", status, "updatedAt", "createdAt")
  VALUES (school, absent_lesson, classmate, 'ABSENT', now(), clock_timestamp()) RETURNING id INTO quiet;
  DELETE FROM "AttendanceRecords" WHERE id = quiet;
  IF pg_temp.nv159_buried('Attendance', quiet) THEN
    RAISE EXCEPTION 'attendance versions: an attendance created and removed while the school had stopped is told';
  END IF;
  -- The raced one may have been read while the school shared: told. So is
  -- one from before the stop that nothing ever versioned.
  DELETE FROM "AbsenceReports" WHERE id = raced;
  IF NOT pg_temp.nv159_buried('Absence', raced) THEN
    RAISE EXCEPTION 'attendance versions: an absence versioned as the school stopped is not told of its removal';
  END IF;
  DELETE FROM "AbsenceReports" WHERE id = planted;
  IF NOT pg_temp.nv159_buried('Absence', planted) THEN
    RAISE EXCEPTION 'attendance versions: an absence from before the stop, never versioned, is not told of its removal';
  END IF;
  -- A pupil who leaves meanwhile takes what they had before the stop, told
  -- at the instant of their own tombstone; what was reported meanwhile is
  -- not told with them (it would count their absences while the school did
  -- not share). They come back before the school starts again.
  INSERT INTO "AbsenceReports" ("schoolId", "studentId", "reportedById", date, type, "createdAt")
  VALUES (school, pupil, app.current_user_id(), current_date + 9, 'SICK', clock_timestamp()) RETURNING id INTO unseen;
  UPDATE "Users" SET "isActive" = false WHERE id = pupil;
  IF NOT pg_temp.nv159_buried('Absence', sick) OR NOT pg_temp.nv159_buried('Attendance', present) THEN
    RAISE EXCEPTION 'attendance versions: a pupil who left while the school had stopped left what they had before it unburied';
  END IF;
  IF pg_temp.nv159_buried('Absence', unseen) THEN
    RAISE EXCEPTION 'attendance versions: an absence reported while the school had stopped is told with the pupil who left';
  END IF;
  UPDATE "Users" SET "isActive" = true WHERE id = pupil;
  INSERT INTO "AttendanceRecords" ("schoolId", "calendarLessonId", "studentId", status, "updatedAt")
  VALUES (school, lesson, classmate, 'ABSENT', now()) RETURNING id INTO fresh;
  DELETE FROM "AbsenceReports" WHERE id = granted;
  -- Told while it is stopped, to the key with the scope (the instruction to
  -- delete), not to one without it; and no version is seen meanwhile.
  IF NOT pg_temp.nv159_buried('Absence', granted) THEN
    RAISE EXCEPTION 'attendance versions: the absences.read key is not told of a removal while the school has stopped';
  END IF;
  IF pg_temp.nv159_buried('Absence', granted, current_setting('app.test_nv_narrow')) THEN
    RAISE EXCEPTION 'attendance versions: a key without absences.read is told of a removal while the school has stopped';
  END IF;
  IF pg_temp.nv159_xid('Attendance', present) IS NOT NULL THEN
    RAISE EXCEPTION 'attendance versions: an attendance''s version is seen while the school has stopped';
  END IF;
  INSERT INTO "AttendanceSharingDecisions" ("schoolId", shares) VALUES (school, true) RETURNING "decidedAt" INTO resumed;
  IF NOT pg_temp.nv159_buried('Absence', granted) THEN
    RAISE EXCEPTION 'attendance versions: an absence removed while the school did not share was not buried';
  END IF;
  IF pg_temp.nv159_xid('Attendance', fresh) IS NOT NULL THEN
    RAISE EXCEPTION 'attendance versions: an attendance written while the school did not share was versioned';
  END IF;
  IF pg_temp.nv159_modified(fresh) IS DISTINCT FROM resumed THEN
    RAISE EXCEPTION 'attendance versions: an attendance written meanwhile reads as modified at %, not when the school started again (%)',
      pg_temp.nv159_modified(fresh), resumed;
  END IF;

  -- A lesson removed takes its attendance with it (the cascade), buried.
  DELETE FROM "CalendarLessons" WHERE id = lesson;
  IF NOT pg_temp.nv159_buried('Attendance', present) THEN RAISE EXCEPTION 'attendance versions: a removed lesson''s attendance was not buried'; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 117: läsaren läser allt och ändrar inget (Läsbehörighet,
-- 20261120090000, 20261120100000).
--
-- Beside the matrix (116), which runs the läsare against every table, and
-- the functions (107): the profile in the catalogue — a value of
-- "AdminProfile" with no area and no decisions, stated by the newest
-- app.admin_profile_writes — and its rules on Users. HR-läs is its own
-- grant: rektor gives it to a läsare and the läsare keeps it, while it goes
-- when the profile becomes a deciding one; the CHECK admits it on a läsare.
-- A läsare makes nobody an administrator, gives nobody HR-läs and changes no
-- profile, its own included. Each attempt must raise, never pass as zero
-- rows: the decisions' trigger runs before row security checks the new row,
-- so a decision is refused as AR403, and what is not one as 42501 (the
-- läsare writes no area). Every change rektor makes is logged with rektor. Run as the API's role, signed in as
-- rektor to read the school's people, as section 108 is.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  m uuid;
  teacher uuid;
  lasare uuid;
  rektor uuid;
  row_ record;
  bad text[] := '{}';
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000106')::text, true);
  teacher := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000111');
  lasare := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000115');
  rektor := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000106');
  IF lasare IS NULL THEN
    RAISE EXCEPTION 'läsare: the läsare is not in rls-roller-school; fixtures did not run';
  END IF;

  -- The catalogue.
  IF NOT ('LASARE' = ANY (enum_range(NULL::"AdminProfile")::text[])) THEN
    bad := bad || 'LASARE is no value of "AdminProfile"'::text;
  END IF;
  IF app.admin_profile_writes('LASARE') IS DISTINCT FROM '{}'::"AdminArea"[] THEN
    bad := bad || format('the läsare writes %s', app.admin_profile_writes('LASARE'));
  END IF;
  IF app.admin_profile_decides('LASARE') THEN
    bad := bad || 'the läsare decides'::text;
  END IF;
  IF pg_get_constraintdef((SELECT oid FROM pg_constraint
                            WHERE conrelid = 'public."Users"'::regclass
                              AND conname = 'Users_hr_read_is_a_narrow_administrators')) NOT LIKE '%LASARE%' THEN
    bad := bad || 'the HR-läs CHECK does not admit a läsare'::text;
  END IF;
  IF (SELECT "hrRead" FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000116') IS DISTINCT FROM true THEN
    bad := bad || 'the läsare planted with HR-läs does not have it'::text;
  END IF;

  -- The läsare decides nothing about anybody, itself included.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000115')::text, true);
  m := app.current_school_id();
  IF m IS NULL OR (SELECT slug FROM "Schools" WHERE id = m) IS DISTINCT FROM 'rls-roller-school' THEN
    RAISE EXCEPTION 'läsare: the läsare is not signed in to rls-roller-school';
  END IF;
  BEGIN
    INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "adminProfile", "authId", "updatedAt")
    VALUES (m, 'roller-lasare-ny@example.invalid', 'Ny', 'Admin', 'SCHOOL_ADMIN', 'LASARE', gen_random_uuid(), now());
    bad := bad || 'the läsare made an administrator'::text;
  EXCEPTION WHEN SQLSTATE 'AR403' OR insufficient_privilege THEN NULL;
  END;
  BEGIN
    UPDATE "Users" SET role = 'SCHOOL_ADMIN', "adminProfile" = 'LASARE' WHERE id = teacher;
    bad := bad || 'the läsare made a teacher a läsare'::text;
  EXCEPTION WHEN SQLSTATE 'AR403' OR insufficient_privilege THEN NULL;
  END;
  BEGIN
    UPDATE "Users" SET "hrRead" = true WHERE id = lasare;
    bad := bad || 'the läsare gave itself HR-läs'::text;
  EXCEPTION WHEN SQLSTATE 'AR403' OR insufficient_privilege THEN NULL;
  END;
  BEGIN
    UPDATE "Users" SET "adminProfile" = 'FULL' WHERE id = lasare;
    bad := bad || 'the läsare made itself full'::text;
  EXCEPTION WHEN SQLSTATE 'AR403' OR insufficient_privilege THEN NULL;
  END;

  -- Rektor makes a teacher a läsare with HR-läs; the läsare keeps HR-läs, and
  -- it goes when rektor makes the läsare full.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000106')::text, true);
  UPDATE "Users" SET role = 'SCHOOL_ADMIN', "adminProfile" = 'LASARE', "hrRead" = true WHERE id = teacher;
  SELECT "adminProfile"::text AS profile, "hrRead" AS hr INTO row_ FROM "Users" WHERE id = teacher;
  IF row_.profile IS DISTINCT FROM 'LASARE' OR row_.hr IS DISTINCT FROM true THEN
    bad := bad || format('rektor''s läsare with HR-läs reads back as %s %s', row_.profile, row_.hr);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "UserRoleChanges"
                  WHERE "userId" = teacher AND "toProfile" = 'LASARE' AND "toHrRead" AND "actorId" = rektor) THEN
    bad := bad || 'making a läsare left no log row with rektor'::text;
  END IF;
  UPDATE "Users" SET "adminProfile" = 'FULL' WHERE id = teacher;
  IF (SELECT "hrRead" FROM "Users" WHERE id = teacher) THEN
    bad := bad || 'a full administrator kept the läsare''s HR-läs'::text;
  END IF;

  IF cardinality(bad) > 0 THEN
    RAISE EXCEPTION 'läsare: %', array_to_string(bad, '; ');
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 180: skolområdena och restiden står i katalogen som migreringen
-- säger (Sites, SiteTravelTimes, Rooms."siteId", 20261124090000).
--
-- Row security on both tables; exactly four arms each, all TO
-- app_authenticated (the staff read and the planner's insert, update and
-- delete); the update arm asks the area in WITH CHECK only; PostgREST's
-- authenticated and anon hold nothing; service_role reads and writes
-- nothing more; the API holds SELECT, INSERT, UPDATE and DELETE and no
-- TRUNCATE, REFERENCES or TRIGGER; no API role holds MAINTAIN on 17. The
-- pair is stored once, the lower id first, 0..240 minutes; a name is
-- trimmed and 1..60 characters; every key is composite with the school, and
-- a room's site empties when the site goes while the room stays.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  t text;
  arm text;
  r text;
  p text;
  n bigint;
BEGIN
  FOREACH t IN ARRAY ARRAY['Sites', 'SiteTravelTimes'] LOOP
    arm := CASE t WHEN 'Sites' THEN 'sites' ELSE 'site_travel_times' END;
    IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = format('public.%I', t)::regclass) THEN
      RAISE EXCEPTION 'sites: row security is off on %', t;
    END IF;
    SELECT count(*) INTO n FROM pg_policies WHERE schemaname = 'public' AND tablename = t;
    IF n <> 4
       OR (SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND tablename = t
            AND (policyname, cmd) IN ((arm || '_staff_select', 'SELECT'), (arm || '_admin_insert', 'INSERT'),
                                      (arm || '_admin_update', 'UPDATE'), (arm || '_admin_delete', 'DELETE'))
            AND roles = '{app_authenticated}') <> 4 THEN
      RAISE EXCEPTION 'sites: % has % arms, not the staff read and the planner''s three writes TO app_authenticated', t, n;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = t AND policyname = arm || '_staff_select'
                     AND qual LIKE '%SCHOOL_ADMIN%' AND qual LIKE '%TEACHER%' AND qual NOT LIKE '%STUDENT%'
                     AND qual NOT LIKE '%GUARDIAN%' AND qual LIKE '%current_school_id()%') THEN
      RAISE EXCEPTION 'sites: %''s read is not the school''s administrators and teachers', t;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_policies WHERE tablename = t AND cmd = 'UPDATE' AND qual LIKE '%current_user_may%')
       OR NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = t AND cmd = 'UPDATE'
                        AND with_check LIKE '%current_user_may(''PLANERING''%') THEN
      RAISE EXCEPTION 'sites: %''s update arm does not ask PLANERING in WITH CHECK alone', t;
    END IF;
    FOREACH r IN ARRAY ARRAY['authenticated', 'anon'] LOOP
      CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
      FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
        IF has_table_privilege(r, format('public.%I', t), p) THEN RAISE EXCEPTION 'sites: % holds % on %', r, p, t; END IF;
      END LOOP;
    END LOOP;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
      FOREACH p IN ARRAY ARRAY['INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
        IF has_table_privilege('service_role', format('public.%I', t), p) THEN RAISE EXCEPTION 'sites: service_role holds % on %', p, t; END IF;
      END LOOP;
    END IF;
    FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE'] LOOP
      IF NOT has_table_privilege('app_authenticated', format('public.%I', t), p) THEN RAISE EXCEPTION 'sites: the API lacks % on %', p, t; END IF;
    END LOOP;
    FOREACH p IN ARRAY ARRAY['TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
      IF has_table_privilege('app_authenticated', format('public.%I', t), p) THEN RAISE EXCEPTION 'sites: the API holds % on %', p, t; END IF;
    END LOOP;
    IF current_setting('server_version_num')::int >= 170000 THEN
      FOREACH r IN ARRAY ARRAY['authenticated', 'app_authenticated', 'service_role', 'anon'] LOOP
        CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
        IF has_table_privilege(r, format('public.%I', t), 'MAINTAIN') THEN RAISE EXCEPTION 'sites: % holds MAINTAIN on %', r, t; END IF;
      END LOOP;
    END IF;
  END LOOP;

  -- The checks and the keys, by what they say rather than by name alone.
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SiteTravelTimes_lower_id_first' AND contype = 'c'
                   AND pg_get_constraintdef(oid) LIKE '%"siteAId" < "siteBId"%')
     OR NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'SiteTravelTimes_minutes_range' AND contype = 'c'
                   AND pg_get_constraintdef(oid) LIKE '%minutes >= 0%' AND pg_get_constraintdef(oid) LIKE '%minutes <= 240%')
     OR NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'Sites_name_named' AND contype = 'c'
                   AND pg_get_constraintdef(oid) LIKE '%btrim%' AND pg_get_constraintdef(oid) LIKE '%60%') THEN
    RAISE EXCEPTION 'sites: the pair order, the minutes'' range or the name check is missing';
  END IF;
  SELECT count(*) INTO n FROM pg_constraint c
   WHERE c.contype = 'f' AND c.confrelid = '"Sites"'::regclass AND c.confdeltype = 'c' AND c.confupdtype = 'a'
     AND c.conrelid = '"SiteTravelTimes"'::regclass
     AND (SELECT array_agg(a.attname::text ORDER BY k.ord) FROM unnest(c.conkey) WITH ORDINALITY k(attnum, ord)
            JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum)
         IN (ARRAY['siteAId', 'schoolId'], ARRAY['siteBId', 'schoolId']);
  IF n <> 2 THEN RAISE EXCEPTION 'sites: the pair''s two keys to Sites are not (site, school) ON DELETE CASCADE ON UPDATE NO ACTION (% found)', n; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
     WHERE c.contype = 'f' AND c.conrelid = '"Rooms"'::regclass AND c.confrelid = '"Sites"'::regclass
       AND c.confdeltype = 'n' AND c.confupdtype = 'a'
       AND (SELECT array_agg(a.attname::text ORDER BY k.ord) FROM unnest(c.conkey) WITH ORDINALITY k(attnum, ord)
              JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum) = ARRAY['siteId', 'schoolId']
       AND (SELECT array_agg(a.attname::text) FROM unnest(c.confdelsetcols) k(attnum)
              JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum) = ARRAY['siteId']) THEN
    RAISE EXCEPTION 'sites: a room''s site is not (siteId, schoolId) -> Sites ON UPDATE NO ACTION ON DELETE SET NULL ("siteId")';
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Section 181: skolans administratör och lärare läser skolans skolområden
-- och restider, inga andras; elev och vårdnadshavare läser inga; den som
-- skriver planering skriver dem, expeditionen inte; PostgREST:s roll når
-- dem inte ens med administratörens anspråk (20261124090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001245')::text, true);
SELECT set_config('app.test_so_other', app.current_school_id()::text, true);
SELECT set_config('app.test_so_other_site', (SELECT id::text FROM "Sites" WHERE name = 'Annan Norra'), true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001240')::text, true);
SELECT set_config('app.test_so_school', app.current_school_id()::text, true);
DO $$
DECLARE
  n bigint;
  who text;
  norra uuid;
  sodra uuid;
  ny uuid;
BEGIN
  -- The other school's admin read their own site above; this school's admin
  -- reads it nowhere below.
  IF coalesce(current_setting('app.test_so_school', true), '') = ''
     OR coalesce(current_setting('app.test_so_other_site', true), '') = '' THEN
    RAISE EXCEPTION 'sites: a fixture admin read no school, or the other school''s admin none of their sites';
  END IF;
  SELECT count(*) INTO n FROM "Sites";
  IF n <> 2 THEN RAISE EXCEPTION 'sites: the admin reads % sites, not the school''s two', n; END IF;
  SELECT count(*) INTO n FROM "SiteTravelTimes";
  IF n <> 1 THEN RAISE EXCEPTION 'sites: the admin reads % travel times, not the school''s one', n; END IF;
  SELECT id INTO norra FROM "Sites" WHERE name = 'SO Norra';
  SELECT id INTO sodra FROM "Sites" WHERE name = 'SO Södra';

  -- The planner writes: a third site, its pair with Norra, a changed figure, both gone again.
  INSERT INTO "Sites" ("schoolId", name) VALUES (app.current_school_id(), 'SO Idrottshallen') RETURNING id INTO ny;
  INSERT INTO "SiteTravelTimes" ("schoolId", "siteAId", "siteBId", minutes)
  VALUES (app.current_school_id(), least(ny, norra), greatest(ny, norra), 25);
  UPDATE "SiteTravelTimes" SET minutes = 30 WHERE "siteAId" = least(ny, norra) AND "siteBId" = greatest(ny, norra);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'sites: the admin updated % of their own travel times', n; END IF;
  UPDATE "Sites" SET name = 'SO Hallen' WHERE id = ny;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'sites: the admin renamed % of their own sites', n; END IF;
  DELETE FROM "Sites" WHERE id = ny;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'sites: the admin removed % of their own sites', n; END IF;

  -- Another school's site and pair: not seen, not changed, not removed, not written into.
  UPDATE "Sites" SET name = 'x' WHERE id = current_setting('app.test_so_other_site')::uuid;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'sites: the admin renamed another school''s site'; END IF;
  DELETE FROM "SiteTravelTimes" WHERE "schoolId" = current_setting('app.test_so_other')::uuid;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'sites: the admin removed another school''s travel time'; END IF;
  BEGIN
    INSERT INTO "Sites" ("schoolId", name) VALUES (current_setting('app.test_so_other')::uuid, 'Inte min');
    RAISE EXCEPTION 'sites: the admin wrote a site into another school';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    UPDATE "Sites" SET "schoolId" = current_setting('app.test_so_other')::uuid WHERE id = norra;
    RAISE EXCEPTION 'sites: the admin moved a site into another school';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    UPDATE "SiteTravelTimes" SET "schoolId" = current_setting('app.test_so_other')::uuid;
    RAISE EXCEPTION 'sites: the admin moved a travel time into another school';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;

  -- The expedition writes nothing here; it reads, as every administrator does.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001244')::text, true);
  SELECT count(*) INTO n FROM "Sites";
  IF n <> 2 THEN RAISE EXCEPTION 'sites: the expedition reads % sites, not the school''s two', n; END IF;
  BEGIN
    INSERT INTO "Sites" ("schoolId", name) VALUES (app.current_school_id(), 'Expeditionens');
    RAISE EXCEPTION 'sites: the expedition created a site';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    UPDATE "SiteTravelTimes" SET minutes = 1;
    RAISE EXCEPTION 'sites: the expedition changed a travel time';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  DELETE FROM "Sites";
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'sites: the expedition removed % sites', n; END IF;

  -- The teacher reads both and writes neither.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001241')::text, true);
  SELECT count(*) INTO n FROM "Sites";
  IF n <> 2 THEN RAISE EXCEPTION 'sites: the teacher reads % sites, not the school''s two', n; END IF;
  SELECT count(*) INTO n FROM "SiteTravelTimes";
  IF n <> 1 THEN RAISE EXCEPTION 'sites: the teacher reads % travel times, not the school''s one', n; END IF;
  UPDATE "Sites" SET name = 'x';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'sites: the teacher renamed % sites', n; END IF;
  DELETE FROM "SiteTravelTimes";
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'sites: the teacher removed % travel times', n; END IF;
  BEGIN
    INSERT INTO "Sites" ("schoolId", name) VALUES (app.current_school_id(), 'Lärarens');
    RAISE EXCEPTION 'sites: the teacher created a site';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  UPDATE "SiteTravelTimes" SET minutes = 1;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'sites: the teacher changed % travel times', n; END IF;
  BEGIN
    INSERT INTO "SiteTravelTimes" ("schoolId", "siteAId", "siteBId", minutes)
    SELECT app.current_school_id(), "siteAId", "siteBId", 1 FROM "SiteTravelTimes" LIMIT 1;
    RAISE EXCEPTION 'sites: the teacher wrote a travel time';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;

  -- Pupil and guardian: nothing read, nothing written.
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000001242', '00000000-0000-4000-8000-000000001243'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    SELECT count(*) INTO n FROM "Sites";
    IF n <> 0 THEN RAISE EXCEPTION 'sites: % (%) reads % sites', who, app.current_user_role(), n; END IF;
    SELECT count(*) INTO n FROM "SiteTravelTimes";
    IF n <> 0 THEN RAISE EXCEPTION 'sites: % (%) reads % travel times', who, app.current_user_role(), n; END IF;
    BEGIN
      INSERT INTO "Sites" ("schoolId", name) VALUES (app.current_school_id(), 'Familjens');
      RAISE EXCEPTION 'sites: % created a site', who;
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
  END LOOP;

  -- The service and the sync principal of the school: nothing.
  PERFORM set_config('request.jwt.claims', '', true);
  FOREACH who IN ARRAY ARRAY['app.service_school_id', 'app.sync_school_id'] LOOP
    PERFORM set_config(who, current_setting('app.test_so_school'), true);
    SELECT count(*) INTO n FROM "Sites";
    IF n <> 0 THEN RAISE EXCEPTION 'sites: % reads % sites', who, n; END IF;
    SELECT count(*) INTO n FROM "SiteTravelTimes";
    IF n <> 0 THEN RAISE EXCEPTION 'sites: % reads % travel times', who, n; END IF;
    PERFORM set_config(who, '', true);
  END LOOP;
END $$;

-- PostgREST's role, with the admin's claims: nothing at all.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001240')::text, true);
SET LOCAL ROLE authenticated;
DO $$
BEGIN
  IF current_user <> 'authenticated' THEN RAISE EXCEPTION 'sites: could not act as authenticated'; END IF;
  BEGIN
    PERFORM 1 FROM "Sites";
    RAISE EXCEPTION 'sites: PostgREST''s role reads the sites';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    PERFORM 1 FROM "SiteTravelTimes";
    RAISE EXCEPTION 'sites: PostgREST''s role reads the travel times';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 182: en restid står en gång per par, och bara mellan skolans egna
-- skolområden; ett rum står bara på sin egen skolas skolområde; ett
-- skolområde som tas bort tar sina restider med sig och lämnar rummen kvar
-- utan skolområde (20261124090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001245')::text, true);
SELECT set_config('app.test_so_other_site', (SELECT id::text FROM "Sites" WHERE name = 'Annan Norra'), true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001240')::text, true);
DO $$
DECLARE
  n bigint;
  norra uuid;
  sodra uuid;
  ny uuid;
  room uuid;
  st text;
BEGIN
  SELECT id INTO norra FROM "Sites" WHERE name = 'SO Norra';
  SELECT id INTO sodra FROM "Sites" WHERE name = 'SO Södra';
  IF norra IS NULL OR sodra IS NULL THEN RAISE EXCEPTION 'sites: the fixture''s two sites are not there'; END IF;

  -- The pair the other way round: refused, so A→B and B→A can never disagree.
  BEGIN
    INSERT INTO "SiteTravelTimes" ("schoolId", "siteAId", "siteBId", minutes)
    VALUES (app.current_school_id(), greatest(norra, sodra), least(norra, sodra), 5);
    RAISE EXCEPTION 'sites: a pair was stored with the higher id first';
  EXCEPTION WHEN check_violation THEN NULL;
  END;
  -- A site with itself: refused by the same check.
  BEGIN
    INSERT INTO "SiteTravelTimes" ("schoolId", "siteAId", "siteBId", minutes) VALUES (app.current_school_id(), norra, norra, 0);
    RAISE EXCEPTION 'sites: a site was given a travel time to itself';
  EXCEPTION WHEN check_violation THEN NULL;
  END;
  -- A second figure for the pair: the key refuses it.
  BEGIN
    INSERT INTO "SiteTravelTimes" ("schoolId", "siteAId", "siteBId", minutes)
    VALUES (app.current_school_id(), least(norra, sodra), greatest(norra, sodra), 5);
    RAISE EXCEPTION 'sites: a pair got a second travel time';
  EXCEPTION WHEN unique_violation THEN NULL;
  END;
  -- The range: 0 and 240 are answers, -1 and 241 are not.
  UPDATE "SiteTravelTimes" SET minutes = 0 WHERE "siteAId" = least(norra, sodra);
  UPDATE "SiteTravelTimes" SET minutes = 240 WHERE "siteAId" = least(norra, sodra);
  FOREACH n IN ARRAY ARRAY[-1, 241] LOOP
    BEGIN
      UPDATE "SiteTravelTimes" SET minutes = n WHERE "siteAId" = least(norra, sodra);
      RAISE EXCEPTION 'sites: a travel time of % minutes was stored', n;
    EXCEPTION WHEN check_violation THEN NULL;
    END;
  END LOOP;
  -- A name: trimmed, 1..60, unique in the school.
  FOREACH st IN ARRAY ARRAY['', ' SO Väst', 'SO Väst ', repeat('x', 61)] LOOP
    BEGIN
      INSERT INTO "Sites" ("schoolId", name) VALUES (app.current_school_id(), st);
      RAISE EXCEPTION 'sites: a site named "%" was stored', st;
    EXCEPTION WHEN check_violation THEN NULL;
    END;
  END LOOP;
  BEGIN
    INSERT INTO "Sites" ("schoolId", name) VALUES (app.current_school_id(), 'SO Norra');
    RAISE EXCEPTION 'sites: two sites of the school share a name';
  EXCEPTION WHEN unique_violation THEN NULL;
  END;
  INSERT INTO "Sites" ("schoolId", name) VALUES (app.current_school_id(), repeat('x', 60));

  -- Another school's site, by its id: no pair with it, and no room on it.
  BEGIN
    INSERT INTO "SiteTravelTimes" ("schoolId", "siteAId", "siteBId", minutes)
    SELECT app.current_school_id(), least(norra, current_setting('app.test_so_other_site')::uuid),
           greatest(norra, current_setting('app.test_so_other_site')::uuid), 5;
    RAISE EXCEPTION 'sites: a travel time was stored to another school''s site';
  EXCEPTION WHEN foreign_key_violation THEN NULL;
  END;
  SELECT id INTO room FROM "Rooms" WHERE name = 'SO SO Norra';
  IF room IS NULL THEN RAISE EXCEPTION 'sites: the fixture''s room on Norra is not there'; END IF;
  BEGIN
    UPDATE "Rooms" SET "siteId" = current_setting('app.test_so_other_site')::uuid WHERE id = room;
    RAISE EXCEPTION 'sites: a room was put on another school''s site';
  EXCEPTION WHEN foreign_key_violation THEN NULL;
  END;
  UPDATE "Rooms" SET "siteId" = sodra WHERE id = room;
  UPDATE "Rooms" SET "siteId" = NULL WHERE id = room;
  UPDATE "Rooms" SET "siteId" = norra WHERE id = room;

  -- Norra goes: its pair goes with it, its room stays, without a site.
  DELETE FROM "Sites" WHERE id = norra;
  SELECT count(*) INTO n FROM "SiteTravelTimes";
  IF n <> 0 THEN RAISE EXCEPTION 'sites: % travel times outlived the site they named', n; END IF;
  SELECT count(*) INTO n FROM "Rooms" WHERE id = room AND "siteId" IS NULL;
  IF n <> 1 THEN RAISE EXCEPTION 'sites: the room on a removed site was removed with it, or kept the site'; END IF;
  SELECT count(*) INTO n FROM "Rooms" WHERE name = 'SO SO Södra' AND "siteId" = sodra;
  IF n <> 1 THEN RAISE EXCEPTION 'sites: the room on the other site lost its site'; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 183: ett rums skolområde flyttar ingen SS12000-version: S1:s Room
-- har ingen plats för det, och leverantören lämnar ut samma rum som förut
-- (20261124090000, app.ss12000_v_rooms från 20261014130000). Kapaciteten,
-- som rummet lämnas ut med, flyttar den: läsningen nedan ser alltså en
-- version som flyttas.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001240')::text, true);
SELECT set_config('app.test_so_school', app.current_school_id()::text, true);
SELECT set_config('app.test_so_room', (SELECT id::text FROM "Rooms" WHERE name = 'SO SO Norra'), true);
SELECT set_config('app.test_so_sodra', (SELECT id::text FROM "Sites" WHERE name = 'SO Södra'), true);
-- The version as it stands, read as the school's service principal.
SELECT set_config('request.jwt.claims', '', true);
SELECT set_config('app.service_school_id', current_setting('app.test_so_school'), true);
SELECT set_config('app.test_so_before',
  coalesce((SELECT "xid"::text FROM "Ss12000EntityVersions"
             WHERE resource = 'Room' AND "entityId" = current_setting('app.test_so_room')::uuid), ''), true);
SELECT set_config('app.service_school_id', '', true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001240')::text, true);
UPDATE "Rooms" SET "siteId" = current_setting('app.test_so_sodra')::uuid WHERE id = current_setting('app.test_so_room')::uuid;
SELECT set_config('request.jwt.claims', '', true);
SELECT set_config('app.service_school_id', current_setting('app.test_so_school'), true);
DO $$
DECLARE
  now_xid text;
BEGIN
  IF current_setting('app.test_so_before') = '' THEN
    RAISE EXCEPTION 'sites: the fixture''s room has no SS12000 version to compare';
  END IF;
  SELECT "xid"::text INTO now_xid FROM "Ss12000EntityVersions"
   WHERE resource = 'Room' AND "entityId" = current_setting('app.test_so_room')::uuid;
  IF now_xid IS DISTINCT FROM current_setting('app.test_so_before') THEN
    RAISE EXCEPTION 'sites: a room''s site moved its SS12000 version (% -> %)', current_setting('app.test_so_before'), now_xid;
  END IF;
END $$;
-- The control: what the room is emitted with does move it.
SELECT set_config('app.service_school_id', '', true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001240')::text, true);
UPDATE "Rooms" SET capacity = coalesce(capacity, 0) + 1 WHERE id = current_setting('app.test_so_room')::uuid;
SELECT set_config('request.jwt.claims', '', true);
SELECT set_config('app.service_school_id', current_setting('app.test_so_school'), true);
DO $$
BEGIN
  IF (SELECT "xid"::text FROM "Ss12000EntityVersions"
       WHERE resource = 'Room' AND "entityId" = current_setting('app.test_so_room')::uuid)
     IS NOT DISTINCT FROM current_setting('app.test_so_before') THEN
    RAISE EXCEPTION 'sites: a room''s capacity did not move its version either; the read above proves nothing';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 160: en lärares dagstak och önskade lediga dag sätts av den som
-- planerar (TeacherWorkRules_day_is_planned, 20261123090000).
--
-- In the matrix school, whose one teacher (111) has a work rule. The cap
-- ("maxTeachingMinutesPerDay") and the wish ("preferredFreeDayOfWeek") sit
-- on the row the teacher writes through teacher_work_rules_teacher_own,
-- which is FOR ALL, so row security alone would let the teacher raise or
-- erase what the administrator set. The trigger refuses that with AR403,
-- the token and the sentence areaRefusal (prisma-errors.ts) hands the web
-- as a 403, and DETAIL area=PLANERING:
--
--   * each column refuses a value outside its range by its own named CHECK
--     (prisma-errors.ts turns the name into a 400) and takes both its ends;
--   * the cap and the wish the fixtures wrote as the owner, with no person
--     signed in, are on the row;
--   * the schemaläggare (PLANERING) sets, changes and removes both, by
--     UPDATE, by the upsert the gateway writes and by DELETE, on the
--     teacher's row and on a row of their own: the trigger asks the area,
--     not whose row it is;
--   * the teacher, as each API role, puts neither on a fresh row (INSERT or
--     the upsert), changes or clears neither on the row they have (UPDATE or
--     the upsert), and deletes no row holding one; and still writes their
--     own lunch and rest with the two kept, restates either unchanged, and
--     deletes their row once it holds neither;
--   * THE UPSERT IS JUDGED AS THE UPDATE IT BECOMES. Postgres fires BEFORE
--     INSERT on the proposed row before it finds the conflict, and the
--     proposed row knows nothing of the stored one, so restating the cap
--     must pass, leaving it out must keep it, and raising or clearing it
--     must be refused; a fresh row carrying one is refused as the insert it
--     is;
--   * the expedition (PERSONAL, not PLANERING), which cannot touch the work
--     rule itself, removes a teacher who holds a cap, and the foreign key's
--     cascade takes the work rule along: the row is not the expedition's
--     own, so the trigger does not ask;
--   * neither the service principal nor the sync has an arm on the table:
--     with either setting alone nothing is read or written. With the
--     teacher's claims beside the setting the teacher's own arm admits the
--     row and the trigger lets the change through on the setting, the shape
--     it keeps for an arm a later migration gives either of them.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
SELECT set_config('app.test_rls160_planned',
  'AR403|WORK_RULE_DAY_IS_PLANNED: dagstaket och den önskade lediga dagen sätts av en administratör som planerar|area=PLANERING|',
  true);

-- 'sqlstate|message|detail|constraint' of a statement's refusal, or 'none'.
CREATE FUNCTION pg_temp.rls160_refusal(statement text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE st text; msg text; det text; con text;
BEGIN
  EXECUTE statement;
  RETURN 'none';
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, msg = MESSAGE_TEXT, det = PG_EXCEPTION_DETAIL, con = CONSTRAINT_NAME;
  RETURN st || '|' || msg || '|' || coalesce(det, '') || '|' || coalesce(con, '');
END $$;

-- The schemaläggare: the owner's values, the CHECKs, a row of their own, and
-- the teacher's row taken away, so the teacher below starts with none.
DO $$
DECLARE
  school uuid := app.current_school_id();
  planner uuid := app.current_user_id();
  teacher uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000111');
  got text;
  c record;
BEGIN
  IF app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' OR NOT app.current_user_may('PLANERING', true)
     OR (SELECT slug FROM "Schools" WHERE id = school) IS DISTINCT FROM 'rls-roller-school' THEN
    RAISE EXCEPTION 'day: expected the matrix school''s schemaläggare, who writes PLANERING';
  END IF;
  IF teacher IS NULL OR NOT EXISTS (SELECT 1 FROM "TeacherWorkRules" WHERE "userId" = teacher) THEN
    RAISE EXCEPTION 'day: the matrix school''s teacher or their work rule is missing; fixtures did not run';
  END IF;

  -- Written by the fixtures as the owner: no person, so the trigger let it be.
  IF NOT EXISTS (SELECT 1 FROM "TeacherWorkRules"
                  WHERE "userId" = teacher AND "maxTeachingMinutesPerDay" = 300 AND "preferredFreeDayOfWeek" = 5) THEN
    RAISE EXCEPTION 'day: the cap and the wish the owner wrote are not on the teacher''s row: %',
      (SELECT row_to_json(w) FROM "TeacherWorkRules" w WHERE "userId" = teacher);
  END IF;

  FOR c IN SELECT * FROM (VALUES
      ('"maxTeachingMinutesPerDay" = 25', 'TeacherWorkRules_maxTeachingMinutesPerDay_check'),
      ('"maxTeachingMinutesPerDay" = 725', 'TeacherWorkRules_maxTeachingMinutesPerDay_check'),
      -- Inside the range, off the five-minute grid the engine plans on.
      ('"maxTeachingMinutesPerDay" = 302', 'TeacherWorkRules_maxTeachingMinutesPerDay_check'),
      ('"maxTeachingMinutesPerDay" = 0', 'TeacherWorkRules_maxTeachingMinutesPerDay_check'),
      ('"preferredFreeDayOfWeek" = 0', 'TeacherWorkRules_preferredFreeDayOfWeek_check'),
      ('"preferredFreeDayOfWeek" = 8', 'TeacherWorkRules_preferredFreeDayOfWeek_check')
    ) AS t(assignment, constraint_name)
  LOOP
    got := pg_temp.rls160_refusal(format('UPDATE "TeacherWorkRules" SET %s WHERE "userId" = %L', c.assignment, teacher));
    IF split_part(got, '|', 1) <> '23514' OR split_part(got, '|', 4) IS DISTINCT FROM c.constraint_name THEN
      RAISE EXCEPTION 'day: % was answered "%", not by %', c.assignment, got, c.constraint_name;
    END IF;
  END LOOP;
  UPDATE "TeacherWorkRules" SET "maxTeachingMinutesPerDay" = 30, "preferredFreeDayOfWeek" = 1 WHERE "userId" = teacher;
  IF NOT FOUND THEN RAISE EXCEPTION 'day: the schemaläggare could not set the lowest cap and Monday'; END IF;
  UPDATE "TeacherWorkRules" SET "maxTeachingMinutesPerDay" = 720, "preferredFreeDayOfWeek" = 7 WHERE "userId" = teacher;
  IF NOT FOUND THEN RAISE EXCEPTION 'day: the schemaläggare could not set the highest cap and Sunday'; END IF;

  -- A schemaläggare who teaches: their own row is theirs to plan.
  INSERT INTO "TeacherWorkRules" ("schoolId", "userId", "maxTeachingMinutesPerDay", "preferredFreeDayOfWeek", "updatedAt")
  VALUES (school, planner, 240, 3, now());
  UPDATE "TeacherWorkRules" SET "maxTeachingMinutesPerDay" = 360, "preferredFreeDayOfWeek" = NULL WHERE "userId" = planner;
  IF NOT FOUND THEN RAISE EXCEPTION 'day: the schemaläggare could not change their own cap'; END IF;
  DELETE FROM "TeacherWorkRules" WHERE "userId" = planner;
  IF NOT FOUND THEN RAISE EXCEPTION 'day: the schemaläggare could not remove their own row holding a cap'; END IF;

  DELETE FROM "TeacherWorkRules" WHERE "userId" = teacher;
  IF NOT FOUND THEN RAISE EXCEPTION 'day: the schemaläggare could not remove the teacher''s row holding a cap'; END IF;
  PERFORM set_config('app.test_rls160', json_build_object('school', school, 'teacher', teacher)::text, true);
END $$;

-- The teacher with no row, as each role: no fresh row carries either, and
-- one without them is theirs to write and to delete.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000111')::text, true);
DO $$
DECLARE
  t jsonb := current_setting('app.test_rls160')::jsonb;
  school uuid := (t ->> 'school')::uuid;
  me uuid := app.current_user_id();
  planned text := current_setting('app.test_rls160_planned');
  via text;
  got text;
  c record;
BEGIN
  IF me IS DISTINCT FROM (t ->> 'teacher')::uuid OR app.current_user_role() IS DISTINCT FROM 'TEACHER' THEN
    RAISE EXCEPTION 'day: expected the matrix school''s teacher, am % (%)', app.current_user_role(), me;
  END IF;
  FOREACH via IN ARRAY ARRAY['authenticated', 'app_authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    IF current_user <> via THEN RAISE EXCEPTION 'day: running as %, not %', current_user, via; END IF;
    IF EXISTS (SELECT 1 FROM "TeacherWorkRules" WHERE "userId" = me) THEN
      RAISE EXCEPTION 'day: the teacher starts with a row as %', via;
    END IF;
    FOR c IN SELECT * FROM (VALUES
        ('an INSERT carrying a cap',
         'INSERT INTO "TeacherWorkRules" ("schoolId", "userId", "maxTeachingMinutesPerDay", "updatedAt") VALUES (%2$L, %1$L, 300, now())'),
        ('an INSERT carrying a wish',
         'INSERT INTO "TeacherWorkRules" ("schoolId", "userId", "preferredFreeDayOfWeek", "updatedAt") VALUES (%2$L, %1$L, 5, now())'),
        ('an upsert carrying a cap',
         'INSERT INTO "TeacherWorkRules" ("schoolId", "userId", "maxTeachingMinutesPerDay", "updatedAt") VALUES (%2$L, %1$L, 300, now())
          ON CONFLICT ("userId") DO UPDATE SET "maxTeachingMinutesPerDay" = EXCLUDED."maxTeachingMinutesPerDay", "updatedAt" = EXCLUDED."updatedAt"'),
        ('an upsert carrying a wish',
         'INSERT INTO "TeacherWorkRules" ("schoolId", "userId", "preferredFreeDayOfWeek", "updatedAt") VALUES (%2$L, %1$L, 5, now())
          ON CONFLICT ("userId") DO UPDATE SET "preferredFreeDayOfWeek" = EXCLUDED."preferredFreeDayOfWeek", "updatedAt" = EXCLUDED."updatedAt"')
      ) AS x(what, statement)
    LOOP
      got := pg_temp.rls160_refusal(format(c.statement, me, school));
      IF got IS DISTINCT FROM planned THEN
        RAISE EXCEPTION 'day: % on a fresh row as % was answered "%"', c.what, via, got;
      END IF;
    END LOOP;

    -- The lunch and the rest, as the gateway writes them: the upsert, here a
    -- fresh row.
    INSERT INTO "TeacherWorkRules"
      ("schoolId", "userId", "lunchMinutes", "lunchStartTime", "lunchEndTime", "minDailyRestMinutes", "updatedAt")
    VALUES (school, me, 30, '10:30', '13:30', 660, now())
    ON CONFLICT ("userId") DO UPDATE SET "lunchMinutes" = EXCLUDED."lunchMinutes", "lunchStartTime" = EXCLUDED."lunchStartTime",
      "lunchEndTime" = EXCLUDED."lunchEndTime", "minDailyRestMinutes" = EXCLUDED."minDailyRestMinutes", "updatedAt" = EXCLUDED."updatedAt";
    IF NOT EXISTS (SELECT 1 FROM "TeacherWorkRules" WHERE "userId" = me AND "lunchMinutes" = 30 AND "minDailyRestMinutes" = 660
                      AND "maxTeachingMinutesPerDay" IS NULL AND "preferredFreeDayOfWeek" IS NULL) THEN
      RAISE EXCEPTION 'day: the teacher could not write their own lunch and rest on a fresh row as %', via;
    END IF;
    DELETE FROM "TeacherWorkRules" WHERE "userId" = me;
    IF NOT FOUND THEN RAISE EXCEPTION 'day: the teacher could not delete their own row holding neither as %', via; END IF;
  END LOOP;
  SET LOCAL ROLE app_authenticated;
END $$;

-- The schemaläggare plans the teacher's day through the gateway's upsert:
-- first a fresh row, then the update it becomes.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
DO $$
DECLARE
  t jsonb := current_setting('app.test_rls160')::jsonb;
  cap integer;
  wish integer;
BEGIN
  FOREACH cap IN ARRAY ARRAY[240, 300] LOOP
    wish := cap / 60;
    INSERT INTO "TeacherWorkRules" ("schoolId", "userId", "maxTeachingMinutesPerDay", "preferredFreeDayOfWeek", "updatedAt")
    VALUES ((t ->> 'school')::uuid, (t ->> 'teacher')::uuid, cap, wish, now())
    ON CONFLICT ("userId") DO UPDATE SET "maxTeachingMinutesPerDay" = EXCLUDED."maxTeachingMinutesPerDay",
      "preferredFreeDayOfWeek" = EXCLUDED."preferredFreeDayOfWeek", "updatedAt" = EXCLUDED."updatedAt";
    IF NOT EXISTS (SELECT 1 FROM "TeacherWorkRules" WHERE "userId" = (t ->> 'teacher')::uuid
                      AND "maxTeachingMinutesPerDay" = cap AND "preferredFreeDayOfWeek" = wish) THEN
      RAISE EXCEPTION 'day: the schemaläggare''s upsert did not leave a cap of % and day %', cap, wish;
    END IF;
  END LOOP;
END $$;

-- The teacher with a cap of 300 and Friday, as each role.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000111')::text, true);
DO $$
DECLARE
  t jsonb := current_setting('app.test_rls160')::jsonb;
  school uuid := (t ->> 'school')::uuid;
  me uuid := app.current_user_id();
  planned text := current_setting('app.test_rls160_planned');
  via text;
  got text;
  c record;
BEGIN
  FOREACH via IN ARRAY ARRAY['authenticated', 'app_authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    IF current_user <> via THEN RAISE EXCEPTION 'day: running as %, not %', current_user, via; END IF;
    FOR c IN SELECT * FROM (VALUES
        ('raising the cap', 'UPDATE "TeacherWorkRules" SET "maxTeachingMinutesPerDay" = 360 WHERE "userId" = %1$L'),
        ('lowering the cap', 'UPDATE "TeacherWorkRules" SET "maxTeachingMinutesPerDay" = 240 WHERE "userId" = %1$L'),
        ('clearing the cap', 'UPDATE "TeacherWorkRules" SET "maxTeachingMinutesPerDay" = NULL WHERE "userId" = %1$L'),
        ('moving the wish', 'UPDATE "TeacherWorkRules" SET "preferredFreeDayOfWeek" = 3 WHERE "userId" = %1$L'),
        ('clearing the wish', 'UPDATE "TeacherWorkRules" SET "preferredFreeDayOfWeek" = NULL WHERE "userId" = %1$L'),
        ('deleting the row', 'DELETE FROM "TeacherWorkRules" WHERE "userId" = %1$L'),
        ('an upsert raising the cap',
         'INSERT INTO "TeacherWorkRules" ("schoolId", "userId", "maxTeachingMinutesPerDay", "updatedAt") VALUES (%2$L, %1$L, 360, now())
          ON CONFLICT ("userId") DO UPDATE SET "maxTeachingMinutesPerDay" = EXCLUDED."maxTeachingMinutesPerDay", "updatedAt" = EXCLUDED."updatedAt"'),
        ('an upsert clearing the cap',
         'INSERT INTO "TeacherWorkRules" ("schoolId", "userId", "maxTeachingMinutesPerDay", "updatedAt") VALUES (%2$L, %1$L, NULL, now())
          ON CONFLICT ("userId") DO UPDATE SET "maxTeachingMinutesPerDay" = EXCLUDED."maxTeachingMinutesPerDay", "updatedAt" = EXCLUDED."updatedAt"'),
        ('an upsert moving the wish',
         'INSERT INTO "TeacherWorkRules" ("schoolId", "userId", "preferredFreeDayOfWeek", "updatedAt") VALUES (%2$L, %1$L, 3, now())
          ON CONFLICT ("userId") DO UPDATE SET "preferredFreeDayOfWeek" = EXCLUDED."preferredFreeDayOfWeek", "updatedAt" = EXCLUDED."updatedAt"'),
        ('an upsert clearing the wish',
         'INSERT INTO "TeacherWorkRules" ("schoolId", "userId", "preferredFreeDayOfWeek", "updatedAt") VALUES (%2$L, %1$L, NULL, now())
          ON CONFLICT ("userId") DO UPDATE SET "preferredFreeDayOfWeek" = EXCLUDED."preferredFreeDayOfWeek", "updatedAt" = EXCLUDED."updatedAt"')
      ) AS x(what, statement)
    LOOP
      got := pg_temp.rls160_refusal(format(c.statement, me, school));
      IF got IS DISTINCT FROM planned THEN
        RAISE EXCEPTION 'day: % as % was answered "%"', c.what, via, got;
      END IF;
    END LOOP;

    -- A plain INSERT beside the stored row: the trigger leaves it to the
    -- update it never becomes, and the unique key answers, never a write.
    got := pg_temp.rls160_refusal(format(
      'INSERT INTO "TeacherWorkRules" ("schoolId", "userId", "maxTeachingMinutesPerDay", "updatedAt") VALUES (%L, %L, 360, now())',
      school, me));
    IF split_part(got, '|', 1) <> '23505' THEN
      RAISE EXCEPTION 'day: an INSERT beside the stored row as % was answered "%", not by the unique key', via, got;
    END IF;

    -- What stays the teacher's: the lunch and the rest by UPDATE, with the
    -- cap and the wish restated unchanged.
    UPDATE "TeacherWorkRules"
       SET "lunchMinutes" = 30, "lunchStartTime" = '10:30', "lunchEndTime" = '13:30', "minDailyRestMinutes" = 660,
           "maxTeachingMinutesPerDay" = 300, "preferredFreeDayOfWeek" = 5, "updatedAt" = now()
     WHERE "userId" = me;
    IF NOT FOUND THEN RAISE EXCEPTION 'day: the teacher could not write their own lunch and rest as %', via; END IF;

    -- The upsert restating both passes: its insert finds the stored row and
    -- its update changes neither.
    INSERT INTO "TeacherWorkRules"
      ("schoolId", "userId", "maxTeachingMinutesPerDay", "preferredFreeDayOfWeek", "lunchMinutes", "lunchStartTime", "lunchEndTime", "updatedAt")
    VALUES (school, me, 300, 5, 45, '11:00', '13:00', now())
    ON CONFLICT ("userId") DO UPDATE SET "maxTeachingMinutesPerDay" = EXCLUDED."maxTeachingMinutesPerDay",
      "preferredFreeDayOfWeek" = EXCLUDED."preferredFreeDayOfWeek", "lunchMinutes" = EXCLUDED."lunchMinutes",
      "lunchStartTime" = EXCLUDED."lunchStartTime", "lunchEndTime" = EXCLUDED."lunchEndTime", "updatedAt" = EXCLUDED."updatedAt";
    IF NOT EXISTS (SELECT 1 FROM "TeacherWorkRules" WHERE "userId" = me AND "lunchMinutes" = 45) THEN
      RAISE EXCEPTION 'day: the teacher''s upsert restating the cap and the wish wrote no lunch as %', via;
    END IF;

    -- And the upsert naming neither keeps both: what the gateway sends for a
    -- teacher, who has the two removed from create and update alike.
    INSERT INTO "TeacherWorkRules"
      ("schoolId", "userId", "lunchMinutes", "lunchStartTime", "lunchEndTime", "minDailyRestMinutes", "updatedAt")
    VALUES (school, me, 40, '11:00', '13:00', 600, now())
    ON CONFLICT ("userId") DO UPDATE SET "lunchMinutes" = EXCLUDED."lunchMinutes", "lunchStartTime" = EXCLUDED."lunchStartTime",
      "lunchEndTime" = EXCLUDED."lunchEndTime", "minDailyRestMinutes" = EXCLUDED."minDailyRestMinutes", "updatedAt" = EXCLUDED."updatedAt";
    IF NOT EXISTS (SELECT 1 FROM "TeacherWorkRules" WHERE "userId" = me AND "lunchMinutes" = 40 AND "minDailyRestMinutes" = 600
                      AND "maxTeachingMinutesPerDay" = 300 AND "preferredFreeDayOfWeek" = 5) THEN
      RAISE EXCEPTION 'day: the teacher''s upsert naming neither left %, not the cap and the wish kept, as %',
        (SELECT row_to_json(w) FROM "TeacherWorkRules" w WHERE "userId" = me), via;
    END IF;
  END LOOP;
  SET LOCAL ROLE app_authenticated;

  -- The service principal and the sync. Alone, neither reads or writes a
  -- work rule; beside the teacher's claims, the setting lets the cap through.
  FOREACH via IN ARRAY ARRAY['app.service_school_id', 'app.sync_school_id'] LOOP
    PERFORM set_config(via, school::text, true);
    UPDATE "TeacherWorkRules" SET "maxTeachingMinutesPerDay" = 360 WHERE "userId" = me;
    IF NOT FOUND THEN RAISE EXCEPTION 'day: with % beside the teacher, the cap was refused', via; END IF;
    UPDATE "TeacherWorkRules" SET "maxTeachingMinutesPerDay" = 300 WHERE "userId" = me;
    PERFORM set_config(via, '', true);
  END LOOP;
  PERFORM set_config('request.jwt.claims', '', true);
  FOREACH via IN ARRAY ARRAY['app.service_school_id', 'app.sync_school_id'] LOOP
    PERFORM set_config(via, school::text, true);
    IF EXISTS (SELECT 1 FROM "TeacherWorkRules") THEN RAISE EXCEPTION 'day: % reads a work rule', via; END IF;
    UPDATE "TeacherWorkRules" SET "updatedAt" = now();
    IF FOUND THEN RAISE EXCEPTION 'day: % wrote a work rule', via; END IF;
    PERFORM set_config(via, '', true);
  END LOOP;
END $$;

-- The expedition takes on a teacher (PERSONAL), and the schemaläggare
-- plans their day.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000108')::text, true);
DO $$
DECLARE
  t jsonb := current_setting('app.test_rls160')::jsonb;
  newcomer uuid;
BEGIN
  IF app.current_user_may('PLANERING', true) OR NOT app.current_user_may('PERSONAL', true) THEN
    RAISE EXCEPTION 'day: expected the expedition (PERSONAL, not PLANERING)';
  END IF;
  INSERT INTO "Users" ("schoolId", email, "firstName", "lastName", role, "authId", "isActive", "updatedAt")
  VALUES ((t ->> 'school')::uuid, 'rls160-newcomer@example.invalid', 'RLS160', 'Nykomling', 'TEACHER',
          '00000000-0000-4000-8000-000000000160', true, now())
  RETURNING id INTO newcomer;
  PERFORM set_config('app.test_rls160', (t || jsonb_build_object('newcomer', newcomer))::text, true);
END $$;

SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
DO $$
DECLARE
  t jsonb := current_setting('app.test_rls160')::jsonb;
BEGIN
  INSERT INTO "TeacherWorkRules" ("schoolId", "userId", "maxTeachingMinutesPerDay", "preferredFreeDayOfWeek", "updatedAt")
  VALUES ((t ->> 'school')::uuid, (t ->> 'newcomer')::uuid, 240, 2, now());
END $$;

-- The expedition removes the newcomer, and the cascade takes the cap along.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000108')::text, true);
DO $$
DECLARE
  t jsonb := current_setting('app.test_rls160')::jsonb;
  newcomer uuid := (t ->> 'newcomer')::uuid;
  got text;
BEGIN
  -- Not by writing the rule itself, which is the arm's to refuse (42501):
  -- the trigger, asked first, lets the write on to the arm, since the row
  -- is not the expedition's own.
  got := pg_temp.rls160_refusal(format(
    'UPDATE "TeacherWorkRules" SET "maxTeachingMinutesPerDay" = NULL WHERE "userId" = %L', newcomer));
  IF split_part(got, '|', 1) <> '42501' OR got NOT LIKE '%row-level security%' THEN
    RAISE EXCEPTION 'day: the expedition''s write of a cap was answered "%", not by row security', got;
  END IF;
  DELETE FROM "Users" WHERE id = newcomer;
  IF NOT FOUND THEN RAISE EXCEPTION 'day: the expedition could not remove a teacher'; END IF;
  IF EXISTS (SELECT 1 FROM "TeacherWorkRules" WHERE "userId" = newcomer) THEN
    RAISE EXCEPTION 'day: the removed teacher''s work rule is still there';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 161: en tjänsts undervisningsdagar är tjänstens (20261123090000).
--
-- TeacherEmployments."maxTeachingDaysPerWeek", deltid in days, is HR data
-- beside the tjänstgöringsgrad, so it is 144's column again. In the läslogg
-- school the admin, who decides, writes teacher 122's days through the
-- API's role; the table refuses a figure outside 1–6 by the named CHECK
-- (prisma-errors.ts turns the name into a 400) and takes both ends. The
-- version a write of the days alone makes carries them, before and after:
-- the log records the row as JSON, so the column is logged with no change
-- to the trigger, and the gateway masks it for a reader without HR-läs
-- (hr-visibility.ts). Teacher 122 reads their own days on the post and in
-- its version, directly and through the API; teacher 126 reads nothing of
-- 122's post or its versions either way, as 129 holds for the row.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000121')::text, true);
SET LOCAL ROLE app_authenticated;
DO $$
DECLARE
  teacher uuid := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000122');
  post uuid;
  versions bigint;
  refused text;
  days integer;
  logged record;
BEGIN
  IF NOT app.current_user_decides() THEN RAISE EXCEPTION 'days: the läslogg school''s admin does not decide'; END IF;
  SELECT id INTO post FROM "TeacherEmployments" WHERE "userId" = teacher;
  IF post IS NULL THEN RAISE EXCEPTION 'days: teacher 122 has no post to write'; END IF;
  IF (SELECT "maxTeachingDaysPerWeek" FROM "TeacherEmployments" WHERE id = post) IS NOT NULL THEN
    RAISE EXCEPTION 'days: teacher 122''s post starts with a days figure';
  END IF;

  FOREACH days IN ARRAY ARRAY[0, 7, -1] LOOP
    BEGIN
      UPDATE "TeacherEmployments" SET "maxTeachingDaysPerWeek" = days WHERE id = post;
      RAISE EXCEPTION 'days: % days a week was written', days;
    EXCEPTION WHEN check_violation THEN
      GET STACKED DIAGNOSTICS refused = CONSTRAINT_NAME;
      IF refused IS DISTINCT FROM 'TeacherEmployments_maxTeachingDaysPerWeek_check' THEN
        RAISE EXCEPTION 'days: % days a week was refused by %', days, refused;
      END IF;
    END;
  END LOOP;
  FOREACH days IN ARRAY ARRAY[1, 6] LOOP
    UPDATE "TeacherEmployments" SET "maxTeachingDaysPerWeek" = days WHERE id = post;
    IF NOT FOUND THEN RAISE EXCEPTION 'days: the admin could not write % days a week', days; END IF;
  END LOOP;
  UPDATE "TeacherEmployments" SET "maxTeachingDaysPerWeek" = NULL WHERE id = post;

  SELECT count(*) INTO versions FROM "TeacherEmploymentLogs" WHERE "entityId" = post;
  UPDATE "TeacherEmployments" SET "maxTeachingDaysPerWeek" = 4 WHERE id = post;
  IF NOT FOUND THEN RAISE EXCEPTION 'days: the admin could not write the days through the API'; END IF;
  IF (SELECT count(*) FROM "TeacherEmploymentLogs" WHERE "entityId" = post) <> versions + 1 THEN
    RAISE EXCEPTION 'days: a write of the days alone made % versions, not one',
      (SELECT count(*) FROM "TeacherEmploymentLogs" WHERE "entityId" = post) - versions;
  END IF;
  SELECT action, before, after INTO logged FROM "TeacherEmploymentLogs"
   WHERE "entityId" = post ORDER BY version DESC LIMIT 1;
  IF logged.action IS DISTINCT FROM 'UPDATE'
     OR (logged.after ->> 'maxTeachingDaysPerWeek')::int IS DISTINCT FROM 4
     OR logged.before -> 'maxTeachingDaysPerWeek' IS DISTINCT FROM 'null'::jsonb THEN
    RAISE EXCEPTION 'days: the version holds % → %', logged.before, logged.after;
  END IF;
END $$;

SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000122')::text, true);
DO $$
DECLARE
  via text;
  got text;
BEGIN
  FOREACH via IN ARRAY ARRAY['authenticated', 'app_authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    IF current_user <> via THEN RAISE EXCEPTION 'days: running as %, not %', current_user, via; END IF;
    SELECT string_agg(coalesce("maxTeachingDaysPerWeek"::text, '-'), ',') INTO got
      FROM "TeacherEmployments" WHERE "userId" = app.current_user_id();
    IF got IS DISTINCT FROM '4' THEN
      RAISE EXCEPTION 'days: as % teacher 122 reads % of their own days', via, got;
    END IF;
    SELECT l.after ->> 'maxTeachingDaysPerWeek' INTO got FROM "TeacherEmploymentLogs" l
     WHERE l."userId" = app.current_user_id() AND l.entity = 'EMPLOYMENT' ORDER BY l.version DESC LIMIT 1;
    IF got IS DISTINCT FROM '4' THEN
      RAISE EXCEPTION 'days: as % teacher 122 reads % in their own post''s latest version', via, got;
    END IF;
  END LOOP;
END $$;

SET LOCAL ROLE app_authenticated;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000126')::text, true);
DO $$
DECLARE
  via text;
  n bigint;
BEGIN
  FOREACH via IN ARRAY ARRAY['authenticated', 'app_authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    IF current_user <> via THEN RAISE EXCEPTION 'days: running as %, not %', current_user, via; END IF;
    SELECT count(*) INTO n FROM "TeacherEmployments" WHERE "maxTeachingDaysPerWeek" IS NOT NULL;
    IF n <> 0 THEN RAISE EXCEPTION 'days: as % teacher 126 reads % colleague''s days', via, n; END IF;
    SELECT count(*) INTO n FROM "TeacherEmploymentLogs" WHERE "userId" <> app.current_user_id();
    IF n <> 0 THEN RAISE EXCEPTION 'days: as % teacher 126 reads % versions of a colleague''s post', via, n; END IF;
  END LOOP;
END $$;
SET LOCAL ROLE app_authenticated;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 162: generatorns körningar läses bara genom API:t
-- (20261123090100).
--
-- A run's stored refusal can say whose deltid the week could not keep (the
-- post, and the teachers in a field the gateway never answers with), which
-- the gateway rewrites for a reader without HR-läs when it answers
-- (src/optimization/optimization-jobs.service.ts); row security cannot
-- rewrite a column, so no other door may open the row. The catalogue:
-- OptimizationJobs has exactly the four administrator's arms, each the
-- API's role's alone (the gateway's arms of section 128, for this table);
-- no policy on another table reads it as the reader, and no function a
-- signed-in user may call reads it as its caller, either of which would
-- now answer empty. "notes", the wishes a finished run could not keep, is
-- jsonb and nullable with no default, so every run before it reads null.
--
-- Then the matrix school's schemaläggare, who writes SCHEMALAGGNING. Through
-- the API's role they read the school's run, start one and write its notes;
-- as PostgREST's role, in the same transaction, they read no run, start
-- none, and neither change, lock nor remove the one they just started;
-- through the API's role again it is as they left it.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  got text;
  col record;
BEGIN
  SELECT string_agg(policyname || ' ' || cmd || ' ' || roles::text, ', ' ORDER BY policyname) INTO got
    FROM pg_policies WHERE schemaname = 'public' AND tablename = 'OptimizationJobs';
  IF got IS DISTINCT FROM 'optimization_jobs_admin_delete DELETE {app_authenticated}, '
                       || 'optimization_jobs_admin_insert INSERT {app_authenticated}, '
                       || 'optimization_jobs_admin_select SELECT {app_authenticated}, '
                       || 'optimization_jobs_admin_update UPDATE {app_authenticated}' THEN
    RAISE EXCEPTION 'runs: OptimizationJobs'' arms are %, not the administrator''s four of the API''s role', got;
  END IF;

  SELECT string_agg(tablename || '.' || policyname, ', ') INTO got
    FROM pg_policies
   WHERE roles && ARRAY['authenticated', 'public']::name[]
     AND (coalesce(qual, '') || ' ' || coalesce(with_check, '')) LIKE '%"OptimizationJobs"%';
  IF got IS NOT NULL THEN
    RAISE EXCEPTION 'runs: % reads the runs as the reader, who now reads none', got;
  END IF;
  SELECT string_agg(n.nspname || '.' || p.proname, ', ') INTO got
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname IN ('public', 'app', 'sign_in', 'auth')
     AND NOT p.prosecdef
     AND p.prosrc LIKE '%"OptimizationJobs"%'
     AND (has_function_privilege('authenticated', p.oid, 'EXECUTE')
          OR (EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') AND has_function_privilege('anon', p.oid, 'EXECUTE')));
  IF got IS NOT NULL THEN
    RAISE EXCEPTION 'runs: % reads the runs as its caller and a signed-in user may call it', got;
  END IF;

  SELECT format_type(a.atttypid, a.atttypmod) AS type, a.attnotnull, a.atthasdef INTO col
    FROM pg_attribute a
   WHERE a.attrelid = 'public."OptimizationJobs"'::regclass AND a.attname = 'notes' AND NOT a.attisdropped;
  IF col.type IS DISTINCT FROM 'jsonb' OR col.attnotnull OR col.atthasdef THEN
    RAISE EXCEPTION 'runs: "notes" is %, not a nullable jsonb with no default', coalesce(row_to_json(col)::text, 'missing');
  END IF;
END $$;

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
DO $$
DECLARE
  school uuid := app.current_school_id();
  yr uuid;
  run uuid;
  seen bigint;
  n bigint;
  st text;
  msg text;
BEGIN
  IF app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' OR NOT app.current_user_may('SCHEMALAGGNING', true)
     OR (SELECT slug FROM "Schools" WHERE id = school) IS DISTINCT FROM 'rls-roller-school' THEN
    RAISE EXCEPTION 'runs: expected the matrix school''s schemaläggare, who writes SCHEMALAGGNING';
  END IF;
  SET LOCAL ROLE app_authenticated;
  SELECT count(*) INTO seen FROM "OptimizationJobs";
  IF seen = 0 THEN RAISE EXCEPTION 'runs: the schemaläggare reads no run through the API; fixtures did not run'; END IF;
  IF EXISTS (SELECT 1 FROM "OptimizationJobs" WHERE notes IS NOT NULL) THEN
    RAISE EXCEPTION 'runs: a run the fixtures planted has notes';
  END IF;
  SELECT id INTO yr FROM "AcademicYears" WHERE "schoolId" = school ORDER BY "isActive" DESC, id LIMIT 1;
  INSERT INTO "OptimizationJobs" ("schoolId", "academicYearId", "actorId")
  VALUES (school, yr, app.current_user_id()) RETURNING id INTO run;
  IF (SELECT notes FROM "OptimizationJobs" WHERE id = run) IS NOT NULL THEN
    RAISE EXCEPTION 'runs: a new run has notes before it has run';
  END IF;
  UPDATE "OptimizationJobs"
     SET status = 'SUCCEEDED', "finishedAt" = now(),
         notes = jsonb_build_array(jsonb_build_object('code', 'TEACHER_FREE_DAY_WISH_NOT_KEPT', 'category', 'AVAILABILITY',
                                                      'params', jsonb_build_object('day', 5), 'subjectIds', jsonb_build_array(gen_random_uuid())))
   WHERE id = run;
  IF NOT FOUND THEN RAISE EXCEPTION 'runs: the schemaläggare could not finish a run through the API'; END IF;

  SET LOCAL ROLE authenticated;
  IF current_user <> 'authenticated' THEN RAISE EXCEPTION 'runs: could not act as authenticated'; END IF;
  SELECT count(*) INTO n FROM "OptimizationJobs";
  IF n <> 0 THEN RAISE EXCEPTION 'runs: as PostgREST''s role the schemaläggare reads % run(s)', n; END IF;
  BEGIN
    INSERT INTO "OptimizationJobs" ("schoolId", "academicYearId") VALUES (school, yr);
    RAISE EXCEPTION 'runs: as PostgREST''s role the schemaläggare started a run';
  EXCEPTION WHEN insufficient_privilege THEN
    GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
    IF msg NOT LIKE '%row-level security%' THEN
      RAISE EXCEPTION 'runs: PostgREST''s start of a run was refused by "%", not by row security', msg;
    END IF;
  END;
  -- No WHERE: a predicate on a column would also need a read arm, and a
  -- write arm alone would hide behind it.
  UPDATE "OptimizationJobs" SET "finishedAt" = now();
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'runs: as PostgREST''s role the schemaläggare changed % run(s)', n; END IF;
  SELECT count(*) INTO n FROM (SELECT 1 FROM "OptimizationJobs" FOR UPDATE) locked;
  IF n <> 0 THEN RAISE EXCEPTION 'runs: as PostgREST''s role the schemaläggare locked % run(s)', n; END IF;
  DELETE FROM "OptimizationJobs";
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'runs: as PostgREST''s role the schemaläggare removed % run(s)', n; END IF;

  SET LOCAL ROLE app_authenticated;
  SELECT count(*) INTO n FROM "OptimizationJobs";
  IF n <> seen + 1 THEN RAISE EXCEPTION 'runs: through the API the schemaläggare reads % runs, not %', n, seen + 1; END IF;
  IF NOT EXISTS (SELECT 1 FROM "OptimizationJobs"
                  WHERE id = run AND status = 'SUCCEEDED' AND notes -> 0 ->> 'code' = 'TEACHER_FREE_DAY_WISH_NOT_KEPT') THEN
    RAISE EXCEPTION 'runs: the run the API finished is not as it was left';
  END IF;
END $$;
SET LOCAL ROLE app_authenticated;
ROLLBACK;

-- Section 170: schemaförslag, katalogen (20261125090000, 20261127090000).
--
-- What sections 171-178 prove by acting, read from the catalogue, where a
-- later migration that loosens one shows up even on a path no section walks.
-- Both tables have row security, not forced on the owner the two functions
-- run as, and exactly the administrator's arms, each TO app_authenticated,
-- each asking the tenant and the role in every expression it applies, none
-- with an OR that could admit a row past them (section 106 holds the areas
-- to src/auth/admin-areas.ts); a candidate has no update arm. The API's role
-- holds what the arms use and nothing past it: no UPDATE of a candidate, no
-- TRUNCATE, REFERENCES or TRIGGER, and no MAINTAIN on 17. service_role
-- reads and does nothing else; PostgREST's authenticated, anon and PUBLIC
-- hold nothing, not one column. The sweep and the count are SECURITY DEFINER
-- with a pinned search_path, return a number, are owned by no API role and
-- are the API's role's alone to call, PUBLIC included; the sweep takes both
-- of its row sets FOR UPDATE SKIP LOCKED, and the count is STABLE. The three
-- keys are the migration's (a candidate's run and a run's year are composite
-- tenant keys) and each cascades, so a school, a year or a run takes its
-- rows along; neither table has a key to anything else, so no live table is
-- in its locks. One active run per year is a partial unique index, every
-- CHECK is in place and validated — the free-day wishes' two of
-- 20261127090000 among them, which added columns and no grant — and the
-- statuses are the five the gateway writes.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  t text;
  r text;
  p text;
  fn text;
  f oid;
  c text;
  bad text;
  got text[];
  idx record;
  api_roles constant text[] := ARRAY['app_authenticated', 'authenticated', 'anon', 'service_role'];
  maintain constant text[] := CASE WHEN current_setting('server_version_num')::int >= 170000
                                   THEN ARRAY['MAINTAIN'] ELSE '{}' END;
BEGIN
  FOREACH t IN ARRAY ARRAY['ScheduleCandidateRuns', 'ScheduleCandidates'] LOOP
    IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = format('public.%I', t)::regclass) THEN
      RAISE EXCEPTION 'candidates catalogue: % has no row security', t;
    END IF;
    -- The sweep and the count read as the owner, past row security; forced
    -- on the owner (who on Supabase is no superuser) they would see no row.
    IF (SELECT relforcerowsecurity FROM pg_class WHERE oid = format('public.%I', t)::regclass) THEN
      RAISE EXCEPTION 'candidates catalogue: % forces row security on its owner', t;
    END IF;
  END LOOP;

  -- The arms, by name, command and role.
  SELECT array_agg(format('%s.%s %s %s', tablename, policyname, cmd, roles) ORDER BY tablename COLLATE "C", policyname COLLATE "C")
    INTO got
    FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('ScheduleCandidateRuns', 'ScheduleCandidates');
  IF got IS DISTINCT FROM ARRAY[
       'ScheduleCandidateRuns.schedule_candidate_runs_admin_delete DELETE {app_authenticated}',
       'ScheduleCandidateRuns.schedule_candidate_runs_admin_insert INSERT {app_authenticated}',
       'ScheduleCandidateRuns.schedule_candidate_runs_admin_select SELECT {app_authenticated}',
       'ScheduleCandidateRuns.schedule_candidate_runs_admin_update UPDATE {app_authenticated}',
       'ScheduleCandidates.schedule_candidates_admin_delete DELETE {app_authenticated}',
       'ScheduleCandidates.schedule_candidates_admin_insert INSERT {app_authenticated}',
       'ScheduleCandidates.schedule_candidates_admin_select SELECT {app_authenticated}'] THEN
    RAISE EXCEPTION 'candidates catalogue: the arms are %', got;
  END IF;
  -- Every expression an arm applies names the school and the role, and no OR
  -- lets a row past them; an insert or update arm has its WITH CHECK.
  SELECT string_agg(format('%s.%s', p.tablename, p.policyname), ', ') INTO bad
    FROM pg_policies p
   WHERE p.schemaname = 'public' AND p.tablename IN ('ScheduleCandidateRuns', 'ScheduleCandidates')
     AND ((p.cmd IN ('INSERT', 'UPDATE') AND p.with_check IS NULL)
          OR (p.cmd <> 'INSERT' AND p.qual IS NULL)
          OR EXISTS (SELECT 1 FROM unnest(ARRAY[p.qual, p.with_check]) e(expr)
                      WHERE e.expr IS NOT NULL
                        AND (e.expr NOT LIKE '%"schoolId" = ( SELECT app.current_school_id() AS current_school_id)%'
                             OR e.expr NOT LIKE '%( SELECT app.current_user_role() AS current_user_role) = ''SCHOOL_ADMIN''::"UserRole"%'
                             OR e.expr ~ '\mOR\M')));
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'candidates catalogue: these arms do not keep to the school''s administrators: %', bad;
  END IF;

  -- The API's role: what the arms use, and a candidate is written once.
  FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE'] LOOP
    IF NOT has_table_privilege('app_authenticated', '"ScheduleCandidateRuns"', p) THEN
      RAISE EXCEPTION 'candidates catalogue: the API may not % a run', p;
    END IF;
    IF has_table_privilege('app_authenticated', '"ScheduleCandidates"', p) IS DISTINCT FROM (p <> 'UPDATE') THEN
      RAISE EXCEPTION 'candidates catalogue: the API''s % on the candidates is %', p,
        has_table_privilege('app_authenticated', '"ScheduleCandidates"', p);
    END IF;
  END LOOP;
  IF has_any_column_privilege('app_authenticated', '"ScheduleCandidates"', 'UPDATE') THEN
    RAISE EXCEPTION 'candidates catalogue: the API may update a column of a candidate, which is written once';
  END IF;
  FOREACH t IN ARRAY ARRAY['"ScheduleCandidateRuns"', '"ScheduleCandidates"'] LOOP
    FOREACH p IN ARRAY ARRAY['TRUNCATE', 'REFERENCES', 'TRIGGER'] || maintain LOOP
      IF has_table_privilege('app_authenticated', t, p) THEN
        RAISE EXCEPTION 'candidates catalogue: the API holds % on %', p, t;
      END IF;
    END LOOP;
    -- PUBLIC has no entry, on the table or on a column.
    IF EXISTS (SELECT 1 FROM pg_class cl, aclexplode(coalesce(cl.relacl, acldefault('r', cl.relowner))) a
                WHERE cl.oid = t::regclass AND a.grantee = 0)
       OR EXISTS (SELECT 1 FROM pg_attribute att, aclexplode(att.attacl) a
                   WHERE att.attrelid = t::regclass AND att.attacl IS NOT NULL AND a.grantee = 0) THEN
      RAISE EXCEPTION 'candidates catalogue: PUBLIC holds a privilege on %', t;
    END IF;
    -- PostgREST's role and anon: nothing, not one column.
    FOREACH r IN ARRAY ARRAY['authenticated', 'anon'] LOOP
      CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
      FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] || maintain LOOP
        IF has_table_privilege(r, t, p) THEN RAISE EXCEPTION 'candidates catalogue: % holds % on %', r, p, t; END IF;
      END LOOP;
      FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'REFERENCES'] LOOP
        IF has_any_column_privilege(r, t, p) THEN RAISE EXCEPTION 'candidates catalogue: % may % a column of %', r, p, t; END IF;
      END LOOP;
    END LOOP;
    -- service_role reads, and does nothing else.
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
      IF NOT has_table_privilege('service_role', t, 'SELECT') THEN
        RAISE EXCEPTION 'candidates catalogue: service_role may not read %', t;
      END IF;
      FOREACH p IN ARRAY ARRAY['INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] || maintain LOOP
        IF has_table_privilege('service_role', t, p) THEN RAISE EXCEPTION 'candidates catalogue: service_role holds % on %', p, t; END IF;
      END LOOP;
      FOREACH p IN ARRAY ARRAY['INSERT', 'UPDATE', 'REFERENCES'] LOOP
        IF has_any_column_privilege('service_role', t, p) THEN
          RAISE EXCEPTION 'candidates catalogue: service_role may % a column of %', p, t;
        END IF;
      END LOOP;
    END IF;
    IF (SELECT relowner FROM pg_class WHERE oid = t::regclass) IN (SELECT oid FROM pg_roles WHERE rolname = ANY (api_roles)) THEN
      RAISE EXCEPTION 'candidates catalogue: % is owned by an API role', t;
    END IF;
  END LOOP;

  -- The sweep and the count.
  FOREACH fn IN ARRAY ARRAY['app.schedule_candidates_sweep()', 'app.schedule_candidate_runs_active()'] LOOP
    f := to_regprocedure(fn);
    IF f IS NULL THEN RAISE EXCEPTION 'candidates catalogue: % is missing', fn; END IF;
    IF NOT (SELECT prosecdef FROM pg_proc WHERE oid = f) THEN
      RAISE EXCEPTION 'candidates catalogue: % runs as its caller', fn;
    END IF;
    IF NOT coalesce((SELECT 'search_path="public", "pg_temp"' = ANY (proconfig) OR 'search_path=public, pg_temp' = ANY (proconfig)
                       FROM pg_proc WHERE oid = f), false) THEN
      RAISE EXCEPTION 'candidates catalogue: % has no pinned search_path (%)', fn, (SELECT proconfig FROM pg_proc WHERE oid = f);
    END IF;
    IF pg_get_function_result(f) IS DISTINCT FROM 'integer' THEN
      RAISE EXCEPTION 'candidates catalogue: % answers %, not a number', fn, pg_get_function_result(f);
    END IF;
    IF (SELECT proowner FROM pg_proc WHERE oid = f) IN (SELECT oid FROM pg_roles WHERE rolname = ANY (api_roles)) THEN
      RAISE EXCEPTION 'candidates catalogue: % is owned by an API role', fn;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_proc pr, aclexplode(coalesce(pr.proacl, acldefault('f', pr.proowner))) a
                WHERE pr.oid = f AND a.grantee = 0) THEN
      RAISE EXCEPTION 'candidates catalogue: PUBLIC may call %', fn;
    END IF;
    IF NOT has_function_privilege('app_authenticated', f, 'EXECUTE') THEN
      RAISE EXCEPTION 'candidates catalogue: the API may not call %', fn;
    END IF;
    FOREACH r IN ARRAY ARRAY['authenticated', 'anon', 'service_role'] LOOP
      CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
      IF has_function_privilege(r, f, 'EXECUTE') THEN RAISE EXCEPTION 'candidates catalogue: % may call %', r, fn; END IF;
    END LOOP;
  END LOOP;
  IF (SELECT provolatile FROM pg_proc WHERE oid = 'app.schedule_candidate_runs_active()'::regprocedure) <> 's' THEN
    RAISE EXCEPTION 'candidates catalogue: the count is not STABLE';
  END IF;

  -- A hand edit's share of the regeneration lock: the caller's own
  -- privileges (it reads and writes nothing), a pinned search_path, and the
  -- API's EXECUTE alone.
  f := to_regprocedure('app.lock_years_for_grundschema_edit(uuid[])');
  IF f IS NULL THEN RAISE EXCEPTION 'candidates catalogue: app.lock_years_for_grundschema_edit(uuid[]) is missing'; END IF;
  IF (SELECT prosecdef FROM pg_proc WHERE oid = f) THEN
    RAISE EXCEPTION 'candidates catalogue: the edit lock runs as its owner, and needs nothing of the owner''s';
  END IF;
  IF NOT coalesce((SELECT 'search_path="public", "pg_temp"' = ANY (proconfig) OR 'search_path=public, pg_temp' = ANY (proconfig)
                     FROM pg_proc WHERE oid = f), false) THEN
    RAISE EXCEPTION 'candidates catalogue: the edit lock has no pinned search_path (%)', (SELECT proconfig FROM pg_proc WHERE oid = f);
  END IF;
  IF EXISTS (SELECT 1 FROM pg_proc pr, aclexplode(coalesce(pr.proacl, acldefault('f', pr.proowner))) a
              WHERE pr.oid = f AND a.grantee = 0) THEN
    RAISE EXCEPTION 'candidates catalogue: PUBLIC may call the edit lock';
  END IF;
  IF NOT has_function_privilege('app_authenticated', f, 'EXECUTE') THEN
    RAISE EXCEPTION 'candidates catalogue: the API may not call the edit lock';
  END IF;
  FOREACH r IN ARRAY ARRAY['authenticated', 'anon', 'service_role'] LOOP
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
    IF has_function_privilege(r, f, 'EXECUTE') THEN RAISE EXCEPTION 'candidates catalogue: % may call the edit lock', r; END IF;
  END LOOP;
  IF (SELECT count(*) FROM pg_proc, regexp_matches(prosrc, 'FOR UPDATE SKIP LOCKED', 'g')
       WHERE oid = 'app.schedule_candidates_sweep()'::regprocedure) <> 2 THEN
    RAISE EXCEPTION 'candidates catalogue: the sweep does not take both of its row sets FOR UPDATE SKIP LOCKED';
  END IF;

  -- The keys: these three, each cascading, and no other.
  SELECT array_agg(format('%s: %s', conname, pg_get_constraintdef(oid)) ORDER BY conname COLLATE "C") INTO got
    FROM pg_constraint
   WHERE contype = 'f' AND conrelid IN ('"ScheduleCandidateRuns"'::regclass, '"ScheduleCandidates"'::regclass);
  IF got IS DISTINCT FROM ARRAY[
       'ScheduleCandidateRuns_academicYearId_schoolId_fkey: FOREIGN KEY ("academicYearId", "schoolId") REFERENCES "AcademicYears"(id, "schoolId") ON UPDATE CASCADE ON DELETE CASCADE',
       'ScheduleCandidateRuns_schoolId_fkey: FOREIGN KEY ("schoolId") REFERENCES "Schools"(id) ON UPDATE CASCADE ON DELETE CASCADE',
       'ScheduleCandidates_runId_schoolId_fkey: FOREIGN KEY ("runId", "schoolId") REFERENCES "ScheduleCandidateRuns"(id, "schoolId") ON UPDATE CASCADE ON DELETE CASCADE'] THEN
    RAISE EXCEPTION 'candidates catalogue: the keys are %', got;
  END IF;
  FOREACH c IN ARRAY ARRAY['ScheduleCandidateRuns_id_schoolId_key', 'ScheduleCandidates_runId_ordinal_key',
                           'ScheduleCandidateRuns_requested_is_one_to_four', 'ScheduleCandidateRuns_lease_is_bounded',
                           'ScheduleCandidateRuns_applied_together', 'ScheduleCandidateRuns_progress_is_of_the_requested',
                           'ScheduleCandidateRuns_basis_is_a_sha256', 'ScheduleCandidateRuns_error_is_short',
                           'ScheduleCandidateRuns_errorCode_is_a_name', 'ScheduleCandidateRuns_discarded_is_finished',
                           'ScheduleCandidateRuns_draftNotes_is_a_list',
                           'ScheduleCandidates_ordinal_is_one_to_four',
                           'ScheduleCandidates_variant_is_a_name', 'ScheduleCandidates_seed_is_not_negative',
                           'ScheduleCandidates_solverStatus_is_known', 'ScheduleCandidates_lessons_is_a_list',
                           'ScheduleCandidates_errorCode_is_a_name', 'ScheduleCandidates_notes_is_a_list'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
                    WHERE conrelid IN ('"ScheduleCandidateRuns"'::regclass, '"ScheduleCandidates"'::regclass)
                      AND conname = c AND convalidated) THEN
      RAISE EXCEPTION 'candidates catalogue: % is not in place', c;
    END IF;
  END LOOP;

  IF to_regclass('public."ScheduleCandidateRuns_one_active_per_year"') IS NULL THEN
    RAISE EXCEPTION 'candidates catalogue: there is no index of the active runs';
  END IF;
  SELECT i.indisunique AS uniq, i.indisvalid AS valid, pg_get_expr(i.indpred, i.indrelid) AS pred,
         ARRAY(SELECT a.attname::text FROM unnest(i.indkey) WITH ORDINALITY k(n, o)
                 JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k.n ORDER BY k.o) AS cols
    INTO idx FROM pg_index i WHERE i.indexrelid = '"ScheduleCandidateRuns_one_active_per_year"'::regclass;
  IF NOT idx.uniq OR NOT idx.valid OR idx.cols IS DISTINCT FROM ARRAY['schoolId', 'academicYearId']
     OR idx.pred IS DISTINCT FROM '(status = ANY (ARRAY[''PENDING''::"ScheduleCandidateRunStatus", ''RUNNING''::"ScheduleCandidateRunStatus", ''CANCELLING''::"ScheduleCandidateRunStatus"]))' THEN
    RAISE EXCEPTION 'candidates catalogue: one active run per year is %', row_to_json(idx);
  END IF;

  IF (SELECT array_agg(e.enumlabel::text ORDER BY e.enumsortorder) FROM pg_enum e
       WHERE e.enumtypid = '"ScheduleCandidateRunStatus"'::regtype)
     IS DISTINCT FROM ARRAY['PENDING', 'RUNNING', 'CANCELLING', 'SUCCEEDED', 'FAILED'] THEN
    RAISE EXCEPTION 'candidates catalogue: the statuses are %',
      (SELECT array_agg(e.enumlabel::text ORDER BY e.enumsortorder) FROM pg_enum e
        WHERE e.enumtypid = '"ScheduleCandidateRunStatus"'::regtype);
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Section 171: skolans administratörer läser schemaförslagen, den vars
-- profil skriver schemaläggning skriver dem, och ingen annan ser dem
-- (20261125090000).
--
-- In the matrix school, against its fixture run and candidate, with a
-- finished run and candidate of the primary school's beside them. Every
-- administrator (FULL, REKTOR, both schemaläggare, both expeditions) reads
-- the school's runs and candidates and nothing of another school's, and
-- locks a run FOR UPDATE: the update arm's USING admits every administrator
-- (section 106 c). FULL, REKTOR and the schemaläggare insert, update and
-- delete. The expedition (DRIFT, PERSONAL) inserts nothing (row security's
-- 42501), updates nothing (the WITH CHECK's 42501, not zero rows) and
-- deletes nothing (zero rows). A teacher, a pupil and a guardian of the
-- school, and the primary school's administrator, read, lock, update and
-- delete none of the school's rows and insert none; the primary school's
-- administrator updates and deletes their own school's rows and no more.
-- Nobody updates a candidate, and nobody truncates either table (TRUNCATE
-- passes row security by): there is no grant. Each write probe has no
-- WHERE, so it meets the write arm alone and never the read arm, and is
-- undone at once.
--
-- Then the gateway's own statements as the schemaläggare: a run started, its
-- heartbeat written only while it is PENDING or RUNNING, its row locked to
-- store a candidate, finished, applied and removed with its candidate; a
-- second run cancelled, after which its heartbeat finds nothing and the task
-- fails it. PostgREST's role, with FULL's claims, reads and writes neither
-- table and calls neither function.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls171_other', :'admin_auth_id', true);

-- 'rows N' (and undone), 'refused' (row security), 'denied' (no grant), or
-- the error.
CREATE FUNCTION pg_temp.rls171_try(statement text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE n bigint; st text; msg text;
BEGIN
  EXECUTE statement;
  GET DIAGNOSTICS n = ROW_COUNT;
  RAISE EXCEPTION USING ERRCODE = 'ZM171', MESSAGE = n::text;
EXCEPTION
  WHEN SQLSTATE 'ZM171' THEN
    GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
    RETURN 'rows ' || msg;
  WHEN insufficient_privilege THEN
    GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
    RETURN CASE WHEN msg LIKE '%row-level security%' THEN 'refused' ELSE 'denied' END;
  WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, msg = MESSAGE_TEXT;
    RETURN 'error ' || st || ' ' || msg;
END $$;

-- The primary school's administrator files a finished run with a candidate,
-- so that another school's rows are there to be missed.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls171_other'))::text, true);
DO $$
DECLARE yr uuid; run uuid;
BEGIN
  IF app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' OR NOT app.current_user_may('SCHEMALAGGNING', true) THEN
    RAISE EXCEPTION 'candidates: the primary school''s administrator does not write schemaläggning';
  END IF;
  SELECT id INTO yr FROM "AcademicYears" WHERE "schoolId" = app.current_school_id() ORDER BY "isActive" DESC, id LIMIT 1;
  INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", status, requested, progress, "finishedAt")
  VALUES (app.current_school_id(), yr, 'SUCCEEDED', 1, 1, now()) RETURNING id INTO run;
  INSERT INTO "ScheduleCandidates" ("runId", "schoolId", ordinal, variant, "solverStatus")
  VALUES (run, app.current_school_id(), 1, 'KEEP', 'OPTIMAL');
  PERFORM set_config('app.test_rls171_school_a', app.current_school_id()::text, true);
END $$;

DO $$
DECLARE
  principals constant text[][] := ARRAY[
    ['00000000-0000-4000-8000-000000000105', 'FULL', 'writes'],
    ['00000000-0000-4000-8000-000000000106', 'REKTOR', 'writes'],
    ['00000000-0000-4000-8000-000000000107', 'SCHEMALAGGARE', 'writes'],
    ['00000000-0000-4000-8000-000000000109', 'SCHEMALAGGARE', 'writes'],
    ['00000000-0000-4000-8000-000000000108', 'EXPEDITION', 'reads'],
    ['00000000-0000-4000-8000-000000000110', 'EXPEDITION', 'reads'],
    ['00000000-0000-4000-8000-000000000111', 'TEACHER', 'none'],
    ['00000000-0000-4000-8000-000000000112', 'STUDENT', 'none'],
    ['00000000-0000-4000-8000-000000000113', 'GUARDIAN', 'none'],
    [current_setting('app.test_rls171_other'), 'SCHOOL_ADMIN', 'elsewhere']];
  a constant uuid := current_setting('app.test_rls171_school_a')::uuid;
  m uuid;
  yr uuid;
  fixture uuid;
  next_ordinal int;
  m_runs bigint;
  m_cands bigint;
  own_runs bigint;
  own_cands bigint;
  i int;
  kind text;
  admin boolean;
  home uuid;
  who text;
  n bigint;
  got text;
  want text;
  probe record;
  wrong text[] := '{}';
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', principals[1][1])::text, true);
  m := app.current_school_id();
  IF m IS NULL OR (SELECT slug FROM "Schools" WHERE id = m) IS DISTINCT FROM 'rls-roller-school' THEN
    RAISE EXCEPTION 'candidates: the full administrator is not in rls-roller-school; fixtures did not run';
  END IF;
  SELECT c."runId", r."academicYearId" INTO fixture, yr
    FROM "ScheduleCandidates" c JOIN "ScheduleCandidateRuns" r ON r.id = c."runId"
   WHERE c."schoolId" = m ORDER BY c."createdAt", c.id LIMIT 1;
  IF fixture IS NULL THEN
    RAISE EXCEPTION 'candidates: the matrix school has no run with a candidate; fixtures did not run';
  END IF;
  SELECT coalesce(max(ordinal), 0) + 1 INTO next_ordinal FROM "ScheduleCandidates" WHERE "runId" = fixture;
  SELECT count(*) INTO m_runs FROM "ScheduleCandidateRuns" WHERE "schoolId" = m;
  SELECT count(*) INTO m_cands FROM "ScheduleCandidates" WHERE "schoolId" = m;

  FOR i IN 1 .. array_length(principals, 1) LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', principals[i][1])::text, true);
    kind := principals[i][3];
    -- An administrator of the matrix school, and the school the principal is of.
    admin := kind IN ('writes', 'reads');
    home := CASE kind WHEN 'elsewhere' THEN a ELSE m END;
    who := CASE kind WHEN 'elsewhere' THEN 'the primary school''s administrator'
                     ELSE format('%s (%s)', principals[i][2], right(principals[i][1], 3)) END;
    IF app.current_user_role()::text IS DISTINCT FROM (CASE WHEN admin THEN 'SCHOOL_ADMIN' ELSE principals[i][2] END)
       OR app.current_school_id() IS DISTINCT FROM home
       OR (admin AND (SELECT "adminProfile"::text FROM "Users" WHERE id = app.current_user_id()) IS DISTINCT FROM principals[i][2]) THEN
      RAISE EXCEPTION 'candidates: % resolved as % in %, expected %', principals[i][1], app.current_user_role(),
        app.current_school_id(), principals[i][2];
    END IF;

    -- Reading and locking.
    SELECT count(*) INTO n FROM "ScheduleCandidateRuns" WHERE "schoolId" = m;
    IF n IS DISTINCT FROM (CASE WHEN admin THEN m_runs ELSE 0 END) THEN
      wrong := wrong || format('%s reads %s of the matrix school''s %s runs', who, n, m_runs);
    END IF;
    SELECT count(*) INTO n FROM "ScheduleCandidates" WHERE "schoolId" = m;
    IF n IS DISTINCT FROM (CASE WHEN admin THEN m_cands ELSE 0 END) THEN
      wrong := wrong || format('%s reads %s of the matrix school''s %s candidates', who, n, m_cands);
    END IF;
    SELECT (SELECT count(*) FROM "ScheduleCandidateRuns" WHERE "schoolId" IS DISTINCT FROM app.current_school_id())
         + (SELECT count(*) FROM "ScheduleCandidates" WHERE "schoolId" IS DISTINCT FROM app.current_school_id()) INTO n;
    IF n <> 0 THEN wrong := wrong || format('%s reads %s rows of another school', who, n); END IF;
    SELECT count(*) INTO n FROM (SELECT 1 FROM "ScheduleCandidateRuns" WHERE id = fixture FOR UPDATE) x;
    IF n IS DISTINCT FROM (CASE WHEN admin THEN 1 ELSE 0 END) THEN
      wrong := wrong || format('%s locks %s of the matrix school''s run', who, n);
    END IF;
    SELECT count(*) INTO own_runs FROM "ScheduleCandidateRuns" WHERE "schoolId" = app.current_school_id();
    SELECT count(*) INTO own_cands FROM "ScheduleCandidates" WHERE "schoolId" = app.current_school_id();
    IF kind = 'elsewhere' AND (own_runs = 0 OR own_cands = 0) THEN
      RAISE EXCEPTION 'candidates: the primary school''s administrator reads none of their own run (% runs, % candidates)', own_runs, own_cands;
    END IF;

    -- Writing, each probe undone.
    FOR probe IN SELECT * FROM (VALUES
      ('insert a run of the matrix school',
       format('INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", status, requested) VALUES (%L, %L, ''FAILED'', 1)', m, yr),
       'rows 1', 'refused', 'refused', 'refused'),
      ('insert a candidate of the matrix school',
       format('INSERT INTO "ScheduleCandidates" ("runId", "schoolId", ordinal, variant, "solverStatus") VALUES (%L, %L, %s, ''KEEP'', ''OPTIMAL'')',
              fixture, m, next_ordinal),
       'rows 1', 'refused', 'refused', 'refused'),
      ('update every run it may', 'UPDATE "ScheduleCandidateRuns" SET "heartbeatAt" = now()',
       'rows ' || m_runs, 'refused', 'rows 0', 'rows ' || own_runs),
      ('update every candidate it may', 'UPDATE "ScheduleCandidates" SET "errorCode" = NULL',
       'denied', 'denied', 'denied', 'denied'),
      ('truncate the runs', 'TRUNCATE "ScheduleCandidateRuns"', 'denied', 'denied', 'denied', 'denied'),
      ('truncate the candidates', 'TRUNCATE "ScheduleCandidates"', 'denied', 'denied', 'denied', 'denied'),
      ('delete every candidate it may', 'DELETE FROM "ScheduleCandidates"',
       'rows ' || m_cands, 'rows 0', 'rows 0', 'rows ' || own_cands),
      ('delete every run it may', 'DELETE FROM "ScheduleCandidateRuns"',
       'rows ' || m_runs, 'rows 0', 'rows 0', 'rows ' || own_runs)
    ) AS t(what, statement, writes, reads, nobody, elsewhere) LOOP
      want := CASE kind WHEN 'writes' THEN probe.writes WHEN 'reads' THEN probe.reads
                        WHEN 'none' THEN probe.nobody ELSE probe.elsewhere END;
      got := pg_temp.rls171_try(probe.statement);
      IF got IS DISTINCT FROM want THEN
        wrong := wrong || format('%s: %s met "%s", expected "%s"', who, probe.what, got, want);
      END IF;
    END LOOP;
  END LOOP;

  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'candidates: %', array_to_string(wrong, '; ');
  END IF;
END $$;

-- The gateway's own statements, as the schemaläggare.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
DO $$
DECLARE
  m uuid := app.current_school_id();
  yr uuid;
  run uuid;
  cand uuid;
BEGIN
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (m, 'RLS171 år', DATE '2081-08-15', DATE '2082-06-10', false, now()) RETURNING id INTO yr;

  -- Started, a candidate stored under the run's lock, finished, applied.
  INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", "createdById", requested, "leaseSeconds", weights)
  VALUES (m, yr, app.current_user_id(), 2, 300, '{"disruption": 8}') RETURNING id INTO run;
  UPDATE "ScheduleCandidateRuns" SET status = 'RUNNING', "heartbeatAt" = now(), "startedAt" = coalesce("startedAt", now())
   WHERE id = run AND status IN ('PENDING', 'RUNNING');
  IF NOT FOUND THEN RAISE EXCEPTION 'candidates: the schemaläggare''s task could not start its run'; END IF;
  PERFORM 1 FROM "ScheduleCandidateRuns" WHERE id = run AND status = 'RUNNING' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'candidates: the schemaläggare''s task could not lock its run'; END IF;
  INSERT INTO "ScheduleCandidates" ("runId", "schoolId", ordinal, variant, weights, "solverStatus", lessons, metrics)
  VALUES (run, m, 1, 'KEEP', '{"disruption": 8}', 'OPTIMAL',
          '[{"requirementId": "00000000-0000-4000-8000-000000001610", "roomId": null, "dayOfWeek": 1, "startTime": "08:00", "endTime": "09:00"}]',
          '{"moved": 0, "movedOf": 1, "roomChanges": 0, "kept": 1, "sameAs": null}') RETURNING id INTO cand;
  UPDATE "ScheduleCandidateRuns" SET progress = progress + 1, "heartbeatAt" = now() WHERE id = run;
  PERFORM 1 FROM "ScheduleCandidateRuns" WHERE id = run AND status = 'RUNNING' FOR UPDATE;
  UPDATE "ScheduleCandidateRuns" SET status = 'SUCCEEDED', "finishedAt" = now() WHERE id = run AND status = 'RUNNING';
  IF NOT FOUND THEN RAISE EXCEPTION 'candidates: the schemaläggare''s task could not finish its run'; END IF;
  UPDATE "ScheduleCandidateRuns" SET "appliedCandidateId" = cand, "appliedAt" = now() WHERE id = run AND status = 'SUCCEEDED';
  IF NOT FOUND THEN RAISE EXCEPTION 'candidates: the schemaläggare could not mark the applied candidate'; END IF;

  -- Removed, and its candidate with it.
  DELETE FROM "ScheduleCandidateRuns" WHERE id = run;
  IF NOT FOUND OR EXISTS (SELECT 1 FROM "ScheduleCandidates" WHERE id = cand) THEN
    RAISE EXCEPTION 'candidates: the schemaläggare could not remove a run with its candidate';
  END IF;

  -- Cancelled: the next heartbeat finds nothing, and the task fails the run.
  INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", "createdById", status, requested, "startedAt")
  VALUES (m, yr, app.current_user_id(), 'RUNNING', 3, now()) RETURNING id INTO run;
  UPDATE "ScheduleCandidateRuns" SET status = 'CANCELLING' WHERE id = run AND status IN ('PENDING', 'RUNNING');
  IF NOT FOUND THEN RAISE EXCEPTION 'candidates: the schemaläggare could not cancel a run'; END IF;
  UPDATE "ScheduleCandidateRuns" SET "heartbeatAt" = now() WHERE id = run AND status IN ('PENDING', 'RUNNING');
  IF FOUND THEN RAISE EXCEPTION 'candidates: a cancelled run took a heartbeat'; END IF;
  UPDATE "ScheduleCandidateRuns" SET status = 'FAILED', "errorCode" = 'CANDIDATE_RUN_CANCELLED', "finishedAt" = now()
   WHERE id = run AND status = 'CANCELLING';
  IF NOT FOUND THEN RAISE EXCEPTION 'candidates: the schemaläggare''s task could not fail its cancelled run'; END IF;
END $$;

-- PostgREST's role, with FULL's claims: neither table, neither function.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
SET LOCAL ROLE authenticated;
DO $$
DECLARE
  s text;
  got text;
BEGIN
  IF current_user <> 'authenticated' THEN RAISE EXCEPTION 'candidates: could not act as authenticated'; END IF;
  FOREACH s IN ARRAY ARRAY[
    'SELECT 1 FROM "ScheduleCandidateRuns"', 'SELECT 1 FROM "ScheduleCandidates"',
    'UPDATE "ScheduleCandidateRuns" SET "heartbeatAt" = now()',
    'DELETE FROM "ScheduleCandidateRuns"', 'DELETE FROM "ScheduleCandidates"',
    'SELECT app.schedule_candidates_sweep()', 'SELECT app.schedule_candidate_runs_active()'] LOOP
    got := pg_temp.rls171_try(s);
    IF got <> 'denied' THEN RAISE EXCEPTION 'candidates: PostgREST''s role met "%" for %', got, s; END IF;
  END LOOP;
END $$;
SET LOCAL ROLE app_authenticated;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 172: ett förslag hör till sin körnings skola och en körning till
-- sitt läsårs, och båda försvinner med körningen, läsåret och skolan
-- (20261125090000).
--
-- The arms ask only the row's own schoolId, so the composite keys are what
-- hold a row to its tenant: a candidate filed under the matrix school on the
-- primary school's run, and a run of the matrix school in the primary
-- school's year, are each the key's 23503 (the arm let them through), as is
-- a run moved to the other school's year, or a candidate the other school's
-- administrator files under their own school on the matrix school's run.
-- Filed under the other school, or moved there with its year, a row is the
-- arm's 42501 first. An update with a WHERE also meets the select arm on
-- the new row, so the move is made once more with none, where the update
-- arm's WITH CHECK alone answers. A run has one candidate per ordinal
-- (23505, named). Deleting a run takes its candidates, and deleting a year
-- takes its runs and theirs; a school's delete cascades the same way
-- (section 170 reads that key, since no administrator may delete a school).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls172_other', :'admin_auth_id', true);

-- 'none' (the row stays) or 'sqlstate:constraint' of a statement's refusal.
CREATE FUNCTION pg_temp.rls172_refusal(statement text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE st text; con text;
BEGIN
  EXECUTE statement;
  RETURN 'none';
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, con = CONSTRAINT_NAME;
  RETURN st || ':' || coalesce(con, '');
END $$;
CREATE FUNCTION pg_temp.rls172_as(sub text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', sub)::text, true);
END $$;

DO $$
DECLARE
  other constant text := current_setting('app.test_rls172_other');
  a uuid;
  ya uuid;
  ra uuid;
  m uuid;
  ym uuid;
  rm uuid;
  yd uuid;
  rd uuid;
  c record;
  got text;
  n bigint;
BEGIN
  -- The primary school's finished run, in its own year.
  PERFORM pg_temp.rls172_as(other);
  a := app.current_school_id();
  SELECT id INTO ya FROM "AcademicYears" WHERE "schoolId" = a ORDER BY "isActive" DESC, id LIMIT 1;
  INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", status, requested, progress)
  VALUES (a, ya, 'SUCCEEDED', 1, 1) RETURNING id INTO ra;

  -- The matrix school's, with two candidates.
  PERFORM pg_temp.rls172_as('00000000-0000-4000-8000-000000000105');
  m := app.current_school_id();
  IF m IS NULL OR m = a OR ya IS NULL THEN RAISE EXCEPTION 'tenant keys: the two schools are not there; fixtures did not run'; END IF;
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (m, 'RLS172 år', DATE '2082-08-15', DATE '2083-06-10', false, now()) RETURNING id INTO ym;
  INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", status, requested, progress)
  VALUES (m, ym, 'SUCCEEDED', 2, 2) RETURNING id INTO rm;
  INSERT INTO "ScheduleCandidates" ("runId", "schoolId", ordinal, variant, "solverStatus")
  VALUES (rm, m, 1, 'KEEP', 'OPTIMAL'), (rm, m, 2, 'TEACHER_GAPS', 'FEASIBLE');

  FOR c IN SELECT * FROM (VALUES
    ('a candidate of the matrix school on the primary school''s run',
     format('INSERT INTO "ScheduleCandidates" ("runId", "schoolId", ordinal, variant, "solverStatus") VALUES (%L, %L, 1, ''KEEP'', ''OPTIMAL'')', ra, m),
     '23503:ScheduleCandidates_runId_schoolId_fkey'),
    ('a candidate filed under the primary school',
     format('INSERT INTO "ScheduleCandidates" ("runId", "schoolId", ordinal, variant, "solverStatus") VALUES (%L, %L, 1, ''KEEP'', ''OPTIMAL'')', ra, a),
     '42501:'),
    ('a run of the matrix school in the primary school''s year',
     format('INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", status, requested) VALUES (%L, %L, ''FAILED'', 1)', m, ya),
     '23503:ScheduleCandidateRuns_academicYearId_schoolId_fkey'),
    ('a run filed under the primary school',
     format('INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", status, requested) VALUES (%L, %L, ''FAILED'', 1)', a, ya),
     '42501:'),
    ('a run moved to the primary school''s year',
     format('UPDATE "ScheduleCandidateRuns" SET "academicYearId" = %L WHERE id = %L', ya, rm),
     '23503:ScheduleCandidateRuns_academicYearId_schoolId_fkey'),
    ('a run moved to the primary school with its year',
     format('UPDATE "ScheduleCandidateRuns" SET "schoolId" = %L, "academicYearId" = %L WHERE id = %L', a, ya, rm),
     '42501:'),
    ('every run moved to the primary school with its year, by an update that reads nothing',
     format('UPDATE "ScheduleCandidateRuns" SET "schoolId" = %L, "academicYearId" = %L', a, ya),
     '42501:'),
    ('a second candidate of an ordinal',
     format('INSERT INTO "ScheduleCandidates" ("runId", "schoolId", ordinal, variant, "solverStatus") VALUES (%L, %L, 2, ''SPREAD'', ''OPTIMAL'')', rm, m),
     '23505:ScheduleCandidates_runId_ordinal_key')
  ) AS t(what, statement, refusal) LOOP
    got := pg_temp.rls172_refusal(c.statement);
    IF got IS DISTINCT FROM c.refusal THEN
      RAISE EXCEPTION 'tenant keys: % was answered "%", expected "%"', c.what, got, c.refusal;
    END IF;
  END LOOP;

  -- The primary school's administrator, on the matrix school's run under their own school: the key.
  PERFORM pg_temp.rls172_as(other);
  got := pg_temp.rls172_refusal(format(
    'INSERT INTO "ScheduleCandidates" ("runId", "schoolId", ordinal, variant, "solverStatus") VALUES (%L, %L, 3, ''SPREAD'', ''OPTIMAL'')', rm, a));
  IF got IS DISTINCT FROM '23503:ScheduleCandidates_runId_schoolId_fkey' THEN
    RAISE EXCEPTION 'tenant keys: another school''s candidate on the matrix school''s run was answered "%"', got;
  END IF;
  IF EXISTS (SELECT 1 FROM "ScheduleCandidates" WHERE "runId" = ra)
     OR (SELECT "academicYearId" FROM "ScheduleCandidateRuns" WHERE id = ra) IS DISTINCT FROM ya THEN
    RAISE EXCEPTION 'tenant keys: the primary school''s run was changed from the matrix school';
  END IF;

  -- A run removed takes its candidates, as the schemaläggare.
  PERFORM pg_temp.rls172_as('00000000-0000-4000-8000-000000000107');
  IF (SELECT "schoolId" FROM "ScheduleCandidateRuns" WHERE id = rm) IS DISTINCT FROM m
     OR (SELECT count(*) FROM "ScheduleCandidates" WHERE "runId" = rm) <> 2 THEN
    RAISE EXCEPTION 'tenant keys: the matrix school''s run or its candidates moved';
  END IF;
  BEGIN
    DELETE FROM "ScheduleCandidateRuns" WHERE id = rm;
    GET DIAGNOSTICS n = ROW_COUNT;
  EXCEPTION WHEN foreign_key_violation THEN
    RAISE EXCEPTION 'tenant keys: a run with candidates could not be removed: %', SQLERRM;
  END;
  IF n <> 1 OR EXISTS (SELECT 1 FROM "ScheduleCandidates" WHERE "runId" = rm) THEN
    RAISE EXCEPTION 'tenant keys: removing a run (% removed) left its candidates', n;
  END IF;

  -- A year removed takes its runs and their candidates, as FULL.
  PERFORM pg_temp.rls172_as('00000000-0000-4000-8000-000000000105');
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (m, 'RLS172 borttaget år', DATE '2083-08-15', DATE '2084-06-10', false, now()) RETURNING id INTO yd;
  INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", status, requested, progress)
  VALUES (m, yd, 'RUNNING', 2, 1) RETURNING id INTO rd;
  INSERT INTO "ScheduleCandidates" ("runId", "schoolId", ordinal, variant, "solverStatus") VALUES (rd, m, 1, 'KEEP', 'OPTIMAL');
  BEGIN
    DELETE FROM "AcademicYears" WHERE id = yd;
  EXCEPTION WHEN foreign_key_violation THEN
    RAISE EXCEPTION 'tenant keys: a year with a candidate run could not be removed: %', SQLERRM;
  END;
  IF EXISTS (SELECT 1 FROM "AcademicYears" WHERE id = yd) THEN RAISE EXCEPTION 'tenant keys: FULL could not remove a year'; END IF;
  IF EXISTS (SELECT 1 FROM "ScheduleCandidateRuns" WHERE id = rd) OR EXISTS (SELECT 1 FROM "ScheduleCandidates" WHERE "runId" = rd) THEN
    RAISE EXCEPTION 'tenant keys: removing a year left its run or its candidate';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 173: en körning åt gången per läsår
-- (ScheduleCandidateRuns_one_active_per_year).
--
-- With a PENDING run in a year, a second PENDING, RUNNING or CANCELLING run
-- of that year is the index's 23505, named (the gateway answers it with 409
-- CANDIDATES_RUNNING), whether it is inserted or a finished run is set
-- active again; a cancelled run holds the year until its task has stopped.
-- Finished runs hold nothing: SUCCEEDED and FAILED ones are let in beside
-- it, as many as there are, and an active run of another year of the same
-- school, of the fixture's year beside its finished run, or of the primary
-- school's year, is let in too. Once the run fails, the year takes a new one.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls173_other', :'admin_auth_id', true);

-- 'none' (the row stays) or 'sqlstate:constraint' of a statement's refusal.
CREATE FUNCTION pg_temp.rls173_refusal(statement text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE st text; con text;
BEGIN
  EXECUTE statement;
  RETURN 'none';
EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, con = CONSTRAINT_NAME;
  RETURN st || ':' || coalesce(con, '');
END $$;

-- The primary school's year has an active run of its own.
SELECT set_config('request.jwt.claims', json_build_object('sub', current_setting('app.test_rls173_other'))::text, true);
DO $$
DECLARE yr uuid;
BEGIN
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (app.current_school_id(), 'RLS173 år', DATE '2085-08-15', DATE '2086-06-10', false, now()) RETURNING id INTO yr;
  INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", status, requested) VALUES (app.current_school_id(), yr, 'RUNNING', 2);
  PERFORM set_config('app.test_rls173_year_a', yr::text, true);
END $$;

SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
DO $$
DECLARE
  m uuid := app.current_school_id();
  fixture_year uuid;
  y1 uuid;
  y2 uuid;
  r1 uuid;
  done uuid;
  st text;
  got text;
  insert_run constant text := 'INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", status, requested) VALUES (%L, %L, %L, 2)';
BEGIN
  SELECT "academicYearId" INTO fixture_year FROM "ScheduleCandidateRuns" WHERE "schoolId" = m AND status = 'SUCCEEDED'
   ORDER BY "createdAt" LIMIT 1;
  IF fixture_year IS NULL THEN RAISE EXCEPTION 'one active run: the matrix school has no finished run; fixtures did not run'; END IF;
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (m, 'RLS173 år 1', DATE '2086-08-15', DATE '2087-06-10', false, now()) RETURNING id INTO y1;
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (m, 'RLS173 år 2', DATE '2087-08-15', DATE '2088-06-10', false, now()) RETURNING id INTO y2;
  INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", status, requested) VALUES (m, y1, 'PENDING', 2) RETURNING id INTO r1;

  FOREACH st IN ARRAY ARRAY['PENDING', 'RUNNING', 'CANCELLING'] LOOP
    got := pg_temp.rls173_refusal(format(insert_run, m, y1, st));
    IF got IS DISTINCT FROM '23505:ScheduleCandidateRuns_one_active_per_year' THEN
      RAISE EXCEPTION 'one active run: a second % run of the year was answered "%"', st, got;
    END IF;
  END LOOP;
  FOREACH st IN ARRAY ARRAY['SUCCEEDED', 'FAILED', 'SUCCEEDED', 'FAILED'] LOOP
    got := pg_temp.rls173_refusal(format(insert_run, m, y1, st));
    IF got <> 'none' THEN RAISE EXCEPTION 'one active run: a % run beside the active one was answered "%"', st, got; END IF;
  END LOOP;
  got := pg_temp.rls173_refusal(format(insert_run, m, y2, 'RUNNING'));
  IF got <> 'none' THEN RAISE EXCEPTION 'one active run: a run of another year of the school was answered "%"', got; END IF;
  got := pg_temp.rls173_refusal(format(insert_run, m, fixture_year, 'CANCELLING'));
  IF got <> 'none' THEN RAISE EXCEPTION 'one active run: a run of the fixture''s year beside its finished run was answered "%"', got; END IF;
  IF (SELECT count(*) FROM "ScheduleCandidateRuns" WHERE "academicYearId" = current_setting('app.test_rls173_year_a')::uuid) <> 0 THEN
    RAISE EXCEPTION 'one active run: the matrix school reads the primary school''s run';
  END IF;

  -- Cancelled, it still holds the year; a finished run set active again is refused the same way.
  UPDATE "ScheduleCandidateRuns" SET status = 'CANCELLING' WHERE id = r1;
  SELECT id INTO done FROM "ScheduleCandidateRuns" WHERE "academicYearId" = y1 AND status = 'FAILED' LIMIT 1;
  got := pg_temp.rls173_refusal(format('UPDATE "ScheduleCandidateRuns" SET status = ''RUNNING'' WHERE id = %L', done));
  IF got IS DISTINCT FROM '23505:ScheduleCandidateRuns_one_active_per_year' THEN
    RAISE EXCEPTION 'one active run: a finished run set running beside a cancelled one was answered "%"', got;
  END IF;
  got := pg_temp.rls173_refusal(format(insert_run, m, y1, 'PENDING'));
  IF got IS DISTINCT FROM '23505:ScheduleCandidateRuns_one_active_per_year' THEN
    RAISE EXCEPTION 'one active run: a run beside a cancelled one was answered "%"', got;
  END IF;

  -- Failed: the year is free.
  UPDATE "ScheduleCandidateRuns" SET status = 'FAILED', "finishedAt" = now() WHERE id = r1;
  got := pg_temp.rls173_refusal(format(insert_run, m, y1, 'PENDING'));
  IF got <> 'none' THEN RAISE EXCEPTION 'one active run: the year took no run after its run failed: "%"', got; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 174: varje CHECK släpper in och vägrar vid sina gränser
-- (20261125090000, 20261127090000).
--
-- As FULL in the matrix school, one row at a time, each undone at once: a
-- run asks for one to four candidates; its progress is from none to what it
-- asked for; its basis is a lowercase sha256 in hex, all of it and nothing
-- after; its lease is from a minute to an hour; a candidate is marked applied
-- with its time or not at all; its error is at most 2 000 characters (not
-- bytes); an error code is a name of at most 64 characters; only a finished
-- run is marked discarded, and a discarded one is never made active again
-- (an active run hidden from the page would still hold the year). A candidate's
-- ordinal is one to four; its variant a name of at most 32 characters; its
-- seed none or not negative; its solver status one of the six the gateway
-- writes; its lessons a JSON list; its error code a name. The free-day
-- wishes a candidate breaks, and the draft's on its run, are none or a JSON
-- list, and JSON's own null is not none. A name is refused
-- with only its first letter in lowercase and with only its last, so that
-- either character class loosened shows. Each refusal is 23514 by the
-- constraint's own name, and each case touches that constraint alone, so a
-- refusal for another reason fails it too.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);

-- 'none' (undone) or 'sqlstate:constraint' of a statement's refusal.
CREATE FUNCTION pg_temp.rls174_try(statement text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE st text; con text;
BEGIN
  EXECUTE statement;
  RAISE EXCEPTION USING ERRCODE = 'ZM174';
EXCEPTION
  WHEN SQLSTATE 'ZM174' THEN RETURN 'none';
  WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, con = CONSTRAINT_NAME;
    RETURN st || ':' || coalesce(con, '');
END $$;

DO $$
DECLARE
  m uuid := app.current_school_id();
  yr uuid;
  run uuid;
  c record;
  got text;
  want text;
  wrong text[] := '{}';
  sha constant text := '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef';
  long_name constant text := 'A' || repeat('Z', 63);
BEGIN
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (m, 'RLS174 år', DATE '2088-08-15', DATE '2089-06-10', false, now()) RETURNING id INTO yr;
  INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", status, requested, progress)
  VALUES (m, yr, 'SUCCEEDED', 4, 4) RETURNING id INTO run;

  -- what, requested, progress, basis, lease, appliedCandidateId, appliedAt, error, errorCode, refused by
  FOR c IN SELECT * FROM (VALUES
    ('requested 0', 0, 0, NULL::text, 600, NULL::uuid, NULL::timestamptz, NULL::text, NULL::text, 'requested_is_one_to_four'),
    ('requested 1', 1, 0, NULL, 600, NULL, NULL, NULL, NULL, NULL),
    ('requested 4', 4, 0, NULL, 600, NULL, NULL, NULL, NULL, NULL),
    ('requested 5', 5, 0, NULL, 600, NULL, NULL, NULL, NULL, 'requested_is_one_to_four'),
    ('progress -1', 3, -1, NULL, 600, NULL, NULL, NULL, NULL, 'progress_is_of_the_requested'),
    ('progress 0 of 3', 3, 0, NULL, 600, NULL, NULL, NULL, NULL, NULL),
    ('progress 3 of 3', 3, 3, NULL, 600, NULL, NULL, NULL, NULL, NULL),
    ('progress 4 of 3', 3, 4, NULL, 600, NULL, NULL, NULL, NULL, 'progress_is_of_the_requested'),
    ('progress 2 of 1', 1, 2, NULL, 600, NULL, NULL, NULL, NULL, 'progress_is_of_the_requested'),
    ('no basis', 2, 0, NULL, 600, NULL, NULL, NULL, NULL, NULL),
    ('a sha256', 2, 0, sha, 600, NULL, NULL, NULL, NULL, NULL),
    ('a sha256 short of a digit', 2, 0, left(sha, 63), 600, NULL, NULL, NULL, NULL, 'basis_is_a_sha256'),
    ('a sha256 and a digit more', 2, 0, sha || '0', 600, NULL, NULL, NULL, NULL, 'basis_is_a_sha256'),
    ('a sha256 in capitals', 2, 0, upper(sha), 600, NULL, NULL, NULL, NULL, 'basis_is_a_sha256'),
    ('a sha256 with a g', 2, 0, 'g' || right(sha, 63), 600, NULL, NULL, NULL, NULL, 'basis_is_a_sha256'),
    ('a sha256 and a newline', 2, 0, sha || E'\n', 600, NULL, NULL, NULL, NULL, 'basis_is_a_sha256'),
    ('an empty basis', 2, 0, '', 600, NULL, NULL, NULL, NULL, 'basis_is_a_sha256'),
    ('lease 59', 2, 0, NULL, 59, NULL, NULL, NULL, NULL, 'lease_is_bounded'),
    ('lease 60', 2, 0, NULL, 60, NULL, NULL, NULL, NULL, NULL),
    ('lease 3600', 2, 0, NULL, 3600, NULL, NULL, NULL, NULL, NULL),
    ('lease 3601', 2, 0, NULL, 3601, NULL, NULL, NULL, NULL, 'lease_is_bounded'),
    ('applied with its time', 2, 0, NULL, 600, gen_random_uuid(), now(), NULL, NULL, NULL),
    ('applied without a time', 2, 0, NULL, 600, gen_random_uuid(), NULL, NULL, NULL, 'applied_together'),
    ('a time without a candidate', 2, 0, NULL, 600, NULL, now(), NULL, NULL, 'applied_together'),
    ('an error of 2000 characters', 2, 0, NULL, 600, NULL, NULL, repeat('x', 2000), NULL, NULL),
    ('an error of 2000 two-byte characters', 2, 0, NULL, 600, NULL, NULL, repeat('å', 2000), NULL, NULL),
    ('an error of 2001 characters', 2, 0, NULL, 600, NULL, NULL, repeat('x', 2001), NULL, 'error_is_short'),
    ('the code A', 2, 0, NULL, 600, NULL, NULL, NULL, 'A', NULL),
    ('a code of 64 characters', 2, 0, NULL, 600, NULL, NULL, NULL, long_name, NULL),
    ('a code with digits and underscores', 2, 0, NULL, 600, NULL, NULL, NULL, 'CANDIDATE_RUN_ABANDONED_2', NULL),
    ('a code of 65 characters', 2, 0, NULL, 600, NULL, NULL, NULL, long_name || 'Z', 'errorCode_is_a_name'),
    ('a code in lowercase', 2, 0, NULL, 600, NULL, NULL, NULL, 'candidate_run_abandoned', 'errorCode_is_a_name'),
    ('a code from a lowercase letter', 2, 0, NULL, 600, NULL, NULL, NULL, 'cANDIDATE_RUN_ABANDONED', 'errorCode_is_a_name'),
    ('a code ending in lowercase', 2, 0, NULL, 600, NULL, NULL, NULL, 'CANDIDATEs', 'errorCode_is_a_name'),
    ('a code from a digit', 2, 0, NULL, 600, NULL, NULL, NULL, '9A', 'errorCode_is_a_name'),
    ('a code from an underscore', 2, 0, NULL, 600, NULL, NULL, NULL, '_A', 'errorCode_is_a_name'),
    ('a code with a dash', 2, 0, NULL, 600, NULL, NULL, NULL, 'A-B', 'errorCode_is_a_name'),
    ('a code and a newline', 2, 0, NULL, 600, NULL, NULL, NULL, 'A' || E'\n', 'errorCode_is_a_name'),
    ('an empty code', 2, 0, NULL, 600, NULL, NULL, NULL, '', 'errorCode_is_a_name')
  ) AS t(what, requested, progress, basis, lease, applied_id, applied_at, error, code, refused_by) LOOP
    got := pg_temp.rls174_try(format(
      'INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", status, requested, progress, basis, "leaseSeconds",
                                            "appliedCandidateId", "appliedAt", error, "errorCode")
       VALUES (%L, %L, ''FAILED'', %s, %s, %L, %s, %L, %L, %L, %L)',
      m, yr, c.requested, c.progress, c.basis, c.lease, c.applied_id, c.applied_at, c.error, c.code));
    want := coalesce('23514:ScheduleCandidateRuns_' || c.refused_by, 'none');
    IF got IS DISTINCT FROM want THEN wrong := wrong || format('run with %s: "%s", expected "%s"', c.what, got, want); END IF;
  END LOOP;

  -- status, discardedAt, refused by
  FOR c IN SELECT * FROM (VALUES
    ('SUCCEEDED', now(), NULL::text),
    ('FAILED', now(), NULL),
    ('PENDING', NULL::timestamptz, NULL),
    ('PENDING', now(), 'discarded_is_finished'),
    ('RUNNING', now(), 'discarded_is_finished'),
    ('CANCELLING', now(), 'discarded_is_finished')
  ) AS t(status, discarded, refused_by) LOOP
    got := pg_temp.rls174_try(format(
      'INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", status, requested, "discardedAt")
       VALUES (%L, %L, %L, 2, %L)', m, yr, c.status, c.discarded));
    want := coalesce('23514:ScheduleCandidateRuns_' || c.refused_by, 'none');
    IF got IS DISTINCT FROM want THEN
      wrong := wrong || format('a %s run discarded %s: "%s", expected "%s"', c.status, coalesce(c.discarded::text, 'never'), got, want);
    END IF;
  END LOOP;
  UPDATE "ScheduleCandidateRuns" SET "discardedAt" = now() WHERE id = run;
  got := pg_temp.rls174_try(format('UPDATE "ScheduleCandidateRuns" SET status = ''RUNNING'' WHERE id = %L', run));
  IF got IS DISTINCT FROM '23514:ScheduleCandidateRuns_discarded_is_finished' THEN
    wrong := wrong || format('a discarded run made RUNNING again: "%s"', got);
  END IF;
  UPDATE "ScheduleCandidateRuns" SET "discardedAt" = NULL WHERE id = run;

  -- what, ordinal, variant, seed, solverStatus, lessons, errorCode, refused by
  FOR c IN SELECT * FROM (VALUES
    ('ordinal 0', 0, 'KEEP', NULL::int, 'OPTIMAL', '[]'::jsonb, NULL::text, 'ordinal_is_one_to_four'),
    ('ordinal 1', 1, 'KEEP', NULL, 'OPTIMAL', '[]', NULL, NULL),
    ('ordinal 4', 4, 'KEEP', NULL, 'OPTIMAL', '[]', NULL, NULL),
    ('ordinal 5', 5, 'KEEP', NULL, 'OPTIMAL', '[]', NULL, 'ordinal_is_one_to_four'),
    ('the variant K', 1, 'K', NULL, 'OPTIMAL', '[]', NULL, NULL),
    ('the variant TEACHER_GAPS', 1, 'TEACHER_GAPS', NULL, 'OPTIMAL', '[]', NULL, NULL),
    ('a variant of 32 characters', 1, 'A' || repeat('B', 31), NULL, 'OPTIMAL', '[]', NULL, NULL),
    ('a variant of 33 characters', 1, 'A' || repeat('B', 32), NULL, 'OPTIMAL', '[]', NULL, 'variant_is_a_name'),
    ('a variant in lowercase', 1, 'keep', NULL, 'OPTIMAL', '[]', NULL, 'variant_is_a_name'),
    ('a variant from a lowercase letter', 1, 'kEEP', NULL, 'OPTIMAL', '[]', NULL, 'variant_is_a_name'),
    ('a variant ending in lowercase', 1, 'KEEp', NULL, 'OPTIMAL', '[]', NULL, 'variant_is_a_name'),
    ('a variant from a digit', 1, '2KEEP', NULL, 'OPTIMAL', '[]', NULL, 'variant_is_a_name'),
    ('a variant with a dash', 1, 'KEEP-2', NULL, 'OPTIMAL', '[]', NULL, 'variant_is_a_name'),
    ('an empty variant', 1, '', NULL, 'OPTIMAL', '[]', NULL, 'variant_is_a_name'),
    ('a variant and a newline', 1, 'KEEP' || E'\n', NULL, 'OPTIMAL', '[]', NULL, 'variant_is_a_name'),
    ('seed 0', 1, 'KEEP', 0, 'OPTIMAL', '[]', NULL, NULL),
    ('the largest seed', 1, 'KEEP', 2147483647, 'OPTIMAL', '[]', NULL, NULL),
    ('seed -1', 1, 'KEEP', -1, 'OPTIMAL', '[]', NULL, 'seed_is_not_negative'),
    ('FEASIBLE', 1, 'KEEP', NULL, 'FEASIBLE', '[]', NULL, NULL),
    ('INFEASIBLE', 1, 'KEEP', NULL, 'INFEASIBLE', '[]', NULL, NULL),
    ('TIMEOUT', 1, 'KEEP', NULL, 'TIMEOUT', '[]', NULL, NULL),
    ('REJECTED', 1, 'KEEP', NULL, 'REJECTED', '[]', NULL, NULL),
    ('FAILED', 1, 'KEEP', NULL, 'FAILED', '[]', NULL, NULL),
    ('a status in lowercase', 1, 'KEEP', NULL, 'optimal', '[]', NULL, 'solverStatus_is_known'),
    ('an unknown status', 1, 'KEEP', NULL, 'UNKNOWN', '[]', NULL, 'solverStatus_is_known'),
    ('a list of lessons', 1, 'KEEP', NULL, 'OPTIMAL', '[{"requirementId": "00000000-0000-4000-8000-000000001640", "dayOfWeek": 1}]', NULL, NULL),
    ('lessons in an object', 1, 'KEEP', NULL, 'OPTIMAL', '{}', NULL, 'lessons_is_a_list'),
    ('lessons in a string', 1, 'KEEP', NULL, 'OPTIMAL', '"[]"', NULL, 'lessons_is_a_list'),
    ('lessons as JSON null', 1, 'KEEP', NULL, 'OPTIMAL', 'null', NULL, 'lessons_is_a_list'),
    ('a code of 64 characters', 1, 'KEEP', NULL, 'FAILED', '[]', long_name, NULL),
    ('a code of 65 characters', 1, 'KEEP', NULL, 'FAILED', '[]', long_name || 'Z', 'errorCode_is_a_name'),
    ('a code in lowercase', 1, 'KEEP', NULL, 'FAILED', '[]', 'engine_timeout', 'errorCode_is_a_name'),
    ('a code from a lowercase letter', 1, 'KEEP', NULL, 'FAILED', '[]', 'eNGINE_TIMEOUT', 'errorCode_is_a_name'),
    ('a code ending in lowercase', 1, 'KEEP', NULL, 'FAILED', '[]', 'ENGINE_TIMEOUt', 'errorCode_is_a_name'),
    ('a code with a dash', 1, 'KEEP', NULL, 'FAILED', '[]', 'ENGINE-TIMEOUT', 'errorCode_is_a_name'),
    ('a code from a digit', 1, 'KEEP', NULL, 'FAILED', '[]', '5XX', 'errorCode_is_a_name')
  ) AS t(what, ordinal, variant, seed, status, lessons, code, refused_by) LOOP
    got := pg_temp.rls174_try(format(
      'INSERT INTO "ScheduleCandidates" ("runId", "schoolId", ordinal, variant, seed, "solverStatus", lessons, "errorCode")
       VALUES (%L, %L, %s, %L, %L, %L, %L, %L)',
      run, m, c.ordinal, c.variant, c.seed, c.status, c.lessons, c.code));
    want := coalesce('23514:ScheduleCandidates_' || c.refused_by, 'none');
    IF got IS DISTINCT FROM want THEN wrong := wrong || format('candidate with %s: "%s", expected "%s"', c.what, got, want); END IF;
  END LOOP;
  -- The lessons are never left out.
  got := pg_temp.rls174_try(format(
    'INSERT INTO "ScheduleCandidates" ("runId", "schoolId", ordinal, variant, "solverStatus", lessons) VALUES (%L, %L, 1, ''KEEP'', ''OPTIMAL'', NULL)', run, m));
  IF split_part(got, ':', 1) <> '23502' THEN wrong := wrong || format('candidate with no lessons: "%s"', got); END IF;

  -- The free-day wishes: a candidate's notes, and the draft's on a run.
  -- what, notes, refused by (the constraint's name after the column)
  FOR c IN SELECT * FROM (VALUES
    ('no notes', NULL::jsonb, NULL::text),
    ('an empty list', '[]', NULL),
    ('a list of notes', '[{"code": "TEACHER_FREE_DAY_WISH_NOT_KEPT", "params": {"day": 3}, "subjectIds": ["00000000-0000-4000-8000-000000000105"]}]', NULL),
    ('notes in an object', '{}', 'is_a_list'),
    ('notes in a string', '"[]"', 'is_a_list'),
    ('notes as JSON null', 'null', 'is_a_list')
  ) AS t(what, notes, refused_by) LOOP
    got := pg_temp.rls174_try(format(
      'INSERT INTO "ScheduleCandidates" ("runId", "schoolId", ordinal, variant, "solverStatus", notes)
       VALUES (%L, %L, 1, ''KEEP'', ''OPTIMAL'', %L)', run, m, c.notes));
    want := coalesce('23514:ScheduleCandidates_notes_' || c.refused_by, 'none');
    IF got IS DISTINCT FROM want THEN wrong := wrong || format('candidate with %s: "%s", expected "%s"', c.what, got, want); END IF;
    got := pg_temp.rls174_try(format(
      'INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", status, requested, progress, "draftNotes")
       VALUES (%L, %L, ''SUCCEEDED'', 2, 2, %L)', m, yr, c.notes));
    want := coalesce('23514:ScheduleCandidateRuns_draftNotes_' || c.refused_by, 'none');
    IF got IS DISTINCT FROM want THEN wrong := wrong || format('run with %s for its draft: "%s", expected "%s"', c.what, got, want); END IF;
  END LOOP;

  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'candidate checks: %', array_to_string(wrong, '; ');
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 175: städningen markerar körningar som har tappat sin instans och
-- tar bort dem som är äldre än sju dagar, i alla skolor
-- (app.schedule_candidates_sweep).
--
-- One transaction, so now() is one instant for the rows planted and for the
-- sweep, and the boundaries are exact. The sweep is called once first, so
-- that whatever the database already holds for it is done and its count
-- below is this section's rows alone. Then, with no principal at all (the
-- gateway's short transaction of its own):
--
--   * an active run whose heartbeat plus its own lease is a millisecond past
--     (RUNNING, lease 600 s), or whose lease of 60 s ran out a second ago,
--     or which no task took up (PENDING, its lease out a minute ago), or
--     which began half an hour and a millisecond ago (CANCELLING, a fresh
--     heartbeat), is FAILED with CANDIDATE_RUN_ABANDONED, its old error and
--     errorParams replaced, finishedAt now; so is the primary school's stale
--     run;
--   * a run whose lease ends exactly now, one begun exactly half an hour
--     ago, one with a lease of an hour and a heartbeat 25 minutes old, and a
--     fresh one stay as they were, as does a finished run with an old
--     heartbeat;
--   * a run created seven days and a millisecond ago is deleted with its
--     candidates, applied or not, in either school, and one created exactly
--     seven days ago is kept;
--   * a discarded run whose engine call ended a millisecond ago, or exactly
--     now, or which has no call, is deleted (its candidate along, should one
--     be left), in either school; one whose call ends a millisecond from now
--     is kept, as is an undiscarded finished run whose call has ended;
--   * the sweep returns 12 (five marked, seven deleted), and 0 when called
--     again; a year whose run it marked takes a new run.
--
-- Only an owner's function sees both schools with no principal; section 170
-- reads that it is one.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls175_other', :'admin_auth_id', true);
SELECT app.schedule_candidates_sweep() >= 0;

CREATE FUNCTION pg_temp.rls175_as(sub text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  PERFORM set_config('request.jwt.claims', CASE WHEN sub IS NULL THEN '' ELSE json_build_object('sub', sub)::text END, true);
END $$;
-- A run of the current principal's school in a year of its own.
CREATE FUNCTION pg_temp.rls175_run(label text, status text, heartbeat timestamptz, lease integer, created timestamptz)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE yr uuid; run uuid;
BEGIN
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (app.current_school_id(), 'RLS175 ' || label, DATE '2070-08-15', DATE '2071-06-10', false, now()) RETURNING id INTO yr;
  INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", status, requested, progress, "heartbeatAt", "leaseSeconds",
                                       "createdAt", error, "errorCode", "errorParams")
  VALUES (app.current_school_id(), yr, status::"ScheduleCandidateRunStatus", 2, 1, heartbeat, lease, created,
          'RLS175 tidigare fel', 'RLS175_EARLIER', '{"x": 1}')
  RETURNING id INTO run;
  RETURN run;
END $$;

DO $$
DECLARE
  t constant timestamptz := now();
  ms constant interval := interval '1 millisecond';
  other constant text := current_setting('app.test_rls175_other');
  r jsonb := '{}';
  n integer;
  rec record;
  cand uuid;
BEGIN
  PERFORM pg_temp.rls175_as('00000000-0000-4000-8000-000000000105');
  IF (SELECT slug FROM "Schools" WHERE id = app.current_school_id()) IS DISTINCT FROM 'rls-roller-school' THEN
    RAISE EXCEPTION 'sweep: the full administrator is not in rls-roller-school; fixtures did not run';
  END IF;
  r := r || jsonb_build_object(
    'past_lease', pg_temp.rls175_run('past_lease', 'RUNNING', t - interval '600 seconds' - ms, 600, t - interval '20 minutes'),
    'short_lease', pg_temp.rls175_run('short_lease', 'RUNNING', t - interval '61 seconds', 60, t - interval '2 minutes'),
    'never_taken', pg_temp.rls175_run('never_taken', 'PENDING', t - interval '11 minutes', 600, t - interval '11 minutes'),
    'half_hour_old', pg_temp.rls175_run('half_hour_old', 'CANCELLING', t, 600, t - interval '30 minutes' - ms),
    'lease_ends_now', pg_temp.rls175_run('lease_ends_now', 'PENDING', t - interval '600 seconds', 600, t - interval '20 minutes'),
    'exactly_half_hour', pg_temp.rls175_run('exactly_half_hour', 'RUNNING', t, 600, t - interval '30 minutes'),
    'long_lease', pg_temp.rls175_run('long_lease', 'RUNNING', t - interval '25 minutes', 3600, t - interval '26 minutes'),
    'fresh', pg_temp.rls175_run('fresh', 'PENDING', t, 600, t),
    'finished', pg_temp.rls175_run('finished', 'SUCCEEDED', t - interval '1 day', 600, t - interval '2 days'),
    'week_old', pg_temp.rls175_run('week_old', 'FAILED', t - interval '7 days', 600, t - interval '7 days' - ms),
    'applied_old', pg_temp.rls175_run('applied_old', 'SUCCEEDED', t - interval '30 days', 600, t - interval '30 days'),
    'exactly_week', pg_temp.rls175_run('exactly_week', 'SUCCEEDED', t - interval '7 days', 600, t - interval '7 days'),
    'discarded_ended', pg_temp.rls175_run('discarded_ended', 'FAILED', t, 600, t - interval '2 minutes'),
    'discarded_ends_now', pg_temp.rls175_run('discarded_ends_now', 'FAILED', t, 600, t - interval '2 minutes'),
    'discarded_no_call', pg_temp.rls175_run('discarded_no_call', 'FAILED', t, 600, t - interval '2 minutes'),
    'discarded_out', pg_temp.rls175_run('discarded_out', 'FAILED', t, 600, t - interval '2 minutes'),
    'call_ended', pg_temp.rls175_run('call_ended', 'FAILED', t, 600, t - interval '2 minutes'));
  INSERT INTO "ScheduleCandidates" ("runId", "schoolId", ordinal, variant, "solverStatus")
  SELECT (r ->> w.name)::uuid, app.current_school_id(), 1, 'KEEP', 'OPTIMAL'
    FROM unnest(ARRAY['week_old', 'applied_old', 'exactly_week', 'discarded_ended']) w(name);
  UPDATE "ScheduleCandidateRuns" c SET "discardedAt" = t - interval '1 minute', "engineBusyUntil" = x.busy
    FROM (VALUES ('discarded_ended', t - ms), ('discarded_ends_now', t), ('discarded_no_call', NULL::timestamptz),
                 ('discarded_out', t + ms)) x(name, busy)
   WHERE c.id = (r ->> x.name)::uuid;
  UPDATE "ScheduleCandidateRuns" SET "engineBusyUntil" = t - ms WHERE id = (r ->> 'call_ended')::uuid;
  UPDATE "ScheduleCandidateRuns" c SET "appliedCandidateId" = x.id, "appliedAt" = t - interval '29 days'
    FROM "ScheduleCandidates" x WHERE x."runId" = c.id AND c.id = (r ->> 'applied_old')::uuid;

  PERFORM pg_temp.rls175_as(other);
  r := r || jsonb_build_object(
    'other_stale', pg_temp.rls175_run('other_stale', 'RUNNING', t - interval '2 hours', 600, t - interval '3 hours'),
    'other_old', pg_temp.rls175_run('other_old', 'FAILED', t - interval '8 days', 600, t - interval '8 days'),
    'other_discarded', pg_temp.rls175_run('other_discarded', 'SUCCEEDED', t, 600, t - interval '2 minutes'));
  INSERT INTO "ScheduleCandidates" ("runId", "schoolId", ordinal, variant, "solverStatus")
  VALUES ((r ->> 'other_old')::uuid, app.current_school_id(), 1, 'KEEP', 'OPTIMAL');
  UPDATE "ScheduleCandidateRuns" SET "discardedAt" = t - interval '1 minute', "engineBusyUntil" = t - interval '1 minute'
   WHERE id = (r ->> 'other_discarded')::uuid;
  PERFORM set_config('app.test_rls175', r::text, true);

  -- The sweep, with no principal.
  PERFORM pg_temp.rls175_as(NULL);
  n := app.schedule_candidates_sweep();
  IF n IS DISTINCT FROM 12 THEN RAISE EXCEPTION 'sweep: it changed % rows, expected 5 marked and 7 deleted', n; END IF;

  -- What it did, as each school's administrator.
  FOR rec IN SELECT * FROM (VALUES
    ('past_lease', 'ABANDONED', '00000000-0000-4000-8000-000000000105'),
    ('short_lease', 'ABANDONED', '00000000-0000-4000-8000-000000000105'),
    ('never_taken', 'ABANDONED', '00000000-0000-4000-8000-000000000105'),
    ('half_hour_old', 'ABANDONED', '00000000-0000-4000-8000-000000000105'),
    ('lease_ends_now', 'PENDING', '00000000-0000-4000-8000-000000000105'),
    ('exactly_half_hour', 'RUNNING', '00000000-0000-4000-8000-000000000105'),
    ('long_lease', 'RUNNING', '00000000-0000-4000-8000-000000000105'),
    ('fresh', 'PENDING', '00000000-0000-4000-8000-000000000105'),
    ('finished', 'SUCCEEDED', '00000000-0000-4000-8000-000000000105'),
    ('week_old', 'GONE', '00000000-0000-4000-8000-000000000105'),
    ('applied_old', 'GONE', '00000000-0000-4000-8000-000000000105'),
    ('exactly_week', 'SUCCEEDED', '00000000-0000-4000-8000-000000000105'),
    ('discarded_ended', 'GONE', '00000000-0000-4000-8000-000000000105'),
    ('discarded_ends_now', 'GONE', '00000000-0000-4000-8000-000000000105'),
    ('discarded_no_call', 'GONE', '00000000-0000-4000-8000-000000000105'),
    ('discarded_out', 'FAILED', '00000000-0000-4000-8000-000000000105'),
    ('call_ended', 'FAILED', '00000000-0000-4000-8000-000000000105'),
    ('other_stale', 'ABANDONED', other),
    ('other_old', 'GONE', other),
    ('other_discarded', 'GONE', other)
  ) AS v(name, expected, sub) LOOP
    PERFORM pg_temp.rls175_as(rec.sub);
    IF rec.expected = 'GONE' THEN
      IF EXISTS (SELECT 1 FROM "ScheduleCandidateRuns" WHERE id = (r ->> rec.name)::uuid)
         OR EXISTS (SELECT 1 FROM "ScheduleCandidates" WHERE "runId" = (r ->> rec.name)::uuid) THEN
        RAISE EXCEPTION 'sweep: the run "%" or its candidate is still there', rec.name;
      END IF;
    ELSIF rec.expected = 'ABANDONED' THEN
      IF NOT EXISTS (SELECT 1 FROM "ScheduleCandidateRuns" WHERE id = (r ->> rec.name)::uuid AND status = 'FAILED'
                        AND "errorCode" = 'CANDIDATE_RUN_ABANDONED' AND error = 'The run stopped before it finished.'
                        AND "errorParams" IS NULL AND "finishedAt" = t) THEN
        RAISE EXCEPTION 'sweep: the run "%" was not marked abandoned: %', rec.name,
          (SELECT row_to_json(x) FROM (SELECT status, error, "errorCode", "errorParams", "finishedAt"
                                         FROM "ScheduleCandidateRuns" WHERE id = (r ->> rec.name)::uuid) x);
      END IF;
    ELSIF NOT EXISTS (SELECT 1 FROM "ScheduleCandidateRuns" WHERE id = (r ->> rec.name)::uuid AND status::text = rec.expected
                         AND "errorCode" = 'RLS175_EARLIER' AND "errorParams" IS NOT NULL AND "finishedAt" IS NULL) THEN
      RAISE EXCEPTION 'sweep: the run "%" was changed: %', rec.name,
        (SELECT row_to_json(x) FROM (SELECT status, "errorCode", "finishedAt" FROM "ScheduleCandidateRuns"
                                       WHERE id = (r ->> rec.name)::uuid) x);
    END IF;
  END LOOP;
  PERFORM pg_temp.rls175_as('00000000-0000-4000-8000-000000000105');
  IF NOT EXISTS (SELECT 1 FROM "ScheduleCandidates" WHERE "runId" = (r ->> 'exactly_week')::uuid) THEN
    RAISE EXCEPTION 'sweep: the candidate of a run exactly seven days old is gone';
  END IF;

  -- Nothing is left for a second call, and the marked run's year is free.
  PERFORM pg_temp.rls175_as(NULL);
  n := app.schedule_candidates_sweep();
  IF n IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'sweep: a second call changed % rows', n; END IF;
  PERFORM pg_temp.rls175_as('00000000-0000-4000-8000-000000000105');
  INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", requested)
  SELECT "schoolId", "academicYearId", 2 FROM "ScheduleCandidateRuns" WHERE id = (r ->> 'past_lease')::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'sweep: the year of an abandoned run took no new run'; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 176: städningen väntar aldrig på en rad som en annan transaktion
-- håller (app.schedule_candidates_sweep, FOR UPDATE SKIP LOCKED).
--
-- The gateway sweeps before every start, and a run's task holds its row FOR
-- UPDATE while it stores a candidate. A sweep that waited on that lock would
-- hold every school's start behind one school's engine call. Showing that it
-- does not takes a second transaction, so this section opens a second
-- connection: \o pipes this connection's output through a shell that starts
-- one more psql (connected the same way, by the \setenv lines; the password
-- is the runner's PGPASSWORD) and passes the output on through cat. That
-- psql commits two runs of the matrix school that the sweep changes, one an
-- hour past its lease and one eight days old with a candidate; locks both
-- FOR UPDATE; says so with the advisory lock (176, 2); and, until this
-- transaction's (176, 1) is gone, polls rather than waits for it, so that a
-- sweep waiting on its rows is no deadlock the server would break by ending
-- the second connection. Here, with lock_timeout 5 s, the sweep returns, and
-- both rows are as they were, still held and still past their time. A sweep
-- that waited would end in 55P03.
--
-- The shell waits for its psql, and \o waits for the shell, so the second
-- connection is this one's child to the end and is never left to the
-- container's init (the postmaster, which would take a child that exits
-- with an error for a crashed backend). Its runs are gone before the next
-- section, and are cleared first if an earlier run left them.
-- ---------------------------------------------------------------------------

\set rls176 'SET statement_timeout = ''120s''; '
\set rls176 :rls176 'SELECT set_config(''request.jwt.claims'', ''{"sub": "00000000-0000-4000-8000-000000000105"}'', false); '
\set rls176 :rls176 'DELETE FROM "ScheduleCandidateRuns" WHERE id IN (''00000000-0000-4000-8000-000000001661'', ''00000000-0000-4000-8000-000000001662''); '
\set rls176 :rls176 'INSERT INTO "ScheduleCandidateRuns" (id, "schoolId", "academicYearId", status, requested, progress, "heartbeatAt", "leaseSeconds", "createdAt") '
\set rls176 :rls176 'SELECT x.id, y."schoolId", y.id, x.status, 2, 1, x.beat, 600, x.made FROM "AcademicYears" y, (VALUES '
\set rls176 :rls176 '(''00000000-0000-4000-8000-000000001661''::uuid, ''RUNNING''::"ScheduleCandidateRunStatus", now() - interval ''1 hour'', now() - interval ''2 hours''), '
\set rls176 :rls176 '(''00000000-0000-4000-8000-000000001662''::uuid, ''FAILED''::"ScheduleCandidateRunStatus", now() - interval ''8 days'', now() - interval ''8 days'')) '
\set rls176 :rls176 'x(id, status, beat, made) WHERE y."schoolId" = app.current_school_id() AND y.name = ''Roller 2030/31''; '
\set rls176 :rls176 'INSERT INTO "ScheduleCandidates" ("runId", "schoolId", ordinal, variant, "solverStatus") '
\set rls176 :rls176 'SELECT id, "schoolId", 1, ''KEEP'', ''OPTIMAL'' FROM "ScheduleCandidateRuns" WHERE id = ''00000000-0000-4000-8000-000000001662''; '
\set rls176 :rls176 'BEGIN; '
\set rls176 :rls176 'SELECT count(*) FROM (SELECT 1 FROM "ScheduleCandidateRuns" WHERE id IN (''00000000-0000-4000-8000-000000001661'', ''00000000-0000-4000-8000-000000001662'') FOR UPDATE) held; '
\set rls176 :rls176 'SELECT pg_advisory_xact_lock(176, 2); '
\set rls176 :rls176 'DO $$ BEGIN WHILE EXISTS (SELECT 1 FROM pg_locks WHERE locktype = ''advisory'' AND classid = 176 AND objid = 1 AND objsubid = 2) '
\set rls176 :rls176 'LOOP PERFORM pg_sleep(0.05); END LOOP; END $$; '
\set rls176 :rls176 'DELETE FROM "ScheduleCandidateRuns" WHERE id IN (''00000000-0000-4000-8000-000000001661'', ''00000000-0000-4000-8000-000000001662''); '
\set rls176 :rls176 'COMMIT;'
\setenv RLS176_SQL :rls176
\setenv PGHOST :HOST
\setenv PGPORT :PORT
\setenv PGUSER :USER
\setenv PGDATABASE :DBNAME

BEGIN;
SELECT pg_advisory_xact_lock(176, 1);
\o | printf '%s\n' "$RLS176_SQL" | psql -X -q -v ON_ERROR_STOP=1 -f - >/dev/null & cat; wait; exit 0

-- The second connection holds its rows.
DO $$
DECLARE
  deadline constant timestamptz := clock_timestamp() + interval '60 seconds';
BEGIN
  LOOP
    EXIT WHEN EXISTS (SELECT 1 FROM pg_locks
                       WHERE locktype = 'advisory' AND database = (SELECT oid FROM pg_database WHERE datname = current_database())
                         AND classid = 176 AND objid = 2 AND objsubid = 2 AND granted AND pid <> pg_backend_pid());
    IF clock_timestamp() > deadline THEN
      RAISE EXCEPTION 'sweep and held rows: the second connection never held its runs (its error, if any, is above)';
    END IF;
    PERFORM pg_sleep(0.05);
  END LOOP;
END $$;

DO $$
DECLARE
  stale constant uuid := '00000000-0000-4000-8000-000000001661';
  old constant uuid := '00000000-0000-4000-8000-000000001662';
  n integer;
BEGIN
  PERFORM set_config('lock_timeout', '5s', true);
  PERFORM set_config('request.jwt.claims', '', true);
  BEGIN
    n := app.schedule_candidates_sweep();
  EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION 'sweep and held rows: the sweep waited on a run another transaction holds (%)', SQLERRM;
  END;
  PERFORM set_config('lock_timeout', '0', true);

  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  IF NOT EXISTS (SELECT 1 FROM "ScheduleCandidateRuns" WHERE id = stale AND status = 'RUNNING' AND "errorCode" IS NULL
                    AND "heartbeatAt" + make_interval(secs => "leaseSeconds") < now()) THEN
    RAISE EXCEPTION 'sweep and held rows: the held run past its lease was changed, or is not past it: %',
      (SELECT row_to_json(r) FROM (SELECT status, "errorCode", "heartbeatAt" FROM "ScheduleCandidateRuns" WHERE id = stale) r);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "ScheduleCandidateRuns" WHERE id = old AND "createdAt" < now() - interval '7 days')
     OR NOT EXISTS (SELECT 1 FROM "ScheduleCandidates" WHERE "runId" = old) THEN
    RAISE EXCEPTION 'sweep and held rows: the held run older than seven days, or its candidate, is gone';
  END IF;
  -- And they are held, which is why the sweep left them.
  FOREACH n IN ARRAY ARRAY[1, 2] LOOP
    BEGIN
      PERFORM 1 FROM "ScheduleCandidateRuns" WHERE id = (CASE n WHEN 1 THEN stale ELSE old END) FOR UPDATE NOWAIT;
      RAISE EXCEPTION 'sweep and held rows: run % is not held by the second connection', n;
    EXCEPTION WHEN lock_not_available THEN NULL;
    END;
  END LOOP;
END $$;
ROLLBACK;
\o
\setenv RLS176_SQL
\setenv PGHOST
\setenv PGPORT
\setenv PGUSER
\setenv PGDATABASE

-- The second connection has removed its runs and is gone.
DO $$
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  IF EXISTS (SELECT 1 FROM "ScheduleCandidateRuns"
              WHERE id IN ('00000000-0000-4000-8000-000000001661', '00000000-0000-4000-8000-000000001662')) THEN
    RAISE EXCEPTION 'sweep and held rows: the second connection left its runs behind';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_locks WHERE locktype = 'advisory' AND classid = 176 AND objsubid = 2) THEN
    RAISE EXCEPTION 'sweep and held rows: the second connection is still there';
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Section 177: hur många körningar som är aktiva, i alla skolor
-- (app.schedule_candidate_runs_active).
--
-- The count the gateway caps concurrent runs with is the runs the sweep
-- would leave active: PENDING, RUNNING and CANCELLING ones whose heartbeat
-- plus their own lease is now or later and which began half an hour ago or
-- later, in every school. In one transaction, against the count before:
-- a fresh run of each active status, one whose lease ends exactly now, one
-- begun exactly half an hour ago, one with a lease of an hour and a 25
-- minutes old heartbeat, and the primary school's fresh run are counted;
-- finished runs, a run a millisecond past its lease or past half an hour,
-- and one whose lease of 60 s ran out are not. A run whose last engine call
-- can still be solving (engineBusyUntil later than now) is counted whatever
-- its status — one failed under its call, as a restart leaves it, one past
-- its lease, and one a discard hid while its call was out — once each; one
-- whose call ended a millisecond ago is not, discarded or not.
-- The count is the same asked by the matrix school's FULL, by its teacher
-- and with no principal, and after a sweep, which marks exactly the runs it
-- left out.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls177_other', :'admin_auth_id', true);

CREATE FUNCTION pg_temp.rls177_as(sub text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  PERFORM set_config('request.jwt.claims', CASE WHEN sub IS NULL THEN '' ELSE json_build_object('sub', sub)::text END, true);
END $$;
-- A run of the current principal's school in a year of its own.
CREATE FUNCTION pg_temp.rls177_run(status text, heartbeat timestamptz, lease integer, created timestamptz,
                                   busy timestamptz DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE yr uuid; run uuid;
BEGIN
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (app.current_school_id(), 'RLS177 år ' || gen_random_uuid(), DATE '2075-08-15', DATE '2076-06-10', false, now()) RETURNING id INTO yr;
  INSERT INTO "ScheduleCandidateRuns" ("schoolId", "academicYearId", status, requested, "heartbeatAt", "leaseSeconds", "createdAt", "engineBusyUntil")
  VALUES (app.current_school_id(), yr, status::"ScheduleCandidateRunStatus", 2, heartbeat, lease, created, busy)
  RETURNING id INTO run;
  RETURN run;
END $$;

DO $$
DECLARE
  t constant timestamptz := now();
  ms constant interval := interval '1 millisecond';
  before integer;
  n integer;
  sub text;
  m uuid;
  d uuid;
BEGIN
  PERFORM pg_temp.rls177_as(NULL);
  before := app.schedule_candidate_runs_active();

  PERFORM pg_temp.rls177_as('00000000-0000-4000-8000-000000000105');
  m := app.current_school_id();
  -- Counted.
  PERFORM pg_temp.rls177_run('PENDING', t, 600, t);
  PERFORM pg_temp.rls177_run('RUNNING', t, 600, t);
  PERFORM pg_temp.rls177_run('CANCELLING', t, 600, t);
  PERFORM pg_temp.rls177_run('RUNNING', t - interval '600 seconds', 600, t - interval '20 minutes');
  PERFORM pg_temp.rls177_run('PENDING', t, 600, t - interval '30 minutes');
  PERFORM pg_temp.rls177_run('RUNNING', t - interval '25 minutes', 3600, t - interval '26 minutes');
  -- Counted for the engine call still out: failed under it, and past its lease.
  PERFORM pg_temp.rls177_run('FAILED', t, 600, t, t + interval '1 second');
  PERFORM pg_temp.rls177_run('RUNNING', t - interval '600 seconds' - ms, 600, t - interval '20 minutes', t + interval '10 seconds');
  d := pg_temp.rls177_run('FAILED', t, 600, t, t + ms);
  UPDATE "ScheduleCandidateRuns" SET "discardedAt" = t WHERE id = d;
  -- Not counted.
  PERFORM pg_temp.rls177_run('FAILED', t, 600, t, t - ms);
  d := pg_temp.rls177_run('FAILED', t, 600, t, t - ms);
  UPDATE "ScheduleCandidateRuns" SET "discardedAt" = t WHERE id = d;
  PERFORM pg_temp.rls177_run('SUCCEEDED', t, 600, t);
  PERFORM pg_temp.rls177_run('FAILED', t, 600, t);
  PERFORM pg_temp.rls177_run('RUNNING', t - interval '600 seconds' - ms, 600, t - interval '20 minutes');
  PERFORM pg_temp.rls177_run('PENDING', t, 600, t - interval '30 minutes' - ms);
  PERFORM pg_temp.rls177_run('RUNNING', t - interval '61 seconds', 60, t - interval '2 minutes');
  -- The primary school's, counted.
  PERFORM pg_temp.rls177_as(current_setting('app.test_rls177_other'));
  PERFORM pg_temp.rls177_run('PENDING', t, 600, t);

  FOREACH sub IN ARRAY ARRAY['00000000-0000-4000-8000-000000000105', '00000000-0000-4000-8000-000000000111', NULL] LOOP
    PERFORM pg_temp.rls177_as(sub);
    n := app.schedule_candidate_runs_active();
    IF n IS DISTINCT FROM before + 10 THEN
      RAISE EXCEPTION 'active runs: asked by %, the count is %, expected % before and 10 more', coalesce(sub, 'no principal'), n, before;
    END IF;
  END LOOP;

  -- The sweep marks what the count left out, and nothing it counted (the run
  -- past its lease it marks FAILED is counted on for its engine call); it
  -- deletes the discarded run whose call ended, and keeps the one counted.
  PERFORM app.schedule_candidates_sweep();
  n := app.schedule_candidate_runs_active();
  IF n IS DISTINCT FROM before + 10 THEN RAISE EXCEPTION 'active runs: after a sweep the count is %, expected %', n, before + 10; END IF;
  PERFORM pg_temp.rls177_as('00000000-0000-4000-8000-000000000105');
  IF EXISTS (SELECT 1 FROM "ScheduleCandidateRuns" WHERE id = d) THEN
    RAISE EXCEPTION 'active runs: the sweep kept a discarded run whose call had ended';
  END IF;
  IF (SELECT count(*) FROM "ScheduleCandidateRuns" WHERE "schoolId" = m AND "discardedAt" IS NOT NULL) <> 1 THEN
    RAISE EXCEPTION 'active runs: the sweep deleted the discarded run whose call is out';
  END IF;
  SELECT count(*) INTO n FROM "ScheduleCandidateRuns" WHERE "schoolId" = m AND status IN ('PENDING', 'RUNNING', 'CANCELLING');
  IF n <> 6 THEN RAISE EXCEPTION 'active runs: the sweep left % of the matrix school''s runs active, the count counted 6', n; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 178: en handredigering tar sin del av läsårets omskrivningslås och
-- lämnar sin lock_timeout som den var (app.lock_years_for_grundschema_edit).
--
-- MasterLessonsService takes it after the plain read that names a lesson's
-- year and before its first row lock, so an edit meeting an apply, a
-- Generera write or a restore (which take the same key exclusively in the
-- gateway) answers 409 within 5 s, and an apply and an edit never deadlock.
-- In one transaction: a call over two years, one of them twice and a NULL
-- beside them, takes exactly two advisory locks, both SHARED and both on the
-- gateway's keys — (hashtext('grundschema-regenerate'), hashtext(year)) — and
-- the caller's lock_timeout is what it was before the call. That a held
-- exclusive key makes it give up in 5 s with 55P03 is the probe's (sc-f),
-- against the real services: one connection cannot hold both sides.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  y1 constant uuid := '00000000-0000-4000-8000-000000001681';
  y2 constant uuid := '00000000-0000-4000-8000-000000001682';
  before_locks integer;
  after_locks integer;
  key1 constant bigint := hashtext('grundschema-regenerate')::bigint & 4294967295;
BEGIN
  PERFORM set_config('lock_timeout', '7s', true);
  SELECT count(*) INTO before_locks FROM pg_locks WHERE locktype = 'advisory' AND pid = pg_backend_pid();

  PERFORM app.lock_years_for_grundschema_edit(ARRAY[y2, y1, y1, NULL]::uuid[]);

  IF current_setting('lock_timeout') <> '7s' THEN
    RAISE EXCEPTION 'edit lock: the caller''s lock_timeout is % after the call, it was 7s', current_setting('lock_timeout');
  END IF;
  SELECT count(*) INTO after_locks FROM pg_locks WHERE locktype = 'advisory' AND pid = pg_backend_pid();
  IF after_locks - before_locks <> 2 THEN
    RAISE EXCEPTION 'edit lock: two years took % advisory locks, expected one each', after_locks - before_locks;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_locks WHERE locktype = 'advisory' AND pid = pg_backend_pid() AND mode <> 'ShareLock') THEN
    RAISE EXCEPTION 'edit lock: it took an advisory lock exclusively, which would keep every other edit of the year out';
  END IF;
  IF (SELECT count(*) FROM pg_locks
       WHERE locktype = 'advisory' AND pid = pg_backend_pid() AND mode = 'ShareLock' AND objsubid = 2
         AND classid::bigint = key1
         AND objid::bigint IN (hashtext(y1::text)::bigint & 4294967295, hashtext(y2::text)::bigint & 4294967295)) <> 2 THEN
    RAISE EXCEPTION 'edit lock: its keys are not the gateway''s (hashtext(''grundschema-regenerate''), hashtext(year))';
  END IF;

  -- No year, no lock, and the setting untouched.
  PERFORM app.lock_years_for_grundschema_edit(ARRAY[]::uuid[]);
  IF current_setting('lock_timeout') <> '7s' THEN
    RAISE EXCEPTION 'edit lock: an empty call left lock_timeout at %', current_setting('lock_timeout');
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 190: specialskolans elfte årskurs (20261126090000).
--
-- Specialskolan's 2028 total is the statute's like the other three: SPECIAL-
-- SKOLA, 8 604 h, HT2028, COHORTS_STARTING, no cells, no pool and no cap, and
-- bilaga 3 points at it — every bilaga's 2028 total is its own plus 534 h.
-- Årskurs 11 fits wherever an årskurs of the tioårig numbering is stored: an
-- admin plans it in a specialskola plan on the new lydelse and attaches it to
-- a läsår, a cancellation names it, and the statements' CHECKs admit it. 12 is
-- refused (sections 18 and 131). A unit's span is not one of them: it is in
-- the nine-year numbering, F–10 at most, and 11 is refused (section 132).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', :'admin_auth_id')::text, true);
DO $$
DECLARE
  school uuid := app.current_school_id();
  v record;
  spe uuid; year uuid; plan uuid; subject uuid;
  n bigint;
  def text;
BEGIN
  IF app.current_user_role() <> 'SCHOOL_ADMIN' THEN
    RAISE EXCEPTION 'åk 11: expected to be acting as an admin, am %', app.current_user_role();
  END IF;

  SELECT * INTO v FROM "NationalTimplanVersions" WHERE code = 'SFS2025:729/SPE';
  IF NOT FOUND OR v."schoolForm" <> 'SPECIALSKOLA' OR v."totalHours" <> 8604 OR v."appliesFromCohortTerm" <> 'HT2028'
     OR v."appliesBy" <> 'COHORTS_STARTING' OR v."skolansValHours" IS NOT NULL OR v."reductionCapPercent" IS NOT NULL
     OR v."supersededByCode" IS NOT NULL THEN
    RAISE EXCEPTION 'åk 11: specialskolan''s 2028 total reads as %', row_to_json(v);
  END IF;
  spe := v.id;
  IF EXISTS (SELECT 1 FROM "NationalTimplanEntries" WHERE "versionId" = spe) THEN
    RAISE EXCEPTION 'åk 11: specialskolan''s 2028 total carries a cell nobody has published';
  END IF;
  IF (SELECT "supersededByCode" FROM "NationalTimplanVersions" WHERE code = 'SFS2023:945/B3') IS DISTINCT FROM 'SFS2025:729/SPE' THEN
    RAISE EXCEPTION 'åk 11: bilaga 3 does not point at specialskolan''s 2028 total';
  END IF;
  SELECT count(*) INTO n FROM "NationalTimplanVersions" old
    JOIN "NationalTimplanVersions" new ON new.code = old."supersededByCode"
   WHERE new."totalHours" = old."totalHours" + 534 AND new."appliesFromCohortTerm" = 'HT2028';
  IF n <> 5 THEN
    RAISE EXCEPTION 'åk 11: % of the five bilagor point at a 2028 total 534 h above their own', n;
  END IF;

  -- An admin's specialskola plan on the new lydelse, åk 11 planned and attached.
  INSERT INTO "Subjects" ("schoolId", name, code, "nationalCode", "updatedAt")
  VALUES (school, 'RLS160 matematik', 'RLS160', 'MA', now()) RETURNING id INTO subject;
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (school, 'RLS160 år', DATE '2098-08-15', DATE '2099-06-10', false, now()) RETURNING id INTO year;
  INSERT INTO "LocalTimplans" ("schoolId", name, "schoolForm", "nationalTimplanVersionId", "updatedAt")
  VALUES (school, 'RLS160 specialskolan', 'SPECIALSKOLA', spe, now()) RETURNING id INTO plan;
  INSERT INTO "LocalTimplanEntries" ("schoolId", "localTimplanId", "subjectId", "gradeLevel", "minutesPerWeek")
  VALUES (school, plan, subject, 11, 120);
  INSERT INTO "AcademicYearTimplans" ("schoolId", "academicYearId", "gradeLevel", "localTimplanId", "updatedAt")
  VALUES (school, year, 11, plan, now());
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN
    RAISE EXCEPTION 'åk 11: an admin attached % of 1 eleventh årskurs', n;
  END IF;

  -- A cancellation for åk 11.
  INSERT INTO "CancellationBatches" ("schoolId", "academicYearId", name, cause, "fromDate", "toDate", scope, "minGradeLevel", "maxGradeLevel")
  VALUES (school, year, 'RLS160 åk 11', 'MANUAL', DATE '2098-09-01', DATE '2098-09-01', 'GRADES', 11, 11);
  -- A unit's span stays nine-year: its CHECK still ends at 10.
  SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint
   WHERE conrelid = '"SchoolUnits"'::regclass AND conname = 'SchoolUnits_span_check';
  IF def NOT LIKE '%"gradeTo" <= 10%' THEN
    RAISE EXCEPTION 'åk 11: a unit''s span CHECK reads %', def;
  END IF;

  -- The statements' two CHECKs admit 11 and nothing above it.
  SELECT string_agg(pg_get_constraintdef(oid), ' ' ORDER BY conname) INTO def
    FROM pg_constraint
   WHERE conrelid = '"TimplanStatements"'::regclass
     AND conname IN ('TimplanStatements_grades_are_sane', 'TimplanStatements_grade_lists_are_sane');
  IF def NOT LIKE '%"gradesTo" <= 11%' OR def NOT LIKE '%10, 11]%' OR def LIKE '%12%' THEN
    RAISE EXCEPTION 'åk 11: the statements'' CHECKs read %', def;
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 191: ett läsår vet sin numrering (20261126091000).
--
-- AcademicYears."gradeNumbering" is NOT NULL, NIOARIG or TIOARIG, TIOARIG
-- only from 2028-07-01, written once (GN409 after) by a trigger whose function
-- no API role may call. Left out, it is filled: NIOARIG before 2028-07-01,
-- else the numbering of the school's latest läsår from that date before this
-- one, else TIOARIG — so an admin's explicit NIOARIG for a läsår from HT 2028
-- (a school outside the four forms) carries to the next läsår made by hand.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  def text;
BEGIN
  IF NOT (SELECT attnotnull FROM pg_attribute WHERE attrelid = '"AcademicYears"'::regclass AND attname = 'gradeNumbering') THEN
    RAISE EXCEPTION 'numbering: AcademicYears.gradeNumbering may be null';
  END IF;
  IF (SELECT array_agg(enumlabel::text ORDER BY enumsortorder) FROM pg_enum WHERE enumtypid = '"GradeNumbering"'::regtype)
     IS DISTINCT FROM ARRAY['NIOARIG', 'TIOARIG'] THEN
    RAISE EXCEPTION 'numbering: the type is not NIOARIG | TIOARIG';
  END IF;
  SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint
   WHERE conrelid = '"AcademicYears"'::regclass AND conname = 'AcademicYears_tioarig_from_2028';
  IF def IS NULL OR def NOT LIKE '%NIOARIG%' OR def NOT LIKE '%2028-07-01%' THEN
    RAISE EXCEPTION 'numbering: the CHECK reads %', def;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger t
     WHERE t.tgrelid = '"AcademicYears"'::regclass AND t.tgname = 'AcademicYears_numbering'
       AND t.tgfoid = 'app.academic_years_numbering()'::regprocedure AND t.tgenabled = 'O'
       AND (t.tgtype & (1 | 2 | 4 | 16)) = (1 | 2 | 4 | 16)
       AND (SELECT array_agg(a.attname::text) FROM pg_attribute a WHERE a.attrelid = t.tgrelid AND a.attnum = ANY (t.tgattr)) = ARRAY['gradeNumbering']) THEN
    RAISE EXCEPTION 'numbering: the trigger is not BEFORE INSERT OR UPDATE OF gradeNumbering, per row';
  END IF;
  IF has_function_privilege('app_authenticated', 'app.academic_years_numbering()', 'EXECUTE')
     OR (EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated')
         AND has_function_privilege('authenticated', 'app.academic_years_numbering()', 'EXECUTE')) THEN
    RAISE EXCEPTION 'numbering: an API role may call the trigger function';
  END IF;
  IF EXISTS (SELECT 1 FROM "AcademicYears" WHERE "gradeNumbering" = 'TIOARIG' AND "startDate" < DATE '2028-07-01') THEN
    RAISE EXCEPTION 'numbering: a läsår before 2028-07-01 is TIOARIG';
  END IF;
END $$;

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', :'admin_auth_id')::text, true);
DO $$
DECLARE
  school uuid := app.current_school_id();
  earlier uuid; first_t uuid; kept uuid; inherited uuid; renewed uuid; next_t uuid;
  n text; con text; st text; seeded text;
BEGIN
  IF app.current_user_role() <> 'SCHOOL_ADMIN' THEN
    RAISE EXCEPTION 'numbering: expected to be acting as an admin, am %', app.current_user_role();
  END IF;
  -- Far from every seeded year, and in an order that makes each fill visible.
  -- The seed's years move with today: once one starts from HT 2028 (from the
  -- end of 2028, or a seed backfilled NIOARIG in production order), the first
  -- fill below takes its numbering, as the rule says; TIOARIG when there is none.
  SELECT "gradeNumbering"::text INTO seeded FROM "AcademicYears"
   WHERE "schoolId" = school AND "startDate" >= DATE '2028-07-01' AND "startDate" < DATE '2096-08-15'
   ORDER BY "startDate" DESC LIMIT 1;
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (school, 'RLS161 före', DATE '2027-08-16', DATE '2028-06-10', false, now()) RETURNING id INTO earlier;
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (school, 'RLS161 första', DATE '2096-08-15', DATE '2097-06-10', false, now()) RETURNING id INTO first_t;
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt", "gradeNumbering")
  VALUES (school, 'RLS161 behåller', DATE '2097-08-15', DATE '2098-06-10', false, now(), 'NIOARIG') RETURNING id INTO kept;
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (school, 'RLS161 ärver', DATE '2098-08-15', DATE '2099-06-10', false, now()) RETURNING id INTO inherited;
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt", "gradeNumbering")
  VALUES (school, 'RLS161 tioårig', DATE '2099-08-15', DATE '2100-06-10', false, now(), 'TIOARIG') RETURNING id INTO renewed;
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (school, 'RLS161 nästa', DATE '2100-08-15', DATE '2101-06-10', false, now()) RETURNING id INTO next_t;
  SELECT string_agg("gradeNumbering"::text, ',' ORDER BY "startDate") INTO n
    FROM "AcademicYears" WHERE id IN (earlier, first_t, kept, inherited, renewed, next_t);
  IF n IS DISTINCT FROM 'NIOARIG,' || COALESCE(seeded, 'TIOARIG') || ',NIOARIG,NIOARIG,TIOARIG,TIOARIG' THEN
    RAISE EXCEPTION 'numbering: the läsår were filled as %', n;
  END IF;

  -- Written once.
  BEGIN
    UPDATE "AcademicYears" SET "gradeNumbering" = 'TIOARIG' WHERE id = kept;
    RAISE EXCEPTION 'numbering: an admin changed a läsår''s numbering';
  EXCEPTION WHEN SQLSTATE 'GN409' THEN
    GET STACKED DIAGNOSTICS st = MESSAGE_TEXT;
    IF st NOT LIKE 'GRADE_NUMBERING_IS_FIXED:%' THEN RAISE EXCEPTION 'numbering: GN409 said %', st; END IF;
  END;
  -- TIOARIG only from 2028-07-01, whichever way it would land before.
  FOREACH n IN ARRAY ARRAY['moved', 'inserted'] LOOP
    BEGIN
      IF n = 'moved' THEN
        UPDATE "AcademicYears" SET "startDate" = DATE '2027-08-16', "endDate" = DATE '2028-06-09' WHERE id = renewed;
      ELSE
        INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt", "gradeNumbering")
        VALUES (school, 'RLS161 för tidig', DATE '2026-08-17', DATE '2027-06-12', false, now(), 'TIOARIG');
      END IF;
      RAISE EXCEPTION 'numbering: a TIOARIG läsår before 2028-07-01 was %', n;
    EXCEPTION WHEN check_violation THEN
      GET STACKED DIAGNOSTICS con = CONSTRAINT_NAME;
      IF con IS DISTINCT FROM 'AcademicYears_tioarig_from_2028' THEN
        RAISE EXCEPTION 'numbering: a TIOARIG läsår % before 2028-07-01 was refused by "%"', n, con;
      END IF;
    END;
  END LOOP;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 230: lektionsloggen och notisen till vikarien står i katalogen som
-- migreringen säger (LessonLogs, LessonSubstituteNotes, 20261203090000).
--
-- Row security on both tables, not forced; exactly the twelve arms (eight on
-- the logs, four on the notes), all TO app_authenticated; no arm on the notes
-- names a pupil, a guardian or an administrator, and the family's arm on the
-- logs asks the caller's own lessons; the note's teacher writes ask REGULAR,
-- the log's any teacher of the lesson; PostgREST's authenticated and anon
-- hold nothing; service_role reads and writes nothing more;
-- app.lesson_teacher_role and app.substitute_noted_lessons are SECURITY
-- DEFINER, STABLE, their search_path pinned, and the API's alone; the writer
-- is stamped by a trigger on both tables, whose function nobody may call; the
-- checks are there and validated; the keys are composite with the school.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  t text;
  r text;
  p text;
  n bigint;
  fn regprocedure;
BEGIN
  FOREACH t IN ARRAY ARRAY['LessonLogs', 'LessonSubstituteNotes'] LOOP
    IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = format('public.%I', t)::regclass)
       OR (SELECT relforcerowsecurity FROM pg_class WHERE oid = format('public.%I', t)::regclass) THEN
      RAISE EXCEPTION 'lesson log: row security on % is off, or forced on the owner', t;
    END IF;
    SELECT count(*) INTO n FROM pg_policies WHERE schemaname = 'public' AND tablename = t;
    IF (t = 'LessonLogs' AND n <> 8) OR (t = 'LessonSubstituteNotes' AND n <> 4) OR EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = t
                           AND (roles <> '{app_authenticated}' OR permissive <> 'PERMISSIVE')) THEN
      RAISE EXCEPTION 'lesson log: % has % arms, or one not a permissive arm TO app_authenticated', t, n;
    END IF;
    FOREACH r IN ARRAY ARRAY['authenticated', 'anon'] LOOP
      CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
      FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
        IF has_table_privilege(r, format('public.%I', t), p) THEN RAISE EXCEPTION 'lesson log: % holds % on %', r, p, t; END IF;
      END LOOP;
    END LOOP;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
      FOREACH p IN ARRAY ARRAY['INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
        IF has_table_privilege('service_role', format('public.%I', t), p) THEN RAISE EXCEPTION 'lesson log: service_role holds % on %', p, t; END IF;
      END LOOP;
    END IF;
    FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE'] LOOP
      IF NOT has_table_privilege('app_authenticated', format('public.%I', t), p) THEN RAISE EXCEPTION 'lesson log: the API lacks % on %', p, t; END IF;
    END LOOP;
    FOREACH p IN ARRAY ARRAY['TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
      IF has_table_privilege('app_authenticated', format('public.%I', t), p) THEN RAISE EXCEPTION 'lesson log: the API holds % on %', p, t; END IF;
    END LOOP;
    IF current_setting('server_version_num')::int >= 170000 THEN
      FOREACH r IN ARRAY ARRAY['authenticated', 'app_authenticated', 'service_role', 'anon'] LOOP
        CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
        IF has_table_privilege(r, format('public.%I', t), 'MAINTAIN') THEN RAISE EXCEPTION 'lesson log: % holds MAINTAIN on %', r, t; END IF;
      END LOOP;
    END IF;
    -- The writer's trigger, before every insert and update.
    IF NOT EXISTS (SELECT 1 FROM pg_trigger g WHERE g.tgrelid = format('public.%I', t)::regclass
                     AND g.tgname = t || '_written_by_the_writer' AND g.tgenabled = 'O'
                     AND g.tgfoid = 'app.lesson_text_written_by()'::regprocedure
                     AND g.tgtype = (1 | 2 | 4 | 16)::int2) THEN
      RAISE EXCEPTION 'lesson log: % has no enabled BEFORE INSERT OR UPDATE FOR EACH ROW trigger stamping the writer', t;
    END IF;
    -- The lesson's key: composite, cascading; the writer's: composite, emptying the writer alone.
    IF NOT EXISTS (
      SELECT 1 FROM pg_constraint c
       WHERE c.contype = 'f' AND c.conrelid = format('public.%I', t)::regclass AND c.confrelid = '"CalendarLessons"'::regclass
         AND c.confdeltype = 'c' AND c.confupdtype = 'a' AND c.convalidated
         AND (SELECT array_agg(a.attname::text ORDER BY k.ord) FROM unnest(c.conkey) WITH ORDINALITY k(attnum, ord)
                JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum) = ARRAY['calendarLessonId', 'schoolId']) THEN
      RAISE EXCEPTION 'lesson log: %''s lesson is not (calendarLessonId, schoolId) -> CalendarLessons ON DELETE CASCADE ON UPDATE NO ACTION', t;
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM pg_constraint c
       WHERE c.contype = 'f' AND c.conrelid = format('public.%I', t)::regclass AND c.confrelid = '"Users"'::regclass
         AND c.confdeltype = 'n' AND c.confupdtype = 'a' AND c.convalidated
         AND (SELECT array_agg(a.attname::text ORDER BY k.ord) FROM unnest(c.conkey) WITH ORDINALITY k(attnum, ord)
                JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum) = ARRAY['writtenById', 'schoolId']
         AND (SELECT array_agg(a.attname::text) FROM unnest(c.confdelsetcols) k(attnum)
                JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum) = ARRAY['writtenById']) THEN
      RAISE EXCEPTION 'lesson log: %''s writer is not (writtenById, schoolId) -> Users ON DELETE SET NULL ("writtenById")', t;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_index i WHERE i.indrelid = format('public.%I', t)::regclass AND i.indisunique
                     AND i.indnatts = 1 AND (SELECT attname FROM pg_attribute WHERE attrelid = i.indrelid AND attnum = i.indkey[0]) = 'calendarLessonId') THEN
      RAISE EXCEPTION 'lesson log: % does not hold one row per lesson', t;
    END IF;
  END LOOP;

  -- Who reaches which table: no pupil, guardian or administrator on the
  -- notes; the family on the logs only through a lesson it can read; the
  -- note's teacher writes are REGULAR's, the log's any teacher's of the lesson.
  IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'LessonSubstituteNotes'
               AND ((coalesce(qual, '') || coalesce(with_check, '')) ~ '(STUDENT|GUARDIAN|SCHOOL_ADMIN|current_user_may)'
                    OR (coalesce(qual, '') || coalesce(with_check, '')) !~ '''TEACHER''')) THEN
    RAISE EXCEPTION 'lesson log: an arm on the notes names a pupil, a guardian or an administrator, or is not a teacher''s';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'LessonLogs' AND policyname = 'lesson_logs_family_select'
                   AND cmd = 'SELECT' AND qual LIKE '%STUDENT%' AND qual LIKE '%GUARDIAN%' AND qual LIKE '%EXISTS%'
                   AND qual LIKE '%"CalendarLessons"%' AND qual LIKE '%current_school_id()%') THEN
    RAISE EXCEPTION 'lesson log: the family''s read is not a lesson the caller can read';
  END IF;
  IF (SELECT count(*) FROM pg_policies WHERE tablename = 'LessonSubstituteNotes' AND policyname LIKE '%teacher_%'
        AND cmd IN ('INSERT', 'UPDATE', 'DELETE')
        AND coalesce(with_check, qual) LIKE '%lesson_teacher_role(%''REGULAR''%'
        AND (cmd <> 'UPDATE' OR qual LIKE '%lesson_teacher_role(%''REGULAR''%')) <> 3 THEN
    RAISE EXCEPTION 'lesson log: the note''s teacher writes are not the lesson''s own teacher''s alone';
  END IF;
  IF (SELECT count(*) FROM pg_policies WHERE tablename = 'LessonLogs' AND policyname LIKE '%teacher_%'
        AND cmd IN ('INSERT', 'UPDATE', 'DELETE') AND coalesce(with_check, qual) LIKE '%lesson_teacher_role(%IS NOT NULL%') <> 3 THEN
    RAISE EXCEPTION 'lesson log: the log''s teacher writes are not the lesson''s teachers''';
  END IF;

  -- The functions.
  FOREACH fn IN ARRAY ARRAY['app.lesson_teacher_role(uuid)'::regprocedure, 'app.substitute_noted_lessons(uuid[])'::regprocedure] LOOP
    IF NOT (SELECT prosecdef AND provolatile = 's' AND proconfig::text LIKE '%search_path=%' FROM pg_proc WHERE oid = fn) THEN
      RAISE EXCEPTION 'lesson log: % is not SECURITY DEFINER, STABLE and with its search_path pinned', fn;
    END IF;
    IF NOT has_function_privilege('app_authenticated', fn, 'EXECUTE') THEN
      RAISE EXCEPTION 'lesson log: the API may not ask %', fn;
    END IF;
    FOREACH r IN ARRAY ARRAY['authenticated', 'anon', 'service_role'] LOOP
      CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
      IF has_function_privilege(r, fn, 'EXECUTE') THEN RAISE EXCEPTION 'lesson log: % may ask %', r, fn; END IF;
    END LOOP;
  END LOOP;
  -- The existence function answers ids, and only to the school's administrators.
  IF NOT EXISTS (SELECT 1 FROM pg_proc WHERE oid = 'app.substitute_noted_lessons(uuid[])'::regprocedure
                   AND proretset AND prorettype = 'uuid'::regtype
                   AND prosrc LIKE '%current_school_id()%' AND prosrc LIKE '%''SCHOOL_ADMIN''%'
                   AND prosrc NOT LIKE '%body%') THEN
    RAISE EXCEPTION 'lesson log: app.substitute_noted_lessons is not a set of lesson ids of the caller''s school, to SCHOOL_ADMIN alone';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) x
              WHERE p.oid IN ('app.lesson_teacher_role(uuid)'::regprocedure, 'app.substitute_noted_lessons(uuid[])'::regprocedure,
                              'app.lesson_text_written_by()'::regprocedure) AND x.grantee = 0) THEN
    RAISE EXCEPTION 'lesson log: PUBLIC may call a function of 20261203090000';
  END IF;
  FOREACH r IN ARRAY ARRAY['authenticated', 'anon', 'service_role', 'app_authenticated'] LOOP
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
    IF has_function_privilege(r, 'app.lesson_text_written_by()'::regprocedure, 'EXECUTE') THEN
      RAISE EXCEPTION 'lesson log: % may call the writer''s trigger function', r;
    END IF;
  END LOOP;

  -- The checks, by what they say, and validated.
  SELECT count(*) INTO n FROM pg_constraint
   WHERE contype = 'c' AND convalidated AND (conname, conrelid) IN (
           ('LessonLogs_topic_is_one_line', '"LessonLogs"'::regclass),
           ('LessonLogs_homework_written', '"LessonLogs"'::regclass),
           ('LessonLogs_says_something', '"LessonLogs"'::regclass),
           ('LessonSubstituteNotes_body_written', '"LessonSubstituteNotes"'::regclass));
  IF n <> 4
     OR NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'LessonLogs_topic_is_one_line'
                      AND pg_get_constraintdef(oid) LIKE '%btrim%' AND pg_get_constraintdef(oid) LIKE '%200%')
     OR NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'LessonLogs_homework_written'
                      AND pg_get_constraintdef(oid) LIKE '%btrim%' AND pg_get_constraintdef(oid) LIKE '%1000%')
     OR NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'LessonSubstituteNotes_body_written'
                      AND pg_get_constraintdef(oid) LIKE '%btrim%' AND pg_get_constraintdef(oid) LIKE '%2000%') THEN
    RAISE EXCEPTION 'lesson log: % of the four checks are there and validated, or one says something else', n;
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Section 231: skolans personal läser skolans loggar; en elev läser loggarna
-- för sina egna lektioner, en vårdnadshavare sina barns; ingen läser en
-- annan skolas; PostgREST:s roll, tjänsten och synken läser inga
-- (20261203090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001311')::text, true);
SELECT set_config('app.test_ll_other', app.current_school_id()::text, true);
SELECT set_config('app.test_ll_l9', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-9'), true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001300')::text, true);
SELECT set_config('app.test_ll_school', app.current_school_id()::text, true);
DO $$
DECLARE
  n bigint;
  seen text;
  who text[];
  cases constant text[][] := ARRAY[
    -- authId, what they read: the logs' topics or homework markers, in order.
    ['00000000-0000-4000-8000-000000001300', 'ett,fyra,två'],  -- the administrator
    ['00000000-0000-4000-8000-000000001308', 'ett,fyra,två'],  -- the läsare
    ['00000000-0000-4000-8000-000000001303', 'ett,fyra,två'],  -- a colleague on none of the lessons
    ['00000000-0000-4000-8000-000000001302', 'ett,fyra,två'],  -- the substitute
    ['00000000-0000-4000-8000-000000001304', 'ett,fyra'],      -- P1: 7A's L1 and the teaching group's L4
    ['00000000-0000-4000-8000-000000001305', 'ett,fyra'],      -- P1's guardian
    ['00000000-0000-4000-8000-000000001306', 'två'],           -- P2: 7B's L2 (L3 has no log)
    ['00000000-0000-4000-8000-000000001307', 'två']];          -- P2's guardian
  i int;
BEGIN
  IF coalesce(current_setting('app.test_ll_school', true), '') = '' OR coalesce(current_setting('app.test_ll_l9', true), '') = '' THEN
    RAISE EXCEPTION 'lesson log: the fixture schools did not resolve; fixtures did not run';
  END IF;
  FOR i IN 1 .. array_length(cases, 1) LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', cases[i][1])::text, true);
    SELECT string_agg(regexp_replace(coalesce(topic, homework), '^(LL|Läxa) ', ''), ',' ORDER BY regexp_replace(coalesce(topic, homework), '^(LL|Läxa) ', ''))
      INTO seen FROM "LessonLogs";
    IF seen IS DISTINCT FROM cases[i][2] THEN
      RAISE EXCEPTION 'lesson log: % (%) reads the logs %, not %', cases[i][1], app.current_user_role(), seen, cases[i][2];
    END IF;
    -- Another school's, by its id: nobody here.
    SELECT count(*) INTO n FROM "LessonLogs" WHERE "calendarLessonId" = current_setting('app.test_ll_l9')::uuid;
    IF n <> 0 THEN RAISE EXCEPTION 'lesson log: % reads another school''s log', cases[i][1]; END IF;
  END LOOP;

  -- The other school's administrator reads their own, and none of these.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001311')::text, true);
  SELECT string_agg(topic, ',') INTO seen FROM "LessonLogs";
  IF seen IS DISTINCT FROM 'LL annan' THEN RAISE EXCEPTION 'lesson log: the other school''s admin reads %', seen; END IF;

  -- The service and the sync principal of the school: nothing.
  PERFORM set_config('request.jwt.claims', '', true);
  FOREACH seen IN ARRAY ARRAY['app.service_school_id', 'app.sync_school_id'] LOOP
    PERFORM set_config(seen, current_setting('app.test_ll_school'), true);
    SELECT count(*) INTO n FROM "LessonLogs";
    IF n <> 0 THEN RAISE EXCEPTION 'lesson log: % reads % logs', seen, n; END IF;
    SELECT count(*) INTO n FROM "LessonSubstituteNotes";
    IF n <> 0 THEN RAISE EXCEPTION 'lesson log: % reads % notes', seen, n; END IF;
    PERFORM set_config(seen, '', true);
  END LOOP;
END $$;

-- PostgREST's role, with a guardian's and a teacher's claims: nothing at all.
SET LOCAL ROLE authenticated;
DO $$
DECLARE
  who text;
BEGIN
  IF current_user <> 'authenticated' THEN RAISE EXCEPTION 'lesson log: could not act as authenticated'; END IF;
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000001305', '00000000-0000-4000-8000-000000001301'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    BEGIN
      PERFORM 1 FROM "LessonLogs";
      RAISE EXCEPTION 'lesson log: PostgREST''s role reads the logs as %', who;
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    BEGIN
      PERFORM 1 FROM "LessonSubstituteNotes";
      RAISE EXCEPTION 'lesson log: PostgREST''s role reads the notes as %', who;
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    BEGIN
      PERFORM app.lesson_teacher_role(gen_random_uuid());
      RAISE EXCEPTION 'lesson log: PostgREST''s role asks app.lesson_teacher_role as %', who;
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
  END LOOP;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 232: notisen till vikarien läses av lektionens egen lärare, dess
-- medlärare och dess vikarie, aldrig av en administratör — vilken profil som
-- helst, läsaren också —, en kollega, en elev eller en vårdnadshavare, inte
-- ens för en lektion de ser. Skolans administratörer får veta att det finns
-- en, genom app.substitute_noted_lessons, för sin egen skolas lektioner och
-- ingen annan, och inget om vad den säger (20261203090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001311')::text, true);
SELECT set_config('app.test_ll_l9', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-9'), true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
SELECT set_config('app.test_ll_roller_lesson', (SELECT "calendarLessonId"::text FROM "LessonLogs" WHERE topic = 'Roller ämne'), true);
SELECT set_config('app.test_ll_roller_admins',
                  (SELECT string_agg("authId"::text, ',' ORDER BY "authId") FROM "Users" WHERE role = 'SCHOOL_ADMIN'), true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001300')::text, true);
SELECT set_config('app.test_ll_lessons',
                  (SELECT string_agg(id::text, ',' ORDER BY note) FROM "CalendarLessons" WHERE note IN ('LL-1', 'LL-2', 'LL-3', 'LL-4')), true);
DO $$
DECLARE
  seen text;
  n bigint;
  cases constant text[][] := ARRAY[
    ['00000000-0000-4000-8000-000000001300', NULL],           -- the administrator who writes drift
    ['00000000-0000-4000-8000-000000001308', NULL],           -- the läsare
    ['00000000-0000-4000-8000-000000001311', NULL],           -- the other school's administrator
    ['00000000-0000-4000-8000-000000001301', 'ett'],          -- A: L1's own teacher (and L4's, which has none)
    ['00000000-0000-4000-8000-000000001312', 'ett'],          -- F: L1's co-teacher (ASSISTANT)
    ['00000000-0000-4000-8000-000000001302', 'ett,tre,två'],  -- B: the substitute on L1, L2 and L3
    ['00000000-0000-4000-8000-000000001309', 'tre'],          -- D: absent, the cover decision on L3 names them
    ['00000000-0000-4000-8000-000000001310', NULL],           -- E: L2's master's teacher in the grundschema, not on the published lesson
    ['00000000-0000-4000-8000-000000001303', NULL],           -- C: a colleague
    ['00000000-0000-4000-8000-000000001304', NULL],           -- P1, who reads L1 and its log
    ['00000000-0000-4000-8000-000000001305', NULL],
    ['00000000-0000-4000-8000-000000001306', NULL],
    ['00000000-0000-4000-8000-000000001307', NULL]];
  i int;
BEGIN
  FOR i IN 1 .. array_length(cases, 1) LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', cases[i][1])::text, true);
    SELECT string_agg(replace(body, 'LL notis ', ''), ',' ORDER BY replace(body, 'LL notis ', '')) INTO seen FROM "LessonSubstituteNotes";
    IF seen IS DISTINCT FROM cases[i][2] THEN
      RAISE EXCEPTION 'lesson log: % (%) reads the notes %, not %', cases[i][1], app.current_user_role(), seen, cases[i][2];
    END IF;
    SELECT count(*) INTO n FROM "LessonSubstituteNotes" WHERE "calendarLessonId" = current_setting('app.test_ll_l9')::uuid;
    IF n <> 0 THEN RAISE EXCEPTION 'lesson log: % reads another school''s note', cases[i][1]; END IF;
  END LOOP;
  -- P1 does read L1 itself, so the note's absence is the note's arm, not the lesson's.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001304')::text, true);
  IF NOT EXISTS (SELECT 1 FROM "CalendarLessons" WHERE note = 'LL-1') THEN
    RAISE EXCEPTION 'lesson log: P1 does not read L1, so the note''s refusal proves nothing';
  END IF;
END $$;

-- What the administrators learn instead: which lessons have a note.
DO $$
DECLARE
  l constant uuid[] := string_to_array(current_setting('app.test_ll_lessons'), ',')::uuid[]
                       || current_setting('app.test_ll_l9')::uuid;
  roller_lesson constant uuid := current_setting('app.test_ll_roller_lesson')::uuid;
  asks constant text[][] := ARRAY[
    -- authId, the lessons with a note among L1–L4 and L9
    ['00000000-0000-4000-8000-000000001300', 'ett,tre,två'],
    ['00000000-0000-4000-8000-000000001308', 'ett,tre,två'],  -- the läsare sees the board, so the mark too
    ['00000000-0000-4000-8000-000000001311', 'annan'],        -- the other school's administrator: their own alone
    ['00000000-0000-4000-8000-000000001301', NULL],           -- a teacher, even of L1: they read the note itself
    ['00000000-0000-4000-8000-000000001302', NULL],
    ['00000000-0000-4000-8000-000000001303', NULL],
    ['00000000-0000-4000-8000-000000001304', NULL],
    ['00000000-0000-4000-8000-000000001305', NULL]];
  i int;
  got text;
  who text;
  n bigint;
BEGIN
  IF array_length(l, 1) <> 5 OR roller_lesson IS NULL THEN
    RAISE EXCEPTION 'lesson log: the fixture lessons did not resolve';
  END IF;
  FOR i IN 1 .. array_length(asks, 1) LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', asks[i][1])::text, true);
    SELECT string_agg(label, ',' ORDER BY label) INTO got
      FROM (SELECT CASE x WHEN l[1] THEN 'ett' WHEN l[2] THEN 'två' WHEN l[3] THEN 'tre' WHEN l[4] THEN 'fyra'
                          WHEN l[5] THEN 'annan' ELSE x::text END AS label
              FROM app.substitute_noted_lessons(l) AS x) q;
    IF got IS DISTINCT FROM asks[i][2] THEN
      RAISE EXCEPTION 'lesson log: app.substitute_noted_lessons answers % (%) %, not %', asks[i][1], app.current_user_role(), got, asks[i][2];
    END IF;
  END LOOP;
  -- Only what is asked, once each; nothing for nothing, and nothing with no principal.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001300')::text, true);
  SELECT count(*) INTO n FROM app.substitute_noted_lessons(ARRAY[l[1], l[1], l[4]]);
  IF n <> 1 THEN RAISE EXCEPTION 'lesson log: asked L1 twice and L4, app.substitute_noted_lessons answered % rows', n; END IF;
  SELECT count(*) INTO n FROM app.substitute_noted_lessons('{}'::uuid[]);
  IF n <> 0 THEN RAISE EXCEPTION 'lesson log: asked nothing, app.substitute_noted_lessons answered % rows', n; END IF;
  PERFORM set_config('request.jwt.claims', '', true);
  SELECT count(*) INTO n FROM app.substitute_noted_lessons(l);
  IF n <> 0 THEN RAISE EXCEPTION 'lesson log: app.substitute_noted_lessons answered % rows with no principal', n; END IF;

  -- Every administrator's profile of the matrix school, the läsare's too:
  -- none reads the note on its lesson, every one learns that it is there.
  -- Each names the matrix school, as the gateway names the school of every
  -- request: a login with a row at another school too (Flera skolor per
  -- inloggning, 20261204090000) is otherwise its first school's.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  PERFORM set_config('app.chosen_school_id', app.current_school_id()::text, true);
  FOREACH who IN ARRAY string_to_array(current_setting('app.test_ll_roller_admins'), ',') LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    SELECT count(*) INTO n FROM "LessonSubstituteNotes";
    IF n <> 0 THEN
      RAISE EXCEPTION 'lesson log: the matrix school''s administrator % reads % notes', who, n;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM app.substitute_noted_lessons(ARRAY[roller_lesson]) AS x WHERE x = roller_lesson) THEN
      RAISE EXCEPTION 'lesson log: the matrix school''s administrator % is not told its lesson has a note', who;
    END IF;
  END LOOP;
  PERFORM set_config('app.chosen_school_id', '', true);
  IF array_length(string_to_array(current_setting('app.test_ll_roller_admins'), ','), 1) < 5 THEN
    RAISE EXCEPTION 'lesson log: the matrix school has % administrators, not one of each profile',
      array_length(string_to_array(current_setting('app.test_ll_roller_admins'), ','), 1);
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 233: loggen skrivs av lektionens lärare, dess medlärare och dess
-- vikarie och av den frånvarande som täckningsbeslutet gällde; aldrig av grundschemats lärare som
-- inte står på den publicerade lektionen (ett opublicerat utkast), en kollega,
-- en elev eller en vårdnadshavare; av den administratör som skriver drift,
-- inte av läsaren. Skribenten är alltid den inloggade, vad som än skickas, och
-- den som raderar en skribent blir inte skribent (20261203090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001300')::text, true);
SELECT set_config('app.test_ll_school', app.current_school_id()::text, true);
SELECT set_config('app.test_ll_l1', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-1'), true);
SELECT set_config('app.test_ll_l2', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-2'), true);
SELECT set_config('app.test_ll_l3', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-3'), true);
SELECT set_config('app.test_ll_l4', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-4'), true);
SELECT set_config('app.test_ll_admin', (SELECT id::text FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000001300'), true);
SELECT set_config('app.test_ll_a', (SELECT id::text FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000001301'), true);
SELECT set_config('app.test_ll_b', (SELECT id::text FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000001302'), true);
SELECT set_config('app.test_ll_c', (SELECT id::text FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000001303'), true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001311')::text, true);
SELECT set_config('app.test_ll_other', app.current_school_id()::text, true);
SELECT set_config('app.test_ll_l9', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-9'), true);
SELECT set_config('app.test_ll_l9b', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-9b'), true);
DO $$
DECLARE
  school constant uuid := current_setting('app.test_ll_school')::uuid;
  l1 constant uuid := current_setting('app.test_ll_l1')::uuid;
  l2 constant uuid := current_setting('app.test_ll_l2')::uuid;
  l3 constant uuid := current_setting('app.test_ll_l3')::uuid;
  l4 constant uuid := current_setting('app.test_ll_l4')::uuid;
  writer uuid;
  n bigint;
  who text;
BEGIN
  IF l1 IS NULL OR l3 IS NULL OR current_setting('app.test_ll_a', true) = '' THEN
    RAISE EXCEPTION 'lesson log: the fixture lessons or people did not resolve';
  END IF;

  -- A, L1's own teacher: updates it, sending another writer; the row names A.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001301')::text, true);
  UPDATE "LessonLogs" SET topic = 'LL ett ändrad', "writtenById" = current_setting('app.test_ll_c')::uuid WHERE "calendarLessonId" = l1;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'lesson log: L1''s own teacher updated % of its logs', n; END IF;
  SELECT "writtenById" INTO writer FROM "LessonLogs" WHERE "calendarLessonId" = l1;
  IF writer IS DISTINCT FROM current_setting('app.test_ll_a')::uuid THEN
    RAISE EXCEPTION 'lesson log: the log names % as its writer, not the teacher who wrote it', writer;
  END IF;
  -- ... and A is nobody's teacher on L2 or L3.
  UPDATE "LessonLogs" SET topic = 'x' WHERE "calendarLessonId" = l2;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'lesson log: A updated L2''s log, whose teacher A is not'; END IF;
  BEGIN
    INSERT INTO "LessonLogs" ("schoolId", "calendarLessonId", topic) VALUES (school, l3, 'A:s');
    RAISE EXCEPTION 'lesson log: A wrote a log for L3, whose teacher A is not';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;

  -- F, L1's co-teacher (ASSISTANT): one of its own teachers, and writes it,
  -- named as the writer. A writes it back, so the row is A's again for the
  -- writer's removal below.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001312')::text, true);
  UPDATE "LessonLogs" SET homework = 'Medlärarens läxa' WHERE "calendarLessonId" = l1 RETURNING "writtenById" INTO writer;
  IF writer IS DISTINCT FROM app.current_user_id() THEN RAISE EXCEPTION 'lesson log: L1''s co-teacher did not update its log as the writer'; END IF;
  UPDATE "LessonLogs" SET topic = 'x' WHERE "calendarLessonId" IN (l2, l4);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'lesson log: L1''s co-teacher updated % logs of lessons not theirs', n; END IF;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001301')::text, true);
  UPDATE "LessonLogs" SET homework = 'Läxa ett' WHERE "calendarLessonId" = l1;

  -- B, the substitute on L2: writes its log too.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001302')::text, true);
  UPDATE "LessonLogs" SET homework = 'Vikariens läxa' WHERE "calendarLessonId" = l2;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'lesson log: the substitute updated % of L2''s logs', n; END IF;

  -- D, absent from L3 by a cover decision: writes L3's log, sending no writer.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001309')::text, true);
  INSERT INTO "LessonLogs" ("schoolId", "calendarLessonId", topic) VALUES (school, l3, 'LL tre') RETURNING "writtenById" INTO writer;
  IF writer IS DISTINCT FROM app.current_user_id() THEN RAISE EXCEPTION 'lesson log: D''s log names % as its writer', writer; END IF;
  DELETE FROM "LessonLogs" WHERE "calendarLessonId" = l3;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'lesson log: D removed % of L3''s logs', n; END IF;

  -- E, whom the grundschema (in a DRAFT school, the unpublished draft) puts
  -- on L2's master, while the published lesson does not have E: nothing.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001310')::text, true);
  UPDATE "LessonLogs" SET topic = 'Utkastets' WHERE "calendarLessonId" = l2;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'lesson log: the grundschema''s teacher, not on the published lesson, updated % of L2''s logs', n; END IF;
  DELETE FROM "LessonLogs" WHERE "calendarLessonId" = l2;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'lesson log: the grundschema''s teacher, not on the published lesson, removed L2''s log'; END IF;

  -- C, a colleague, reads every log and writes none.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001303')::text, true);
  UPDATE "LessonLogs" SET topic = 'x';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'lesson log: a colleague updated % logs', n; END IF;
  DELETE FROM "LessonLogs";
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'lesson log: a colleague removed % logs', n; END IF;
  BEGIN
    INSERT INTO "LessonLogs" ("schoolId", "calendarLessonId", topic) VALUES (school, l3, 'Kollegans');
    RAISE EXCEPTION 'lesson log: a colleague wrote a log';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;

  -- Pupils and guardians, who read L1's and L2's logs: write nothing.
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000001304', '00000000-0000-4000-8000-000000001305',
                             '00000000-0000-4000-8000-000000001306', '00000000-0000-4000-8000-000000001307'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    UPDATE "LessonLogs" SET topic = 'x';
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 0 THEN RAISE EXCEPTION 'lesson log: % (%) updated % logs', who, app.current_user_role(), n; END IF;
    DELETE FROM "LessonLogs";
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 0 THEN RAISE EXCEPTION 'lesson log: % (%) removed % logs', who, app.current_user_role(), n; END IF;
    BEGIN
      INSERT INTO "LessonLogs" ("schoolId", "calendarLessonId", topic) VALUES (school, l3, 'Familjens');
      RAISE EXCEPTION 'lesson log: % (%) wrote a log', who, app.current_user_role();
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
  END LOOP;

  -- The läsare: nothing written.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001308')::text, true);
  BEGIN
    UPDATE "LessonLogs" SET topic = 'x' WHERE "calendarLessonId" = l1;
    RAISE EXCEPTION 'lesson log: the läsare updated a log';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  DELETE FROM "LessonLogs";
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'lesson log: the läsare removed % logs', n; END IF;

  -- The administrator who writes drift: writes and removes, named as the writer.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001300')::text, true);
  INSERT INTO "LessonLogs" ("schoolId", "calendarLessonId", topic, "writtenById")
  VALUES (school, l3, 'Rektors', current_setting('app.test_ll_a')::uuid) RETURNING "writtenById" INTO writer;
  IF writer IS DISTINCT FROM current_setting('app.test_ll_admin')::uuid THEN
    RAISE EXCEPTION 'lesson log: the administrator''s log names % as its writer', writer;
  END IF;
  DELETE FROM "LessonLogs" WHERE "calendarLessonId" = l4;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'lesson log: the administrator removed % of L4''s logs', n; END IF;
  -- ... but nothing into another school, and no log of this school onto another school's lesson.
  BEGIN
    INSERT INTO "LessonLogs" ("schoolId", "calendarLessonId", topic) VALUES (current_setting('app.test_ll_other')::uuid, current_setting('app.test_ll_l9')::uuid, 'x');
    RAISE EXCEPTION 'lesson log: the administrator wrote a log into another school';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    INSERT INTO "LessonLogs" ("schoolId", "calendarLessonId", topic) VALUES (school, current_setting('app.test_ll_l9b')::uuid, 'x');
    RAISE EXCEPTION 'lesson log: a log of this school stands on another school''s lesson';
  EXCEPTION WHEN foreign_key_violation THEN NULL;
  END;
  -- A note on another school's lesson never reaches the key: no administrator
  -- writes notes, and app.lesson_teacher_role is NULL for another school's
  -- lesson, so every arm refuses first. The composite key behind it is
  -- section 230's to show.
  BEGIN
    INSERT INTO "LessonSubstituteNotes" ("schoolId", "calendarLessonId", body) VALUES (school, current_setting('app.test_ll_l9b')::uuid, 'x');
    RAISE EXCEPTION 'lesson log: a note of this school stands on another school''s lesson';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;

  -- Deleting a writer empties the writer; the deleting administrator is not stamped in.
  DELETE FROM "Users" WHERE id = current_setting('app.test_ll_a')::uuid;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'lesson log: the administrator removed % of teacher A', n; END IF;
  SELECT "writtenById" INTO writer FROM "LessonLogs" WHERE "calendarLessonId" = l1;
  IF NOT FOUND OR writer IS NOT NULL THEN
    RAISE EXCEPTION 'lesson log: L1''s log names % after its writer was removed, not nobody', writer;
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 234: notisen skrivs av lektionens egen lärare — på lektionen, som
-- dess medlärare eller frånvarande enligt ett täckningsbeslut; aldrig av en
-- administratör (den som skriver drift lika lite som läsaren), vikarien,
-- grundschemats lärare som inte står på den publicerade lektionen, en
-- kollega, en elev eller en vårdnadshavare (20261203090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001300')::text, true);
SELECT set_config('app.test_ll_school', app.current_school_id()::text, true);
SELECT set_config('app.test_ll_l1', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-1'), true);
SELECT set_config('app.test_ll_l2', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-2'), true);
SELECT set_config('app.test_ll_l3', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-3'), true);
SELECT set_config('app.test_ll_l4', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-4'), true);
DO $$
DECLARE
  school constant uuid := current_setting('app.test_ll_school')::uuid;
  l1 constant uuid := current_setting('app.test_ll_l1')::uuid;
  l2 constant uuid := current_setting('app.test_ll_l2')::uuid;
  l3 constant uuid := current_setting('app.test_ll_l3')::uuid;
  l4 constant uuid := current_setting('app.test_ll_l4')::uuid;
  n bigint;
  who text;
BEGIN
  -- A writes L1's and, having none, L4's.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001301')::text, true);
  UPDATE "LessonSubstituteNotes" SET body = 'Ändrad' WHERE "calendarLessonId" = l1;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'lesson log: L1''s own teacher updated % of its notes', n; END IF;
  INSERT INTO "LessonSubstituteNotes" ("schoolId", "calendarLessonId", body) VALUES (school, l4, 'Till vikarien på L4');
  DELETE FROM "LessonSubstituteNotes" WHERE "calendarLessonId" = l4;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'lesson log: L4''s own teacher removed % of its notes', n; END IF;
  UPDATE "LessonSubstituteNotes" SET body = 'x' WHERE "calendarLessonId" IN (l2, l3);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'lesson log: A updated % notes of lessons not theirs', n; END IF;

  -- F, L1's co-teacher (ASSISTANT), is one of its own teachers: writes L1's, and no other.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001312')::text, true);
  UPDATE "LessonSubstituteNotes" SET body = 'Från medläraren' WHERE "calendarLessonId" = l1;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'lesson log: L1''s co-teacher updated % of its notes', n; END IF;
  BEGIN
    INSERT INTO "LessonSubstituteNotes" ("schoolId", "calendarLessonId", body) VALUES (school, l4, 'Medlärarens');
    RAISE EXCEPTION 'lesson log: L1''s co-teacher wrote a note on L4, whose teacher F is not';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;

  -- E, on L2's master in the grundschema only, neither reads nor writes L2's; D writes L3's.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001310')::text, true);
  UPDATE "LessonSubstituteNotes" SET body = 'Från utkastet' WHERE "calendarLessonId" = l2;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'lesson log: the grundschema''s teacher, not on the published lesson, updated % of L2''s notes', n; END IF;
  BEGIN
    INSERT INTO "LessonSubstituteNotes" ("schoolId", "calendarLessonId", body) VALUES (school, l4, 'Utkastets');
    RAISE EXCEPTION 'lesson log: the grundschema''s teacher wrote a note on a lesson not theirs';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001309')::text, true);
  UPDATE "LessonSubstituteNotes" SET body = 'Från den frånvarande' WHERE "calendarLessonId" = l3;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'lesson log: L3''s absent teacher updated % of its notes', n; END IF;

  -- B, the substitute on L1–L3, reads them and writes none.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001302')::text, true);
  SELECT count(*) INTO n FROM "LessonSubstituteNotes";
  IF n <> 3 THEN RAISE EXCEPTION 'lesson log: the substitute reads % notes, not L1''s, L2''s and L3''s', n; END IF;
  UPDATE "LessonSubstituteNotes" SET body = 'Tack!';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'lesson log: the substitute answered % notes', n; END IF;
  DELETE FROM "LessonSubstituteNotes";
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'lesson log: the substitute removed % notes', n; END IF;
  BEGIN
    INSERT INTO "LessonSubstituteNotes" ("schoolId", "calendarLessonId", body) VALUES (school, l4, 'Vikariens');
    RAISE EXCEPTION 'lesson log: the substitute wrote a note';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;

  -- C and the families: nothing.
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000001303', '00000000-0000-4000-8000-000000001304',
                             '00000000-0000-4000-8000-000000001305'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    UPDATE "LessonSubstituteNotes" SET body = 'x';
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 0 THEN RAISE EXCEPTION 'lesson log: % (%) updated % notes', who, app.current_user_role(), n; END IF;
    BEGIN
      INSERT INTO "LessonSubstituteNotes" ("schoolId", "calendarLessonId", body) VALUES (school, l4, 'x');
      RAISE EXCEPTION 'lesson log: % (%) wrote a note', who, app.current_user_role();
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
  END LOOP;

  -- No administrator writes one: not the one who writes drift, not the läsare.
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000001300', '00000000-0000-4000-8000-000000001308'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    UPDATE "LessonSubstituteNotes" SET body = 'Från expeditionen';
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 0 THEN RAISE EXCEPTION 'lesson log: the administrator % updated % notes', who, n; END IF;
    DELETE FROM "LessonSubstituteNotes";
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 0 THEN RAISE EXCEPTION 'lesson log: the administrator % removed % notes', who, n; END IF;
    BEGIN
      INSERT INTO "LessonSubstituteNotes" ("schoolId", "calendarLessonId", body) VALUES (school, l4, 'Från expeditionen');
      RAISE EXCEPTION 'lesson log: the administrator % wrote a note', who;
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
  END LOOP;
  -- And the notes stand: B, the substitute, still reads all three.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001302')::text, true);
  SELECT count(*) INTO n FROM "LessonSubstituteNotes";
  IF n <> 3 THEN RAISE EXCEPTION 'lesson log: after the administrators'' tries the substitute reads % notes', n; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 235: app.lesson_teacher_role svarar för den inloggade läraren och
-- ingen annan; kontrollerna släpper in och vägrar vid sina gränser; en logg
-- och en notis går med sin lektion (20261203090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001311')::text, true);
SELECT set_config('app.test_ll_l9', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-9'), true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001300')::text, true);
SELECT set_config('app.test_ll_school', app.current_school_id()::text, true);
SELECT set_config('app.test_ll_l1', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-1'), true);
SELECT set_config('app.test_ll_l2', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-2'), true);
SELECT set_config('app.test_ll_l3', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-3'), true);
SELECT set_config('app.test_ll_l4', (SELECT id::text FROM "CalendarLessons" WHERE note = 'LL-4'), true);
DO $$
DECLARE
  school constant uuid := current_setting('app.test_ll_school')::uuid;
  l1 constant uuid := current_setting('app.test_ll_l1')::uuid;
  l2 constant uuid := current_setting('app.test_ll_l2')::uuid;
  l3 constant uuid := current_setting('app.test_ll_l3')::uuid;
  l4 constant uuid := current_setting('app.test_ll_l4')::uuid;
  l9 constant uuid := current_setting('app.test_ll_l9')::uuid;
  answers constant text[][] := ARRAY[
    -- authId, L1, L2, L3, L4
    ['00000000-0000-4000-8000-000000001301', 'REGULAR', NULL, NULL, 'REGULAR'],
    -- F: L1's co-teacher (ASSISTANT), one of its own teachers.
    ['00000000-0000-4000-8000-000000001312', 'REGULAR', NULL, NULL, NULL],
    ['00000000-0000-4000-8000-000000001302', 'SUBSTITUTE', 'SUBSTITUTE', 'SUBSTITUTE', NULL],
    ['00000000-0000-4000-8000-000000001303', NULL, NULL, NULL, NULL],
    ['00000000-0000-4000-8000-000000001309', NULL, NULL, 'REGULAR', NULL],
    -- E: on L2's master in the grundschema (a draft), not on the published lesson: nobody's teacher.
    ['00000000-0000-4000-8000-000000001310', NULL, NULL, NULL, NULL],
    ['00000000-0000-4000-8000-000000001300', NULL, NULL, NULL, NULL],
    ['00000000-0000-4000-8000-000000001304', NULL, NULL, NULL, NULL],
    ['00000000-0000-4000-8000-000000001305', NULL, NULL, NULL, NULL]];
  i int;
  got text[];
  con text;
  v text;
  cases text[][];
BEGIN
  FOR i IN 1 .. array_length(answers, 1) LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', answers[i][1])::text, true);
    got := ARRAY[app.lesson_teacher_role(l1), app.lesson_teacher_role(l2), app.lesson_teacher_role(l3), app.lesson_teacher_role(l4)];
    IF got IS DISTINCT FROM ARRAY[answers[i][2], answers[i][3], answers[i][4], answers[i][5]] THEN
      RAISE EXCEPTION 'lesson log: app.lesson_teacher_role answers % for %, not %', got, answers[i][1],
        ARRAY[answers[i][2], answers[i][3], answers[i][4], answers[i][5]];
    END IF;
    IF app.lesson_teacher_role(l9) IS NOT NULL OR app.lesson_teacher_role(gen_random_uuid()) IS NOT NULL THEN
      RAISE EXCEPTION 'lesson log: app.lesson_teacher_role answers for another school''s or no lesson as %', answers[i][1];
    END IF;
  END LOOP;
  PERFORM set_config('request.jwt.claims', '', true);
  IF app.lesson_teacher_role(l1) IS NOT NULL THEN RAISE EXCEPTION 'lesson log: app.lesson_teacher_role answers with no principal'; END IF;

  -- The checks, at their edges: the log's as the administrator on L3 (which
  -- has none), the note's as A, L4's own teacher, on L4.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001300')::text, true);
  cases := ARRAY[
    ['topic', repeat('x', 200), NULL],
    ['topic', repeat('x', 201), 'LessonLogs_topic_is_one_line'],
    ['topic', 'Rad ett' || chr(10) || 'rad två', 'LessonLogs_topic_is_one_line'],
    ['topic', ' Bråk', 'LessonLogs_topic_is_one_line'],
    ['topic', '', 'LessonLogs_topic_is_one_line'],
    ['homework', repeat('å', 1000), NULL],
    ['homework', 'Rad ett' || chr(10) || 'rad två', NULL],
    ['homework', repeat('x', 1001), 'LessonLogs_homework_written'],
    ['homework', 'Läxa' || chr(10), 'LessonLogs_homework_written'],
    ['nothing', NULL, 'LessonLogs_says_something']];
  FOR i IN 1 .. array_length(cases, 1) LOOP
    BEGIN
      IF cases[i][1] = 'topic' THEN
        INSERT INTO "LessonLogs" ("schoolId", "calendarLessonId", topic) VALUES (school, l3, cases[i][2]);
      ELSIF cases[i][1] = 'homework' THEN
        INSERT INTO "LessonLogs" ("schoolId", "calendarLessonId", homework) VALUES (school, l3, cases[i][2]);
      ELSE
        INSERT INTO "LessonLogs" ("schoolId", "calendarLessonId") VALUES (school, l3);
      END IF;
      IF cases[i][3] IS NOT NULL THEN
        RAISE EXCEPTION 'lesson log: % of % characters was taken, not refused by %', cases[i][1], char_length(coalesce(cases[i][2], '')), cases[i][3];
      END IF;
      DELETE FROM "LessonLogs" WHERE "calendarLessonId" = l3;
    EXCEPTION WHEN check_violation THEN
      GET STACKED DIAGNOSTICS con = CONSTRAINT_NAME;
      IF con IS DISTINCT FROM cases[i][3] THEN
        RAISE EXCEPTION 'lesson log: % case % was refused by %, expected %', cases[i][1], i, con, coalesce(cases[i][3], 'nothing');
      END IF;
    END;
  END LOOP;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001301')::text, true);
  FOREACH v IN ARRAY ARRAY[repeat('x', 2000), repeat('x', 2001), ' x', '', 'Rad ett' || chr(10) || 'rad två'] LOOP
    BEGIN
      INSERT INTO "LessonSubstituteNotes" ("schoolId", "calendarLessonId", body) VALUES (school, l4, v);
      IF char_length(v) > 2000 OR v = '' OR v LIKE ' %' THEN
        RAISE EXCEPTION 'lesson log: a note of % characters was taken', char_length(v);
      END IF;
      DELETE FROM "LessonSubstituteNotes" WHERE "calendarLessonId" = l4;
    EXCEPTION WHEN check_violation THEN
      GET STACKED DIAGNOSTICS con = CONSTRAINT_NAME;
      IF con IS DISTINCT FROM 'LessonSubstituteNotes_body_written' OR NOT (char_length(v) > 2000 OR v = '' OR v LIKE ' %') THEN
        RAISE EXCEPTION 'lesson log: a note of % characters was refused by %', char_length(v), con;
      END IF;
    END;
  END LOOP;

  -- One per lesson (A, L1's own teacher, writes both of L1's).
  BEGIN
    INSERT INTO "LessonLogs" ("schoolId", "calendarLessonId", topic) VALUES (school, l1, 'En till');
    RAISE EXCEPTION 'lesson log: a lesson took a second log';
  EXCEPTION WHEN unique_violation THEN NULL;
  END;
  BEGIN
    INSERT INTO "LessonSubstituteNotes" ("schoolId", "calendarLessonId", body) VALUES (school, l1, 'En till');
    RAISE EXCEPTION 'lesson log: a lesson took a second note';
  EXCEPTION WHEN unique_violation THEN NULL;
  END;

  -- With the lesson: the administrator who writes drift removes L1, and its
  -- log and note go. The administrator reads no note, and nobody's row
  -- security reaches a note whose lesson is gone, so the existence function
  -- (which reads the table itself) is what says the note is gone.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001300')::text, true);
  IF NOT EXISTS (SELECT 1 FROM app.substitute_noted_lessons(ARRAY[l1])) THEN
    RAISE EXCEPTION 'lesson log: L1 has no note before it is removed, so its going proves nothing';
  END IF;
  DELETE FROM "CalendarLessons" WHERE id = l1;
  IF EXISTS (SELECT 1 FROM "LessonLogs" WHERE "calendarLessonId" = l1)
     OR EXISTS (SELECT 1 FROM app.substitute_noted_lessons(ARRAY[l1])) THEN
    RAISE EXCEPTION 'lesson log: L1''s log or note outlived the lesson';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 240: vilken rad ett anrop är (Flera skolor per inloggning,
-- 20261204090000).
--
-- A login has one row per school, and app.current_user_id() picks the row
-- the request names: the gateway's app.chosen_school_id first, PostgREST's
-- x-school-id header second, else the login's oldest active row. The fixtures'
-- logins …0240-…0244 have two rows each (rls-fixtures.sql). For both API roles
-- (the gateway's app_authenticated and PostgREST's authenticated), all six
-- helpers are asked:
--
--   240a  a login with one row resolves to it named or not, in either case
--         of the uuid, and to nothing when another school, a value that is
--         no uuid or an empty header is named… (empty is "not named");
--   240b  a login with two rows: none named gives the row that took the
--         login first ("loginSince"), not the row made first; each school
--         named, by setting and by header, gives that row; the setting wins
--         over the header; a school the login has no row in gives nothing;
--   240c  current_user_may and current_user_decides answer for the chosen
--         row only: FULL at A and LASARE in the roller school writes nothing
--         and decides nothing there (the bool_or over every row they took
--         before 20261204090000), and the other way round;
--   240d  an inactive row is never chosen: named, it gives nothing; not
--         named, the next active row;
--   240e  a school the access-token hook closed (rastra_closed_schools) is
--         never chosen, named or not;
--   240f  app.my_schools() lists the login's own active rows, oldest first,
--         with each school's name, why it is closed and which one is chosen;
--   240g  a pupil with a row and a class at each school: the class
--         (current_user_group_id) is the chosen row's, by setting and by
--         header, and none at a school the pupil has no row in.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls240_a', :'school_a', true),
       set_config('app.test_rls240_b', :'school_b', true);

DO $$
DECLARE
  a uuid := current_setting('app.test_rls240_a')::uuid;
  b uuid := current_setting('app.test_rls240_b')::uuid;
  m uuid;
  via text;
  r record;
  got record;
  n int := 0;
  m1 constant text := 'fe000000-0000-4000-8000-000000000240';
  m2 constant text := 'fe000000-0000-4000-8000-000000000241';
  m3 constant text := 'fe000000-0000-4000-8000-000000000242';
  pupil constant text := 'fe000000-0000-4000-8000-000000000248';
  single constant text := '00000000-0000-4000-8000-000000000105';
  class_a uuid;
  class_m uuid;
  want_role text;
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', single)::text, true);
  m := app.current_school_id();
  IF m IS NULL OR m IN (a, b) THEN
    RAISE EXCEPTION 'flera 240: the roller school''s full administrator resolves to %; fixtures did not run', m;
  END IF;
  -- The pupil's two classes, as each school's administrator reads the
  -- pupil's row there (the roller school's here, A's as …0240 with nothing
  -- named), so that neither leans on current_user_group_id.
  SELECT "studentGroupId" INTO class_m FROM "Users" WHERE "authId" = pupil::uuid AND "schoolId" = m;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', m1)::text, true);
  SELECT "studentGroupId" INTO class_a FROM "Users" WHERE "authId" = pupil::uuid AND "schoolId" = a;
  IF class_a IS NULL OR class_m IS NULL OR class_a = class_m THEN
    RAISE EXCEPTION 'flera 240g: the pupil''s classes are % and %; fixtures did not run', class_a, class_m;
  END IF;

  FOREACH via IN ARRAY ARRAY['app_authenticated', 'authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    IF current_user <> via THEN
      RAISE EXCEPTION 'flera 240: running as %, not %', current_user, via;
    END IF;

    FOR r IN
      SELECT * FROM (VALUES
        -- sub, claims extra, setting, header, expected school, role, may PERSONAL write, decides, case
        (single, NULL::jsonb, '',            '',                       m,    'SCHOOL_ADMIN', true,  true,  '240a one row, none named'),
        (single, NULL,        m::text,       '',                       m,    'SCHOOL_ADMIN', true,  true,  '240a one row, its school by setting'),
        (single, NULL,        '',            m::text,                  m,    'SCHOOL_ADMIN', true,  true,  '240a one row, its school by header'),
        (single, NULL,        '',            upper(m::text),           m,    'SCHOOL_ADMIN', true,  true,  '240a one row, upper case'),
        (single, NULL,        '',            ' ' || m::text || ' ',    m,    'SCHOOL_ADMIN', true,  true,  '240a one row, padded'),
        (single, NULL,        a::text,       '',                       NULL, NULL,           false, false, '240a one row, another school by setting'),
        (single, NULL,        '',            a::text,                  NULL, NULL,           false, false, '240a one row, another school by header'),
        (single, NULL,        '',            'not-a-uuid',             NULL, NULL,           false, false, '240a one row, no uuid'),
        (m1,     NULL,        '',            '',                       a,    'SCHOOL_ADMIN', true,  true,  '240b two rows, none named: the oldest'),
        (m1,     NULL,        a::text,       '',                       a,    'SCHOOL_ADMIN', true,  true,  '240b two rows, A by setting'),
        (m1,     NULL,        m::text,       '',                       m,    'SCHOOL_ADMIN', false, false, '240c two rows, roller by setting (LASARE there)'),
        (m1,     NULL,        '',            m::text,                  m,    'SCHOOL_ADMIN', false, false, '240c two rows, roller by header (LASARE there)'),
        (m1,     NULL,        a::text,       m::text,                  a,    'SCHOOL_ADMIN', true,  true,  '240b the setting wins over the header'),
        (m1,     NULL,        '',            b::text,                  NULL, NULL,           false, false, '240b a school the login has no row in'),
        ('fe000000-0000-4000-8000-000000000246', NULL, '', '',          a,    'TEACHER',      false, false, '240b the row made first took the login later: not the default'),
        ('fe000000-0000-4000-8000-000000000246', NULL, '', m::text,     m,    'TEACHER',      false, false, '240b that row, named'),
        (m2,     NULL,        '',            '',                       a,    'SCHOOL_ADMIN', false, false, '240c LASARE at A (oldest), FULL in roller: none named'),
        (m2,     NULL,        '',            m::text,                  m,    'SCHOOL_ADMIN', true,  true,  '240c FULL in roller, by header'),
        (m3,     NULL,        '',            '',                       m,    'TEACHER',      false, false, '240d the oldest row is inactive: the next one'),
        (m3,     NULL,        a::text,       '',                       NULL, NULL,           false, false, '240d the inactive row named'),
        (m3,     NULL,        '',            a::text,                  NULL, NULL,           false, false, '240d the inactive row named by header'),
        (m3,     NULL,        '',            m::text,                  m,    'TEACHER',      false, false, '240d a school where the row has another role: that row''s role, not the other''s'),
        (m1,     jsonb_build_object(a::text, 'sso_required'), '', '',  m,    'SCHOOL_ADMIN', false, false, '240e A closed: none named gives roller'),
        (m1,     jsonb_build_object(a::text, 'sso_required'), a::text, '', NULL, NULL,       false, false, '240e A closed, named by setting'),
        (m1,     jsonb_build_object(a::text, 'sso_required'), '', a::text, NULL, NULL,       false, false, '240e A closed, named by header'),
        (single, jsonb_build_object(m::text, 'sso_required'), '', '',  NULL, NULL,           false, false, '240e the only school closed')
      ) v(sub, closed, setting, header, school, role, may_write, decides, label)
    LOOP
      PERFORM set_config('request.jwt.claims',
        (jsonb_build_object('sub', r.sub, 'role', 'authenticated')
          || CASE WHEN r.closed IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('rastra_closed_schools', r.closed) END)::text,
        true);
      PERFORM set_config('app.chosen_school_id', r.setting, true);
      PERFORM set_config('request.headers',
        CASE WHEN r.header = '' THEN '' ELSE json_build_object('x-school-id', r.header, 'accept', '*/*')::text END, true);

      SELECT app.current_user_id() AS id, app.current_school_id() AS school, app.current_user_role()::text AS role,
             app.current_user_may('PERSONAL', true) AS may_write, app.current_user_may('PERSONAL', false) AS may_read,
             app.current_user_decides() AS decides, app.current_user_group_id() AS grp
        INTO got;
      IF got.school IS DISTINCT FROM r.school OR got.role IS DISTINCT FROM r.role
         OR got.may_write IS DISTINCT FROM r.may_write OR got.decides IS DISTINCT FROM r.decides
         OR got.may_read IS DISTINCT FROM coalesce(r.role = 'SCHOOL_ADMIN', false)
         OR (got.id IS NULL) IS DISTINCT FROM (r.school IS NULL)
         OR got.grp IS NOT NULL THEN
        RAISE EXCEPTION 'flera %: % as % resolved to school %, role %, may write %, may read %, decides %, user %, group %; expected school %, role %, may write %, decides %',
          via, r.label, r.sub, got.school, got.role, got.may_write, got.may_read, got.decides, got.id, got.grp,
          r.school, r.role, r.may_write, r.decides;
      END IF;
      IF got.id IS NOT NULL AND (SELECT "schoolId" FROM "Users" WHERE id = got.id) IS DISTINCT FROM r.school THEN
        RAISE EXCEPTION 'flera %: % reads its own row in another school', via, r.label;
      END IF;
      n := n + 1;
    END LOOP;

    FOR r IN
      SELECT * FROM (VALUES
        ('',       '',       a,          class_a,    '240g a pupil at two schools, none named: A''s row and class'),
        (m::text,  '',       m,          class_m,    '240g the roller school by setting: its class'),
        ('',       m::text,  m,          class_m,    '240g the roller school by header: its class'),
        (a::text,  m::text,  a,          class_a,    '240g the setting over the header: A''s class'),
        ('',       b::text,  NULL::uuid, NULL::uuid, '240g a school the pupil has no row in: no class')
      ) v(setting, header, school, grp, label)
    LOOP
      PERFORM set_config('request.jwt.claims', json_build_object('sub', pupil, 'role', 'authenticated')::text, true);
      PERFORM set_config('app.chosen_school_id', r.setting, true);
      PERFORM set_config('request.headers',
        CASE WHEN r.header = '' THEN '' ELSE json_build_object('x-school-id', r.header)::text END, true);
      SELECT app.current_school_id() AS school, app.current_user_role()::text AS role,
             app.current_user_group_id() AS grp, app.current_user_id() AS id
        INTO got;
      want_role := CASE WHEN r.school IS NULL THEN NULL ELSE 'STUDENT' END;
      IF got.school IS DISTINCT FROM r.school OR got.grp IS DISTINCT FROM r.grp
         OR got.role IS DISTINCT FROM want_role
         OR (got.id IS NULL) IS DISTINCT FROM (r.school IS NULL) THEN
        RAISE EXCEPTION 'flera %: % resolved to school %, role %, class %; expected school %, class %',
          via, r.label, got.school, got.role, got.grp, r.school, r.grp;
      END IF;
      n := n + 1;
    END LOOP;
    SET LOCAL ROLE app_authenticated;
  END LOOP;

  PERFORM set_config('app.chosen_school_id', '', true);
  PERFORM set_config('request.headers', '', true);

  -- The contrast 240b leans on: …0246's row in the roller school was made
  -- before its row at A and took the login after it.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000246')::text, true);
  PERFORM set_config('app.chosen_school_id', m::text, true);
  SELECT "createdAt", "loginSince" INTO got FROM "Users" WHERE id = app.current_user_id();
  PERFORM set_config('app.chosen_school_id', a::text, true);
  IF NOT (got."createdAt" < (SELECT "createdAt" FROM "Users" WHERE id = app.current_user_id())
          AND got."loginSince" > (SELECT "loginSince" FROM "Users" WHERE id = app.current_user_id())) THEN
    RAISE EXCEPTION 'flera 240: …0246''s rows are not made one way and logged in the other; fixtures did not run';
  END IF;
  PERFORM set_config('app.chosen_school_id', '', true);

  -- 240f, as the API role (the only one that may execute it).
  PERFORM set_config('request.jwt.claims', json_build_object('sub', m1)::text, true);
  IF (SELECT array_agg(school_id ORDER BY ord) FROM (SELECT school_id, row_number() OVER () AS ord FROM app.my_schools()) x)
     IS DISTINCT FROM ARRAY[a, m] THEN
    RAISE EXCEPTION 'flera 240f: my_schools lists % for the two-row login', (SELECT array_agg(school_id) FROM app.my_schools());
  END IF;
  IF (SELECT array_agg(is_current ORDER BY school_id = a DESC) FROM app.my_schools()) IS DISTINCT FROM ARRAY[true, false]
     OR (SELECT count(*) FROM app.my_schools() WHERE school_name IS NULL OR closed_reason IS NOT NULL) <> 0
     OR (SELECT role::text || '/' || admin_profile::text FROM app.my_schools() WHERE school_id = m) <> 'SCHOOL_ADMIN/LASARE' THEN
    RAISE EXCEPTION 'flera 240f: my_schools said %', (SELECT json_agg(x) FROM app.my_schools() x);
  END IF;
  PERFORM set_config('request.headers', json_build_object('x-school-id', m)::text, true);
  IF (SELECT school_id FROM app.my_schools() WHERE is_current) IS DISTINCT FROM m THEN
    RAISE EXCEPTION 'flera 240f: with the roller school named, my_schools marks % as chosen', (SELECT school_id FROM app.my_schools() WHERE is_current);
  END IF;
  PERFORM set_config('request.headers', '', true);
  PERFORM set_config('request.jwt.claims',
    json_build_object('sub', m1, 'rastra_closed_schools', json_build_object(a, 'sso_required'))::text, true);
  IF (SELECT closed_reason FROM app.my_schools() WHERE school_id = a) IS DISTINCT FROM 'sso_required'
     OR (SELECT school_id FROM app.my_schools() WHERE is_current) IS DISTINCT FROM m THEN
    RAISE EXCEPTION 'flera 240f: with A closed, my_schools said %', (SELECT json_agg(x) FROM app.my_schools() x);
  END IF;
  -- The inactive row is not listed.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', m3)::text, true);
  IF (SELECT array_agg(school_id) FROM app.my_schools()) IS DISTINCT FROM ARRAY[m] THEN
    RAISE EXCEPTION 'flera 240f: the login with an inactive row lists %', (SELECT array_agg(school_id) FROM app.my_schools());
  END IF;
  -- Nobody signed in: nothing.
  PERFORM set_config('request.jwt.claims', '', true);
  IF EXISTS (SELECT 1 FROM app.my_schools()) THEN
    RAISE EXCEPTION 'flera 240f: my_schools lists rows with nobody signed in';
  END IF;

  RAISE NOTICE 'flera 240: % resolutions', n;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 241: varje tabell svarar för den valda skolan och ingen annan.
--
-- Every table with row security, for both API roles:
--
--   241a  a login with two rows, choosing either school, sees no row filed
--         under another school (a table's "schoolId", or the school itself
--         for Schools): the admin with FULL at A and LASARE in the roller
--         school, the guardian with a child at each, the teacher at A
--         and at school B, and the pupil with a class at A and one in the
--         roller school;
--   241b  and sees in the chosen school exactly what a login with only that
--         row sees: …0240 choosing A against school A's administrator, both
--         FULL; …0240 choosing the roller school against its läsare (…0115);
--         the guardian choosing the roller school against its guardian
--         (…0113), who has the same child. The tables named below answer for
--         a person's own rows (notices, devices, feeds, a private schedule
--         proposal) and are compared by whether they answer at all.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls241_a', :'school_a', true),
       set_config('app.test_rls241_b', :'school_b', true),
       set_config('app.test_rls241_admin', :'admin_auth_id', true);

DO $$
DECLARE
  a uuid := current_setting('app.test_rls241_a')::uuid;
  b uuid := current_setting('app.test_rls241_b')::uuid;
  admin_a constant text := current_setting('app.test_rls241_admin');
  m uuid;
  via text;
  t record;
  c record;
  n bigint;
  twin_n bigint;
  key_col text;
  wrong text[] := '{}';
  cells int := 0;
  -- Tables whose rows are the reader's own, so two different people with
  -- the same role see different rows: compared by whether they read at all.
  own_rows constant text[] := ARRAY['Notifications', 'NotificationOptOuts', 'PushDevices', 'CalendarFeeds',
                                    'ScheduleCandidateRuns', 'ScheduleCandidates', 'PersonalDataAccess'];
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  m := app.current_school_id();
  IF m IS NULL THEN
    RAISE EXCEPTION 'flera 241: the roller school is not there; fixtures did not run';
  END IF;

  FOREACH via IN ARRAY ARRAY['app_authenticated', 'authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    FOR c IN
      SELECT * FROM (VALUES
        ('fe000000-0000-4000-8000-000000000240', a, admin_a,                                 'admin FULL at A'),
        ('fe000000-0000-4000-8000-000000000240', m, '00000000-0000-4000-8000-000000000115', 'admin LASARE in roller'),
        ('fe000000-0000-4000-8000-000000000243', a, NULL,                                    'guardian at A'),
        ('fe000000-0000-4000-8000-000000000243', m, '00000000-0000-4000-8000-000000000113', 'guardian in roller'),
        ('fe000000-0000-4000-8000-000000000244', a, NULL,                                    'teacher at A'),
        ('fe000000-0000-4000-8000-000000000244', b, NULL,                                    'teacher at B'),
        ('fe000000-0000-4000-8000-000000000248', a, NULL,                                    'pupil at A'),
        ('fe000000-0000-4000-8000-000000000248', m, NULL,                                    'pupil in roller')
      ) v(sub, school, twin, label)
    LOOP
      FOR t IN
        SELECT cl.relname AS tbl,
               EXISTS (SELECT 1 FROM pg_attribute at WHERE at.attrelid = cl.oid AND at.attname = 'schoolId' AND NOT at.attisdropped) AS has_school
          FROM pg_class cl JOIN pg_namespace ns ON ns.oid = cl.relnamespace
         WHERE ns.nspname = 'public' AND cl.relkind = 'r' AND cl.relrowsecurity
         ORDER BY 1
      LOOP
        key_col := CASE WHEN t.tbl = 'Schools' THEN 'id' WHEN t.has_school THEN 'schoolId' END;

        -- As the login, the school named by header for PostgREST's role and
        -- by the gateway's setting for the API's.
        PERFORM set_config('request.jwt.claims', json_build_object('sub', c.sub)::text, true);
        PERFORM set_config('app.chosen_school_id', CASE via WHEN 'app_authenticated' THEN c.school::text ELSE '' END, true);
        PERFORM set_config('request.headers', CASE via WHEN 'authenticated' THEN json_build_object('x-school-id', c.school)::text ELSE '' END, true);
        IF app.current_school_id() IS DISTINCT FROM c.school THEN
          RAISE EXCEPTION 'flera 241: % did not resolve to its school as %', c.label, via;
        END IF;
        BEGIN
          IF key_col IS NOT NULL THEN
            EXECUTE format('SELECT count(*) FROM %I WHERE %I IS DISTINCT FROM $1 AND %I IS NOT NULL', t.tbl, key_col, key_col)
              INTO n USING c.school;
            IF n > 0 THEN
              wrong := wrong || format('%s as %s sees %s rows of %s filed under another school', c.label, via, n, t.tbl);
            END IF;
          END IF;
          EXECUTE format('SELECT count(*) FROM %I', t.tbl) INTO n;
        EXCEPTION WHEN insufficient_privilege THEN
          n := -1;
        END;
        cells := cells + 1;

        CONTINUE WHEN c.twin IS NULL;
        PERFORM set_config('request.jwt.claims', json_build_object('sub', c.twin)::text, true);
        PERFORM set_config('app.chosen_school_id', '', true);
        PERFORM set_config('request.headers', '', true);
        IF app.current_school_id() IS DISTINCT FROM c.school THEN
          RAISE EXCEPTION 'flera 241: the twin of % is not in its school', c.label;
        END IF;
        BEGIN
          EXECUTE format('SELECT count(*) FROM %I', t.tbl) INTO twin_n;
        EXCEPTION WHEN insufficient_privilege THEN
          twin_n := -1;
        END;
        IF t.tbl = ANY (own_rows) THEN
          IF (n = -1) IS DISTINCT FROM (twin_n = -1) THEN
            wrong := wrong || format('%s as %s: %s answers %s, the single-school twin %s', c.label, via, t.tbl, n, twin_n);
          END IF;
        ELSIF n IS DISTINCT FROM twin_n THEN
          wrong := wrong || format('%s as %s sees %s rows of %s, the single-school twin %s', c.label, via, n, t.tbl, twin_n);
        END IF;
        cells := cells + 1;
      END LOOP;
    END LOOP;
    SET LOCAL ROLE app_authenticated;
  END LOOP;

  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'flera 241: % of % cells wrong: %', cardinality(wrong), cells, array_to_string(wrong, '; ');
  END IF;
  RAISE NOTICE 'flera 241: % cells', cells;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 242: en inloggning ansluts till en annan skola bara genom
-- inbjudan, och en delad inloggning är personens (20261204090000).
--
--   242a  as the roller school's FULL administrator (the API's role): a row
--         that takes a login another row holds, inserted or updated, is
--         refused with 23505 on Users_authId_key, as before a login could
--         be shared, unless app.login_join names that very row; a login
--         nobody holds, and any write that leaves authId alone, pass;
--   242b  app.login_is_held_elsewhere answers for the API role only: true
--         for a row whose login another row holds, false for a login of
--         one row, for a login nobody holds and with nobody signed in;
--   242c  gallring leaves a shared login alone: with the gallring school's
--         departed pupil's login also held by a row the roller school's
--         administrator joined to it, app.gallring_claim_person answers
--         invited = false, so the job deletes no login.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  shared constant uuid := 'fe000000-0000-4000-8000-000000000244';
  m uuid;
  pupil2 uuid;
  new_id uuid;
  con text;
  st text;
  r record;
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  m := app.current_school_id();
  SELECT id INTO pupil2 FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000114';
  IF m IS NULL OR pupil2 IS NULL THEN
    RAISE EXCEPTION 'flera 242: the roller school or its second pupil is missing; fixtures did not run';
  END IF;

  FOR r IN SELECT * FROM (VALUES
      ('insert, not named',          'insert', shared,            false, false),
      ('insert, named',              'insert', shared,            true,  true),
      ('update, not named',          'update', shared,            false, false),
      ('update, another row named',  'update', shared,            NULL,  false),
      ('update, named',              'update', shared,            true,  true),
      ('update to a login nobody holds', 'update', gen_random_uuid(), false, true)
    ) AS t(label, cmd, login, named, admitted)
  LOOP
    new_id := gen_random_uuid();
    PERFORM set_config('app.login_join',
      CASE WHEN r.named IS NULL THEN gen_random_uuid()::text
           WHEN r.named AND r.cmd = 'insert' THEN new_id::text
           WHEN r.named THEN pupil2::text
           ELSE '' END, true);
    BEGIN
      IF r.cmd = 'insert' THEN
        INSERT INTO "Users" (id, "schoolId", email, "firstName", "lastName", role, "authId", "updatedAt")
        VALUES (new_id, m, 'flera-242@example.invalid', 'Flera', 'Ansluten', 'TEACHER', r.login, now());
      ELSE
        UPDATE "Users" SET "authId" = r.login WHERE id = pupil2;
        IF NOT FOUND THEN RAISE EXCEPTION 'flera 242: % updated no row', r.label; END IF;
      END IF;
      IF NOT r.admitted THEN
        RAISE EXCEPTION 'flera 242: % was admitted', r.label;
      END IF;
      RAISE EXCEPTION USING ERRCODE = 'ZF242';
    EXCEPTION
      WHEN SQLSTATE 'ZF242' THEN NULL;
      WHEN unique_violation THEN
        GET STACKED DIAGNOSTICS con = CONSTRAINT_NAME, st = MESSAGE_TEXT;
        IF r.admitted THEN
          RAISE EXCEPTION 'flera 242: % was refused: %', r.label, st;
        END IF;
        IF con IS DISTINCT FROM 'Users_authId_key' OR st NOT LIKE '%"Users_authId_key"%' THEN
          RAISE EXCEPTION 'flera 242: % was refused as % (%), not as Users_authId_key', r.label, con, st;
        END IF;
    END;
  END LOOP;
  PERFORM set_config('app.login_join', '', true);

  -- A write that leaves the shared login where it is.
  UPDATE "Users" SET "firstName" = 'Flera' WHERE "authId" = 'fe000000-0000-4000-8000-000000000240' AND "schoolId" = m;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'flera 242: the roller row of the shared login could not be written';
  END IF;

  -- 242d: an administrator cannot move a person's default school by
  -- writing "loginSince"; it moves only with the login.
  UPDATE "Users" SET "loginSince" = timestamptz '1900-01-01', "firstName" = 'Flera'
   WHERE "authId" = 'fe000000-0000-4000-8000-000000000246' AND "schoolId" = m;
  IF NOT FOUND THEN RAISE EXCEPTION 'flera 242d: the roller row of …0246 could not be written'; END IF;
  IF (SELECT "loginSince" FROM "Users" WHERE "authId" = 'fe000000-0000-4000-8000-000000000246' AND "schoolId" = m)
     < timestamptz '2000-01-01' THEN
    RAISE EXCEPTION 'flera 242d: an administrator moved a row''s loginSince';
  END IF;
  new_id := gen_random_uuid();
  INSERT INTO "Users" (id, "schoolId", email, "firstName", "lastName", role, "authId", "loginSince", "updatedAt")
  VALUES (new_id, m, 'flera-242d@example.invalid', 'Flera', 'Ny', 'TEACHER', gen_random_uuid(), timestamptz '1900-01-01', now());
  IF (SELECT "loginSince" FROM "Users" WHERE id = new_id) < timestamptz '2000-01-01' THEN
    RAISE EXCEPTION 'flera 242d: a new row kept the loginSince its writer gave it';
  END IF;
  -- A new login restamps it.
  UPDATE "Users" SET "authId" = gen_random_uuid() WHERE id = pupil2 RETURNING "loginSince" INTO con;
  IF con::timestamptz < (SELECT max("loginSince") FROM "Users" WHERE "schoolId" = m AND id <> pupil2) THEN
    RAISE EXCEPTION 'flera 242d: a row that took a new login was not stamped now';
  END IF;

  -- 242b.
  IF NOT app.login_is_held_elsewhere('fe000000-0000-4000-8000-000000000240',
           (SELECT id FROM "Users" WHERE "authId" = 'fe000000-0000-4000-8000-000000000240' AND "schoolId" = m))
     OR app.login_is_held_elsewhere('00000000-0000-4000-8000-000000000105',
           (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000105'))
     OR app.login_is_held_elsewhere(gen_random_uuid(), NULL) THEN
    RAISE EXCEPTION 'flera 242b: login_is_held_elsewhere answered wrongly';
  END IF;
  -- Without the row's id, any row holding it counts (a row just removed).
  IF NOT app.login_is_held_elsewhere('00000000-0000-4000-8000-000000000105', NULL) THEN
    RAISE EXCEPTION 'flera 242b: a held login counted as nobody''s';
  END IF;
  PERFORM set_config('request.jwt.claims', '', true);
  IF NOT app.login_is_held_elsewhere('fe000000-0000-4000-8000-000000000240', NULL) THEN
    RAISE EXCEPTION 'flera 242b: with nobody signed in, the shared login was nobody''s';
  END IF;
  SET LOCAL ROLE authenticated;
  BEGIN
    PERFORM app.login_is_held_elsewhere(gen_random_uuid(), NULL);
    RAISE EXCEPTION 'flera 242b: PostgREST''s role may ask whether a login is shared';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  SET LOCAL ROLE app_authenticated;
END $$;
ROLLBACK;

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000081')::text, true);
DO $$
BEGIN
  PERFORM set_config('app.test_rls242_school', app.current_school_id()::text, true);
  PERFORM set_config('app.test_rls242_pupil', (SELECT id::text FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000085'), true);
  IF current_setting('app.test_rls242_pupil', true) IS NULL THEN
    RAISE EXCEPTION 'flera 242c: the gallring school''s departed pupil is not in the fixtures';
  END IF;
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
DO $$
DECLARE
  joined uuid := gen_random_uuid();
BEGIN
  -- The roller school's administrator joins the departed pupil's login to a
  -- guardian row of theirs, as the gateway's invitation does.
  PERFORM set_config('app.login_join', joined::text, true);
  INSERT INTO "Users" (id, "schoolId", email, "firstName", "lastName", role, "authId", "invitedAt", "updatedAt")
  VALUES (joined, app.current_school_id(), 'flera-242c@example.invalid', 'Flera', 'Förälder', 'GUARDIAN',
          '00000000-0000-4000-8000-000000000085', now(), now());
  PERFORM set_config('app.login_join', '', true);
END $$;
SELECT set_config('request.jwt.claims', '', true);
DO $$
DECLARE
  run uuid := app.gallring_begin(current_setting('app.test_rls242_school')::uuid, clock_timestamp());
  c record;
BEGIN
  SELECT * INTO c FROM app.gallring_claim_person(run, current_setting('app.test_rls242_pupil')::uuid);
  IF c.auth_id IS DISTINCT FROM '00000000-0000-4000-8000-000000000085' OR c.invited IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'flera 242c: the departed pupil whose login another school holds was claimed as % %', c.auth_id, c.invited;
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 243: kroken dömer varje skola för sig (20261204090000).
--
-- As supabase_auth_admin, like section 76. The teacher …0244 is at school A,
-- which has no school-account row, and at school B, whose staff must sign in
-- with B's Entra tenant:
--
--   243a  by password: the claims, with rastra_closed_schools {B:
--         sso_required}; refreshed, the same;
--   243b  by school account with an identity of B's tenant: the claims,
--         with {A: sso_not_enabled};
--   243c  by school account with no identity: neither school lets it in, so
--         the 403 of the oldest row (A's sso_not_enabled);
--   243d  logins whose schools all let the session in get exactly the
--         claims Auth signed, without the key, also when Auth's claims
--         carried a stale one: the admin with FULL at A and LASARE in the
--         roller school, and the login whose older row is inactive (only
--         its active row is judged);
--   243e  by SAML: no school pins it, so the 403 of section 76;
--   243f  a deactivated row whose school refuses the session is closed in
--         the claim too, so making it active again during the token's life
--         does not open it (…0247: active at A, inactive at B);
--   243g  whether a token is issued is judged on the active rows: a person
--         active only at B, which refuses a password, is refused, though
--         their inactive row at A would let them in (…0245).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls243_a', :'school_a', true),
       set_config('app.test_rls243_b', :'school_b', true);
DO $$
DECLARE
  a constant text := current_setting('app.test_rls243_a');
  b constant text := current_setting('app.test_rls243_b');
  now_s bigint := extract(epoch FROM now())::bigint;
  b_tenant constant text := '7b0c2a9e-3c1d-4e5f-8a6b-0c1d2e3f4a5b';
  t constant text := 'fe000000-0000-4000-8000-000000000244';
  r record;
  claims jsonb;
  got jsonb;
  expected jsonb;
  cases int := 0;
BEGIN
  SET LOCAL ROLE supabase_auth_admin;
  IF current_user <> 'supabase_auth_admin' THEN RAISE EXCEPTION 'flera 243: running as %', current_user; END IF;

  FOR r IN SELECT * FROM (VALUES
      ('243a the teacher at A and B by password',  t, 'password', '["password"]'::jsonb, NULL::jsonb, jsonb_build_object(b, 'sso_required'), NULL::text, false),
      ('243a refreshed',                           t, 'token_refresh', '["password"]', NULL, jsonb_build_object(b, 'sso_required'), NULL, false),
      ('243c by school account, no identity',      t, 'oauth', '["oauth"]', NULL, NULL, 'sso_not_enabled', false),
      ('243d FULL at A, LASARE in roller',         'fe000000-0000-4000-8000-000000000240', 'password', '["password"]', NULL, NULL, NULL, false),
      ('243d with a stale key in the claims',      'fe000000-0000-4000-8000-000000000240', 'password', '["password"]', jsonb_build_object(a, 'sso_required'), NULL, NULL, false),
      ('243d an inactive older row',               'fe000000-0000-4000-8000-000000000242', 'password', '["password"]', NULL, NULL, NULL, false),
      ('243e by SAML',                             t, 'sso/saml', '["sso/saml"]', NULL, NULL, 'sign_in_method_not_allowed', false),
      ('243f an inactive row refuses: closed too',  'fe000000-0000-4000-8000-000000000247', 'password', '["password"]', NULL, jsonb_build_object(b, 'sso_required'), NULL, false),
      ('243g only an inactive row would let it in', 'fe000000-0000-4000-8000-000000000245', 'password', '["password"]', NULL, NULL, 'sso_required', false),
      ('243b by school account, B''s tenant',      t, 'oauth', '["oauth"]', NULL, jsonb_build_object(a, 'sso_not_enabled'), NULL, true)
    ) AS v(label, sub, method, amr, stale, closed, refusal, needs_identity)
  LOOP
    IF r.needs_identity THEN
      INSERT INTO auth.identities (provider_id, user_id, identity_data, provider)
      VALUES ('rls243-entra', t::uuid,
              jsonb_build_object('iss', 'https://login.microsoftonline.com/' || b_tenant || '/v2.0', 'sub', 'rls243-entra',
                                 'custom_claims', jsonb_build_object('tid', b_tenant)),
              'azure');
    END IF;
    claims := jsonb_build_object(
      'aud', 'authenticated', 'sub', r.sub, 'role', 'authenticated', 'email', 'rls243@example.invalid',
      'session_id', gen_random_uuid(), 'aal', 'aal1', 'is_anonymous', false,
      'app_metadata', jsonb_build_object('provider', 'email'), 'user_metadata', '{}'::jsonb,
      'amr', (SELECT jsonb_agg(jsonb_build_object('method', e #>> '{}', 'timestamp', now_s - 60)) FROM jsonb_array_elements(r.amr) e));
    got := sign_in.custom_access_token_hook(jsonb_build_object(
      'user_id', r.sub, 'claims', claims || CASE WHEN r.stale IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('rastra_closed_schools', r.stale) END,
      'authentication_method', r.method));
    expected := CASE
      WHEN r.refusal IS NOT NULL THEN jsonb_build_object('error', jsonb_build_object('http_code', 403, 'message', r.refusal))
      WHEN r.closed IS NULL THEN jsonb_build_object('claims', claims)
      ELSE jsonb_build_object('claims', claims || jsonb_build_object('rastra_closed_schools', r.closed)) END;
    IF got IS DISTINCT FROM expected THEN
      RAISE EXCEPTION 'flera %: gave %, expected %', r.label, got, expected;
    END IF;
    cases := cases + 1;
  END LOOP;
  IF cases <> 10 THEN RAISE EXCEPTION 'flera 243: only % cases ran', cases; END IF;
  SET LOCAL ROLE app_authenticated;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 244: lösarens funktioner står i katalogen som migreringen skrev dem
-- (20261204090000).
--
--   244a  the six helpers are SECURITY DEFINER, STABLE, with search_path
--         public, pg_temp, and executable by both API roles; the two that
--         read the request (app.requested_school, app.closed_schools) by no
--         API role at all: the helpers call them as their owner;
--   244b  app.my_schools and app.login_is_held_elsewhere are the API role's
--         alone; sign_in.rules is supabase_auth_admin's alone;
--   244c  the join trigger is there, enabled, AFTER INSERT OR UPDATE OF
--         "authId", row-level (after row security, so it tells a refused
--         writer nothing), and takes the login's lock before it looks for
--         another row, for a row invited to the login (two writers of one
--         login wait for each other, as on the unique index; the race
--         itself takes two sessions, so the PR's demo shows it); the
--         loginSince trigger BEFORE, on "authId" and "loginSince".
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  bad text;
BEGIN
  SELECT string_agg(p.proname, ', ') INTO bad
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'app'
     AND p.proname IN ('current_user_id', 'current_school_id', 'current_user_role', 'current_user_group_id',
                       'current_user_may', 'current_user_decides')
     AND NOT (p.prosecdef AND p.provolatile = 's'
              AND p.proconfig = ARRAY['search_path=public, pg_temp']
              AND has_function_privilege('app_authenticated', p.oid, 'EXECUTE')
              AND has_function_privilege('authenticated', p.oid, 'EXECUTE'));
  IF bad IS NOT NULL OR (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
                          WHERE n.nspname = 'app' AND p.proname IN ('current_user_id', 'current_school_id', 'current_user_role',
                                'current_user_group_id', 'current_user_may', 'current_user_decides')) <> 6 THEN
    RAISE EXCEPTION 'flera 244a: helpers not as written: %', bad;
  END IF;

  SELECT string_agg(fn || ' for ' || r, ', ') INTO bad
    FROM unnest(ARRAY['app.requested_school()', 'app.closed_schools()', 'app.my_schools()',
                      'app.login_is_held_elsewhere(uuid, uuid)', 'sign_in.rules(uuid)']) fn,
         unnest(ARRAY['app_authenticated', 'authenticated', 'anon', 'service_role', 'supabase_auth_admin']) r
   WHERE EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r)
     AND has_function_privilege(r, fn::regprocedure, 'EXECUTE')
         IS DISTINCT FROM ((fn IN ('app.my_schools()', 'app.login_is_held_elsewhere(uuid, uuid)') AND r = 'app_authenticated')
                           OR (fn = 'sign_in.rules(uuid)' AND r = 'supabase_auth_admin'));
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'flera 244b: EXECUTE is wrong on %', bad;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger tg
     WHERE tg.tgrelid = '"Users"'::regclass AND tg.tgname = 'Users_login_since_is_the_logins'
       AND tg.tgenabled = 'O'
       AND pg_get_triggerdef(tg.oid) LIKE '%BEFORE INSERT OR UPDATE OF "authId", "loginSince" ON public."Users" FOR EACH ROW%') THEN
    RAISE EXCEPTION 'flera 244c: the loginSince trigger is missing or not as written';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger tg
     WHERE tg.tgrelid = '"Users"'::regclass AND tg.tgname = 'Users_a_login_joins_another_school_by_invitation'
       AND tg.tgenabled = 'O'
       AND pg_get_triggerdef(tg.oid) LIKE '%AFTER INSERT OR UPDATE OF "authId" ON public."Users" FOR EACH ROW%') THEN
    RAISE EXCEPTION 'flera 244c: the join trigger is missing or not as written: %',
      (SELECT pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid = '"Users"'::regclass AND tgname = 'Users_a_login_joins_another_school_by_invitation');
  END IF;
  IF pg_get_functiondef('app.users_a_login_joins_another_school_by_invitation()'::regprocedure) NOT LIKE
       '%IF NEW."invitedAt" IS NOT NULL THEN%PERFORM pg_advisory_xact_lock(hashtext(''Users.authId''), hashtext(NEW."authId"::text));%END IF;%IF EXISTS (SELECT 1 FROM "Users" o WHERE o."authId" = NEW."authId"%' THEN
    RAISE EXCEPTION 'flera 244c: the join trigger does not take the login''s lock before it looks for another row';
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Section 245: ingen skrivning går över skolgränsen, och en enhet följer
-- skolan den registrerades för (Flera skolor per inloggning,
-- 20261204090000).
--
--   245a  every table with row security and a "schoolId", every write verb,
--         both directions, both API roles: a login with rows at two schools
--         reads a row of one school (stashing it whole, as that school's
--         row), then names the other school and tries to write it.
--         …0240 reads the roller school (LASARE) and writes with FULL at A;
--         …0241 reads A (LASARE) and writes with FULL in the roller school.
--         So the profile at the writing school would let every write
--         through, and only the school stops it: an INSERT of the stashed
--         row is refused by row security (42501) or by the role's grants,
--         an UPDATE or DELETE of it by its ctid meets no row. Through the
--         gateway's setting for app_authenticated, through PostgREST's
--         header for authenticated;
--   245b  a device registered at one school of a login moves when it is
--         registered at the other: one row, the new school's, and only the
--         new school's delivery (app.push_targets) finds it. A push is the
--         notices of the school the app works in; the other school's stay
--         in its inbox.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls245_a', :'school_a', true);
DO $$
DECLARE
  a uuid := current_setting('app.test_rls245_a')::uuid;
  m uuid;
  via text;
  d record;
  t record;
  key_col text;
  ins_cols text;
  upd_col text;
  tid text;
  stashed jsonb;
  n bigint;
  st text;
  msg text;
  outcome text;
  cmd text;
  probed int;
  at_least int;
  tried text[] := '{}';
  wrong text[] := '{}';
  others text[] := '{}';
  cells int := 0;
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  m := app.current_school_id();

  FOREACH via IN ARRAY ARRAY['app_authenticated', 'authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    FOR d IN SELECT * FROM (VALUES
        ('fe000000-0000-4000-8000-000000000240', m, a, 'reads roller as LASARE, writes with FULL at A'),
        ('fe000000-0000-4000-8000-000000000241', a, m, 'reads A as LASARE, writes with FULL in roller')
      ) v(sub, read_at, write_at, label)
    LOOP
      PERFORM set_config('request.jwt.claims', json_build_object('sub', d.sub)::text, true);
      probed := 0;
      FOR t IN
        SELECT cl.relname AS tbl
          FROM pg_class cl JOIN pg_namespace ns ON ns.oid = cl.relnamespace
         WHERE ns.nspname = 'public' AND cl.relkind = 'r' AND cl.relrowsecurity
           AND (cl.relname = 'Schools'
                OR EXISTS (SELECT 1 FROM pg_attribute at WHERE at.attrelid = cl.oid AND at.attname = 'schoolId' AND NOT at.attisdropped))
         ORDER BY 1
      LOOP
        key_col := CASE t.tbl WHEN 'Schools' THEN 'id' ELSE 'schoolId' END;
        -- Read one row of the reading school, as that school.
        PERFORM set_config('app.chosen_school_id', CASE via WHEN 'app_authenticated' THEN d.read_at::text ELSE '' END, true);
        PERFORM set_config('request.headers', CASE via WHEN 'authenticated' THEN json_build_object('x-school-id', d.read_at)::text ELSE '' END, true);
        tid := NULL;
        BEGIN
          EXECUTE format('SELECT x.ctid::text, to_jsonb(x) FROM %I x WHERE x.%I = $1 LIMIT 1', t.tbl, key_col)
            INTO tid, stashed USING d.read_at;
        EXCEPTION WHEN insufficient_privilege THEN tid := NULL;
        END;
        CONTINUE WHEN tid IS NULL;
        probed := probed + 1;
        SELECT string_agg(quote_ident(at.attname), ', ' ORDER BY at.attnum) INTO ins_cols
          FROM pg_attribute at
         WHERE at.attrelid = format('public.%I', t.tbl)::regclass AND at.attnum > 0 AND NOT at.attisdropped
           AND has_column_privilege(format('public.%I', t.tbl), at.attname, 'INSERT');
        SELECT quote_ident(at.attname) INTO upd_col
          FROM pg_attribute at
         WHERE at.attrelid = format('public.%I', t.tbl)::regclass AND at.attnum > 0 AND NOT at.attisdropped
           AND has_column_privilege(format('public.%I', t.tbl), at.attname, 'UPDATE')
         ORDER BY at.attnum LIMIT 1;

        -- Now name the writing school, and try to write the other's row.
        PERFORM set_config('app.chosen_school_id', CASE via WHEN 'app_authenticated' THEN d.write_at::text ELSE '' END, true);
        PERFORM set_config('request.headers', CASE via WHEN 'authenticated' THEN json_build_object('x-school-id', d.write_at)::text ELSE '' END, true);
        IF app.current_school_id() IS DISTINCT FROM d.write_at THEN
          RAISE EXCEPTION 'flera 245a: % did not resolve to the writing school as %', d.label, via;
        END IF;
        FOREACH cmd IN ARRAY ARRAY['insert', 'update', 'delete'] LOOP
          outcome := NULL;
          BEGIN
            IF cmd = 'insert' THEN
              IF ins_cols IS NULL THEN
                outcome := 'denied';
              ELSE
                EXECUTE format('INSERT INTO %I (%s) SELECT %s FROM jsonb_populate_record(NULL::%I, $1)',
                               t.tbl, ins_cols, ins_cols, t.tbl) USING stashed;
                GET DIAGNOSTICS n = ROW_COUNT;
                outcome := CASE WHEN n = 1 THEN 'admitted' ELSE 'none' END;
              END IF;
            ELSIF cmd = 'update' THEN
              IF upd_col IS NULL THEN
                outcome := 'denied';
              ELSE
                EXECUTE format('UPDATE %I SET %s = %s WHERE ctid = $1::tid', t.tbl, upd_col, upd_col) USING tid;
                GET DIAGNOSTICS n = ROW_COUNT;
                outcome := CASE WHEN n = 0 THEN 'none' ELSE 'admitted' END;
              END IF;
            ELSE
              EXECUTE format('DELETE FROM %I WHERE ctid = $1::tid', t.tbl) USING tid;
              GET DIAGNOSTICS n = ROW_COUNT;
              outcome := CASE WHEN n = 0 THEN 'none' ELSE 'admitted' END;
            END IF;
            RAISE EXCEPTION USING ERRCODE = 'ZF245';
          EXCEPTION
            WHEN SQLSTATE 'ZF245' THEN NULL;
            WHEN unique_violation OR foreign_key_violation OR exclusion_violation OR check_violation OR not_null_violation THEN
              -- Past row security, which PostgreSQL checks before the
              -- table's constraints: the row reached them.
              outcome := 'admitted';
            WHEN insufficient_privilege THEN
              GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
              outcome := CASE WHEN msg LIKE '%row-level security%' THEN 'refused' ELSE 'denied' END;
            WHEN OTHERS THEN
              GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, msg = MESSAGE_TEXT;
              -- A BEFORE trigger refusing first is no write either, but proves
              -- less: counted and named below.
              outcome := 'other ' || st;
          END;
          IF outcome LIKE 'other %' THEN
            others := others || format('%s %s %s', t.tbl, cmd, outcome);
          END IF;
          IF outcome = 'admitted' THEN
            wrong := wrong || format('%s as %s: %s %s of the other school was admitted', d.label, via, cmd, t.tbl);
          END IF;
          cells := cells + 1;
        END LOOP;
      END LOOP;
      -- PostgREST's role reads few of the tables at all; the API's most of
      -- them, though school A (the seed's) has rows in fewer than the
      -- roller school, which has one in each.
      at_least := CASE via WHEN 'app_authenticated' THEN 20 ELSE 5 END;
      IF probed < at_least THEN
        wrong := wrong || format('%s as %s: only %s tables had a row to try', d.label, via, probed);
      END IF;
      tried := tried || format('%s %s: %s tables', via, d.label, probed);
    END LOOP;
    SET LOCAL ROLE app_authenticated;
  END LOOP;

  PERFORM set_config('app.chosen_school_id', '', true);
  PERFORM set_config('request.headers', '', true);
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'flera 245a: % of % cells wrong: %', cardinality(wrong), cells, array_to_string(wrong, '; ');
  END IF;
  RAISE NOTICE 'flera 245a: % cells (%); refused by a trigger before row security: %', cells,
    array_to_string(tried, '; '), coalesce(nullif(array_to_string(others, ', '), ''), 'none');
END $$;
ROLLBACK;

BEGIN;
SELECT set_config('app.test_rls245_a', :'school_a', true),
       set_config('app.test_rls245_b', :'school_b', true);
DO $$
DECLARE
  a uuid := current_setting('app.test_rls245_a')::uuid;
  b uuid := current_setting('app.test_rls245_b')::uuid;
  t constant text := 'fe000000-0000-4000-8000-000000000244';
  token constant text := 'ExponentPushToken[rls245flera000]';
  row_a uuid;
  row_b uuid;
  r record;
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', t)::text, true);
  PERFORM set_config('app.chosen_school_id', a::text, true);
  row_a := app.current_user_id();
  PERFORM app.claim_device_push_token(token, 'IOS', 'sv');
  PERFORM set_config('app.chosen_school_id', b::text, true);
  row_b := app.current_user_id();
  IF row_a IS NULL OR row_b IS NULL OR row_a = row_b THEN
    RAISE EXCEPTION 'flera 245b: the teacher at A and B did not resolve to two rows';
  END IF;
  PERFORM app.claim_device_push_token(token, 'IOS', 'sv');

  -- As the delivery asks, with no principal.
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM set_config('app.chosen_school_id', '', true);
  IF EXISTS (SELECT 1 FROM app.push_targets(a, ARRAY[row_a], 'LESSON_CANCELLED', true)) THEN
    RAISE EXCEPTION 'flera 245b: the device still receives school A''s notices after registering at B';
  END IF;
  SELECT count(*) AS n, min(user_id::text) AS who INTO r FROM app.push_targets(b, ARRAY[row_b], 'LESSON_CANCELLED', true);
  IF r.n <> 1 OR r.who IS DISTINCT FROM row_b::text THEN
    RAISE EXCEPTION 'flera 245b: school B''s delivery found % devices (%)', r.n, r.who;
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 205: lärarandelarna står i katalogen som migreringen säger
-- (TeachingRequirementShares, 20261205090000).
--
-- Row security on; exactly four arms, all TO app_authenticated (the staff read
-- and the planner's insert, update and delete); the update arm asks the area
-- in WITH CHECK only; PostgREST's authenticated and anon hold nothing;
-- service_role reads and writes nothing more; the API holds SELECT, INSERT,
-- UPDATE and DELETE and no TRUNCATE, REFERENCES or TRIGGER; no API role holds
-- MAINTAIN on 17. 1..39 lessons, 15..240 minutes on the grid; the post's key
-- (requirementId, schoolId) cascades, the teacher's (teacherId, schoolId) sets
-- the teacher alone to null; the post's own (id, schoolId) is unique; both
-- triggers are there, on the function nobody else may call.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  r text;
  p text;
  n bigint;
BEGIN
  IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = '"TeachingRequirementShares"'::regclass) THEN
    RAISE EXCEPTION 'shares: row security is off on TeachingRequirementShares';
  END IF;
  SELECT count(*) INTO n FROM pg_policies WHERE schemaname = 'public' AND tablename = 'TeachingRequirementShares';
  IF n <> 4
     OR (SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND tablename = 'TeachingRequirementShares'
          AND (policyname, cmd) IN (('teaching_requirement_shares_staff_select', 'SELECT'),
                                    ('teaching_requirement_shares_admin_insert', 'INSERT'),
                                    ('teaching_requirement_shares_admin_update', 'UPDATE'),
                                    ('teaching_requirement_shares_admin_delete', 'DELETE'))
          AND roles = '{app_authenticated}') <> 4 THEN
    RAISE EXCEPTION 'shares: TeachingRequirementShares has % arms, not the staff read and the planner''s three writes TO app_authenticated', n;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'TeachingRequirementShares'
                   AND policyname = 'teaching_requirement_shares_staff_select'
                   AND qual LIKE '%SCHOOL_ADMIN%' AND qual LIKE '%TEACHER%' AND qual NOT LIKE '%STUDENT%'
                   AND qual NOT LIKE '%GUARDIAN%' AND qual LIKE '%current_school_id()%') THEN
    RAISE EXCEPTION 'shares: the read is not the school''s administrators and teachers';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'TeachingRequirementShares' AND cmd = 'UPDATE'
               AND qual LIKE '%current_user_may%')
     OR NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'TeachingRequirementShares' AND cmd = 'UPDATE'
                      AND with_check LIKE '%current_user_may(''PLANERING''%')
     OR (SELECT count(*) FROM pg_policies WHERE tablename = 'TeachingRequirementShares' AND cmd IN ('INSERT', 'DELETE')
           AND coalesce(with_check, qual) LIKE '%current_user_may(''PLANERING''%') <> 2 THEN
    RAISE EXCEPTION 'shares: the writes do not ask PLANERING, or the update asks it outside WITH CHECK';
  END IF;
  FOREACH r IN ARRAY ARRAY['authenticated', 'anon'] LOOP
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
    FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
      IF has_table_privilege(r, 'public."TeachingRequirementShares"', p) THEN
        RAISE EXCEPTION 'shares: % holds % on TeachingRequirementShares', r, p;
      END IF;
    END LOOP;
  END LOOP;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
    FOREACH p IN ARRAY ARRAY['INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
      IF has_table_privilege('service_role', 'public."TeachingRequirementShares"', p) THEN
        RAISE EXCEPTION 'shares: service_role holds % on TeachingRequirementShares', p;
      END IF;
    END LOOP;
  END IF;
  FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE'] LOOP
    IF NOT has_table_privilege('app_authenticated', 'public."TeachingRequirementShares"', p) THEN
      RAISE EXCEPTION 'shares: the API lacks % on TeachingRequirementShares', p;
    END IF;
  END LOOP;
  FOREACH p IN ARRAY ARRAY['TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
    IF has_table_privilege('app_authenticated', 'public."TeachingRequirementShares"', p) THEN
      RAISE EXCEPTION 'shares: the API holds % on TeachingRequirementShares', p;
    END IF;
  END LOOP;
  IF current_setting('server_version_num')::int >= 170000 THEN
    FOREACH r IN ARRAY ARRAY['authenticated', 'app_authenticated', 'service_role', 'anon'] LOOP
      CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
      IF has_table_privilege(r, 'public."TeachingRequirementShares"', 'MAINTAIN') THEN
        RAISE EXCEPTION 'shares: % holds MAINTAIN on TeachingRequirementShares', r;
      END IF;
    END LOOP;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'TeachingRequirementShares_lessons_is_sane' AND contype = 'c'
                   AND pg_get_constraintdef(oid) LIKE '%lessons >= 1%' AND pg_get_constraintdef(oid) LIKE '%lessons <= 39%')
     OR NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'TeachingRequirementShares_minutes_is_sane' AND contype = 'c'
                   AND pg_get_constraintdef(oid) LIKE '%minutes >= 15%' AND pg_get_constraintdef(oid) LIKE '%minutes <= 240%'
                   AND pg_get_constraintdef(oid) LIKE '%minutes % 5%') THEN
    RAISE EXCEPTION 'shares: the lessons'' or the minutes'' check is missing';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
     WHERE c.contype = 'f' AND c.conrelid = '"TeachingRequirementShares"'::regclass
       AND c.confrelid = '"TeachingRequirements"'::regclass AND c.confdeltype = 'c'
       AND (SELECT array_agg(a.attname::text ORDER BY k.ord) FROM unnest(c.conkey) WITH ORDINALITY k(attnum, ord)
              JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum) = ARRAY['requirementId', 'schoolId']) THEN
    RAISE EXCEPTION 'shares: the post''s key is not (requirementId, schoolId) ON DELETE CASCADE';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
     WHERE c.contype = 'f' AND c.conrelid = '"TeachingRequirementShares"'::regclass
       AND c.confrelid = '"Users"'::regclass AND c.confdeltype = 'n'
       AND (SELECT array_agg(a.attname::text ORDER BY k.ord) FROM unnest(c.conkey) WITH ORDINALITY k(attnum, ord)
              JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum) = ARRAY['teacherId', 'schoolId']
       AND (SELECT array_agg(a.attname::text) FROM unnest(c.confdelsetcols) k(attnum)
              JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum) = ARRAY['teacherId']) THEN
    RAISE EXCEPTION 'shares: the teacher''s key is not (teacherId, schoolId) ON DELETE SET NULL ("teacherId")';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_index i WHERE i.indrelid = '"TeachingRequirements"'::regclass AND i.indisunique
                   AND (SELECT array_agg(a.attname::text ORDER BY k.ord) FROM unnest(i.indkey) WITH ORDINALITY k(attnum, ord)
                          JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k.attnum) = ARRAY['id', 'schoolId']) THEN
    RAISE EXCEPTION 'shares: TeachingRequirements has no unique (id, schoolId) for the shares'' key';
  END IF;
  SELECT count(*) INTO n FROM pg_trigger t
   WHERE NOT t.tgisinternal AND t.tgfoid = 'app.teaching_requirement_shares_fit()'::regprocedure
     AND t.tgrelid IN ('"TeachingRequirementShares"'::regclass, '"TeachingRequirements"'::regclass);
  IF n <> 2 THEN RAISE EXCEPTION 'shares: % triggers call the fit check, not the two', n; END IF;
  IF NOT (SELECT prosecdef FROM pg_proc WHERE oid = 'app.teaching_requirement_shares_fit()'::regprocedure) THEN
    RAISE EXCEPTION 'shares: the fit check is not SECURITY DEFINER, so it reads only what the writer may';
  END IF;
  FOREACH r IN ARRAY ARRAY['authenticated', 'anon', 'service_role', 'app_authenticated'] LOOP
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
    IF has_function_privilege(r, 'app.teaching_requirement_shares_fit()', 'EXECUTE') THEN
      RAISE EXCEPTION 'shares: % may call the fit check', r;
    END IF;
  END LOOP;
END $$;

-- ---------------------------------------------------------------------------
-- Section 206: skolans administratör och lärare läser skolans lärarandelar,
-- inga andras; elev och vårdnadshavare läser inga; den som skriver planering
-- skriver dem, expeditionen och läraren inte; PostgREST:s roll når dem inte
-- ens med administratörens anspråk; tjänsten och synken inget (20261205090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
SELECT set_config('app.test_dl_other_post', (SELECT "requirementId"::text FROM "TeachingRequirementShares" LIMIT 1), true);
SELECT set_config('app.test_dl_other_school', app.current_school_id()::text, true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002051')::text, true);
SELECT set_config('app.test_dl_school', app.current_school_id()::text, true);
DO $$
DECLARE
  n bigint;
  who text;
  post uuid;
  cilla uuid;
  ny uuid;
BEGIN
  IF coalesce(current_setting('app.test_dl_school', true), '') = ''
     OR coalesce(current_setting('app.test_dl_other_post', true), '') = '' THEN
    RAISE EXCEPTION 'shares: a fixture admin read no school, or the roller school''s admin none of its shares';
  END IF;
  SELECT count(*) INTO n FROM "TeachingRequirementShares";
  IF n <> 1 THEN RAISE EXCEPTION 'shares: the admin reads % shares, not the school''s one', n; END IF;
  SELECT "requirementId" INTO post FROM "TeachingRequirementShares";
  SELECT id INTO cilla FROM "Users" WHERE email = 'delade-cilla@example.invalid';

  -- The planner writes: Cilla's share, changed, gone again.
  INSERT INTO "TeachingRequirementShares" ("schoolId", "requirementId", "teacherId", lessons, minutes, "updatedAt")
  VALUES (app.current_school_id(), post, cilla, 1, 60, now()) RETURNING id INTO ny;
  UPDATE "TeachingRequirementShares" SET lessons = 1, "updatedAt" = now() WHERE id = ny;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'shares: the admin updated % of their own shares', n; END IF;
  DELETE FROM "TeachingRequirementShares" WHERE id = ny;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'shares: the admin removed % of their own shares', n; END IF;

  -- Another school's share: not seen, not changed, not removed, not written into.
  SELECT count(*) INTO n FROM "TeachingRequirementShares" WHERE "requirementId" = current_setting('app.test_dl_other_post')::uuid;
  IF n <> 0 THEN RAISE EXCEPTION 'shares: the admin reads another school''s share'; END IF;
  UPDATE "TeachingRequirementShares" SET lessons = 1 WHERE "schoolId" = current_setting('app.test_dl_other_school')::uuid;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'shares: the admin changed another school''s share'; END IF;
  DELETE FROM "TeachingRequirementShares" WHERE "schoolId" = current_setting('app.test_dl_other_school')::uuid;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'shares: the admin removed another school''s share'; END IF;
  BEGIN
    INSERT INTO "TeachingRequirementShares" ("schoolId", "requirementId", "teacherId", lessons, minutes, "updatedAt")
    VALUES (current_setting('app.test_dl_other_school')::uuid, current_setting('app.test_dl_other_post')::uuid, NULL, 1, 60, now());
    RAISE EXCEPTION 'shares: the admin wrote a share into another school';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  -- Filed under their own school but naming another school's post, or a
  -- teacher of another school: the composite keys refuse what row security
  -- cannot, since a key check runs as the owner.
  BEGIN
    INSERT INTO "TeachingRequirementShares" ("schoolId", "requirementId", "teacherId", lessons, minutes, "updatedAt")
    VALUES (app.current_school_id(), current_setting('app.test_dl_other_post')::uuid, NULL, 1, 60, now());
    RAISE EXCEPTION 'shares: a share named another school''s post';
  EXCEPTION WHEN foreign_key_violation THEN NULL;
  END;
  BEGIN
    INSERT INTO "TeachingRequirementShares" ("schoolId", "requirementId", "teacherId", lessons, minutes, "updatedAt")
    SELECT app.current_school_id(), post, t."teacherId", 1, 60, now()
      FROM (SELECT '00000000-0000-4000-8000-0000000000aa'::uuid AS "teacherId") t;
    RAISE EXCEPTION 'shares: a share named a teacher of no school of its own';
  EXCEPTION WHEN foreign_key_violation THEN NULL;
  END;
  BEGIN
    UPDATE "TeachingRequirementShares" SET "schoolId" = current_setting('app.test_dl_other_school')::uuid;
    RAISE EXCEPTION 'shares: the admin moved a share into another school';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;

  -- The expedition reads, as every administrator does, and writes nothing.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002052')::text, true);
  SELECT count(*) INTO n FROM "TeachingRequirementShares";
  IF n <> 1 THEN RAISE EXCEPTION 'shares: the expedition reads % shares, not the school''s one', n; END IF;
  BEGIN
    INSERT INTO "TeachingRequirementShares" ("schoolId", "requirementId", "teacherId", lessons, minutes, "updatedAt")
    VALUES (app.current_school_id(), post, cilla, 1, 60, now());
    RAISE EXCEPTION 'shares: the expedition created a share';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    UPDATE "TeachingRequirementShares" SET lessons = 1;
    RAISE EXCEPTION 'shares: the expedition changed a share';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  DELETE FROM "TeachingRequirementShares";
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'shares: the expedition removed % shares', n; END IF;

  -- A teacher, Bo, reads them — Min tjänst counts his own — and writes none.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002054')::text, true);
  SELECT count(*) INTO n FROM "TeachingRequirementShares";
  IF n <> 1 THEN RAISE EXCEPTION 'shares: the teacher reads % shares, not the school''s one', n; END IF;
  UPDATE "TeachingRequirementShares" SET lessons = 1;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'shares: the teacher changed % shares', n; END IF;
  DELETE FROM "TeachingRequirementShares";
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'shares: the teacher removed % shares', n; END IF;
  BEGIN
    INSERT INTO "TeachingRequirementShares" ("schoolId", "requirementId", "teacherId", lessons, minutes, "updatedAt")
    VALUES (app.current_school_id(), post, cilla, 1, 60, now());
    RAISE EXCEPTION 'shares: the teacher created a share';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;

  -- Pupil and guardian: nothing read, nothing written.
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000002056', '00000000-0000-4000-8000-000000002057'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    SELECT count(*) INTO n FROM "TeachingRequirementShares";
    IF n <> 0 THEN RAISE EXCEPTION 'shares: % (%) reads % shares', who, app.current_user_role(), n; END IF;
    BEGIN
      INSERT INTO "TeachingRequirementShares" ("schoolId", "requirementId", "teacherId", lessons, minutes, "updatedAt")
      VALUES (app.current_school_id(), post, cilla, 1, 60, now());
      RAISE EXCEPTION 'shares: % created a share', who;
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
  END LOOP;

  -- The service and the sync principal of the school: nothing.
  PERFORM set_config('request.jwt.claims', '', true);
  FOREACH who IN ARRAY ARRAY['app.service_school_id', 'app.sync_school_id'] LOOP
    PERFORM set_config(who, current_setting('app.test_dl_school'), true);
    SELECT count(*) INTO n FROM "TeachingRequirementShares";
    IF n <> 0 THEN RAISE EXCEPTION 'shares: % reads % shares', who, n; END IF;
    PERFORM set_config(who, '', true);
  END LOOP;
END $$;

-- PostgREST's role, with the admin's claims: nothing at all.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002051')::text, true);
SET LOCAL ROLE authenticated;
DO $$
BEGIN
  IF current_user <> 'authenticated' THEN RAISE EXCEPTION 'shares: could not act as authenticated'; END IF;
  BEGIN
    PERFORM 1 FROM "TeachingRequirementShares";
    RAISE EXCEPTION 'shares: PostgREST''s role reads the shares';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 207: andelarna ryms i postens lektioner (TS409,
-- REQUIREMENT_SHARES_DO_NOT_FIT), vilken väg skrivningen än tar; en lärare som
-- tas bort lämnar sin andel utan lärare, två sådana stoppar inte borttagningen;
-- en borttagen post tar sina andelar med sig; postens skrivning i ordningen
-- andelar bort, post, andelar in går igenom (20261205090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002051')::text, true);
DO $$
DECLARE
  post uuid;
  anna uuid;
  bo uuid;
  cilla uuid;
  n bigint;
  st text;
  msg text;
  detail text;
  con text;
  rule text;
BEGIN
  SELECT "requirementId" INTO post FROM "TeachingRequirementShares";
  SELECT id INTO anna FROM "Users" WHERE email = 'delade-anna@example.invalid';
  SELECT id INTO bo FROM "Users" WHERE email = 'delade-bo@example.invalid';
  SELECT id INTO cilla FROM "Users" WHERE email = 'delade-cilla@example.invalid';
  IF post IS NULL OR anna IS NULL OR bo IS NULL OR cilla IS NULL THEN
    RAISE EXCEPTION 'shares fit: the fixture school''s post or teachers are missing';
  END IF;

  -- Each rule, by the statement that breaks it. The post is 3 × 60 with Anna
  -- its huvudlärare and Bo's 1 × 60.
  -- Each case is "<the reason it must name>:<which write breaks it>".
  FOR rule IN SELECT unnest(ARRAY['TEACHER_ON_POST:share is the lead', 'TEACHER_ON_POST:co-teacher is a share''s',
                                  'TEACHER_ON_POST:lead is a share''s', 'LENGTH_NOT_ON_POST:share of 45',
                                  'LENGTH_NOT_ON_POST:post becomes 55', 'TOO_MANY_OF_LENGTH:three more 60s',
                                  'LEAD_KEEPS_NONE:two more 60s', 'LEAD_KEEPS_NONE:post becomes one lesson']) LOOP
    BEGIN
      CASE split_part(rule, ':', 2)
        WHEN 'share is the lead' THEN
          INSERT INTO "TeachingRequirementShares" ("schoolId", "requirementId", "teacherId", lessons, minutes, "updatedAt")
          VALUES (app.current_school_id(), post, anna, 1, 60, now());
        WHEN 'co-teacher is a share''s' THEN
          UPDATE "TeachingRequirements" SET "coTeacherId" = bo WHERE id = post;
        WHEN 'lead is a share''s' THEN
          UPDATE "TeachingRequirements" SET "teacherId" = bo WHERE id = post;
        WHEN 'share of 45' THEN
          INSERT INTO "TeachingRequirementShares" ("schoolId", "requirementId", "teacherId", lessons, minutes, "updatedAt")
          VALUES (app.current_school_id(), post, cilla, 1, 45, now());
        WHEN 'post becomes 55' THEN
          UPDATE "TeachingRequirements" SET "minutesPerLesson" = 55 WHERE id = post;
        WHEN 'three more 60s' THEN
          INSERT INTO "TeachingRequirementShares" ("schoolId", "requirementId", "teacherId", lessons, minutes, "updatedAt")
          VALUES (app.current_school_id(), post, cilla, 3, 60, now());
        WHEN 'two more 60s' THEN
          INSERT INTO "TeachingRequirementShares" ("schoolId", "requirementId", "teacherId", lessons, minutes, "updatedAt")
          VALUES (app.current_school_id(), post, cilla, 2, 60, now());
        WHEN 'post becomes one lesson' THEN
          UPDATE "TeachingRequirements" SET "lessonsPerWeek" = 1 WHERE id = post;
      END CASE;
      RAISE EXCEPTION 'shares fit: "%" was let through', rule;
    EXCEPTION WHEN SQLSTATE 'TS409' THEN
      GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT, detail = PG_EXCEPTION_DETAIL;
      IF msg NOT LIKE 'REQUIREMENT_SHARES_DO_NOT_FIT:%'
         OR detail IS DISTINCT FROM format('requirementId=%s reason=%s', post, split_part(rule, ':', 1)) THEN
        RAISE EXCEPTION 'shares fit: "%" was refused as "%" / "%"', rule, msg, detail;
      END IF;
    END;
  END LOOP;

  -- What fits passes: two lessons left the post, Bo's one stays, Anna keeps one.
  UPDATE "TeachingRequirements" SET "lessonsPerWeek" = 2 WHERE id = post;
  -- The gateway's replacing write, in its order: shares out, post, shares in.
  DELETE FROM "TeachingRequirementShares" WHERE "requirementId" = post;
  UPDATE "TeachingRequirements" SET "lessonsPerWeek" = 2, "minutesPerLesson" = 80,
         "lessonLengths" = ARRAY[80, 40] WHERE id = post;
  INSERT INTO "TeachingRequirementShares" ("schoolId", "requirementId", "teacherId", lessons, minutes, "updatedAt")
  VALUES (app.current_school_id(), post, bo, 1, 40, now());
  -- On 1 × 80 + 1 × 40, a second share of the 40 is one too many.
  BEGIN
    INSERT INTO "TeachingRequirementShares" ("schoolId", "requirementId", "teacherId", lessons, minutes, "updatedAt")
    VALUES (app.current_school_id(), post, cilla, 1, 40, now());
    RAISE EXCEPTION 'shares fit: two shares of the post''s one 40 were let through';
  EXCEPTION WHEN SQLSTATE 'TS409' THEN
    GET STACKED DIAGNOSTICS detail = PG_EXCEPTION_DETAIL;
    IF detail NOT LIKE '%reason=TOO_MANY_OF_LENGTH' THEN RAISE EXCEPTION 'shares fit: the second 40 was refused as %', detail; END IF;
  END;

  -- The CHECKs, at their bounds.
  FOREACH con IN ARRAY ARRAY['0:60', '40:60', '1:10', '1:245', '1:62'] LOOP
    BEGIN
      INSERT INTO "TeachingRequirementShares" ("schoolId", "requirementId", "teacherId", lessons, minutes, "updatedAt")
      VALUES (app.current_school_id(), post, cilla, split_part(con, ':', 1)::int, split_part(con, ':', 2)::int, now());
      RAISE EXCEPTION 'shares fit: % lessons × % minutes were let through', split_part(con, ':', 1), split_part(con, ':', 2);
    EXCEPTION WHEN check_violation THEN
      GET STACKED DIAGNOSTICS st = CONSTRAINT_NAME;
      IF st NOT IN ('TeachingRequirementShares_lessons_is_sane', 'TeachingRequirementShares_minutes_is_sane') THEN
        RAISE EXCEPTION 'shares fit: % was refused by %', con, st;
      END IF;
    END;
  END LOOP;

  -- Back to 3 × 60 with Bo's and Cilla's ones; both teachers deleted leave two
  -- teacherless shares, and neither deletion fails on the unique key.
  DELETE FROM "TeachingRequirementShares" WHERE "requirementId" = post;
  UPDATE "TeachingRequirements" SET "lessonsPerWeek" = 3, "minutesPerLesson" = 60, "lessonLengths" = '{}' WHERE id = post;
  INSERT INTO "TeachingRequirementShares" ("schoolId", "requirementId", "teacherId", lessons, minutes, "updatedAt")
  VALUES (app.current_school_id(), post, bo, 1, 60, now()), (app.current_school_id(), post, cilla, 1, 60, now());
  DELETE FROM "Users" WHERE id IN (bo, cilla);
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 2 THEN RAISE EXCEPTION 'shares fit: the admin deleted % of the two teachers', n; END IF;
  SELECT count(*) INTO n FROM "TeachingRequirementShares" WHERE "requirementId" = post AND "teacherId" IS NULL AND lessons = 1;
  IF n <> 2 THEN RAISE EXCEPTION 'shares fit: deleting the two teachers left % teacherless shares, not two', n; END IF;
  SELECT "teacherId" INTO st FROM "TeachingRequirements" WHERE id = post;
  IF st IS DISTINCT FROM anna::text THEN RAISE EXCEPTION 'shares fit: the post''s lead moved to %', st; END IF;

  -- A post deleted takes its shares with it.
  DELETE FROM "TeachingRequirements" WHERE id = post;
  SELECT count(*) INTO n FROM "TeachingRequirementShares" WHERE "requirementId" = post;
  IF n <> 0 THEN RAISE EXCEPTION 'shares fit: a deleted post left % shares', n; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 208: en inloggning med rader på två skolor läser och skriver bara
-- den valda skolans lärarandelar (20261205090000, ovanpå Flera skolor per
-- inloggning, 20261204090000).
--
-- The four arms ask app.current_school_id(), app.current_user_role() and
-- app.current_user_may(), which answer for the row the request names. The
-- fixtures' …0240 is FULL at A and LASARE in the roller school, …0241 the
-- other way round; the roller school's post carries one share. For each login
-- and each school named by the gateway's setting: the roller school's shares
-- are read only with the roller school named, and written only where the
-- named row writes planering — never across to the school not named.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls208_a', :'school_a', true);
DO $$
DECLARE
  a uuid := current_setting('app.test_rls208_a')::uuid;
  m uuid;
  r record;
  n bigint;
  wrote boolean;
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  PERFORM set_config('app.chosen_school_id', '', true);
  PERFORM set_config('request.headers', '', true);
  m := app.current_school_id();
  IF m IS NULL OR m = a THEN
    RAISE EXCEPTION 'shares 208: the roller school''s administrator resolves to %; fixtures did not run', m;
  END IF;
  SELECT count(*) INTO n FROM "TeachingRequirementShares" WHERE "schoolId" = m;
  IF n <> 1 THEN RAISE EXCEPTION 'shares 208: the roller school has % shares, not its one', n; END IF;

  FOR r IN
    SELECT * FROM (VALUES
      ('fe000000-0000-4000-8000-000000000240', m, 1, false, '208 FULL at A, LASARE in the roller school, which is named: reads its share, writes none'),
      ('fe000000-0000-4000-8000-000000000240', a, 0, false, '208 the same login with A named: the roller school''s share is no share of its'),
      ('fe000000-0000-4000-8000-000000000241', m, 1, true,  '208 LASARE at A, FULL in the roller school, which is named: writes its share'),
      ('fe000000-0000-4000-8000-000000000241', a, 0, false, '208 the same login with A named: neither reads nor writes the roller school''s share')
    ) v(sub, school, sees, writes, label)
  LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', r.sub, 'role', 'authenticated')::text, true);
    PERFORM set_config('app.chosen_school_id', r.school::text, true);
    IF app.current_school_id() IS DISTINCT FROM r.school THEN
      RAISE EXCEPTION '%: the login resolves to %', r.label, app.current_school_id();
    END IF;
    SELECT count(*) INTO n FROM "TeachingRequirementShares" WHERE "schoolId" = m;
    IF n <> r.sees THEN RAISE EXCEPTION '%: reads % of the roller school''s shares', r.label, n; END IF;
    -- A write that touches no column the trigger reads, undone either way.
    wrote := false;
    BEGIN
      UPDATE "TeachingRequirementShares" SET "updatedAt" = "updatedAt" WHERE "schoolId" = m;
      GET DIAGNOSTICS n = ROW_COUNT;
      wrote := n > 0;
      RAISE EXCEPTION 'undone' USING ERRCODE = 'RL208';
    EXCEPTION
      WHEN SQLSTATE 'RL208' THEN NULL;
      WHEN insufficient_privilege THEN wrote := false;
    END;
    IF wrote IS DISTINCT FROM r.writes THEN
      RAISE EXCEPTION '%: wrote the roller school''s share: %', r.label, wrote;
    END IF;
  END LOOP;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 200: rastvaktsområdena och rastvaktsschemat står i katalogen som
-- migreringen säger (SupervisionAreas, SupervisionShifts, 20261207090000).
--
-- Row security on both tables, every arm TO app_authenticated: the areas'
-- staff read and the planner's three writes; the passes' administrator read,
-- the teacher's read of their own, and the planner's three writes. The update
-- arms ask the area in WITH CHECK only. PostgREST's authenticated and anon
-- hold nothing, service_role reads and writes nothing more, the API holds
-- SELECT, INSERT, UPDATE and DELETE and no TRUNCATE, REFERENCES or TRIGGER,
-- and no API role holds MAINTAIN on 17. Each CHECK says what the migration
-- says, one place at a time is an EXCLUDE over the teacher, the year, the
-- weekday, the minutes and the dates, and every key is composite with the
-- school, ON UPDATE NO ACTION.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  t text;
  r text;
  p text;
  n bigint;
  def text;
BEGIN
  FOREACH t IN ARRAY ARRAY['SupervisionAreas', 'SupervisionShifts'] LOOP
    IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = format('public.%I', t)::regclass) THEN
      RAISE EXCEPTION 'supervision: row security is off on %', t;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = t AND roles <> '{app_authenticated}') THEN
      RAISE EXCEPTION 'supervision: % has an arm for another role than the API''s', t;
    END IF;
    FOREACH r IN ARRAY ARRAY['authenticated', 'anon'] LOOP
      CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
      FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
        IF has_table_privilege(r, format('public.%I', t), p) THEN RAISE EXCEPTION 'supervision: % holds % on %', r, p, t; END IF;
      END LOOP;
    END LOOP;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
      FOREACH p IN ARRAY ARRAY['INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
        IF has_table_privilege('service_role', format('public.%I', t), p) THEN RAISE EXCEPTION 'supervision: service_role holds % on %', p, t; END IF;
      END LOOP;
    END IF;
    FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE'] LOOP
      IF NOT has_table_privilege('app_authenticated', format('public.%I', t), p) THEN RAISE EXCEPTION 'supervision: the API lacks % on %', p, t; END IF;
    END LOOP;
    FOREACH p IN ARRAY ARRAY['TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
      IF has_table_privilege('app_authenticated', format('public.%I', t), p) THEN RAISE EXCEPTION 'supervision: the API holds % on %', p, t; END IF;
    END LOOP;
    IF current_setting('server_version_num')::int >= 170000 THEN
      FOREACH r IN ARRAY ARRAY['authenticated', 'app_authenticated', 'service_role', 'anon'] LOOP
        CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
        IF has_table_privilege(r, format('public.%I', t), 'MAINTAIN') THEN RAISE EXCEPTION 'supervision: % holds MAINTAIN on %', r, t; END IF;
      END LOOP;
    END IF;
    -- The planner's writes: the area in the insert's and update's WITH
    -- CHECK and the delete's USING, never in the update's USING.
    IF (SELECT count(*) FROM pg_policies WHERE tablename = t AND cmd IN ('INSERT', 'UPDATE', 'DELETE')
          AND coalesce(with_check, qual) LIKE '%current_user_may(''PLANERING''%'
          AND coalesce(with_check, qual) LIKE '%SCHOOL_ADMIN%') <> 3
       OR EXISTS (SELECT 1 FROM pg_policies WHERE tablename = t AND cmd = 'UPDATE' AND qual LIKE '%current_user_may%') THEN
      RAISE EXCEPTION 'supervision: %''s writes are not the planner''s three, with the update asking in WITH CHECK alone', t;
    END IF;
  END LOOP;

  SELECT count(*) INTO n FROM pg_policies WHERE schemaname = 'public' AND tablename = 'SupervisionAreas'
     AND (policyname, cmd) IN (('supervision_areas_staff_select', 'SELECT'), ('supervision_areas_admin_insert', 'INSERT'),
                               ('supervision_areas_admin_update', 'UPDATE'), ('supervision_areas_admin_delete', 'DELETE'));
  IF n <> 4 OR (SELECT count(*) FROM pg_policies WHERE tablename = 'SupervisionAreas') <> 4 THEN
    RAISE EXCEPTION 'supervision: the areas have not exactly the staff read and the planner''s three writes';
  END IF;
  SELECT count(*) INTO n FROM pg_policies WHERE schemaname = 'public' AND tablename = 'SupervisionShifts'
     AND (policyname, cmd) IN (('supervision_shifts_admin_select', 'SELECT'), ('supervision_shifts_teacher_own_select', 'SELECT'),
                               ('supervision_shifts_admin_insert', 'INSERT'), ('supervision_shifts_admin_update', 'UPDATE'),
                               ('supervision_shifts_admin_delete', 'DELETE'));
  IF n <> 5 OR (SELECT count(*) FROM pg_policies WHERE tablename = 'SupervisionShifts') <> 5 THEN
    RAISE EXCEPTION 'supervision: the passes have not exactly the two reads and the planner''s three writes';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'supervision_areas_staff_select'
                   AND qual LIKE '%SCHOOL_ADMIN%' AND qual LIKE '%TEACHER%' AND qual NOT LIKE '%STUDENT%'
                   AND qual NOT LIKE '%GUARDIAN%' AND qual LIKE '%current_school_id()%') THEN
    RAISE EXCEPTION 'supervision: the areas'' read is not the school''s administrators and teachers';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'supervision_shifts_admin_select'
                   AND qual LIKE '%SCHOOL_ADMIN%' AND qual NOT LIKE '%TEACHER%' AND qual LIKE '%current_school_id()%')
     OR NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'supervision_shifts_teacher_own_select'
                   AND qual LIKE '%''TEACHER''%' AND qual NOT LIKE '%SCHOOL_ADMIN%' AND qual LIKE '%"userId" = %current_user_id()%'
                   AND qual LIKE '%current_school_id()%') THEN
    RAISE EXCEPTION 'supervision: the passes'' reads are not the administrators'' and the teacher''s own';
  END IF;

  -- The checks, by what they say.
  FOR def IN SELECT unnest(ARRAY[
      'SupervisionAreas_name_named|btrim|60',
      'SupervisionAreas_grade_span|IS NULL|12',
      'SupervisionAreas_guards_range|>= 0|<= 10',
      'SupervisionShifts_day_is_iso|>= 1|<= 7',
      'SupervisionShifts_window_is_ordered|"endTime" > "startTime"|"endTime" > "startTime"',
      'SupervisionShifts_within_the_day|"endTime" < |24:00',
      'SupervisionShifts_whole_minutes|SECOND|SECOND',
      'SupervisionShifts_dates_are_ordered|"validTo" >= "validFrom"|"validTo" >= "validFrom"',
      'SupervisionShifts_dates_on_the_weekday|isodow FROM "validFrom"|isodow FROM "validTo"',
      'SupervisionShifts_note_is_short|btrim|200'])
  LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = split_part(def, '|', 1) AND contype = 'c' AND convalidated
                     AND pg_get_constraintdef(oid) ILIKE '%' || split_part(def, '|', 2) || '%'
                     AND pg_get_constraintdef(oid) ILIKE '%' || split_part(def, '|', 3) || '%') THEN
      RAISE EXCEPTION 'supervision: the check % is missing or says something else', split_part(def, '|', 1);
    END IF;
  END LOOP;
  -- A pseudonym's passes lose their note with their tjänst's (section 84 runs it).
  IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
                  WHERE n.nspname = 'app' AND p.proname = 'gallring_pseudonymise' AND p.prosecdef
                    AND p.prosrc LIKE '%UPDATE "SupervisionShifts" SET "note" = NULL%'
                    AND p.prosrc LIKE '%UPDATE "TeacherEmployments" SET "signature" = NULL, "note" = NULL%') THEN
    RAISE EXCEPTION 'supervision: app.gallring_pseudonymise does not clear a pseudonym''s pass notes beside their tjänst''s';
  END IF;
  SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint
   WHERE conname = 'SupervisionShifts_one_place_at_a_time' AND contype = 'x';
  IF def IS NULL OR def NOT LIKE 'EXCLUDE USING gist ("userId" WITH =, "academicYearId" WITH =, "dayOfWeek" WITH =, tsrange(%startTime%endTime%) WITH &&, daterange("validFrom", "validTo", %[]%) WITH &&)' THEN
    RAISE EXCEPTION 'supervision: one place at a time is not the EXCLUDE the migration writes: %', def;
  END IF;

  -- The keys: composite with the school, ON UPDATE NO ACTION, and what a
  -- delete of the other end does.
  FOR def IN SELECT unnest(ARRAY[
      'SupervisionShifts|AcademicYears|academicYearId,schoolId|c',
      'SupervisionShifts|SupervisionAreas|areaId,schoolId|c',
      'SupervisionShifts|Users|userId,schoolId|c',
      'SupervisionAreas|Sites|siteId,schoolId|n'])
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_constraint c
       WHERE c.contype = 'f' AND c.conrelid = format('public.%I', split_part(def, '|', 1))::regclass
         AND c.confrelid = format('public.%I', split_part(def, '|', 2))::regclass
         AND c.confupdtype = 'a' AND c.confdeltype = split_part(def, '|', 4)
         AND (SELECT string_agg(a.attname::text, ',' ORDER BY k.ord) FROM unnest(c.conkey) WITH ORDINALITY k(attnum, ord)
                JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum) = split_part(def, '|', 3)
         AND (split_part(def, '|', 4) <> 'n'
              OR (SELECT array_agg(a.attname::text) FROM unnest(c.confdelsetcols) k(attnum)
                    JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum) = ARRAY['siteId'])) THEN
      RAISE EXCEPTION 'supervision: the key % is not as the migration writes it', def;
    END IF;
  END LOOP;
END $$;

-- ---------------------------------------------------------------------------
-- Section 201: skolans administratörer läser områdena och hela schemat, en
-- lärare områdena och sina egna pass, ingen annans skola; den som skriver
-- planering skriver dem, expeditionen inte; elev, vårdnadshavare, tjänsten
-- och synken läser inget; PostgREST:s roll når dem inte ens med
-- administratörens anspråk (20261207090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002025')::text, true);
SELECT set_config('app.test_rv_other', app.current_school_id()::text, true);
SELECT set_config('app.test_rv_other_area', (SELECT id::text FROM "SupervisionAreas" WHERE name = 'Annan gård'), true);
SELECT set_config('app.test_rv_other_shift', (SELECT min(id::text) FROM "SupervisionShifts"), true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002020')::text, true);
SELECT set_config('app.test_rv_school', app.current_school_id()::text, true);
DO $$
DECLARE
  n bigint;
  who text;
  garden uuid;
  yr uuid;
  bo uuid;
  ny uuid;
  pass uuid;
BEGIN
  IF coalesce(current_setting('app.test_rv_school', true), '') = ''
     OR coalesce(current_setting('app.test_rv_other_area', true), '') = ''
     OR coalesce(current_setting('app.test_rv_other_shift', true), '') = '' THEN
    RAISE EXCEPTION 'supervision: a fixture admin read no school, or the other school''s admin none of its area and pass';
  END IF;
  SELECT count(*) INTO n FROM "SupervisionAreas";
  IF n <> 2 THEN RAISE EXCEPTION 'supervision: the admin reads % areas, not the school''s two', n; END IF;
  SELECT count(*) INTO n FROM "SupervisionShifts";
  IF n <> 3 THEN RAISE EXCEPTION 'supervision: the admin reads % passes, not the school''s three', n; END IF;
  SELECT id INTO garden FROM "SupervisionAreas" WHERE name = 'RV Skolgården';
  SELECT "academicYearId" INTO yr FROM "SupervisionShifts" LIMIT 1;
  SELECT id INTO bo FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000002026';

  -- The planner writes: an area, a pass on it, both changed, both gone.
  INSERT INTO "SupervisionAreas" ("schoolId", name) VALUES (app.current_school_id(), 'RV Korridoren') RETURNING id INTO ny;
  INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime")
  VALUES (app.current_school_id(), yr, ny, bo, 3, '12:00', '12:20') RETURNING id INTO pass;
  UPDATE "SupervisionShifts" SET "endTime" = '12:30' WHERE id = pass;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'supervision: the admin changed % of their own passes', n; END IF;
  UPDATE "SupervisionAreas" SET "guardsNeeded" = 2 WHERE id = ny;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'supervision: the admin changed % of their own areas', n; END IF;
  DELETE FROM "SupervisionShifts" WHERE id = pass;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'supervision: the admin removed % of their own passes', n; END IF;
  DELETE FROM "SupervisionAreas" WHERE id = ny;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'supervision: the admin removed % of their own areas', n; END IF;

  -- Another school's area and pass: not seen, not changed, not removed, not written into.
  UPDATE "SupervisionAreas" SET name = 'x' WHERE id = current_setting('app.test_rv_other_area')::uuid;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'supervision: the admin renamed another school''s area'; END IF;
  DELETE FROM "SupervisionShifts" WHERE id = current_setting('app.test_rv_other_shift')::uuid;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'supervision: the admin removed another school''s pass'; END IF;
  BEGIN
    INSERT INTO "SupervisionAreas" ("schoolId", name) VALUES (current_setting('app.test_rv_other')::uuid, 'Inte min');
    RAISE EXCEPTION 'supervision: the admin wrote an area into another school';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    UPDATE "SupervisionAreas" SET "schoolId" = current_setting('app.test_rv_other')::uuid WHERE id = garden;
    RAISE EXCEPTION 'supervision: the admin moved an area into another school';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    UPDATE "SupervisionShifts" SET "schoolId" = current_setting('app.test_rv_other')::uuid;
    RAISE EXCEPTION 'supervision: the admin moved a pass into another school';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;

  -- The expedition reads, as every administrator does, and writes nothing here.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002024')::text, true);
  SELECT count(*) INTO n FROM "SupervisionShifts";
  IF n <> 3 THEN RAISE EXCEPTION 'supervision: the expedition reads % passes, not the school''s three', n; END IF;
  BEGIN
    INSERT INTO "SupervisionAreas" ("schoolId", name) VALUES (app.current_school_id(), 'Expeditionens');
    RAISE EXCEPTION 'supervision: the expedition created an area';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    UPDATE "SupervisionShifts" SET "dayOfWeek" = 4;
    RAISE EXCEPTION 'supervision: the expedition moved a pass';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  DELETE FROM "SupervisionShifts";
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'supervision: the expedition removed % passes', n; END IF;

  -- Anna reads both areas and her own two passes, not Bo's, and writes nothing.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002021')::text, true);
  SELECT count(*) INTO n FROM "SupervisionAreas";
  IF n <> 2 THEN RAISE EXCEPTION 'supervision: the teacher reads % areas, not the school''s two', n; END IF;
  SELECT count(*) INTO n FROM "SupervisionShifts" WHERE "userId" = app.current_user_id();
  IF n <> 2 OR (SELECT count(*) FROM "SupervisionShifts") <> 2 THEN
    RAISE EXCEPTION 'supervision: the teacher reads % of her own passes and % in all, not her two alone',
      n, (SELECT count(*) FROM "SupervisionShifts");
  END IF;
  UPDATE "SupervisionAreas" SET name = 'x';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'supervision: the teacher renamed % areas', n; END IF;
  UPDATE "SupervisionShifts" SET "endTime" = '10:30';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'supervision: the teacher changed % of her passes', n; END IF;
  DELETE FROM "SupervisionShifts";
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'supervision: the teacher removed % passes', n; END IF;
  BEGIN
    INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime")
    VALUES (app.current_school_id(), yr, garden, app.current_user_id(), 5, '10:00', '10:20');
    RAISE EXCEPTION 'supervision: the teacher gave herself a pass';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  -- Bo reads his one.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002026')::text, true);
  SELECT count(*) INTO n FROM "SupervisionShifts";
  IF n <> 1 THEN RAISE EXCEPTION 'supervision: Bo reads % passes, not his one', n; END IF;

  -- Pupil and guardian: nothing read, nothing written.
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000002022', '00000000-0000-4000-8000-000000002023'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    SELECT count(*) INTO n FROM "SupervisionAreas";
    IF n <> 0 THEN RAISE EXCEPTION 'supervision: % (%) reads % areas', who, app.current_user_role(), n; END IF;
    SELECT count(*) INTO n FROM "SupervisionShifts";
    IF n <> 0 THEN RAISE EXCEPTION 'supervision: % (%) reads % passes', who, app.current_user_role(), n; END IF;
    BEGIN
      INSERT INTO "SupervisionAreas" ("schoolId", name) VALUES (app.current_school_id(), 'Familjens');
      RAISE EXCEPTION 'supervision: % created an area', who;
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
  END LOOP;

  -- The service and the sync principal of the school: nothing.
  PERFORM set_config('request.jwt.claims', '', true);
  FOREACH who IN ARRAY ARRAY['app.service_school_id', 'app.sync_school_id'] LOOP
    PERFORM set_config(who, current_setting('app.test_rv_school'), true);
    SELECT count(*) INTO n FROM "SupervisionAreas";
    IF n <> 0 THEN RAISE EXCEPTION 'supervision: % reads % areas', who, n; END IF;
    SELECT count(*) INTO n FROM "SupervisionShifts";
    IF n <> 0 THEN RAISE EXCEPTION 'supervision: % reads % passes', who, n; END IF;
    PERFORM set_config(who, '', true);
  END LOOP;
END $$;

-- PostgREST's role, with the admin's claims: nothing at all.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002020')::text, true);
SET LOCAL ROLE authenticated;
DO $$
BEGIN
  IF current_user <> 'authenticated' THEN RAISE EXCEPTION 'supervision: could not act as authenticated'; END IF;
  BEGIN
    PERFORM 1 FROM "SupervisionAreas";
    RAISE EXCEPTION 'supervision: PostgREST''s role reads the areas';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
  BEGIN
    PERFORM 1 FROM "SupervisionShifts";
    RAISE EXCEPTION 'supervision: PostgREST''s role reads the passes';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 202: ett område och ett pass håller sina gränser, ett pass hör till
-- sin skolas läsår, område och lärare, och en lärare är på ett ställe i taget
-- (20261207090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002025')::text, true);
SELECT set_config('app.test_rv_other_area', (SELECT id::text FROM "SupervisionAreas" WHERE name = 'Annan gård'), true);
SELECT set_config('app.test_rv_other_year', (SELECT min(id::text) FROM "AcademicYears"), true);
SELECT set_config('app.test_rv_other_teacher', (SELECT id::text FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000002027'), true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001245')::text, true);
SELECT set_config('app.test_rv_other_site', (SELECT id::text FROM "Sites" WHERE name = 'Annan Norra'), true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002020')::text, true);
DO $$
DECLARE
  n bigint;
  st text;
  span int[];
  garden uuid;
  hall uuid;
  yr uuid;
  later uuid;
  anna uuid;
  bo uuid;
  pass uuid;
BEGIN
  IF coalesce(current_setting('app.test_rv_other_year', true), '') = ''
     OR coalesce(current_setting('app.test_rv_other_teacher', true), '') = ''
     OR coalesce(current_setting('app.test_rv_other_site', true), '') = '' THEN
    RAISE EXCEPTION 'supervision: another school''s year, teacher or site could not be read for the keys below';
  END IF;
  SELECT id INTO garden FROM "SupervisionAreas" WHERE name = 'RV Skolgården';
  SELECT id INTO hall FROM "SupervisionAreas" WHERE name = 'RV Matsalen';
  SELECT "academicYearId" INTO yr FROM "SupervisionShifts" LIMIT 1;
  SELECT id INTO anna FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000002021';
  SELECT id INTO bo FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000002026';

  -- An area's name: trimmed, 1..60, unique in the school.
  FOREACH st IN ARRAY ARRAY['', ' RV Väst', 'RV Väst ', repeat('x', 61)] LOOP
    BEGIN
      INSERT INTO "SupervisionAreas" ("schoolId", name) VALUES (app.current_school_id(), st);
      RAISE EXCEPTION 'supervision: an area named "%" was stored', st;
    EXCEPTION WHEN check_violation THEN NULL;
    END;
  END LOOP;
  BEGIN
    INSERT INTO "SupervisionAreas" ("schoolId", name) VALUES (app.current_school_id(), 'RV Matsalen');
    RAISE EXCEPTION 'supervision: two areas of the school share a name';
  EXCEPTION WHEN unique_violation THEN NULL;
  END;
  INSERT INTO "SupervisionAreas" ("schoolId", name) VALUES (app.current_school_id(), repeat('x', 60));
  -- A span: both ends or neither, 0..12, in order.
  FOREACH span SLICE 1 IN ARRAY ARRAY[[1, NULL], [NULL, 3], [4, 3], [-1, 2], [0, 13]] LOOP
    BEGIN
      UPDATE "SupervisionAreas" SET "minGradeLevel" = span[1], "maxGradeLevel" = span[2] WHERE id = garden;
      RAISE EXCEPTION 'supervision: an area was given the span %', span;
    EXCEPTION WHEN check_violation THEN NULL;
    END;
  END LOOP;
  UPDATE "SupervisionAreas" SET "minGradeLevel" = 0, "maxGradeLevel" = 12 WHERE id = garden;
  UPDATE "SupervisionAreas" SET "minGradeLevel" = 5, "maxGradeLevel" = 5 WHERE id = garden;
  UPDATE "SupervisionAreas" SET "minGradeLevel" = NULL, "maxGradeLevel" = NULL WHERE id = garden;
  -- Rastvakter at once: 0 and 10 are answers, -1 and 11 are not.
  UPDATE "SupervisionAreas" SET "guardsNeeded" = 0 WHERE id = garden;
  UPDATE "SupervisionAreas" SET "guardsNeeded" = 10 WHERE id = garden;
  FOREACH n IN ARRAY ARRAY[-1, 11] LOOP
    BEGIN
      UPDATE "SupervisionAreas" SET "guardsNeeded" = n WHERE id = garden;
      RAISE EXCEPTION 'supervision: an area was said to need % rastvakter', n;
    EXCEPTION WHEN check_violation THEN NULL;
    END;
  END LOOP;
  -- Another school's site: refused by the key.
  BEGIN
    UPDATE "SupervisionAreas" SET "siteId" = current_setting('app.test_rv_other_site')::uuid WHERE id = garden;
    RAISE EXCEPTION 'supervision: an area was put on another school''s site';
  EXCEPTION WHEN foreign_key_violation THEN NULL;
  END;

  -- A pass's weekday, window, minutes, dates and note.
  FOREACH n IN ARRAY ARRAY[0, 8] LOOP
    BEGIN
      INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime")
      VALUES (app.current_school_id(), yr, garden, bo, n, '10:00', '10:20');
      RAISE EXCEPTION 'supervision: a pass was stored on weekday %', n;
    EXCEPTION WHEN check_violation THEN NULL;
    END;
  END LOOP;
  FOREACH st IN ARRAY ARRAY['10:20|10:20', '10:20|10:00', '10:00:30|10:20', '10:00|10:20:01', '23:00|24:00'] LOOP
    BEGIN
      INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime")
      VALUES (app.current_school_id(), yr, garden, bo, 4, split_part(st, '|', 1)::time, split_part(st, '|', 2)::time);
      RAISE EXCEPTION 'supervision: a pass % was stored', st;
    EXCEPTION WHEN check_violation THEN NULL;
    END;
  END LOOP;
  -- Thursdays both, so the order alone refuses it.
  BEGIN
    INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime", "validFrom", "validTo")
    VALUES (app.current_school_id(), yr, garden, bo, 4, '10:00', '10:20', DATE '2031-01-16', DATE '2031-01-09');
    RAISE EXCEPTION 'supervision: a pass ending before it begins was stored';
  EXCEPTION WHEN check_violation THEN NULL;
  END;
  -- Från and Till on the pass's weekday: a Thursday pass from a Wednesday,
  -- or until a Friday, is not a row; from and until Thursdays it is.
  FOREACH st IN ARRAY ARRAY['2031-01-08|', '|2031-01-10', '2031-01-08|2031-01-16'] LOOP
    BEGIN
      INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime", "validFrom", "validTo")
      VALUES (app.current_school_id(), yr, garden, bo, 4, '10:00', '10:20',
              NULLIF(split_part(st, '|', 1), '')::date, NULLIF(split_part(st, '|', 2), '')::date);
      RAISE EXCEPTION 'supervision: a Thursday pass dated % was stored', st;
    EXCEPTION WHEN check_violation THEN NULL;
    END;
  END LOOP;
  INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime", "validFrom", "validTo")
  VALUES (app.current_school_id(), yr, garden, bo, 4, '10:00', '10:20', DATE '2031-01-09', DATE '2031-01-16') RETURNING id INTO pass;
  DELETE FROM "SupervisionShifts" WHERE id = pass;
  FOREACH st IN ARRAY ARRAY['', ' Norra', 'Norra ', repeat('x', 201)] LOOP
    BEGIN
      INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime", note)
      VALUES (app.current_school_id(), yr, garden, bo, 4, '10:00', '10:20', st);
      RAISE EXCEPTION 'supervision: a pass with the note "%" was stored', left(st, 20);
    EXCEPTION WHEN check_violation THEN NULL;
    END;
  END LOOP;

  -- Another school's area, teacher and year, by their ids: refused by the keys.
  BEGIN
    INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime")
    VALUES (app.current_school_id(), yr, current_setting('app.test_rv_other_area')::uuid, bo, 4, '10:00', '10:20');
    RAISE EXCEPTION 'supervision: a pass was put on another school''s area';
  EXCEPTION WHEN foreign_key_violation THEN NULL;
  END;
  BEGIN
    INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime")
    VALUES (app.current_school_id(), yr, garden, current_setting('app.test_rv_other_teacher')::uuid, 4, '10:00', '10:20');
    RAISE EXCEPTION 'supervision: another school''s teacher was given a pass';
  EXCEPTION WHEN foreign_key_violation THEN NULL;
  END;
  BEGIN
    INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime")
    VALUES (app.current_school_id(), current_setting('app.test_rv_other_year')::uuid, garden, bo, 4, '10:00', '10:20');
    RAISE EXCEPTION 'supervision: a pass was put in another school''s year';
  EXCEPTION WHEN foreign_key_violation THEN NULL;
  END;

  -- One place at a time. Anna watches the yard every Monday 10:00–10:20.
  BEGIN
    INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime")
    VALUES (app.current_school_id(), yr, hall, anna, 1, '10:10', '10:30');
    RAISE EXCEPTION 'supervision: Anna was put in the hall while she watches the yard';
  EXCEPTION WHEN exclusion_violation THEN NULL;
  END;
  -- The minute she leaves the yard she may be in the hall, and on another weekday at the same time.
  INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime")
  VALUES (app.current_school_id(), yr, hall, anna, 1, '10:20', '10:40') RETURNING id INTO pass;
  INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime")
  VALUES (app.current_school_id(), yr, hall, anna, 3, '10:00', '10:20');
  -- Her autumn Tuesdays on the yard: the hall from January is free, December is not.
  INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime", "validFrom")
  VALUES (app.current_school_id(), yr, hall, anna, 2, '10:00', '10:20', DATE '2031-01-07');
  BEGIN
    INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime", "validFrom", "validTo")
    VALUES (app.current_school_id(), yr, hall, anna, 2, '10:00', '10:20', DATE '2030-12-03', DATE '2030-12-31');
    RAISE EXCEPTION 'supervision: Anna was put in the hall on December Tuesdays she watches the yard';
  EXCEPTION WHEN exclusion_violation THEN NULL;
  END;
  -- A pass moved onto another: refused as the insert is.
  BEGIN
    UPDATE "SupervisionShifts" SET "startTime" = '10:15' WHERE id = pass;
    RAISE EXCEPTION 'supervision: a pass was moved onto another of the same teacher';
  EXCEPTION WHEN exclusion_violation THEN NULL;
  END;
  -- Two Friday passes of Bo's that never share a Friday: the yard until
  -- Friday 3 January, the hall from Friday the 10th. With the dates on the
  -- weekday their ranges do not meet; from the 3rd they would.
  INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime", "validTo")
  VALUES (app.current_school_id(), yr, garden, bo, 5, '10:00', '10:20', DATE '2031-01-03');
  INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime", "validFrom")
  VALUES (app.current_school_id(), yr, hall, bo, 5, '10:00', '10:20', DATE '2031-01-10');
  BEGIN
    INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime", "validFrom")
    VALUES (app.current_school_id(), yr, hall, bo, 5, '10:10', '10:30', DATE '2031-01-03');
    RAISE EXCEPTION 'supervision: Bo was put in the hall on a Friday he watches the yard';
  EXCEPTION WHEN exclusion_violation THEN NULL;
  END;
  -- Two teachers on one place at once: what guardsNeeded asks for.
  INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime")
  VALUES (app.current_school_id(), yr, garden, bo, 1, '10:00', '10:20');
  -- Another läsår is another schedule.
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (app.current_school_id(), 'Rastvakt 2031/32', DATE '2031-08-14', DATE '2032-06-11', false, now()) RETURNING id INTO later;
  INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime")
  VALUES (app.current_school_id(), later, hall, anna, 1, '10:00', '10:20');
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 203: ett skolområde som tas bort lämnar sina rastvaktsområden kvar
-- utan skolområde; ett område tar sina pass med sig, och det gör också en
-- lärare och ett läsår (20261207090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002020')::text, true);
DO $$
DECLARE
  n bigint;
  garden uuid;
  later uuid;
  bo uuid;
BEGIN
  SELECT id INTO garden FROM "SupervisionAreas" WHERE name = 'RV Skolgården';
  SELECT id INTO bo FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000002026';

  DELETE FROM "Sites" WHERE name = 'RV Norra';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'supervision: the fixture''s site was not removed (%)', n; END IF;
  SELECT count(*) INTO n FROM "SupervisionAreas" WHERE id = garden AND "siteId" IS NULL;
  IF n <> 1 THEN RAISE EXCEPTION 'supervision: the area on a removed site went with it, or kept the site'; END IF;

  -- The yard goes, and Anna's two passes with it; Bo's in the hall stays.
  DELETE FROM "SupervisionAreas" WHERE id = garden;
  SELECT count(*) INTO n FROM "SupervisionShifts";
  IF n <> 1 OR NOT EXISTS (SELECT 1 FROM "SupervisionShifts" WHERE "userId" = bo) THEN
    RAISE EXCEPTION 'supervision: % passes outlived or went with the yard, not Bo''s one alone', n;
  END IF;

  -- A year removed takes its passes.
  INSERT INTO "AcademicYears" ("schoolId", name, "startDate", "endDate", "isActive", "updatedAt")
  VALUES (app.current_school_id(), 'Rastvakt 2031/32', DATE '2031-08-14', DATE '2032-06-11', false, now()) RETURNING id INTO later;
  INSERT INTO "SupervisionShifts" ("schoolId", "academicYearId", "areaId", "userId", "dayOfWeek", "startTime", "endTime")
  SELECT app.current_school_id(), later, "areaId", bo, 2, '11:00', '11:30' FROM "SupervisionShifts" WHERE "userId" = bo;
  DELETE FROM "AcademicYears" WHERE id = later;
  SELECT count(*) INTO n FROM "SupervisionShifts" WHERE "academicYearId" = later;
  IF n <> 0 THEN RAISE EXCEPTION 'supervision: % passes outlived their year', n; END IF;

  -- Bo removed takes his pass: the hall's break shows unwatched, nobody's pass dangles.
  DELETE FROM "Users" WHERE id = bo;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'supervision: the fixture''s teacher was not removed (%)', n; END IF;
  SELECT count(*) INTO n FROM "SupervisionShifts";
  IF n <> 0 THEN RAISE EXCEPTION 'supervision: % passes outlived their teacher', n; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 210: vikarietavlans beslut om en frånvarande rastvakts pass står i
-- katalogen som migreringen säger (SupervisionCovers, 20261210090000).
--
-- Row security, every arm TO app_authenticated and permissive: the
-- administrators' read, the teacher's read as vikarie and as the absent, each
-- an AND anchored to the caller with no OR, and Drift's three writes, the
-- update asking the area in WITH CHECK alone. PostgREST's authenticated and
-- anon hold nothing, service_role reads and nothing more, the API holds
-- SELECT, INSERT, UPDATE and DELETE and no TRUNCATE, REFERENCES or TRIGGER,
-- and no API role holds MAINTAIN on 17. Each CHECK says what the migration
-- says, a pass has one decision a date, every key is composite with the
-- school and cascades but the decider's, which empties that column alone, the
-- two notice types exist, and the guard on a teacher's own absence asks the
-- pass decisions beside the lessons'.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  r text;
  p text;
  n bigint;
  def text;
BEGIN
  IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = 'public."SupervisionCovers"'::regclass) THEN
    RAISE EXCEPTION 'pass covers: row security is off';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'SupervisionCovers'
               AND (roles <> '{app_authenticated}' OR permissive <> 'PERMISSIVE')) THEN
    RAISE EXCEPTION 'pass covers: an arm for another role than the API''s, or a restrictive one';
  END IF;
  FOREACH r IN ARRAY ARRAY['authenticated', 'anon'] LOOP
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
    FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
      IF has_table_privilege(r, 'public."SupervisionCovers"', p) THEN RAISE EXCEPTION 'pass covers: % holds %', r, p; END IF;
    END LOOP;
  END LOOP;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
    FOREACH p IN ARRAY ARRAY['INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
      IF has_table_privilege('service_role', 'public."SupervisionCovers"', p) THEN RAISE EXCEPTION 'pass covers: service_role holds %', p; END IF;
    END LOOP;
  END IF;
  FOREACH p IN ARRAY ARRAY['SELECT', 'INSERT', 'UPDATE', 'DELETE'] LOOP
    IF NOT has_table_privilege('app_authenticated', 'public."SupervisionCovers"', p) THEN RAISE EXCEPTION 'pass covers: the API lacks %', p; END IF;
  END LOOP;
  FOREACH p IN ARRAY ARRAY['TRUNCATE', 'REFERENCES', 'TRIGGER'] LOOP
    IF has_table_privilege('app_authenticated', 'public."SupervisionCovers"', p) THEN RAISE EXCEPTION 'pass covers: the API holds %', p; END IF;
  END LOOP;
  IF current_setting('server_version_num')::int >= 170000 THEN
    FOREACH r IN ARRAY ARRAY['authenticated', 'app_authenticated', 'service_role', 'anon'] LOOP
      CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r);
      IF has_table_privilege(r, 'public."SupervisionCovers"', 'MAINTAIN') THEN RAISE EXCEPTION 'pass covers: % holds MAINTAIN', r; END IF;
    END LOOP;
  END IF;

  SELECT count(*) INTO n FROM pg_policies WHERE schemaname = 'public' AND tablename = 'SupervisionCovers'
     AND (policyname, cmd) IN (('supervision_covers_admin_select', 'SELECT'), ('supervision_covers_substitute_select', 'SELECT'),
                               ('supervision_covers_absent_select', 'SELECT'), ('supervision_covers_admin_insert', 'INSERT'),
                               ('supervision_covers_admin_update', 'UPDATE'), ('supervision_covers_admin_delete', 'DELETE'));
  IF n <> 6 OR (SELECT count(*) FROM pg_policies WHERE tablename = 'SupervisionCovers') <> 6 THEN
    RAISE EXCEPTION 'pass covers: not exactly the three reads and Drift''s three writes';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'supervision_covers_admin_select'
                   AND qual LIKE '%''SCHOOL_ADMIN''%' AND qual NOT LIKE '%TEACHER%' AND qual LIKE '%current_school_id()%'
                   AND qual NOT LIKE '% OR %')
     OR NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'supervision_covers_substitute_select'
                   AND qual LIKE '%''TEACHER''%' AND qual NOT LIKE '%SCHOOL_ADMIN%' AND qual LIKE '%current_school_id()%'
                   AND qual LIKE '%("substituteId" = ( SELECT app.current_user_id() AS current_user_id))%' AND qual NOT LIKE '% OR %')
     OR NOT EXISTS (SELECT 1 FROM pg_policies WHERE policyname = 'supervision_covers_absent_select'
                   AND qual LIKE '%''TEACHER''%' AND qual NOT LIKE '%SCHOOL_ADMIN%' AND qual LIKE '%current_school_id()%'
                   AND qual LIKE '%("absentTeacherId" = ( SELECT app.current_user_id() AS current_user_id))%' AND qual NOT LIKE '% OR %') THEN
    RAISE EXCEPTION 'pass covers: the reads are not the administrators'', the vikarie''s own and the absent teacher''s own';
  END IF;
  IF (SELECT count(*) FROM pg_policies WHERE tablename = 'SupervisionCovers' AND cmd IN ('INSERT', 'UPDATE', 'DELETE')
        AND coalesce(with_check, qual) LIKE '%current_user_may(''DRIFT''%'
        AND coalesce(with_check, qual) LIKE '%SCHOOL_ADMIN%' AND coalesce(with_check, qual) LIKE '%current_school_id()%') <> 3
     OR EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'SupervisionCovers' AND cmd = 'UPDATE' AND qual LIKE '%current_user_may%') THEN
    RAISE EXCEPTION 'pass covers: the writes are not Drift''s three, with the update asking in WITH CHECK alone';
  END IF;

  FOR def IN SELECT unnest(ARRAY[
      'SupervisionCovers_window_is_ordered|"endsAt" > "startsAt"|"endsAt" > "startsAt"',
      'SupervisionCovers_substitute_iff_substitute|''SUBSTITUTE''|"substituteId" IS NOT NULL',
      'SupervisionCovers_substitute_is_not_the_absent|"substituteId" <> "absentTeacherId"|"substituteId" IS NULL'])
  LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = split_part(def, '|', 1) AND contype = 'c' AND convalidated
                     AND pg_get_constraintdef(oid) ILIKE '%' || split_part(def, '|', 2) || '%'
                     AND pg_get_constraintdef(oid) ILIKE '%' || split_part(def, '|', 3) || '%') THEN
      RAISE EXCEPTION 'pass covers: the check % is missing or says something else', split_part(def, '|', 1);
    END IF;
  END LOOP;
  IF NOT EXISTS (SELECT 1 FROM pg_indexes WHERE tablename = 'SupervisionCovers' AND indexname = 'SupervisionCovers_shiftId_date_key'
                   AND indexdef LIKE 'CREATE UNIQUE INDEX%("shiftId", date)') THEN
    RAISE EXCEPTION 'pass covers: a pass may hold more than one decision a date';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_indexes WHERE tablename = 'SupervisionShifts' AND indexname = 'SupervisionShifts_id_schoolId_key'
                   AND indexdef LIKE 'CREATE UNIQUE INDEX%(id, "schoolId")') THEN
    RAISE EXCEPTION 'pass covers: the pass has no (id, schoolId) key for the decision''s';
  END IF;

  -- The keys: composite with the school, ON UPDATE NO ACTION, ON DELETE CASCADE.
  FOR def IN SELECT unnest(ARRAY[
      'SupervisionShifts|shiftId,schoolId|id,schoolId',
      'SupervisionAreas|areaId,schoolId|id,schoolId',
      'TeacherAbsences|absenceId,absentTeacherId,schoolId|id,userId,schoolId',
      'Users|substituteId,schoolId|id,schoolId'])
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_constraint c
       WHERE c.contype = 'f' AND c.conrelid = 'public."SupervisionCovers"'::regclass
         AND c.confrelid = format('public.%I', split_part(def, '|', 1))::regclass
         AND c.confupdtype = 'a' AND c.confdeltype = 'c' AND c.convalidated
         AND (SELECT string_agg(a.attname::text, ',' ORDER BY k.ord) FROM unnest(c.conkey) WITH ORDINALITY k(attnum, ord)
                JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum) = split_part(def, '|', 2)
         AND (SELECT string_agg(a.attname::text, ',' ORDER BY k.ord) FROM unnest(c.confkey) WITH ORDINALITY k(attnum, ord)
                JOIN pg_attribute a ON a.attrelid = c.confrelid AND a.attnum = k.attnum) = split_part(def, '|', 3)) THEN
      RAISE EXCEPTION 'pass covers: the key % is not as the migration writes it', def;
    END IF;
  END LOOP;
  -- The decider: a person of the school, whose removal keeps the decision.
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
     WHERE c.contype = 'f' AND c.conrelid = 'public."SupervisionCovers"'::regclass
       AND c.confrelid = 'public."Users"'::regclass
       AND c.confupdtype = 'a' AND c.confdeltype = 'n' AND c.convalidated
       AND (SELECT string_agg(a.attname::text, ',' ORDER BY k.ord) FROM unnest(c.conkey) WITH ORDINALITY k(attnum, ord)
              JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum) = 'decidedByUserId,schoolId'
       AND (SELECT string_agg(a.attname::text, ',') FROM unnest(c.confdelsetcols) k(attnum)
              JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum) = 'decidedByUserId') THEN
    RAISE EXCEPTION 'pass covers: the decider is not keyed to a person of the school, emptied on their removal';
  END IF;

  IF (SELECT count(*) FROM pg_enum e JOIN pg_type t ON t.oid = e.enumtypid
       WHERE t.typname = 'NotificationType' AND e.enumlabel IN ('SUPERVISION_COVER', 'SUPERVISION_COVER_WITHDRAWN')) <> 2 THEN
    RAISE EXCEPTION 'pass covers: the notice types are missing';
  END IF;

  -- The guard on a teacher's own absence (20261012130000) asks both kinds of
  -- decision, in the early end and in the withdrawal, and is the trigger's.
  SELECT p.prosrc INTO def FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
   WHERE ns.nspname = 'app' AND p.proname = 'teacher_absences_own_writes_are_narrow' AND p.prosecdef;
  IF def IS NULL
     OR (length(def) - length(replace(def, 'FROM "SupervisionCovers" s', ''))) / length('FROM "SupervisionCovers" s') <> 2
     OR (length(def) - length(replace(def, 'FROM "TeacherAbsenceCovers" c', ''))) / length('FROM "TeacherAbsenceCovers" c') <> 2
     OR def NOT LIKE '%NOT (s."startsAt" < NEW."endsAt" AND s."endsAt" > NEW."startsAt")%' THEN
    RAISE EXCEPTION 'pass covers: the guard on a teacher''s own absence does not ask the pass decisions beside the lessons''';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'TeacherAbsences_own_writes_are_narrow'
                   AND tgrelid = 'public."TeacherAbsences"'::regclass AND tgenabled = 'O') THEN
    RAISE EXCEPTION 'pass covers: the guard''s trigger is gone or off';
  END IF;
  IF has_function_privilege('app_authenticated', 'app.teacher_absences_own_writes_are_narrow()', 'EXECUTE') THEN
    RAISE EXCEPTION 'pass covers: the API may call the guard';
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Section 211: skolans administratörer läser varje beslut om ett pass, den
-- som skriver Drift skriver dem, och expeditionen gör det; en lärare läser
-- bara de beslut där hen är vikarie eller den frånvarande; elev,
-- vårdnadshavare, tjänsten och synken läser inget; en annan skolas
-- administratör når inget här; PostgREST:s roll når inget ens med
-- administratörens anspråk (20261210090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002025')::text, true);
SELECT set_config('app.test_pc_other', app.current_school_id()::text, true);
SELECT set_config('app.test_pc_other_cover', (SELECT min(id::text) FROM "SupervisionCovers"), true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002020')::text, true);
SELECT set_config('app.test_pc_school', app.current_school_id()::text, true);
DO $$
DECLARE
  n bigint;
  who text;
  anna uuid;
  bo uuid;
  annas uuid;
  bos uuid;
  pass uuid;
  garden uuid;
  absence uuid;
  ny uuid;
BEGIN
  IF coalesce(current_setting('app.test_pc_school', true), '') = '' OR coalesce(current_setting('app.test_pc_other_cover', true), '') = '' THEN
    RAISE EXCEPTION 'pass covers: a fixture admin read no school, or the other school''s admin none of its decisions';
  END IF;
  SELECT count(*) INTO n FROM "SupervisionCovers";
  IF n <> 2 THEN RAISE EXCEPTION 'pass covers: the admin reads % decisions, not the school''s two', n; END IF;
  SELECT id INTO anna FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000002021';
  SELECT id INTO bo FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000002026';
  SELECT id, "shiftId", "areaId", "absenceId" INTO annas, pass, garden, absence FROM "SupervisionCovers" WHERE "absentTeacherId" = anna;
  SELECT id INTO bos FROM "SupervisionCovers" WHERE "absentTeacherId" = bo;

  -- Drift writes: a decision on the next Monday, changed, removed.
  INSERT INTO "SupervisionCovers" ("schoolId", "shiftId", date, "areaId", "startsAt", "endsAt", "absenceId", "absentTeacherId", decision)
  VALUES (app.current_school_id(), pass, DATE '2030-09-16', garden, timestamptz '2030-09-16 08:00 UTC', timestamptz '2030-09-16 08:20 UTC',
          absence, anna, 'NO_COVER')
  RETURNING id INTO ny;
  UPDATE "SupervisionCovers" SET decision = 'SUBSTITUTE', "substituteId" = bo WHERE id = ny;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'pass covers: the admin changed % of the school''s decisions', n; END IF;
  DELETE FROM "SupervisionCovers" WHERE id = ny;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'pass covers: the admin removed % of the school''s decisions', n; END IF;

  -- Another school's decision: not seen, not changed, not removed, not written into.
  UPDATE "SupervisionCovers" SET "decidedAt" = now() WHERE id = current_setting('app.test_pc_other_cover')::uuid;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'pass covers: the admin changed another school''s decision'; END IF;
  DELETE FROM "SupervisionCovers" WHERE id = current_setting('app.test_pc_other_cover')::uuid;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN RAISE EXCEPTION 'pass covers: the admin removed another school''s decision'; END IF;
  BEGIN
    UPDATE "SupervisionCovers" SET "schoolId" = current_setting('app.test_pc_other')::uuid WHERE id = annas;
    RAISE EXCEPTION 'pass covers: the admin moved a decision into another school';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;

  -- The expedition writes Drift: it reads the two and changes one.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002024')::text, true);
  SELECT count(*) INTO n FROM "SupervisionCovers";
  IF n <> 2 THEN RAISE EXCEPTION 'pass covers: the expedition reads % decisions, not the school''s two', n; END IF;
  UPDATE "SupervisionCovers" SET "decidedAt" = now() WHERE id = bos;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'pass covers: the expedition changed % decisions', n; END IF;

  -- Anna reads the decision on her absence, not Bo's; Bo reads the one he
  -- is the vikarie of and the one on his own absence. Neither writes.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002021')::text, true);
  IF (SELECT count(*) FROM "SupervisionCovers") <> 1 OR NOT EXISTS (SELECT 1 FROM "SupervisionCovers" WHERE id = annas) THEN
    RAISE EXCEPTION 'pass covers: the absent teacher reads % decisions, not the one on her absence', (SELECT count(*) FROM "SupervisionCovers");
  END IF;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002026')::text, true);
  IF (SELECT count(*) FROM "SupervisionCovers") <> 2 THEN
    RAISE EXCEPTION 'pass covers: the vikarie reads % decisions, not his as vikarie and his as the absent', (SELECT count(*) FROM "SupervisionCovers");
  END IF;
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000002021', '00000000-0000-4000-8000-000000002026'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    UPDATE "SupervisionCovers" SET "decidedAt" = now();
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 0 THEN RAISE EXCEPTION 'pass covers: teacher % changed % decisions', who, n; END IF;
    DELETE FROM "SupervisionCovers";
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n <> 0 THEN RAISE EXCEPTION 'pass covers: teacher % removed % decisions', who, n; END IF;
    BEGIN
      INSERT INTO "SupervisionCovers" ("schoolId", "shiftId", date, "areaId", "startsAt", "endsAt", "absenceId", "absentTeacherId", decision)
      VALUES (app.current_school_id(), pass, DATE '2030-09-23', garden, timestamptz '2030-09-23 08:00 UTC', timestamptz '2030-09-23 08:20 UTC',
              absence, anna, 'NO_COVER');
      RAISE EXCEPTION 'pass covers: teacher % wrote a decision', who;
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
  END LOOP;

  -- The other school's teacher, absent there: their own decision, none here.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002027')::text, true);
  IF (SELECT count(*) FROM "SupervisionCovers") <> 1 OR EXISTS (SELECT 1 FROM "SupervisionCovers" WHERE "schoolId" = current_setting('app.test_pc_school')::uuid) THEN
    RAISE EXCEPTION 'pass covers: the other school''s teacher reads % decisions, not her own alone', (SELECT count(*) FROM "SupervisionCovers");
  END IF;

  -- Pupil and guardian: nothing read, nothing written.
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000002022', '00000000-0000-4000-8000-000000002023'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    SELECT count(*) INTO n FROM "SupervisionCovers";
    IF n <> 0 THEN RAISE EXCEPTION 'pass covers: % (%) reads % decisions', who, app.current_user_role(), n; END IF;
    BEGIN
      INSERT INTO "SupervisionCovers" ("schoolId", "shiftId", date, "areaId", "startsAt", "endsAt", "absenceId", "absentTeacherId", decision)
      VALUES (app.current_school_id(), pass, DATE '2030-09-23', garden, timestamptz '2030-09-23 08:00 UTC', timestamptz '2030-09-23 08:20 UTC',
              absence, anna, 'NO_COVER');
      RAISE EXCEPTION 'pass covers: % wrote a decision', who;
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
  END LOOP;

  -- The service and the sync principal of the school: nothing.
  PERFORM set_config('request.jwt.claims', '', true);
  FOREACH who IN ARRAY ARRAY['app.service_school_id', 'app.sync_school_id'] LOOP
    PERFORM set_config(who, current_setting('app.test_pc_school'), true);
    SELECT count(*) INTO n FROM "SupervisionCovers";
    IF n <> 0 THEN RAISE EXCEPTION 'pass covers: % reads % decisions', who, n; END IF;
    PERFORM set_config(who, '', true);
  END LOOP;
END $$;

-- PostgREST's role, with the admin's claims: nothing at all.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002020')::text, true);
SET LOCAL ROLE authenticated;
DO $$
BEGIN
  IF current_user <> 'authenticated' THEN RAISE EXCEPTION 'pass covers: could not act as authenticated'; END IF;
  BEGIN
    PERFORM 1 FROM "SupervisionCovers";
    RAISE EXCEPTION 'pass covers: PostgREST''s role reads the decisions';
  EXCEPTION WHEN insufficient_privilege THEN NULL;
  END;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 212: ett beslut håller sina gränser — en vikarie bara för
-- SUBSTITUTE och aldrig den frånvarande, ett slut efter starten, ett beslut
-- om dagen per pass — och hör till sin skolas pass, område, frånvaro med dess
-- person och vikarie; passet, området och frånvaron tar sina beslut med sig
-- (20261210090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002025')::text, true);
SELECT set_config('app.test_pc_other_pass', (SELECT min(id::text) FROM "SupervisionShifts"), true);
SELECT set_config('app.test_pc_other_area', (SELECT min(id::text) FROM "SupervisionAreas"), true);
SELECT set_config('app.test_pc_other_absence', (SELECT min(id::text) FROM "TeacherAbsences" WHERE "startsAt" = timestamptz '2030-09-01 22:00 UTC'), true);
SELECT set_config('app.test_pc_other_teacher', (SELECT id::text FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000002027'), true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002020')::text, true);
CREATE OR REPLACE FUNCTION pg_temp.pc_refused(label text, stmt text, expected text) RETURNS void
LANGUAGE plpgsql AS $$
BEGIN
  BEGIN
    EXECUTE stmt;
  EXCEPTION
    WHEN check_violation THEN
      IF expected <> 'check' THEN RAISE EXCEPTION 'pass covers: % met a CHECK, not %: %', label, expected, SQLERRM USING ERRCODE = 'P0001'; END IF;
      RETURN;
    WHEN unique_violation THEN
      IF expected <> 'unique' THEN RAISE EXCEPTION 'pass covers: % met a key, not %: %', label, expected, SQLERRM USING ERRCODE = 'P0001'; END IF;
      RETURN;
    WHEN foreign_key_violation THEN
      IF expected <> 'foreign' THEN RAISE EXCEPTION 'pass covers: % met a foreign key, not %: %', label, expected, SQLERRM USING ERRCODE = 'P0001'; END IF;
      RETURN;
  END;
  RAISE EXCEPTION 'pass covers: % was let through', label USING ERRCODE = 'P0001';
END $$;
DO $$
DECLARE
  n bigint;
  anna uuid;
  bo uuid;
  pass uuid;
  garden uuid;
  absence uuid;
  bos_absence uuid;
  values_of text;
BEGIN
  SELECT id INTO anna FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000002021';
  SELECT id INTO bo FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000002026';
  SELECT "shiftId", "areaId", "absenceId" INTO pass, garden, absence FROM "SupervisionCovers" WHERE "absentTeacherId" = anna;
  SELECT "absenceId" INTO bos_absence FROM "SupervisionCovers" WHERE "absentTeacherId" = bo;
  -- A fresh Monday's row, and every column the statements vary.
  values_of := format('INSERT INTO "SupervisionCovers" ("schoolId", "shiftId", date, "areaId", "startsAt", "endsAt", "absenceId", "absentTeacherId", decision, "substituteId") '
                      'VALUES (%L, %%s, DATE %%L, %%s, %%L, %%L, %%s, %%s, %%L, %%s)', app.current_school_id());

  PERFORM pg_temp.pc_refused('a vikarie for NO_COVER',
    format(values_of, quote_literal(pass), '2030-09-16', quote_literal(garden), '2030-09-16 08:00Z', '2030-09-16 08:20Z',
           quote_literal(absence), quote_literal(anna), 'NO_COVER', quote_literal(bo)), 'check');
  PERFORM pg_temp.pc_refused('SUBSTITUTE without a vikarie',
    format(values_of, quote_literal(pass), '2030-09-16', quote_literal(garden), '2030-09-16 08:00Z', '2030-09-16 08:20Z',
           quote_literal(absence), quote_literal(anna), 'SUBSTITUTE', 'NULL'), 'check');
  PERFORM pg_temp.pc_refused('the absent teacher as her own vikarie',
    format(values_of, quote_literal(pass), '2030-09-16', quote_literal(garden), '2030-09-16 08:00Z', '2030-09-16 08:20Z',
           quote_literal(absence), quote_literal(anna), 'SUBSTITUTE', quote_literal(anna)), 'check');
  PERFORM pg_temp.pc_refused('an end not after the start',
    format(values_of, quote_literal(pass), '2030-09-16', quote_literal(garden), '2030-09-16 08:20Z', '2030-09-16 08:20Z',
           quote_literal(absence), quote_literal(anna), 'NO_COVER', 'NULL'), 'check');
  PERFORM pg_temp.pc_refused('a second decision on the pass that day',
    format(values_of, quote_literal(pass), '2030-09-02', quote_literal(garden), '2030-09-02 08:00Z', '2030-09-02 08:20Z',
           quote_literal(absence), quote_literal(anna), 'NO_COVER', 'NULL'), 'unique');
  PERFORM pg_temp.pc_refused('an absence of another person than the one named',
    format(values_of, quote_literal(pass), '2030-09-16', quote_literal(garden), '2030-09-16 08:00Z', '2030-09-16 08:20Z',
           quote_literal(bos_absence), quote_literal(anna), 'NO_COVER', 'NULL'), 'foreign');
  PERFORM pg_temp.pc_refused('another school''s pass',
    format(values_of, quote_literal(current_setting('app.test_pc_other_pass')), '2030-09-16', quote_literal(garden), '2030-09-16 08:00Z',
           '2030-09-16 08:20Z', quote_literal(absence), quote_literal(anna), 'NO_COVER', 'NULL'), 'foreign');
  PERFORM pg_temp.pc_refused('another school''s area',
    format(values_of, quote_literal(pass), '2030-09-16', quote_literal(current_setting('app.test_pc_other_area')), '2030-09-16 08:00Z',
           '2030-09-16 08:20Z', quote_literal(absence), quote_literal(anna), 'NO_COVER', 'NULL'), 'foreign');
  PERFORM pg_temp.pc_refused('another school''s absence',
    format(values_of, quote_literal(pass), '2030-09-16', quote_literal(garden), '2030-09-16 08:00Z', '2030-09-16 08:20Z',
           quote_literal(current_setting('app.test_pc_other_absence')), quote_literal(current_setting('app.test_pc_other_teacher')),
           'NO_COVER', 'NULL'), 'foreign');
  PERFORM pg_temp.pc_refused('another school''s vikarie',
    format(values_of, quote_literal(pass), '2030-09-16', quote_literal(garden), '2030-09-16 08:00Z', '2030-09-16 08:20Z',
           quote_literal(absence), quote_literal(anna), 'SUBSTITUTE', quote_literal(current_setting('app.test_pc_other_teacher'))), 'foreign');

  -- The pass removed takes its decision; so do the absence and the area.
  DELETE FROM "SupervisionShifts" WHERE id = pass;
  SELECT count(*) INTO n FROM "SupervisionCovers" WHERE "shiftId" = pass;
  IF n <> 0 THEN RAISE EXCEPTION 'pass covers: % decisions outlived their pass', n; END IF;
  DELETE FROM "TeacherAbsences" WHERE id = bos_absence;
  SELECT count(*) INTO n FROM "SupervisionCovers";
  IF n <> 0 THEN RAISE EXCEPTION 'pass covers: % decisions outlived their absence', n; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 213: en lärares egen frånvaro går inte förbi ett beslut om ett pass
-- (20261012130000, utvidgad i 20261210090000): Anna kan inte återkalla en
-- frånvaro som ett pass har ett beslut på, inte avsluta den före ett beslutat
-- pass som ligger framför, men väl efter det; utan beslut återkallar hon den.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002020')::text, true);
INSERT INTO "CoverSettings" ("schoolId", "teacherSelfReport") VALUES (app.current_school_id(), true)
ON CONFLICT ("schoolId") DO UPDATE SET "teacherSelfReport" = true;
SELECT set_config('app.test_pc_absence',
  (SELECT "absenceId"::text FROM "SupervisionCovers" WHERE "absentTeacherId" =
     (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000002021')), true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002021')::text, true);
DO $$
DECLARE
  own uuid := current_setting('app.test_pc_absence')::uuid;
  n bigint;
BEGIN
  IF app.current_user_role() IS DISTINCT FROM 'TEACHER' THEN RAISE EXCEPTION 'pass covers: expected Anna, a TEACHER'; END IF;
  BEGIN
    UPDATE "TeacherAbsences" SET status = 'WITHDRAWN', "withdrawnAt" = now(), "withdrawnByUserId" = app.current_user_id() WHERE id = own;
    RAISE EXCEPTION 'pass covers: a teacher withdrew an absence a pass decision references';
  EXCEPTION WHEN SQLSTATE 'TA403' THEN NULL;
  END;
  -- The decided pass runs 08:00–08:20 UTC on the 2nd: ending at 07:00 leaves it outside.
  BEGIN
    UPDATE "TeacherAbsences" SET "endsAt" = timestamptz '2030-09-02 07:00 UTC' WHERE id = own;
    RAISE EXCEPTION 'pass covers: a teacher ended an absence before a decided pass still ahead';
  EXCEPTION WHEN SQLSTATE 'TA403' THEN NULL;
  END;
  UPDATE "TeacherAbsences" SET "endsAt" = timestamptz '2030-09-02 12:00 UTC' WHERE id = own;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'pass covers: a teacher could not end early with the decided pass still inside'; END IF;
END $$;
-- The board undoes its decision; then the withdrawal is hers.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002020')::text, true);
DELETE FROM "SupervisionCovers" WHERE "absenceId" = current_setting('app.test_pc_absence')::uuid;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000002021')::text, true);
DO $$
DECLARE n bigint;
BEGIN
  UPDATE "TeacherAbsences" SET status = 'WITHDRAWN', "withdrawnAt" = now(), "withdrawnByUserId" = app.current_user_id()
   WHERE id = current_setting('app.test_pc_absence')::uuid;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN RAISE EXCEPTION 'pass covers: a teacher could not withdraw an absence nothing references any more'; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 250: en elev i en tillagd undervisningsgrupp, katalogen
-- (20261208090000): elevens två armar är vidgade som migreringen skrev dem,
-- för authenticated som förut, och ingen annan arm frågar elevens hjälpare;
-- hjälparna SECURITY DEFINER, STABLE, med fäst search_path, körbara av
-- authenticated och app_authenticated och av ingen annan. Sedan
-- 20261211090000 (Ersättande grupper) frågar också elevens hem- och
-- undervisningsgruppsarm en current_student_-hjälpare, och participant-armen
-- bär efter sitt predikat den avsmalning den migreringen skrev; avsnitt 270
-- prövar den.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  bad text;
  r text;
  fn text;
  -- The member arm's groups: a pupil's teaching groups and home class, the
  -- old one group for every other role. Here and in the participant arm's
  -- branch the role is asked inside the initplan, so that for staff no
  -- helper runs (20261208090000, "Why these shapes").
  groups constant text := '( SELECT CASE WHEN (app.current_user_role() = ''STUDENT''::"UserRole") '
                          'THEN (app.current_student_teaching_group_ids() || app.current_user_group_id()) '
                          'ELSE ARRAY[app.current_user_group_id()] END AS "array")::uuid[]';
BEGIN
  -- qual names functions relative to the search_path; read it as the migration's guard does.
  PERFORM set_config('search_path', 'public, pg_temp', true);
  SELECT string_agg(tablename || '.' || policyname || ' ' || cmd || ' ' || permissive || ' ' || roles::text, ', ' ORDER BY tablename, policyname)
    INTO bad
    FROM pg_policies
   WHERE schemaname = 'public' AND (coalesce(qual, '') || coalesce(with_check, '')) LIKE '%current\_student\_%';
  IF bad IS DISTINCT FROM 'CalendarLessonGroups.calendar_lesson_groups_member_select SELECT PERMISSIVE {authenticated}, '
                          'CalendarLessons.calendar_lessons_participant_select SELECT PERMISSIVE {authenticated}, '
                          'CalendarLessons.calendar_lessons_student_select SELECT PERMISSIVE {authenticated}, '
                          'CalendarLessons.calendar_lessons_teaching_group_select SELECT PERMISSIVE {authenticated}' THEN
    RAISE EXCEPTION 'joined group: the arms that ask a current_student_ helper are %', bad;
  END IF;
  IF (SELECT regexp_replace(qual, '\s+', ' ', 'g') FROM pg_policies
       WHERE schemaname = 'public' AND tablename = 'CalendarLessons' AND policyname = 'calendar_lessons_participant_select')
     IS DISTINCT FROM '(("schoolId" = ( SELECT app.current_school_id() AS current_school_id)) AND ((EXISTS ( SELECT 1 FROM "CalendarLessonStudents" cls '
                      'WHERE ((cls."calendarLessonId" = "CalendarLessons".id) AND (cls."studentId" = ( SELECT app.current_user_id() AS current_user_id))))) '
                      'OR (EXISTS ( SELECT 1 FROM "CalendarLessonGroups" clg WHERE ((clg."calendarLessonId" = "CalendarLessons".id) '
                      'AND (clg."studentGroupId" = ( SELECT app.current_user_group_id() AS current_user_group_id))))) '
                      'OR (id = ANY (( SELECT CASE WHEN (app.current_user_role() = ''STUDENT''::"UserRole") THEN app.current_student_joined_lesson_ids() '
                      'ELSE NULL::uuid[] END AS "case")::uuid[]))) '
                      'AND (NOT (id = ANY (( SELECT CASE WHEN (app.current_user_role() = ''STUDENT''::"UserRole") THEN app.current_student_replaced_lesson_ids() '
                      'ELSE ''{}''::uuid[] END AS "case")::uuid[]))))' THEN
    RAISE EXCEPTION 'joined group: calendar_lessons_participant_select is not as 20261208090000 and 20261211090000 wrote it';
  END IF;
  IF (SELECT regexp_replace(qual, '\s+', ' ', 'g') FROM pg_policies
       WHERE schemaname = 'public' AND tablename = 'CalendarLessonGroups' AND policyname = 'calendar_lesson_groups_member_select')
     IS DISTINCT FROM '(("schoolId" = ( SELECT app.current_school_id() AS current_school_id)) AND ("studentGroupId" = ANY (' || groups || ')))' THEN
    RAISE EXCEPTION 'joined group: calendar_lesson_groups_member_select is not as 20261208090000 wrote it';
  END IF;

  FOREACH fn IN ARRAY ARRAY['app.current_student_teaching_group_ids()', 'app.current_student_joined_lesson_ids()'] LOOP
    IF NOT (SELECT prosecdef FROM pg_proc WHERE oid = fn::regprocedure) THEN RAISE EXCEPTION 'joined group: % is not SECURITY DEFINER', fn; END IF;
    IF (SELECT provolatile FROM pg_proc WHERE oid = fn::regprocedure) <> 's' THEN RAISE EXCEPTION 'joined group: % is not STABLE', fn; END IF;
    IF (SELECT proconfig FROM pg_proc WHERE oid = fn::regprocedure) IS DISTINCT FROM ARRAY['search_path=public, pg_temp'] THEN
      RAISE EXCEPTION 'joined group: % does not pin its search_path', fn;
    END IF;
    -- A policy runs as whoever reads: both roles the arms answer call it.
    FOREACH r IN ARRAY ARRAY['authenticated', 'app_authenticated'] LOOP
      IF NOT has_function_privilege(r, fn, 'EXECUTE') THEN RAISE EXCEPTION 'joined group: % may not call %', r, fn; END IF;
    END LOOP;
    FOREACH r IN ARRAY ARRAY['anon', 'service_role'] LOOP
      IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) AND has_function_privilege(r, fn, 'EXECUTE') THEN
        RAISE EXCEPTION 'joined group: % may call %', r, fn;
      END IF;
    END LOOP;
    IF (SELECT proacl::text FROM pg_proc WHERE oid = fn::regprocedure) ~ '[{,]=X/' THEN
      RAISE EXCEPTION 'joined group: PUBLIC may call %', fn;
    END IF;
  END LOOP;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 251: en elev i SvA7, som är tillagd till 7B:s svenska, läser
-- lektionen, dess SvA7-rad och dess logg, som PostgREST:s roll och som
-- API:ts; en elev i ingen av grupperna gör det inte, inte en elev som slutat,
-- och inte en annan skolas elev, också när en rad i hens skola pekar över
-- skolgränsen; ett medlemskap från förra läsåret räknas, som för
-- vårdnadshavaren; en inloggning med en rad på varje skola läser den skola
-- anropet namnger (inställningen eller huvudet), annars den äldsta raden;
-- vårdnadshavarna läser som förut, och en som står i SvA7 av misstag läser
-- ingenting av det (20261208090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001400')::text, true);
SELECT set_config('app.test_tg_school', app.current_school_id()::text, true);
SELECT set_config('app.test_tg_sva', (SELECT id::text FROM "StudentGroups" WHERE name = 'TG SvA7'), true);
SELECT set_config('app.test_tg_spa', (SELECT id::text FROM "StudentGroups" WHERE name = 'TG Spanska'), true);
SELECT set_config('app.test_tg_sva6', (SELECT id::text FROM "StudentGroups" WHERE name = 'TG SvA6'), true);
SELECT set_config('app.test_tg_l0', (SELECT id::text FROM "CalendarLessons" WHERE note = 'TG-0'), true);
SELECT set_config('app.test_tg_l1', (SELECT id::text FROM "CalendarLessons" WHERE note = 'TG-1'), true);
SELECT set_config('app.test_tg_l2', (SELECT id::text FROM "CalendarLessons" WHERE note = 'TG-2'), true);
SELECT set_config('app.test_tg_l3', (SELECT id::text FROM "CalendarLessons" WHERE note = 'TG-3'), true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001409')::text, true);
SELECT set_config('app.test_tg_school9', app.current_school_id()::text, true);
SELECT set_config('app.test_tg_sva9', (SELECT id::text FROM "StudentGroups" WHERE name = 'Annan TG SvA7'), true);
SELECT set_config('app.test_tg_l9', (SELECT id::text FROM "CalendarLessons" WHERE note = 'TG-9'), true);
-- What the caller reads of this section's rows, as one line: the lessons, the
-- extra-group rows as lesson/group, the logs (as the API only: LessonLogs has
-- no arm for PostgREST's role) and the helpers' teaching groups/joined
-- lessons. A row without a name
-- of this section shows as its id, so any leak fails the comparison.
CREATE FUNCTION pg_temp.tg_reads(api boolean) RETURNS text LANGUAGE plpgsql AS $f$
DECLARE
  lessons text;
  groups text;
  logs text := '';
  helper text;
BEGIN
  SELECT coalesce(string_agg(coalesce(note, id::text), ',' ORDER BY coalesce(note, id::text)), '') INTO lessons FROM "CalendarLessons";
  SELECT coalesce(string_agg(lbl, ',' ORDER BY lbl), '') INTO groups
    FROM (SELECT CASE g."calendarLessonId"::text
                   WHEN current_setting('app.test_tg_l0') THEN 'TG-0' WHEN current_setting('app.test_tg_l1') THEN 'TG-1'
                   WHEN current_setting('app.test_tg_l2') THEN 'TG-2' WHEN current_setting('app.test_tg_l3') THEN 'TG-3'
                   WHEN current_setting('app.test_tg_l9') THEN 'TG-9' ELSE g."calendarLessonId"::text END
                 || '/' ||
                 CASE g."studentGroupId"::text
                   WHEN current_setting('app.test_tg_sva') THEN 'SvA7' WHEN current_setting('app.test_tg_spa') THEN 'Spanska'
                   WHEN current_setting('app.test_tg_sva6') THEN 'SvA6' WHEN current_setting('app.test_tg_sva9') THEN 'SvA7 annan'
                   ELSE g."studentGroupId"::text END AS lbl
            FROM "CalendarLessonGroups" g) x;
  IF api THEN
    SELECT coalesce(string_agg(coalesce(topic, "calendarLessonId"::text), ',' ORDER BY coalesce(topic, "calendarLessonId"::text)), '')
      INTO logs FROM "LessonLogs";
  END IF;
  SELECT coalesce(string_agg(lbl, ',' ORDER BY lbl), '') || '/' INTO helper
    FROM (SELECT CASE t::text WHEN current_setting('app.test_tg_sva') THEN 'SvA7' WHEN current_setting('app.test_tg_sva6') THEN 'SvA6'
                              WHEN current_setting('app.test_tg_sva9') THEN 'SvA7 annan' ELSE t::text END AS lbl
            FROM unnest(app.current_student_teaching_group_ids()) t) h;
  SELECT helper || coalesce(string_agg(lbl, ',' ORDER BY lbl), '') INTO helper
    FROM (SELECT CASE l::text WHEN current_setting('app.test_tg_l0') THEN 'TG-0' WHEN current_setting('app.test_tg_l1') THEN 'TG-1'
                              WHEN current_setting('app.test_tg_l2') THEN 'TG-2' WHEN current_setting('app.test_tg_l9') THEN 'TG-9'
                              ELSE l::text END AS lbl
            FROM unnest(app.current_student_joined_lesson_ids()) l) j;
  RETURN lessons || ' | ' || groups || ' | ' || logs || ' | ' || helper;
END
$f$;
GRANT EXECUTE ON FUNCTION pg_temp.tg_reads(boolean) TO PUBLIC;
DO $$
DECLARE
  via text;
  i int;
  seen text;
  expected text;
  cases constant text[][] := ARRAY[
    -- authId; what they read as the API (app_authenticated) and as PostgREST
    -- (authenticated): lessons | extra groups | logs (the API's) | helpers.
    ['00000000-0000-4000-8000-000000001402', 'TG-1 | TG-1/SvA7 | TG ett | SvA7/TG-1', 'TG-1 | TG-1/SvA7 |  | SvA7/TG-1'],                 -- P1: 7A, in SvA7
    ['00000000-0000-4000-8000-000000001403', ' |  |  | /', ' |  |  | /'],                                                           -- P2: 7A, in no group
    ['00000000-0000-4000-8000-000000001404', 'TG-1,TG-2,TG-3 |  | TG ett | /', 'TG-1,TG-2,TG-3 |  |  | /'],                     -- P3: 7B
    ['00000000-0000-4000-8000-000000001413', ' |  |  | /', ' |  |  | /'],                                                           -- P6: in SvA7, deactivated
    ['00000000-0000-4000-8000-000000001411', 'TG-0 | TG-0/SvA6 | TG noll | SvA6/TG-0', 'TG-0 | TG-0/SvA6 |  | SvA6/TG-0'],             -- P5: in last year's SvA6
    ['00000000-0000-4000-8000-000000001405', 'TG-1 | TG-1/SvA7 | TG ett | /', ' |  |  | /'],                                     -- P1's guardian
    ['00000000-0000-4000-8000-000000001406', ' |  |  | /', ' |  |  | /'],                                                           -- P2's guardian
    ['00000000-0000-4000-8000-000000001407', 'TG-1,TG-2,TG-3 |  | TG ett | /', ' |  |  | /'],                                   -- P3's guardian
    ['00000000-0000-4000-8000-000000001412', 'TG-0 | TG-0/SvA6 | TG noll | /', ' |  |  | /'],                                   -- P5's guardian
    ['00000000-0000-4000-8000-000000001410', ' |  |  | /', ' |  |  | /'],                                                           -- G4: a guardian in SvA7
    ['00000000-0000-4000-8000-000000001401', 'TG-0,TG-1,TG-2,TG-3 | TG-0/SvA6,TG-1/SvA7,TG-3/Spanska | TG ett,TG noll | /',
                                             'TG-0,TG-1,TG-2,TG-3 | TG-0/SvA6,TG-1/SvA7,TG-3/Spanska |  | /'],                -- the teacher
    -- Q, the other school's pupil in its SvA7 and, by the row that points
    -- across, in this school's: the arms' school checks keep TG-2 (joined
    -- to Q's SvA7 by a row of Q's school) and TG-1's SvA7 row out.
    ['00000000-0000-4000-8000-000000001408', 'TG-9 | TG-2/SvA7 annan,TG-9/SvA7 annan | TG annan | SvA7,SvA7 annan/TG-2,TG-9',
                                             'TG-9 | TG-2/SvA7 annan,TG-9/SvA7 annan |  | SvA7,SvA7 annan/TG-2,TG-9']];
BEGIN
  IF coalesce(current_setting('app.test_tg_l1', true), '') = '' OR coalesce(current_setting('app.test_tg_l9', true), '') = ''
     OR coalesce(current_setting('app.test_tg_l0', true), '') = '' OR coalesce(current_setting('app.test_tg_sva9', true), '') = '' THEN
    RAISE EXCEPTION 'joined group: the fixture schools did not resolve; fixtures did not run';
  END IF;
  FOREACH via IN ARRAY ARRAY['app_authenticated', 'authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    IF current_user <> via THEN RAISE EXCEPTION 'joined group: could not act as %', via; END IF;
    FOR i IN 1 .. array_length(cases, 1) LOOP
      PERFORM set_config('request.jwt.claims', json_build_object('sub', cases[i][1])::text, true);
      seen := pg_temp.tg_reads(via = 'app_authenticated');
      expected := CASE via WHEN 'app_authenticated' THEN cases[i][2] ELSE cases[i][3] END;
      IF seen IS DISTINCT FROM expected THEN
        RAISE EXCEPTION 'joined group: % (%) as % reads "%", not "%"', cases[i][1], app.current_user_role(), via, seen, expected;
      END IF;
    END LOOP;
  END LOOP;
  SET LOCAL ROLE app_authenticated;
END $$;

-- A login with a row at each school (Flera skolor, 20261204090000) reads
-- what its row at the named school reads: the API names it in the setting
-- app.chosen_school_id, PostgREST in the x-school-id header; named nowhere,
-- the row that took the login first, here this school's.
DO $$
DECLARE
  via text;
  i int;
  seen text;
  expected text;
  named text;
  school text;
  -- authId; the school named ('' none, 'S1' this school, 'S2' the other);
  -- what the API reads; what PostgREST reads.
  cases constant text[][] := ARRAY[
    ['00000000-0000-4000-8000-000000001414', '',   'TG-1 | TG-1/SvA7 | TG ett | SvA7/TG-1', 'TG-1 | TG-1/SvA7 |  | SvA7/TG-1'],
    ['00000000-0000-4000-8000-000000001414', 'S1', 'TG-1 | TG-1/SvA7 | TG ett | SvA7/TG-1', 'TG-1 | TG-1/SvA7 |  | SvA7/TG-1'],
    ['00000000-0000-4000-8000-000000001414', 'S2', 'TG-9 | TG-2/SvA7 annan,TG-9/SvA7 annan | TG annan | /',
                                                   'TG-9 | TG-2/SvA7 annan,TG-9/SvA7 annan |  | /'],            -- M1: the teacher there
    ['00000000-0000-4000-8000-000000001415', '',   'TG-1 | TG-1/SvA7 | TG ett | SvA7/TG-1', 'TG-1 | TG-1/SvA7 |  | SvA7/TG-1'],
    ['00000000-0000-4000-8000-000000001415', 'S1', 'TG-1 | TG-1/SvA7 | TG ett | SvA7/TG-1', 'TG-1 | TG-1/SvA7 |  | SvA7/TG-1'],
    ['00000000-0000-4000-8000-000000001415', 'S2', 'TG-9 | TG-2/SvA7 annan,TG-9/SvA7 annan | TG annan | SvA7 annan/TG-2,TG-9',
                                                   'TG-9 | TG-2/SvA7 annan,TG-9/SvA7 annan |  | SvA7 annan/TG-2,TG-9'],  -- M2: the pupil there
    ['00000000-0000-4000-8000-000000001416', '',   ' |  |  | /', ' |  |  | /'],                                    -- M3: the guardian in SvA7 here
    ['00000000-0000-4000-8000-000000001416', 'S1', ' |  |  | /', ' |  |  | /'],
    ['00000000-0000-4000-8000-000000001416', 'S2', 'TG-9 | TG-2/SvA7 annan,TG-9/SvA7 annan | TG annan | SvA7 annan/TG-2,TG-9',
                                                   'TG-9 | TG-2/SvA7 annan,TG-9/SvA7 annan |  | SvA7 annan/TG-2,TG-9']];
BEGIN
  FOREACH via IN ARRAY ARRAY['app_authenticated', 'authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    IF current_user <> via THEN RAISE EXCEPTION 'joined group: could not act as %', via; END IF;
    FOR i IN 1 .. array_length(cases, 1) LOOP
      named := CASE cases[i][2] WHEN 'S1' THEN current_setting('app.test_tg_school') WHEN 'S2' THEN current_setting('app.test_tg_school9') ELSE '' END;
      PERFORM set_config('request.jwt.claims', json_build_object('sub', cases[i][1])::text, true);
      PERFORM set_config('app.chosen_school_id', CASE WHEN via = 'app_authenticated' THEN named ELSE '' END, true);
      PERFORM set_config('request.headers', CASE WHEN via = 'authenticated' AND named <> '' THEN json_build_object('x-school-id', named)::text ELSE '' END, true);
      school := app.current_school_id()::text;
      expected := coalesce(nullif(named, ''), current_setting('app.test_tg_school'));
      IF school IS DISTINCT FROM expected THEN
        RAISE EXCEPTION 'joined group: % naming "%" as % resolved to school %', cases[i][1], cases[i][2], via, school;
      END IF;
      seen := pg_temp.tg_reads(via = 'app_authenticated');
      expected := CASE via WHEN 'app_authenticated' THEN cases[i][3] ELSE cases[i][4] END;
      IF seen IS DISTINCT FROM expected THEN
        RAISE EXCEPTION 'joined group: % naming "%" (%) as % reads "%", not "%"', cases[i][1], cases[i][2], app.current_user_role(), via, seen, expected;
      END IF;
    END LOOP;
  END LOOP;
  PERFORM set_config('app.chosen_school_id', '', true);
  PERFORM set_config('request.headers', '', true);
  SET LOCAL ROLE app_authenticated;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 221: brytaren för restid i generatorn är Skolreglernas och skrivs
-- av den som planerar (LunchSettings."generatorKeepsTravelTime",
-- 20261209090000).
--
-- In the matrix school, whose Skolregler row the fixtures wrote as the owner
-- without naming the column:
--   * the column is boolean, NOT NULL, default false, with its comment, and
--     the fixtures' row reads false: off for every school until it says so;
--   * it has no privilege of its own: every role — the API's, PostgREST's
--     two — has on the column exactly what it has on the row, so the row's
--     arms are the whole of who reads and writes it;
--   * the schemaläggare (PLANERING) turns it on and off again, by UPDATE and
--     by the upsert the gateway writes; the full administrator and the rektor
--     hold PLANERING and turn it too;
--   * the expedition (PERSONAL, not PLANERING) and the läsare are refused by
--     the arm's WITH CHECK (insufficient_privilege, as section 181's
--     expedition is) and both still read it;
--   * the teacher reads it, as staff read the row, and an UPDATE reaches no
--     row of it;
--   * a pupil and a guardian read no row at all.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
DO $$
DECLARE
  col record;
  school uuid := app.current_school_id();
BEGIN
  IF (SELECT slug FROM "Schools" WHERE id = school) IS DISTINCT FROM 'rls-roller-school'
     OR NOT app.current_user_may('PLANERING', true) THEN
    RAISE EXCEPTION 'travel switch: expected the matrix school''s schemaläggare';
  END IF;
  SELECT a.attnotnull AS not_null, format_type(a.atttypid, a.atttypmod) AS type_name,
         pg_get_expr(d.adbin, d.adrelid) AS default_value,
         col_description(a.attrelid, a.attnum) AS comment
    INTO col
    FROM pg_attribute a
    LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
   WHERE a.attrelid = '"LunchSettings"'::regclass AND a.attname = 'generatorKeepsTravelTime'
     AND NOT a.attisdropped;
  IF col IS NULL OR NOT col.not_null OR col.type_name <> 'boolean' OR col.default_value <> 'false'
     OR col.comment IS NULL OR col.comment NOT LIKE 'Restid i generatorn:%' THEN
    RAISE EXCEPTION 'travel switch: the column is not boolean NOT NULL DEFAULT false with its comment: %', row_to_json(col);
  END IF;
  -- Row-level arms only: the column is the row's, for whoever the row is —
  -- every role holds on it exactly what it holds on the row's other columns
  -- (lunchMinutes stands for them), and the API's role all three it writes
  -- with.
  IF NOT has_column_privilege('app_authenticated', '"LunchSettings"', 'generatorKeepsTravelTime', 'SELECT')
     OR NOT has_column_privilege('app_authenticated', '"LunchSettings"', 'generatorKeepsTravelTime', 'UPDATE')
     OR NOT has_column_privilege('app_authenticated', '"LunchSettings"', 'generatorKeepsTravelTime', 'INSERT') THEN
    RAISE EXCEPTION 'travel switch: app_authenticated cannot read and write the column as it does the row';
  END IF;
  FOR col IN
    SELECT r.rolname, p.privilege
      FROM pg_roles r
      CROSS JOIN unnest(ARRAY['SELECT', 'INSERT', 'UPDATE']) AS p(privilege)
     WHERE r.rolname IN ('app_authenticated', 'authenticated', 'anon')
  LOOP
    IF has_column_privilege(col.rolname, '"LunchSettings"', 'generatorKeepsTravelTime', col.privilege)
       IS DISTINCT FROM has_column_privilege(col.rolname, '"LunchSettings"', 'lunchMinutes', col.privilege) THEN
      RAISE EXCEPTION 'travel switch: % holds % on the column as it does not on the row''s other columns', col.rolname, col.privilege;
    END IF;
  END LOOP;

  IF (SELECT "generatorKeepsTravelTime" FROM "LunchSettings" WHERE "schoolId" = school) IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'travel switch: the row written before the column does not read off';
  END IF;
  UPDATE "LunchSettings" SET "generatorKeepsTravelTime" = true WHERE "schoolId" = school;
  IF NOT FOUND THEN RAISE EXCEPTION 'travel switch: the schemaläggare could not turn it on'; END IF;
  -- The gateway's own write: INSERT … ON CONFLICT ("schoolId") DO UPDATE.
  INSERT INTO "LunchSettings" ("schoolId", "lunchStartTime", "lunchEndTime", "lunchMinutes", "updatedAt", "generatorKeepsTravelTime")
  VALUES (school, '11:00', '13:00', 30, now(), false)
  ON CONFLICT ("schoolId") DO UPDATE SET "generatorKeepsTravelTime" = EXCLUDED."generatorKeepsTravelTime";
  IF (SELECT "generatorKeepsTravelTime" FROM "LunchSettings" WHERE "schoolId" = school) THEN
    RAISE EXCEPTION 'travel switch: the schemaläggare''s upsert did not turn it off';
  END IF;
  UPDATE "LunchSettings" SET "generatorKeepsTravelTime" = true WHERE "schoolId" = school;
END $$;
SELECT set_config('app.test_rls221_school', app.current_school_id()::text, true);

-- The full administrator and the rektor hold PLANERING: each turns it once.
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
DO $$
BEGIN
  UPDATE "LunchSettings" SET "generatorKeepsTravelTime" = false WHERE "schoolId" = app.current_school_id();
  IF NOT FOUND THEN RAISE EXCEPTION 'travel switch: the full administrator could not turn it off'; END IF;
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000106')::text, true);
DO $$
BEGIN
  UPDATE "LunchSettings" SET "generatorKeepsTravelTime" = true WHERE "schoolId" = app.current_school_id();
  IF NOT FOUND THEN RAISE EXCEPTION 'travel switch: the rektor could not turn it on'; END IF;
END $$;

-- The expedition and the läsare read it on and are refused a change by the
-- arm's WITH CHECK; the teacher reads it on and an UPDATE reaches no row.
DO $$
DECLARE
  who text;
  n bigint;
  msg text;
  school uuid := current_setting('app.test_rls221_school')::uuid;
BEGIN
  FOREACH who IN ARRAY ARRAY[
    '00000000-0000-4000-8000-000000000108',
    '00000000-0000-4000-8000-000000000115',
    '00000000-0000-4000-8000-000000000111'
  ] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    IF (SELECT "generatorKeepsTravelTime" FROM "LunchSettings" WHERE "schoolId" = school) IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'travel switch: % does not read the switch the rektor turned on', who;
    END IF;
    BEGIN
      UPDATE "LunchSettings" SET "generatorKeepsTravelTime" = false WHERE "schoolId" = school;
      GET DIAGNOSTICS n = ROW_COUNT;
      IF n <> 0 THEN RAISE EXCEPTION 'travel switch: % turned it off without PLANERING', who; END IF;
      IF app.current_user_role() = 'SCHOOL_ADMIN' THEN
        RAISE EXCEPTION 'travel switch: % (an administrator without PLANERING) was not refused', who;
      END IF;
    EXCEPTION WHEN insufficient_privilege THEN
      GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
      IF msg NOT LIKE '%row-level security%' THEN
        RAISE EXCEPTION 'travel switch: % was refused by "%", not by row security', who, msg;
      END IF;
      IF app.current_user_role() <> 'SCHOOL_ADMIN' THEN
        RAISE EXCEPTION 'travel switch: % (%) was refused where no row is theirs', who, app.current_user_role();
      END IF;
    END;
  END LOOP;
END $$;

-- A pupil and a guardian read no row of the Skolregler at all.
DO $$
DECLARE
  who text;
BEGIN
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000000112', '00000000-0000-4000-8000-000000000113'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    IF EXISTS (SELECT 1 FROM "LunchSettings") THEN
      RAISE EXCEPTION 'travel switch: % reads the Skolregler', who;
    END IF;
  END LOOP;
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000107')::text, true);
DO $$
BEGIN
  IF (SELECT "generatorKeepsTravelTime" FROM "LunchSettings" WHERE "schoolId" = app.current_school_id()) IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'travel switch: a profile without PLANERING moved it after all';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 270: Ersättande grupper, katalogen (20261211090000). Kolumnen
-- StudentGroups."replacesSubjectId", dess CHECK och sammansatta nyckel;
-- elevens hjälpare SECURITY DEFINER, STABLE, med fäst search_path, körbar av
-- authenticated och app_authenticated och av ingen annan; tre av elevens armar
-- på CalendarLessons avsmalnade och ingen annan arm som frågar hjälparen;
-- vårdnadshavarens grupparm för API:ts roll ensam; ICS-funktionens kropp
-- tillämpar regeln.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  bad text;
  r text;
  fn constant text := 'app.current_student_replaced_lesson_ids()';
BEGIN
  PERFORM set_config('search_path', 'public, pg_temp', true);
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                  WHERE table_schema = 'public' AND table_name = 'StudentGroups' AND column_name = 'replacesSubjectId'
                    AND data_type = 'uuid' AND is_nullable = 'YES') THEN
    RAISE EXCEPTION 'replacing: StudentGroups."replacesSubjectId" is not a nullable uuid';
  END IF;
  IF (SELECT convalidated FROM pg_constraint WHERE conname = 'StudentGroups_only_a_teaching_group_replaces') IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'replacing: the CHECK is missing or not validated';
  END IF;
  IF (SELECT confdeltype FROM pg_constraint WHERE conname = 'StudentGroups_replacesSubjectId_schoolId_fkey') IS DISTINCT FROM 'n'
     OR (SELECT array_length(confdelsetcols, 1) FROM pg_constraint WHERE conname = 'StudentGroups_replacesSubjectId_schoolId_fkey') IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'replacing: the subject key is not ON DELETE SET NULL of the column alone';
  END IF;

  SELECT string_agg(tablename || '.' || policyname || ' ' || cmd || ' ' || roles::text, ', ' ORDER BY tablename, policyname)
    INTO bad
    FROM pg_policies
   WHERE schemaname = 'public' AND (coalesce(qual, '') || coalesce(with_check, '')) LIKE '%current\_student\_replaced\_lesson\_ids%';
  IF bad IS DISTINCT FROM 'CalendarLessons.calendar_lessons_participant_select SELECT {authenticated}, '
                          'CalendarLessons.calendar_lessons_student_select SELECT {authenticated}, '
                          'CalendarLessons.calendar_lessons_teaching_group_select SELECT {authenticated}' THEN
    RAISE EXCEPTION 'replacing: the arms that ask the pupil''s helper are %', bad;
  END IF;
  -- Each narrowing in front of a NULL-free array: NOT (id = ANY (NULL)) would drop the row.
  IF EXISTS (SELECT 1 FROM pg_policies
              WHERE schemaname = 'public' AND tablename = 'CalendarLessons'
                AND qual LIKE '%current\_student\_replaced\_lesson\_ids%'
                AND regexp_replace(qual, '\s+', ' ', 'g') NOT LIKE '%THEN app.current_student_replaced_lesson_ids() ELSE ''{}''::uuid[] END%') THEN
    RAISE EXCEPTION 'replacing: a narrowed arm''s helper has an ELSE other than ''{}''';
  END IF;
  IF (SELECT string_agg(policyname || ' ' || cmd || ' ' || roles::text, ', ') FROM pg_policies
       WHERE schemaname = 'public' AND tablename = 'StudentGroups' AND policyname = 'student_groups_guardian_select')
     IS DISTINCT FROM 'student_groups_guardian_select SELECT {app_authenticated}' THEN
    RAISE EXCEPTION 'replacing: the guardian''s group arm is not SELECT for app_authenticated alone';
  END IF;
  -- The role inside the initplan, so no staff read of the groups runs the
  -- guardian's helper (the arm's array is an index condition).
  IF (SELECT regexp_replace(qual, '\s+', ' ', 'g') FROM pg_policies
       WHERE schemaname = 'public' AND tablename = 'StudentGroups' AND policyname = 'student_groups_guardian_select')
     NOT LIKE '%CASE WHEN (app.current_user_role() = ''GUARDIAN''::"UserRole") THEN app.current_guardian_group_ids() ELSE NULL::uuid[] END%' THEN
    RAISE EXCEPTION 'replacing: the guardian''s group arm asks its helper outside a CASE on the role';
  END IF;

  IF NOT (SELECT prosecdef FROM pg_proc WHERE oid = fn::regprocedure) THEN RAISE EXCEPTION 'replacing: % is not SECURITY DEFINER', fn; END IF;
  IF (SELECT provolatile FROM pg_proc WHERE oid = fn::regprocedure) <> 's' THEN RAISE EXCEPTION 'replacing: % is not STABLE', fn; END IF;
  IF (SELECT proconfig FROM pg_proc WHERE oid = fn::regprocedure) IS DISTINCT FROM ARRAY['search_path=public, pg_temp'] THEN
    RAISE EXCEPTION 'replacing: % does not pin its search_path', fn;
  END IF;
  FOREACH r IN ARRAY ARRAY['authenticated', 'app_authenticated'] LOOP
    IF NOT has_function_privilege(r, fn, 'EXECUTE') THEN RAISE EXCEPTION 'replacing: % may not call %', r, fn; END IF;
  END LOOP;
  FOREACH r IN ARRAY ARRAY['anon', 'service_role'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) AND has_function_privilege(r, fn, 'EXECUTE') THEN
      RAISE EXCEPTION 'replacing: % may call %', r, fn;
    END IF;
  END LOOP;
  IF (SELECT proacl::text FROM pg_proc WHERE oid = fn::regprocedure) ~ '[{,]=X/' THEN
    RAISE EXCEPTION 'replacing: PUBLIC may call %', fn;
  END IF;

  IF (SELECT prosrc FROM pg_proc WHERE oid = 'app.calendar_feed_pupil_lessons(uuid, uuid, date, date, text, "TeacherDisplay")'::regprocedure)
     NOT LIKE '%g.subject = cl."subjectId"%' THEN
    RAISE EXCEPTION 'replacing: the pupil''s calendar feed does not apply the rule';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 271: en elev i SvA7, som ersätter svenska, läser inte klassens
-- svenska: varken 7A:s egen, 7B:s med 7A tillagd, halvklassens 7A:1 eller 7B:s
-- med 7A:1 tillagd, och inte dess logg eller lärarrader; den läser SvA7:s
-- (också dess lektion i ämnet svenska), 7B:s svenska dit SvA7 är tillagd,
-- svenskan som namnger hen, svenskan i EG Sv7 fördjupning (en
-- undervisningsgrupp hen är placerad i) och klassens övriga lektioner. Hen
-- går också i EnS7, som ersätter engelska: varje grupp tar hen av sitt eget
-- ämne och inget annat, och EnS7 tillagd på klassens svenska (EG-14)
-- behåller hen inte där. P3 går i både SvA7 och EG SvA7 stöd, som båda
-- ersätter svenska, och läser lektionerna som bär någon av dem, men inte
-- 7B:s svenska med fjolårets SvA6 tillagd (EG-15): en ersättande grupp från
-- ett annat läsår behåller ingen. P5, vars hemrad pekar på EG Sv7
-- fördjupning (en undervisningsgrupp) och som går i SvA7, är inte placerad
-- i fördjupningen och läser inte dess svenska (EG-13). En elev som
-- gick i SvA6 i fjol läser årets svenska: en
-- ersättande grupp tar bara av lektioner i sitt eget läsår. En elev i
-- ingen ersättande grupp läser som förut, också när en annan skolas
-- administratör skrivit en medlemsrad för hen i en ersättande grupp här
-- (EG SvA7 tom): hjälparen läser bara skolans egna rader. Som PostgREST:s
-- roll och som API:ts. Personalen läser allt som förut. En inloggning med
-- en rad på varje skola läser efter den skola anropet namnger: här i ingen
-- ersättande grupp, där i den skolans SvA7 (20261211090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001500')::text, true);
SELECT set_config('app.test_eg_school', app.current_school_id()::text, true);
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001508')::text, true);
SELECT set_config('app.test_eg_school2', app.current_school_id()::text, true);
-- What the caller reads of this section's lessons, as one line: the lessons,
-- the logs (the API's only), the lessons whose teacher rows they read, and
-- the helper's answer. A row of no name here shows as its id, so a leak fails.
CREATE FUNCTION pg_temp.eg_reads(api boolean) RETURNS text LANGUAGE plpgsql AS $f$
DECLARE
  lessons text;
  logs text := '';
  teachers text;
  helper text;
BEGIN
  SELECT coalesce(string_agg(coalesce(note, id::text), ',' ORDER BY coalesce(note, id::text)), '') INTO lessons
    FROM "CalendarLessons" WHERE note LIKE 'EG-%' OR note IS NULL;
  IF api THEN
    SELECT coalesce(string_agg(topic, ',' ORDER BY topic), '') INTO logs FROM "LessonLogs" WHERE topic LIKE 'EG %';
  END IF;
  SELECT coalesce(string_agg(DISTINCT coalesce(l.note, t."calendarLessonId"::text), ',' ORDER BY coalesce(l.note, t."calendarLessonId"::text)), '')
    INTO teachers
    FROM "CalendarLessonTeachers" t LEFT JOIN "CalendarLessons" l ON l.id = t."calendarLessonId"
   WHERE l.note LIKE 'EG-%' OR l.id IS NULL;
  SELECT coalesce(string_agg(coalesce(l.note, x::text), ',' ORDER BY coalesce(l.note, x::text)), '') INTO helper
    FROM unnest(app.current_student_replaced_lesson_ids()) x LEFT JOIN "CalendarLessons" l ON l.id = x;
  RETURN lessons || ' | ' || logs || ' | ' || teachers || ' | ' || helper;
END
$f$;
GRANT EXECUTE ON FUNCTION pg_temp.eg_reads(boolean) TO PUBLIC;
DO $$
DECLARE
  via text;
  i int;
  seen text;
  expected text;
  -- authId; what they read as the API and as PostgREST:
  -- lessons | logs (the API's) | teacher rows' lessons | the helper's lessons.
  -- The helper's lessons are the ones the caller cannot read, so they show by id.
  cases constant text[][] := ARRAY[
    ['00000000-0000-4000-8000-000000001502', 'EG-11,EG-13,EG-2,EG-3,EG-4,EG-5,EG-8 |  | EG-2,EG-5 | 6 hidden',
                                             'EG-11,EG-13,EG-2,EG-3,EG-4,EG-5,EG-8 |  | EG-2,EG-5 | 6 hidden'],               -- P1: 7A, SvA7, EnS7, 7A:1
    -- P2: 7A, 7A:1; last year in Sv6n and SvA6, which takes P2 off EG-0 (that
    -- year's) and off nothing of this year's.
    ['00000000-0000-4000-8000-000000001503', 'EG-1,EG-10,EG-12,EG-14,EG-15,EG-2,EG-5,EG-6,EG-7,EG-8 | EG ett | EG-1,EG-10,EG-14,EG-2,EG-5 | 1 hidden',
                                             'EG-1,EG-10,EG-12,EG-14,EG-15,EG-2,EG-5,EG-6,EG-7,EG-8 |  | EG-1,EG-10,EG-14,EG-2,EG-5 | 1 hidden'],
    -- P3: 7B, SvA7. The teacher rows of 7B's own svenska with SvA7 added
    -- (EG-4), and not of 7B's with 7A added (EG-6), which P3 does not attend.
    ['00000000-0000-4000-8000-000000001504', 'EG-11,EG-3,EG-4 |  | EG-4 | 3 hidden', 'EG-11,EG-3,EG-4 |  | EG-4 | 3 hidden'],
    -- P5: home row EG Sv7 fördjupning (a teaching group), in SvA7. Not a
    -- member of the fördjupning, so not placed in it: EG-13 is hidden.
    ['00000000-0000-4000-8000-000000001510', 'EG-11,EG-3,EG-4 |  |  | 1 hidden', 'EG-11,EG-3,EG-4 |  |  | 1 hidden'],
    ['00000000-0000-4000-8000-000000001501', 'EG-0,EG-1,EG-10,EG-11,EG-12,EG-13,EG-14,EG-15,EG-2,EG-3,EG-4,EG-5,EG-6,EG-7,EG-8 | EG ett | EG-0,EG-1,EG-10,EG-11,EG-12,EG-13,EG-14,EG-15,EG-2,EG-3,EG-4,EG-5,EG-6,EG-7,EG-8 | ',
                                             'EG-0,EG-1,EG-10,EG-11,EG-12,EG-13,EG-14,EG-15,EG-2,EG-3,EG-4,EG-5,EG-6,EG-7,EG-8 |  | EG-0,EG-1,EG-10,EG-11,EG-12,EG-13,EG-14,EG-15,EG-2,EG-3,EG-4,EG-5,EG-6,EG-7,EG-8 | ']];  -- the teacher
BEGIN
  IF coalesce(current_setting('app.test_eg_school', true), '') = '' OR coalesce(current_setting('app.test_eg_school2', true), '') = '' THEN
    RAISE EXCEPTION 'replacing: the fixture schools did not resolve; fixtures did not run';
  END IF;
  FOREACH via IN ARRAY ARRAY['app_authenticated', 'authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    IF current_user <> via THEN RAISE EXCEPTION 'replacing: could not act as %', via; END IF;
    FOR i IN 1 .. array_length(cases, 1) LOOP
      PERFORM set_config('request.jwt.claims', json_build_object('sub', cases[i][1])::text, true);
      seen := pg_temp.eg_reads(via = 'app_authenticated');
      -- The helper's lessons are unreadable to the pupil: count them.
      seen := regexp_replace(seen, '\| ([0-9a-f-]{36}(,[0-9a-f-]{36})*)$',
                             '| ' || coalesce(array_length(app.current_student_replaced_lesson_ids(), 1), 0)::text || ' hidden');
      expected := CASE via WHEN 'app_authenticated' THEN cases[i][2] ELSE cases[i][3] END;
      IF seen IS DISTINCT FROM expected THEN
        RAISE EXCEPTION 'replacing: % (%) as % reads "%", not "%"', cases[i][1], app.current_user_role(), via, seen, expected;
      END IF;
    END LOOP;
  END LOOP;
  SET LOCAL ROLE app_authenticated;
END $$;

-- The helper's lessons, named, read by the school's administrator.
DO $$
DECLARE
  p1 uuid;
  got text;
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001502')::text, true);
  CREATE TEMP TABLE eg_hidden ON COMMIT DROP AS SELECT unnest(app.current_student_replaced_lesson_ids()) AS id;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001500')::text, true);
  SELECT string_agg(l.note, ',' ORDER BY l.note) INTO got FROM eg_hidden h JOIN "CalendarLessons" l ON l.id = h.id;
  IF got IS DISTINCT FROM 'EG-1,EG-10,EG-12,EG-14,EG-6,EG-7' THEN
    RAISE EXCEPTION 'replacing: P1''s helper takes them off %, not EG-1,EG-10,EG-12,EG-14,EG-6,EG-7', coalesce(got, '(nothing)');
  END IF;
END $$;

-- M, a pupil at both schools: here in no replacing group (reads EG-1), there
-- in that school's SvA7 (does not read EG-9, its svenska).
DO $$
DECLARE
  via text;
  i int;
  named text;
  seen text;
  cases constant text[][] := ARRAY[
    ['',   'EG-1,EG-10,EG-14,EG-2,EG-5,EG-6'],
    ['S1', 'EG-1,EG-10,EG-14,EG-2,EG-5,EG-6'],
    ['S2', '']];
BEGIN
  FOREACH via IN ARRAY ARRAY['app_authenticated', 'authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    FOR i IN 1 .. array_length(cases, 1) LOOP
      named := CASE cases[i][1] WHEN 'S1' THEN current_setting('app.test_eg_school') WHEN 'S2' THEN current_setting('app.test_eg_school2') ELSE '' END;
      PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001509')::text, true);
      PERFORM set_config('app.chosen_school_id', CASE WHEN via = 'app_authenticated' THEN named ELSE '' END, true);
      PERFORM set_config('request.headers', CASE WHEN via = 'authenticated' AND named <> '' THEN json_build_object('x-school-id', named)::text ELSE '' END, true);
      SELECT coalesce(string_agg(note, ',' ORDER BY note), '') INTO seen FROM "CalendarLessons" WHERE note LIKE 'EG-%';
      IF seen IS DISTINCT FROM cases[i][2] THEN
        RAISE EXCEPTION 'replacing: M naming "%" as % reads "%", not "%"', cases[i][1], via, seen, cases[i][2];
      END IF;
    END LOOP;
  END LOOP;
  PERFORM set_config('app.chosen_school_id', '', true);
  PERFORM set_config('request.headers', '', true);
  SET LOCAL ROLE app_authenticated;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 272: vårdnadshavaren läser sina barns grupper genom API:ts roll,
-- och bara dem: G1 SvA-barnets 7A, 7A:1 och SvA7, G2 7A-barnets 7A och 7A:1,
-- tvillingarnas vårdnadshavare båda barnens; genom PostgREST:s roll inga.
-- Vårdnadshavarens lektionsarmar är oförändrade: G1 läser fortfarande 7A:s
-- svenska, och familjeveckan filtrerar per barn (20261211090000).
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  via text;
  i int;
  seen text;
  expected text;
  cases constant text[][] := ARRAY[
    -- authId; groups as the API; lessons as the API; groups as PostgREST.
    ['00000000-0000-4000-8000-000000001505', 'EG EnS7,EG Sv7 fördjupning,EG SvA7,EG7A,EG7A:1', 'EG-1,EG-10,EG-11,EG-12,EG-13,EG-14,EG-2,EG-3,EG-4,EG-5,EG-6,EG-7,EG-8', ''],
    ['00000000-0000-4000-8000-000000001506', 'EG Sv6n,EG SvA6,EG7A,EG7A:1', 'EG-0,EG-1,EG-10,EG-12,EG-14,EG-15,EG-2,EG-5,EG-6,EG-7,EG-8', ''],
    ['00000000-0000-4000-8000-000000001507', 'EG EnS7,EG Sv6n,EG Sv7 fördjupning,EG SvA6,EG SvA7,EG7A,EG7A:1', 'EG-0,EG-1,EG-10,EG-11,EG-12,EG-13,EG-14,EG-15,EG-2,EG-3,EG-4,EG-5,EG-6,EG-7,EG-8', ''],
    -- A pupil reads its home class's row as before, and no teaching group's.
    ['00000000-0000-4000-8000-000000001502', 'EG7A', 'EG-11,EG-13,EG-2,EG-3,EG-4,EG-5,EG-8', 'EG7A']];
BEGIN
  FOREACH via IN ARRAY ARRAY['app_authenticated', 'authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    IF current_user <> via THEN RAISE EXCEPTION 'replacing: could not act as %', via; END IF;
    FOR i IN 1 .. array_length(cases, 1) LOOP
      PERFORM set_config('request.jwt.claims', json_build_object('sub', cases[i][1])::text, true);
      SELECT coalesce(string_agg(name, ',' ORDER BY name), '') INTO seen FROM "StudentGroups" WHERE name LIKE 'EG%';
      expected := CASE via WHEN 'app_authenticated' THEN cases[i][2] ELSE cases[i][4] END;
      IF seen IS DISTINCT FROM expected THEN
        RAISE EXCEPTION 'replacing: % (%) as % reads the groups "%"', cases[i][1], app.current_user_role(), via, seen;
      END IF;
      IF via = 'app_authenticated' THEN
        SELECT coalesce(string_agg(note, ',' ORDER BY note), '') INTO seen FROM "CalendarLessons" WHERE note LIKE 'EG-%';
        IF seen IS DISTINCT FROM cases[i][3] THEN
          RAISE EXCEPTION 'replacing: % (%) reads the lessons "%", not "%"', cases[i][1], app.current_user_role(), seen, cases[i][3];
        END IF;
      END IF;
    END LOOP;
  END LOOP;
  -- The other school's administrator reads none of these groups, and this
  -- school's guardian none of that school's.
  SET LOCAL ROLE app_authenticated;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001505')::text, true);
  IF EXISTS (SELECT 1 FROM "StudentGroups" WHERE name LIKE 'EG annan%') THEN
    RAISE EXCEPTION 'replacing: a guardian reads another school''s groups';
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 273: kalenderprenumerationen tillämpar regeln: SvA-elevens eget
-- flöde och vårdnadshavarens flöde för hen visar inte klassens svenska men
-- SvA7:s, den dit SvA7 är tillagd, den som namnger hen och svenskan i EG Sv7
-- fördjupning, där hen är placerad; 7A-elevens flöde visar klassens svenska,
-- också med den andra skolans medlemsrad för hen i EG SvA7 tom; P3, som går
-- i både SvA7 och EG SvA7 stöd, behåller lektionerna som bär någon av dem
-- (20261211090000).
-- ---------------------------------------------------------------------------

BEGIN;
CREATE FUNCTION pg_temp.eg_as(sub text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', sub)::text, true);
END $$;
-- The feed's lessons by note, read as the school's administrator; the door
-- asked as a calendar asks it, with no principal.
CREATE FUNCTION pg_temp.eg_feed(hash text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE got jsonb; ids uuid[]; notes text;
BEGIN
  PERFORM set_config('request.jwt.claims', '', true);
  got := app.calendar_feed(hash);
  PERFORM pg_temp.eg_as('00000000-0000-4000-8000-000000001500');
  IF got IS NULL THEN RETURN '(no feed)'; END IF;
  SELECT array_agg((e->>'id')::uuid) INTO ids FROM jsonb_array_elements(got->'lessons') e;
  SELECT coalesce(string_agg(l.note, ',' ORDER BY l.note), '') INTO notes FROM "CalendarLessons" l WHERE l.id = ANY (coalesce(ids, '{}'));
  RETURN notes;
END $$;
DO $$
DECLARE
  school uuid;
  p1 uuid;
  got text;
BEGIN
  PERFORM pg_temp.eg_as('00000000-0000-4000-8000-000000001500');
  school := app.current_school_id();
  p1 := (SELECT id FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000001502');
  INSERT INTO "PublicationSettings" ("schoolId") VALUES (school) ON CONFLICT ("schoolId") DO NOTHING;
  UPDATE "PublicationSettings" SET "calendarFeedStudents" = true, "calendarFeedGuardians" = true WHERE "schoolId" = school;
  PERFORM pg_temp.eg_as('00000000-0000-4000-8000-000000001502');
  PERFORM app.calendar_feed_create(NULL, repeat('a', 64), 'sv');
  PERFORM pg_temp.eg_as('00000000-0000-4000-8000-000000001503');
  PERFORM app.calendar_feed_create(NULL, repeat('b', 64), 'sv');
  PERFORM pg_temp.eg_as('00000000-0000-4000-8000-000000001504');
  PERFORM app.calendar_feed_create(NULL, repeat('d', 64), 'sv');
  PERFORM pg_temp.eg_as('00000000-0000-4000-8000-000000001505');
  PERFORM app.calendar_feed_create(p1, repeat('c', 64), 'sv');

  got := pg_temp.eg_feed(repeat('a', 64));
  IF got IS DISTINCT FROM 'EG-11,EG-13,EG-2,EG-3,EG-4,EG-5,EG-8' THEN RAISE EXCEPTION 'replacing: the SvA pupil''s feed shows %', got; END IF;
  got := pg_temp.eg_feed(repeat('c', 64));
  IF got IS DISTINCT FROM 'EG-11,EG-13,EG-2,EG-3,EG-4,EG-5,EG-8' THEN RAISE EXCEPTION 'replacing: the guardian''s feed for the SvA pupil shows %', got; END IF;
  -- The 7A pupil was in SvA6 last year: this year's svenska is theirs.
  got := pg_temp.eg_feed(repeat('b', 64));
  IF got IS DISTINCT FROM 'EG-1,EG-10,EG-12,EG-14,EG-15,EG-2,EG-5,EG-6,EG-7,EG-8' THEN RAISE EXCEPTION 'replacing: the 7A pupil''s feed shows %', got; END IF;
  -- P3 is in SvA7 and in SvA7 stöd, which both replace svenska: P3 keeps the
  -- lessons that carry either, and leaves 7B's own svenska.
  got := pg_temp.eg_feed(repeat('d', 64));
  IF got IS DISTINCT FROM 'EG-11,EG-3,EG-4' THEN RAISE EXCEPTION 'replacing: the feed of the pupil in two groups replacing svenska shows %', got; END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 274: en ersättande grupp skrivs bara som undervisningsgrupp, med
-- ett av skolans egna ämnen: CHECK-villkoret vägrar en klass och en
-- halvklass, nyckeln ett ämne från en annan skola, och ett borttaget ämne
-- lämnar gruppen kvar utan ersättning. En skola utan ersättande grupp: varje
-- elevs hjälpare svarar '{}' (20261211090000).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001500')::text, true);
DO $$
DECLARE
  sv uuid := (SELECT id FROM "Subjects" WHERE code = 'RLSEGSV');
  other uuid;
BEGIN
  BEGIN
    UPDATE "StudentGroups" SET "replacesSubjectId" = sv WHERE name = 'EG7A';
    RAISE EXCEPTION 'replacing: a class was made to replace a subject';
  EXCEPTION WHEN check_violation THEN NULL;
  END;
  BEGIN
    UPDATE "StudentGroups" SET "replacesSubjectId" = sv WHERE name = 'EG7A:1';
    RAISE EXCEPTION 'replacing: a half was made to replace a subject';
  EXCEPTION WHEN check_violation THEN NULL;
  END;
  BEGIN
    UPDATE "StudentGroups" SET kind = 'CLASS' WHERE name = 'EG SvA7';
    RAISE EXCEPTION 'replacing: a replacing group was made a class';
  EXCEPTION WHEN check_violation THEN NULL;
  END;
  -- Another school's subject: invisible here, so read as the owner sees it
  -- would be; the key refuses it.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001508')::text, true);
  other := (SELECT id FROM "Subjects" WHERE code = 'RLSEGSV2');
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001500')::text, true);
  IF other IS NULL THEN RAISE EXCEPTION 'replacing: the other school''s subject did not resolve'; END IF;
  BEGIN
    UPDATE "StudentGroups" SET "replacesSubjectId" = other WHERE name = 'EG SvA7';
    RAISE EXCEPTION 'replacing: another school''s subject was taken';
  EXCEPTION WHEN foreign_key_violation THEN NULL;
  END;
  -- The subject deleted: SvA7 stays, replacing nothing.
  DELETE FROM "Subjects" WHERE id = sv;
  IF (SELECT "replacesSubjectId" FROM "StudentGroups" WHERE name = 'EG SvA7') IS NOT NULL THEN
    RAISE EXCEPTION 'replacing: a deleted subject is still replaced';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "StudentGroups" WHERE name = 'EG SvA7') THEN
    RAISE EXCEPTION 'replacing: deleting the subject deleted the group';
  END IF;
END $$;
ROLLBACK;

BEGIN;
DO $$
DECLARE
  who text;
BEGIN
  -- Pupils of #193's school, which has no replacing group: nothing hidden.
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000001402', '00000000-0000-4000-8000-000000001403',
                             '00000000-0000-4000-8000-000000001404', '00000000-0000-4000-8000-000000001411'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    IF app.current_student_replaced_lesson_ids() IS DISTINCT FROM '{}'::uuid[] THEN
      RAISE EXCEPTION 'replacing: % at a school with no replacing group has hidden lessons', who;
    END IF;
  END LOOP;
  -- Staff and guardians: '{}' whatever their school.
  FOREACH who IN ARRAY ARRAY['00000000-0000-4000-8000-000000001500', '00000000-0000-4000-8000-000000001501',
                             '00000000-0000-4000-8000-000000001505'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', who)::text, true);
    IF app.current_student_replaced_lesson_ids() IS DISTINCT FROM '{}'::uuid[] THEN
      RAISE EXCEPTION 'replacing: % (%) has hidden lessons', who, app.current_user_role();
    END IF;
  END LOOP;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 260: huvudmannen står i katalogen som migreringen skrev den
-- (Huvudman, 20261212090000–090200).
--
--   260a  the six tables have row security, and only the gateway's role
--         reaches them: SELECT on all six; on HuvudmanMembers INSERT and
--         UPDATE of the columns the kommunadministratör writes, never the
--         login (authId, invitedAt); on HuvudmanApiKeys INSERT of a new key
--         and UPDATE of revokedAt and lastUsedAt only; no write at all on
--         Huvudmen, HuvudmanSchools, HuvudmanSchoolRequests and
--         HuvudmanSchoolEvents, and no DELETE anywhere. PostgREST's role and
--         anon reach none;
--   260b  the functions are SECURITY DEFINER with search_path public,
--         pg_temp (the lock and the key's setting aside), and EXECUTE is
--         exactly as granted: the gateway's role runs the acts, the reader's
--         lookup and the arms' helpers; nobody runs who the reader is, the
--         lock, the decider and kommunadministratör checks, or
--         app.same_huvudman;
--   260c  the three helpers without a second branch (current_user_id,
--         current_user_group_id, current_user_decides) never name a
--         huvudman; app.current_service_school_id() is SECURITY DEFINER,
--         STABLE, with search_path public, pg_temp, executable as it was
--         (by PUBLIC), and answers the setting at once, reading no table,
--         when no huvudman's key is set (20261212090300); every one of the
--         36 arms that name it calls it once, as an initplan;
--   260d  the key's trigger is there, BEFORE UPDATE; the read log's two
--         columns, their foreign keys and the CHECK are there and validated,
--         and so are the six tables' CHECKs.
-- ---------------------------------------------------------------------------

DO $$
DECLARE
  bad text;
BEGIN
  SELECT string_agg(t, ', ') INTO bad
    FROM unnest(ARRAY['Huvudmen', 'HuvudmanMembers', 'HuvudmanSchools', 'HuvudmanSchoolRequests',
                      'HuvudmanSchoolEvents', 'HuvudmanApiKeys']) t
   WHERE NOT (SELECT relrowsecurity FROM pg_class WHERE oid = format('public.%I', t)::regclass)
      OR NOT has_table_privilege('app_authenticated', format('public.%I', t), 'SELECT')
      OR has_table_privilege('app_authenticated', format('public.%I', t), 'DELETE')
      OR has_table_privilege('app_authenticated', format('public.%I', t), 'TRUNCATE')
      OR has_any_column_privilege('authenticated', format('public.%I', t), 'SELECT, INSERT, UPDATE')
      OR has_table_privilege('authenticated', format('public.%I', t), 'DELETE')
      OR (EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon')
          AND has_any_column_privilege('anon', format('public.%I', t), 'SELECT, INSERT, UPDATE'))
      OR (t NOT IN ('HuvudmanMembers', 'HuvudmanApiKeys')
          AND has_any_column_privilege('app_authenticated', format('public.%I', t), 'INSERT, UPDATE'));
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'huvudman 260a: row security or table privileges wrong on %', bad;
  END IF;

  SELECT string_agg(format('%s.%s %s', tbl, col, priv), ', ') INTO bad
    FROM (VALUES
      ('HuvudmanMembers', 'huvudmanId', 'INSERT', true), ('HuvudmanMembers', 'email', 'INSERT', true),
      ('HuvudmanMembers', 'firstName', 'INSERT', true), ('HuvudmanMembers', 'lastName', 'INSERT', true),
      ('HuvudmanMembers', 'role', 'INSERT', true), ('HuvudmanMembers', 'isActive', 'INSERT', true),
      ('HuvudmanMembers', 'authId', 'INSERT', false), ('HuvudmanMembers', 'invitedAt', 'INSERT', false),
      ('HuvudmanMembers', 'id', 'INSERT', false),
      ('HuvudmanMembers', 'firstName', 'UPDATE', true), ('HuvudmanMembers', 'lastName', 'UPDATE', true),
      ('HuvudmanMembers', 'role', 'UPDATE', true), ('HuvudmanMembers', 'isActive', 'UPDATE', true),
      ('HuvudmanMembers', 'authId', 'UPDATE', false), ('HuvudmanMembers', 'invitedAt', 'UPDATE', false),
      ('HuvudmanMembers', 'huvudmanId', 'UPDATE', false), ('HuvudmanMembers', 'email', 'UPDATE', false),
      ('HuvudmanApiKeys', 'huvudmanId', 'INSERT', true), ('HuvudmanApiKeys', 'name', 'INSERT', true),
      ('HuvudmanApiKeys', 'keyHash', 'INSERT', true), ('HuvudmanApiKeys', 'scopes', 'INSERT', true),
      ('HuvudmanApiKeys', 'createdById', 'INSERT', true),
      ('HuvudmanApiKeys', 'revokedAt', 'INSERT', false), ('HuvudmanApiKeys', 'lastUsedAt', 'INSERT', false),
      ('HuvudmanApiKeys', 'revokedAt', 'UPDATE', true), ('HuvudmanApiKeys', 'lastUsedAt', 'UPDATE', true),
      ('HuvudmanApiKeys', 'name', 'UPDATE', false), ('HuvudmanApiKeys', 'scopes', 'UPDATE', false),
      ('HuvudmanApiKeys', 'keyHash', 'UPDATE', false), ('HuvudmanApiKeys', 'huvudmanId', 'UPDATE', false)
    ) v(tbl, col, priv, expected)
   WHERE has_column_privilege('app_authenticated', format('public.%I', tbl), col, priv) IS DISTINCT FROM expected;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'huvudman 260a: column privileges wrong: %', bad;
  END IF;

  SELECT string_agg(fn, ', ') INTO bad
    FROM unnest(ARRAY['app.my_huvudman_ids()', 'app.my_kommunadmin_huvudman_ids()', 'app.school_huvudman_ids()',
                      'app.current_huvudman_member_id()', 'app.huvudman_reader()', 'app.my_schools()',
                      'app.huvudman_member_takes_login(uuid, uuid)', 'app.huvudman_kommunadmin(uuid)', 'app.school_decider()',
                      'app.huvudman_request_school(uuid, text)', 'app.huvudman_withdraw_request(uuid, uuid)',
                      'app.huvudman_release_school(uuid, uuid)', 'app.school_accepts_huvudman(uuid)',
                      'app.school_declines_huvudman(uuid)', 'app.school_leaves_huvudman()',
                      'app.school_huvudman_readers()', 'app.school_huvudman_keys()', 'app.same_huvudman(uuid, uuid)',
                      'app.huvudman_schools(uuid)', 'app.huvudman_history(uuid, integer)', 'app.school_huvudman_history(integer)',
                      'app.huvudman_key_schools()', 'app.huvudman_key_owner()', 'app.huvudman_key_opens_school(uuid, uuid)',
                      'app.access_log_huvudman_names(uuid[], uuid[])', 'app.huvudman_api_keys_writes_are_narrow()',
                      'app.current_school_id()', 'app.current_user_role()', 'app.current_user_may("AdminArea", boolean)']) fn
   WHERE NOT (SELECT p.prosecdef AND p.proconfig = ARRAY['search_path=public, pg_temp'] FROM pg_proc p WHERE p.oid = fn::regprocedure);
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'huvudman 260b: not SECURITY DEFINER with search_path public, pg_temp: %', bad;
  END IF;

  SELECT string_agg(fn || ' for ' || r, ', ') INTO bad
    FROM unnest(ARRAY['app.my_huvudman_ids()', 'app.my_kommunadmin_huvudman_ids()', 'app.school_huvudman_ids()',
                      'app.current_huvudman_member_id()', 'app.huvudman_reader()', 'app.my_schools()',
                      'app.huvudman_member_takes_login(uuid, uuid)', 'app.huvudman_school_lock(uuid)',
                      'app.huvudman_kommunadmin(uuid)', 'app.school_decider()',
                      'app.huvudman_request_school(uuid, text)', 'app.huvudman_withdraw_request(uuid, uuid)',
                      'app.huvudman_release_school(uuid, uuid)', 'app.school_accepts_huvudman(uuid)',
                      'app.school_declines_huvudman(uuid)', 'app.school_leaves_huvudman()',
                      'app.school_huvudman_readers()', 'app.school_huvudman_keys()', 'app.same_huvudman(uuid, uuid)',
                      'app.huvudman_schools(uuid)', 'app.huvudman_history(uuid, integer)', 'app.school_huvudman_history(integer)',
                      'app.current_service_huvudman_key_id()', 'app.huvudman_key_schools()', 'app.huvudman_key_owner()',
                      'app.huvudman_key_opens_school(uuid, uuid)', 'app.access_log_huvudman_names(uuid[], uuid[])',
                      'app.huvudman_api_keys_writes_are_narrow()']) fn,
         unnest(ARRAY['app_authenticated', 'authenticated', 'anon', 'service_role', 'supabase_auth_admin']) r
   WHERE EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r)
     AND has_function_privilege(r, fn::regprocedure, 'EXECUTE')
         -- app.current_service_huvudman_key_id() is the gateway's role's since
         -- 20261212090300, whose four service arms ask it.
         IS DISTINCT FROM (r = 'app_authenticated' AND fn NOT IN (
           'app.current_huvudman_member_id()', 'app.huvudman_school_lock(uuid)', 'app.huvudman_kommunadmin(uuid)',
           'app.school_decider()', 'app.same_huvudman(uuid, uuid)',
           'app.huvudman_api_keys_writes_are_narrow()'));
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'huvudman 260b: EXECUTE is wrong on %', bad;
  END IF;

  SELECT string_agg(p.proname, ', ') INTO bad
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'app' AND p.proname IN ('current_user_id', 'current_user_group_id', 'current_user_decides')
     AND p.prosrc ~* 'huvudman';
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'huvudman 260c: % answer for the huvudman''s reader; they are to answer as for nobody', bad;
  END IF;
  IF (SELECT NOT (p.prosecdef AND p.provolatile = 's' AND p.proconfig = ARRAY['search_path=public, pg_temp']
                  AND has_function_privilege('public', p.oid, 'EXECUTE'))
        FROM pg_proc p WHERE p.oid = 'app.current_service_school_id()'::regprocedure) THEN
    RAISE EXCEPTION 'huvudman 260c: app.current_service_school_id() is not SECURITY DEFINER, STABLE, search_path public, pg_temp, PUBLIC''s';
  END IF;
  -- With no huvudman's key the first statement returns, before any table:
  -- the text up to the first RETURN names neither of the two tables.
  IF (SELECT substring(p.prosrc FROM '^(.*?)RETURN v_school;') ~ '"HuvudmanApiKeys"|"HuvudmanSchools"|FROM'
          OR substring(p.prosrc FROM '^(.*?)RETURN v_school;') IS NULL
          OR p.prosrc !~ 'IF v_key IS NULL OR v_school IS NULL THEN\s+RETURN v_school;'
        FROM pg_proc p WHERE p.oid = 'app.current_service_school_id()'::regprocedure) THEN
    RAISE EXCEPTION 'huvudman 260c: app.current_service_school_id() reads a table before it answers a school''s own principal: %',
      (SELECT prosrc FROM pg_proc WHERE oid = 'app.current_service_school_id()'::regprocedure);
  END IF;
  IF (SELECT count(*) FROM pg_policies WHERE schemaname = 'public'
        AND (coalesce(qual, '') || coalesce(with_check, '')) ~ 'app\.current_service_school_id\(\)') < 36
     OR EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public'
        AND (coalesce(qual, '') || coalesce(with_check, '')) ~ '(?<!SELECT )app\.current_service_school_id\(\)') THEN
    RAISE EXCEPTION 'huvudman 260c: the service arms are not the 36 initplans: %',
      (SELECT string_agg(tablename || '.' || policyname, ', ') FROM pg_policies WHERE schemaname = 'public'
        AND (coalesce(qual, '') || coalesce(with_check, '')) ~ '(?<!SELECT )app\.current_service_school_id\(\)');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_trigger tg WHERE tg.tgrelid = '"HuvudmanApiKeys"'::regclass
                    AND tg.tgname = 'HuvudmanApiKeys_writes_are_narrow' AND tg.tgenabled = 'O'
                    AND pg_get_triggerdef(tg.oid) LIKE '%BEFORE UPDATE ON public."HuvudmanApiKeys" FOR EACH ROW%') THEN
    RAISE EXCEPTION 'huvudman 260d: the key''s trigger is missing or not as written';
  END IF;
  SELECT string_agg(conrelid::regclass || '.' || conname, ', ') INTO bad
    FROM pg_constraint
   WHERE (conrelid IN ('"Huvudmen"'::regclass, '"HuvudmanMembers"'::regclass, '"HuvudmanSchools"'::regclass,
                       '"HuvudmanSchoolRequests"'::regclass, '"HuvudmanSchoolEvents"'::regclass, '"HuvudmanApiKeys"'::regclass)
          OR conname IN ('PersonalDataAccess_huvudmanMemberId_fkey', 'PersonalDataAccess_huvudmanApiKeyId_fkey',
                         'PersonalDataAccess_a_huvudman_reader_or_key'))
     AND NOT convalidated;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'huvudman 260d: not validated: %', bad;
  END IF;
  IF (SELECT count(*) FROM pg_constraint WHERE conname IN ('PersonalDataAccess_huvudmanMemberId_fkey',
        'PersonalDataAccess_huvudmanApiKeyId_fkey', 'PersonalDataAccess_a_huvudman_reader_or_key')) <> 3
     OR (SELECT count(*) FROM pg_constraint WHERE contype = 'c' AND conname IN ('Huvudmen_name_is_a_name',
           'Huvudmen_organisation_number_is_ten_digits', 'Huvudmen_municipality_code_is_four_digits',
           'HuvudmanMembers_email_is_an_address', 'HuvudmanMembers_names_are_names', 'HuvudmanMembers_a_login_was_invited',
           'HuvudmanSchoolEvents_one_side_acts', 'HuvudmanApiKeys_name_is_a_name', 'HuvudmanApiKeys_hash_is_sha256',
           'HuvudmanApiKeys_scopes_are_reads')) <> 10 THEN
    RAISE EXCEPTION 'huvudman 260d: a constraint is missing';
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Section 261: lösaren svarar för huvudmannens läsare (20261212090000).
--
-- For both API roles, the school named by the gateway's setting for
-- app_authenticated and by PostgREST's header for authenticated, all six
-- helpers and who the reader is (app.huvudman_reader(), the gateway's view
-- of app.current_huvudman_member_id()):
--
--   261a  the planner P of H, with no row anywhere, naming each school H
--         owns (A, the roller school, C) is an administrator there who reads
--         every area, writes none and decides nothing, with no user id and
--         no class; in either case of the uuid, padded;
--   261b  P naming nothing, a school H only asked for (B, D), or no uuid:
--         no principal;
--   261c  a deactivated member (X), and a member of a huvudman that owns
--         nothing and only asked for the roller school (Q): no principal,
--         named or not;
--   261d  an own row wins: L, a teacher with a row at A, is the teacher at A
--         (named or not) and H's reader in the roller school. A deactivated
--         own row does not: G, whose guardian row in the roller school is
--         deactivated, is under #190 nobody there, and with H owning the
--         school is H's reader there, since the huvudman's access is its own
--         decision, which the school took; nobody with nothing named. The
--         school's deciders see it in the list of who reads the school
--         (265a: own_row INACTIVE);
--   261e  a school the hook closed is no reader's, by setting or header;
--         the setting wins over the header as for a row;
--   261f  the kommunadministratör K reads as P does;
--   261g  app.my_schools(): P's three schools as the läsare, with the
--         huvudman, its role and which is chosen; L's own row first and no
--         reader's entry at A; nobody's for X; G's three as the reader, the
--         roller school among them, where G's own row is deactivated; a
--         closed school with its reason;
--   261h  Ersättande grupper's helper (20261211090000) answers the reader '{}'
--         at a school with replacing groups: H takes rls-ersattande-school
--         for the transaction, its SvA pupil has lessons hidden (the
--         control), and P, naming the school by the setting and by the
--         header, has none.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls261_a', :'school_a', true),
       set_config('app.test_rls261_b', :'school_b', true);
DO $$
DECLARE
  a uuid := current_setting('app.test_rls261_a')::uuid;
  b uuid := current_setting('app.test_rls261_b')::uuid;
  m uuid;
  c uuid;
  d uuid;
  via text;
  r record;
  got record;
  rd record;
  n int := 0;
  p  constant text := 'fe000000-0000-4000-8000-000000000260';
  k  constant text := 'fe000000-0000-4000-8000-000000000261';
  x  constant text := 'fe000000-0000-4000-8000-000000000262';
  q  constant text := 'fe000000-0000-4000-8000-000000000263';
  l  constant text := 'fe000000-0000-4000-8000-000000000264';
  g  constant text := 'fe000000-0000-4000-8000-000000000265';
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  m := app.current_school_id();
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000269')::text, true);
  c := app.current_school_id();
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000266')::text, true);
  d := app.current_school_id();
  IF m IS NULL OR c IS NULL OR d IS NULL OR c IN (a, b, m) OR d IN (a, b, m, c) THEN
    RAISE EXCEPTION 'huvudman 261: schools m %, c %, d %; fixtures did not run', m, c, d;
  END IF;

  FOREACH via IN ARRAY ARRAY['app_authenticated', 'authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    IF current_user <> via THEN
      RAISE EXCEPTION 'huvudman 261: running as %, not %', current_user, via;
    END IF;
    FOR r IN
      SELECT * FROM (VALUES
        -- sub, closed, named, the other channel's value (261e), expected school, role, reader?, case
        (p, NULL::jsonb, a::text,                '',     a,          'SCHOOL_ADMIN', true,  '261a P names A'),
        (p, NULL,        m::text,                '',     m,          'SCHOOL_ADMIN', true,  '261a P names the roller school'),
        (p, NULL,        c::text,                '',     c,          'SCHOOL_ADMIN', true,  '261a P names C'),
        (p, NULL,        upper(m::text),         '',     m,          'SCHOOL_ADMIN', true,  '261a P names it in upper case'),
        (p, NULL,        ' ' || c::text || ' ',  '',     c,          'SCHOOL_ADMIN', true,  '261a P names it padded'),
        (p, NULL,        '',                     '',     NULL::uuid, NULL,           false, '261b P names nothing'),
        (p, NULL,        b::text,                '',     NULL,       NULL,           false, '261b P names B, only asked for'),
        (p, NULL,        d::text,                '',     NULL,       NULL,           false, '261b P names D, only asked for'),
        (p, NULL,        'not-a-uuid',           '',     NULL,       NULL,           false, '261b P names no uuid'),
        (x, NULL,        a::text,                '',     NULL,       NULL,           false, '261c a deactivated member names A'),
        (x, NULL,        '',                     '',     NULL,       NULL,           false, '261c a deactivated member names nothing'),
        (q, NULL,        m::text,                '',     NULL,       NULL,           false, '261c H2''s planner names the school H2 asked for'),
        (q, NULL,        a::text,                '',     NULL,       NULL,           false, '261c H2''s planner names H''s school'),
        (l, NULL,        a::text,                '',     a,          'TEACHER',      false, '261d L names A, where L is a teacher'),
        (l, NULL,        '',                     '',     a,          'TEACHER',      false, '261d L names nothing: the own row'),
        (l, NULL,        m::text,                '',     m,          'SCHOOL_ADMIN', true,  '261d L names the roller school: H''s reader'),
        (g, NULL,        m::text,                '',     m,          'SCHOOL_ADMIN', true,  '261d G''s row there is deactivated: H''s reader'),
        (g, NULL,        '',                     '',     NULL,       NULL,           false, '261d G names nothing: nobody'),
        (p, jsonb_build_object(c::text, 'sso_required'), c::text, '', NULL, NULL,    false, '261e C closed, named'),
        (p, jsonb_build_object(c::text, 'sso_required'), m::text, '', m,    'SCHOOL_ADMIN', true, '261e C closed, the roller school named'),
        (p, NULL,        m::text,                c::text, m,         'SCHOOL_ADMIN', true,  '261e the setting wins over the header'),
        (k, NULL,        m::text,                '',     m,          'SCHOOL_ADMIN', true,  '261f K names the roller school'),
        (k, NULL,        '',                     '',     NULL,       NULL,           false, '261f K names nothing')
      ) v(sub, closed, named, other, school, role, reader, label)
    LOOP
      -- 261e's "setting wins" is the gateway's alone: PostgREST's role has
      -- the header only.
      CONTINUE WHEN r.other <> '' AND via = 'authenticated';
      PERFORM set_config('request.jwt.claims',
        (jsonb_build_object('sub', r.sub, 'role', 'authenticated')
          || CASE WHEN r.closed IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('rastra_closed_schools', r.closed) END)::text,
        true);
      PERFORM set_config('app.chosen_school_id', CASE via WHEN 'app_authenticated' THEN r.named ELSE '' END, true);
      PERFORM set_config('request.headers',
        CASE WHEN via = 'authenticated' AND r.named <> '' THEN json_build_object('x-school-id', r.named)::text
             WHEN via = 'app_authenticated' AND r.other <> '' THEN json_build_object('x-school-id', r.other)::text
             ELSE '' END, true);
      SELECT app.current_user_id() AS id, app.current_school_id() AS school, app.current_user_role()::text AS role,
             app.current_user_may('PERSONAL', true) AS may_write, app.current_user_may('PERSONAL', false) AS may_read,
             app.current_user_may('PLANERING', true) AS may_write2, app.current_user_may(NULL, false) AS may_null,
             app.current_user_decides() AS decides, app.current_user_group_id() AS grp
        INTO got;
      IF got.school IS DISTINCT FROM r.school OR got.role IS DISTINCT FROM r.role
         OR got.decides OR got.grp IS NOT NULL OR got.may_null
         OR (r.reader AND (got.id IS NOT NULL OR NOT got.may_read OR got.may_write OR got.may_write2))
         OR (NOT r.reader AND r.school IS NULL AND (got.id IS NOT NULL OR got.may_read))
         OR (NOT r.reader AND r.school IS NOT NULL AND got.id IS NULL) THEN
        RAISE EXCEPTION 'huvudman % %: school %, role %, id %, may read %, may write % / %, may(NULL) %, decides %, class %; expected school %, role %, reader %',
          via, r.label, got.school, got.role, got.id, got.may_read, got.may_write, got.may_write2, got.may_null, got.decides, got.grp,
          r.school, r.role, r.reader;
      END IF;
      -- Who the reader is, as the gateway asks it.
      IF via = 'app_authenticated' THEN
        SELECT count(*) AS n, min(huvudman_name) AS hm, min(school_id::text) AS school, min(member_role::text) AS mrole
          INTO rd FROM app.huvudman_reader();
        IF (rd.n = 1) IS DISTINCT FROM r.reader
           OR (r.reader AND (rd.school IS DISTINCT FROM r.school::text
                             OR rd.hm IS DISTINCT FROM 'RLS Kommun'
                             OR rd.mrole IS DISTINCT FROM CASE r.sub WHEN k THEN 'KOMMUNADMINISTRATOR' ELSE 'PLANERARE' END)) THEN
          RAISE EXCEPTION 'huvudman % %: huvudman_reader gave % rows (%, %, %)', via, r.label, rd.n, rd.hm, rd.school, rd.mrole;
        END IF;
      END IF;
      n := n + 1;
    END LOOP;
    SET LOCAL ROLE app_authenticated;
  END LOOP;
  PERFORM set_config('app.chosen_school_id', '', true);
  PERFORM set_config('request.headers', '', true);

  -- 261g, as the API role (the only one that may execute it).
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p)::text, true);
  IF (SELECT array_agg(school_id ORDER BY school_id) FROM app.my_schools()) IS DISTINCT FROM (SELECT array_agg(s ORDER BY s) FROM unnest(ARRAY[a, m, c]) s)
     OR EXISTS (SELECT 1 FROM app.my_schools() WHERE user_id IS NOT NULL OR role <> 'SCHOOL_ADMIN' OR admin_profile <> 'LASARE'
                   OR huvudman_name IS DISTINCT FROM 'RLS Kommun' OR huvudman_role IS DISTINCT FROM 'PLANERARE'
                   OR huvudman_member_id IS NULL OR is_current OR closed_reason IS NOT NULL) THEN
    RAISE EXCEPTION 'huvudman 261g: P''s my_schools said %', (SELECT json_agg(ms) FROM app.my_schools() ms);
  END IF;
  PERFORM set_config('app.chosen_school_id', m::text, true);
  IF (SELECT array_agg(school_id) FROM app.my_schools() WHERE is_current) IS DISTINCT FROM ARRAY[m] THEN
    RAISE EXCEPTION 'huvudman 261g: with the roller school named, P''s chosen school is %', (SELECT array_agg(school_id) FROM app.my_schools() WHERE is_current);
  END IF;
  PERFORM set_config('app.chosen_school_id', '', true);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p, 'rastra_closed_schools', json_build_object(c, 'sso_required'))::text, true);
  IF (SELECT closed_reason FROM app.my_schools() WHERE school_id = c) IS DISTINCT FROM 'sso_required' THEN
    RAISE EXCEPTION 'huvudman 261g: with C closed, my_schools said %', (SELECT json_agg(ms) FROM app.my_schools() ms);
  END IF;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', l)::text, true);
  IF (SELECT array_agg(school_id::text || '/' || role::text || '/' || (huvudman_member_id IS NOT NULL)::text) FROM app.my_schools())
     IS DISTINCT FROM ARRAY[a::text || '/TEACHER/false']
                      || (SELECT array_agg(s::text || '/SCHOOL_ADMIN/true' ORDER BY (SELECT name FROM "Schools" WHERE id = s), s)
                            FROM unnest(ARRAY[m, c]) s) THEN
    -- The order of the reader's entries is by the school's name, which L
    -- cannot read; compare as a set after the own row instead.
    IF (SELECT (array_agg(school_id))[1] FROM app.my_schools()) IS DISTINCT FROM a
       OR (SELECT count(*) FROM app.my_schools()) <> 3
       OR (SELECT count(*) FROM app.my_schools() WHERE school_id = a) <> 1
       OR (SELECT role FROM app.my_schools() WHERE school_id = a) <> 'TEACHER'
       OR (SELECT count(*) FROM app.my_schools() WHERE school_id IN (m, c) AND huvudman_member_id IS NOT NULL) <> 2 THEN
      RAISE EXCEPTION 'huvudman 261g: L''s my_schools said %', (SELECT json_agg(ms) FROM app.my_schools() ms);
    END IF;
  END IF;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', x)::text, true);
  IF EXISTS (SELECT 1 FROM app.my_schools()) THEN
    RAISE EXCEPTION 'huvudman 261g: a deactivated member lists %', (SELECT json_agg(ms) FROM app.my_schools() ms);
  END IF;
  -- G, whose own row in the roller school is deactivated: no own entry, and
  -- the roller school among the reader's three, as the resolver answers.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', g)::text, true);
  IF (SELECT count(*) FROM app.my_schools() WHERE user_id IS NOT NULL) <> 0
     OR (SELECT array_agg(school_id ORDER BY school_id) FROM app.my_schools() WHERE huvudman_member_id IS NOT NULL)
        IS DISTINCT FROM (SELECT array_agg(s ORDER BY s) FROM unnest(ARRAY[a, m, c]) s) THEN
    RAISE EXCEPTION 'huvudman 261g: G''s my_schools said %', (SELECT json_agg(ms) FROM app.my_schools() ms);
  END IF;
  PERFORM set_config('request.jwt.claims', '', true);
  RAISE NOTICE 'huvudman 261: % resolutions', n;
END $$;
ROLLBACK;

-- 261h
BEGIN;
DO $$
DECLARE
  h uuid;
  eg uuid;
  via text;
  hidden uuid[];
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000261')::text, true);
  SELECT "huvudmanId" INTO h FROM "HuvudmanMembers" WHERE "authId" = 'fe000000-0000-4000-8000-000000000261';
  PERFORM app.huvudman_request_school(h, 'rls-ersattande-school');
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001500')::text, true);
  eg := app.current_school_id();
  PERFORM app.school_accepts_huvudman(h);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000001502')::text, true);
  IF cardinality(app.current_student_replaced_lesson_ids()) = 0 THEN
    RAISE EXCEPTION 'huvudman 261h: the SvA pupil has no lesson hidden, so the reader''s answer proves nothing';
  END IF;
  FOREACH via IN ARRAY ARRAY['app_authenticated', 'authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000260')::text, true);
    PERFORM set_config('app.chosen_school_id', CASE via WHEN 'app_authenticated' THEN eg::text ELSE '' END, true);
    PERFORM set_config('request.headers', CASE via WHEN 'authenticated' THEN json_build_object('x-school-id', eg)::text ELSE '' END, true);
    IF app.current_school_id() IS DISTINCT FROM eg OR app.current_user_role() IS DISTINCT FROM 'SCHOOL_ADMIN' THEN
      RAISE EXCEPTION 'huvudman 261h: as %, P is not the reader at the replacing school (school %, role %)', via,
        app.current_school_id(), app.current_user_role();
    END IF;
    hidden := app.current_student_replaced_lesson_ids();
    IF hidden IS DISTINCT FROM '{}'::uuid[] THEN
      RAISE EXCEPTION 'huvudman 261h: as %, the reader has % lessons hidden by the pupils'' branch', via, cardinality(hidden);
    END IF;
    SET LOCAL ROLE app_authenticated;
  END LOOP;
  PERFORM set_config(g, '', true) FROM unnest(ARRAY['request.jwt.claims', 'app.chosen_school_id', 'request.headers']) g;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 262: huvudmannens läsare läser det skolans läsare läser, och inget
-- annat (20261212090000).
--
-- Every table with row security, for both API roles, the school named by
-- setting for app_authenticated and by header for authenticated:
--
--   262a  P naming the roller school reads exactly what the roller school's
--         läsare (…0115) reads, and P naming A what A's läsare (…0241, A
--         named) reads; the tables of a person's own rows (notices, devices,
--         feeds, a private schedule proposal, the read log) are compared by
--         whether they answer at all, and P's own notices, devices, feeds
--         and opt-outs are none. The huvudman's own tables answer for the
--         huvudman and are section 265's;
--   262b  P sees no row filed under another school than the one named;
--   262c  nothing named, a school H only asked for (B, D), a deactivated
--         member (X) and H2's planner naming the school H2 asked for (Q):
--         no row in any table but the huvudman's own (and X not even there).
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls262_a', :'school_a', true),
       set_config('app.test_rls262_b', :'school_b', true);
DO $$
DECLARE
  a uuid := current_setting('app.test_rls262_a')::uuid;
  b uuid := current_setting('app.test_rls262_b')::uuid;
  m uuid;
  d uuid;
  via text;
  t record;
  cs record;
  n bigint;
  twin_n bigint;
  key_col text;
  wrong text[] := '{}';
  cells int := 0;
  own_rows constant text[] := ARRAY['Notifications', 'NotificationOptOuts', 'PushDevices', 'CalendarFeeds',
                                    'ScheduleCandidateRuns', 'ScheduleCandidates', 'PersonalDataAccess'];
  -- Notifications aside: every administrator reads the school's notices
  -- (notifications_admin_select), the läsare and the reader alike.
  none_of_own constant text[] := ARRAY['NotificationOptOuts', 'PushDevices', 'CalendarFeeds'];
  huvudmans constant text[] := ARRAY['Huvudmen', 'HuvudmanMembers', 'HuvudmanSchools', 'HuvudmanSchoolRequests',
                                     'HuvudmanSchoolEvents', 'HuvudmanApiKeys'];
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  m := app.current_school_id();
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000266')::text, true);
  d := app.current_school_id();
  IF m IS NULL OR d IS NULL THEN
    RAISE EXCEPTION 'huvudman 262: the roller school or D is not there; fixtures did not run';
  END IF;

  FOREACH via IN ARRAY ARRAY['app_authenticated', 'authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    FOR cs IN
      SELECT * FROM (VALUES
        ('fe000000-0000-4000-8000-000000000260', m::text, m,          '00000000-0000-4000-8000-000000000115', '',      'P in the roller school'),
        ('fe000000-0000-4000-8000-000000000260', a::text, a,          'fe000000-0000-4000-8000-000000000241', a::text, 'P at A'),
        ('fe000000-0000-4000-8000-000000000261', m::text, m,          '00000000-0000-4000-8000-000000000115', '',      'K in the roller school'),
        ('fe000000-0000-4000-8000-000000000260', '',      NULL::uuid, NULL,                                   NULL,    'P naming nothing'),
        ('fe000000-0000-4000-8000-000000000260', b::text, NULL,       NULL,                                   NULL,    'P naming B'),
        ('fe000000-0000-4000-8000-000000000260', d::text, NULL,       NULL,                                   NULL,    'P naming D'),
        ('fe000000-0000-4000-8000-000000000262', a::text, NULL,       NULL,                                   NULL,    'X naming A'),
        ('fe000000-0000-4000-8000-000000000263', m::text, NULL,       NULL,                                   NULL,    'Q naming the roller school')
      ) v(sub, named, school, twin, twin_named, label)
    LOOP
      FOR t IN
        SELECT cl.relname AS tbl,
               EXISTS (SELECT 1 FROM pg_attribute at WHERE at.attrelid = cl.oid AND at.attname = 'schoolId' AND NOT at.attisdropped) AS has_school
          FROM pg_class cl JOIN pg_namespace ns ON ns.oid = cl.relnamespace
         WHERE ns.nspname = 'public' AND cl.relkind = 'r' AND cl.relrowsecurity
         ORDER BY 1
      LOOP
        key_col := CASE WHEN t.tbl = 'Schools' THEN 'id' WHEN t.has_school THEN 'schoolId' END;
        PERFORM set_config('request.jwt.claims', json_build_object('sub', cs.sub)::text, true);
        PERFORM set_config('app.chosen_school_id', CASE via WHEN 'app_authenticated' THEN cs.named ELSE '' END, true);
        PERFORM set_config('request.headers', CASE WHEN via = 'authenticated' AND cs.named <> '' THEN json_build_object('x-school-id', cs.named)::text ELSE '' END, true);
        IF app.current_school_id() IS DISTINCT FROM cs.school THEN
          RAISE EXCEPTION 'huvudman 262: % resolved to % as %', cs.label, app.current_school_id(), via;
        END IF;
        BEGIN
          IF key_col IS NOT NULL AND NOT (t.tbl = ANY (huvudmans)) THEN
            EXECUTE format('SELECT count(*) FROM %I WHERE %I IS DISTINCT FROM $1 AND %I IS NOT NULL', t.tbl, key_col, key_col)
              INTO n USING cs.school;
            IF n > 0 THEN
              wrong := wrong || format('%s as %s sees %s rows of %s filed under another school', cs.label, via, n, t.tbl);
            END IF;
          END IF;
          EXECUTE format('SELECT count(*) FROM %I', t.tbl) INTO n;
        EXCEPTION WHEN insufficient_privilege THEN
          n := -1;
        END;
        cells := cells + 1;

        -- 262c: no principal, so nothing (the huvudman's own tables aside,
        -- which answer for a membership; a deactivated one has none).
        IF cs.school IS NULL THEN
          IF n > 0 AND NOT (t.tbl = ANY (huvudmans) AND cs.label <> 'X naming A') THEN
            wrong := wrong || format('%s as %s reads %s rows of %s', cs.label, via, n, t.tbl);
          END IF;
          CONTINUE;
        END IF;
        CONTINUE WHEN t.tbl = ANY (huvudmans);
        IF t.tbl = ANY (none_of_own) AND n > 0 THEN
          wrong := wrong || format('%s as %s reads %s of its own %s, which it cannot have', cs.label, via, n, t.tbl);
        END IF;

        -- 262a: the school's läsare, who has a row there.
        PERFORM set_config('request.jwt.claims', json_build_object('sub', cs.twin)::text, true);
        PERFORM set_config('app.chosen_school_id', CASE via WHEN 'app_authenticated' THEN cs.twin_named ELSE '' END, true);
        PERFORM set_config('request.headers', CASE WHEN via = 'authenticated' AND cs.twin_named <> '' THEN json_build_object('x-school-id', cs.twin_named)::text ELSE '' END, true);
        IF app.current_school_id() IS DISTINCT FROM cs.school OR NOT app.current_user_may('PERSONAL', false)
           OR app.current_user_may('PERSONAL', true) THEN
          RAISE EXCEPTION 'huvudman 262: the läsare twin of % is not a läsare in its school', cs.label;
        END IF;
        BEGIN
          EXECUTE format('SELECT count(*) FROM %I', t.tbl) INTO twin_n;
        EXCEPTION WHEN insufficient_privilege THEN
          twin_n := -1;
        END;
        -- Users, through PostgREST, is a person's own row: the läsare reads
        -- theirs, the reader has none.
        IF t.tbl = ANY (own_rows) OR (t.tbl = 'Users' AND via = 'authenticated') THEN
          IF (n = -1) IS DISTINCT FROM (twin_n = -1) THEN
            wrong := wrong || format('%s as %s: %s answers %s, the läsare %s', cs.label, via, t.tbl, n, twin_n);
          END IF;
          IF t.tbl = 'Users' AND n > 0 THEN
            wrong := wrong || format('%s as %s reads %s Users rows through PostgREST', cs.label, via, n);
          END IF;
        ELSIF n IS DISTINCT FROM twin_n THEN
          wrong := wrong || format('%s as %s sees %s rows of %s, the läsare %s', cs.label, via, n, t.tbl, twin_n);
        END IF;
        cells := cells + 1;
      END LOOP;
    END LOOP;
    SET LOCAL ROLE app_authenticated;
  END LOOP;
  PERFORM set_config('app.chosen_school_id', '', true);
  PERFORM set_config('request.headers', '', true);

  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'huvudman 262: % of % cells wrong: %', cardinality(wrong), cells, array_to_string(wrong, '; ');
  END IF;
  RAISE NOTICE 'huvudman 262: % cells', cells;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 263: huvudmannens läsare skriver ingenting (20261212090000).
--
--   263a  every table with row security, from the catalogue (114), every
--         write verb, both API roles, P naming the roller school and A
--         through the setting and the header: an INSERT of a row of the
--         school read as its full administrator through the gateway's role
--         (who reads the most), an INSERT of a new row of the school with
--         every other column its default, and an UPDATE and a DELETE of
--         every row the reader's USING meets. None is admitted: refused by
--         row security (42501), denied by the role's grants, or meeting no
--         row. The counts are printed; the section fails when fewer than
--         114 tables, or fewer than 95 and 24 rows to copy, are tried;
--   263b  the functions the gateway's role may run that write on a
--         caller's behalf, called as P naming the roller school, refuse (an
--         error, or a refusal in the answer: the feed's NO_PRINCIPAL, the
--         referral's false) or write nothing: a calendar feed, a device, an integration key's
--         webhook secret, an SS12000 source's secrets, a leave request's
--         referral, the new mentors' notices, and the school's answers to a
--         huvudman. (The publication and grundschema locks take a lock and
--         answer the school's publish mode, and write nothing.)
--   263c  every function either API role may run that may write, from the
--         catalogue (see the block), refuses or writes nothing for P, or is
--         one of the gateway's jobs, named in the block, and writes no more
--         than it writes with no principal;
--   263d  (scripts/test/rls-owner-checks.sql, run as the tables' owner after
--         this file, since it reads every row past row security) every
--         write policy's WITH CHECK, and every USING a DELETE takes,
--         evaluated over every row as P, K and the läsare: none admits one.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls263_a', :'school_a', true),
       set_config('app.test_rls263_admin', :'admin_auth_id', true);
DO $$
DECLARE
  a uuid := current_setting('app.test_rls263_a')::uuid;
  admin_a constant text := current_setting('app.test_rls263_admin');
  p constant text := 'fe000000-0000-4000-8000-000000000260';
  m uuid;
  via text;
  d record;
  t record;
  key_col text;
  ins_cols text;
  upd_col text;
  school_ins boolean;
  stashed jsonb;
  n bigint;
  st text;
  msg text;
  outcome text;
  cmd text;
  probed int;
  copied int;
  tables int;
  floor_copies int;
  tried text[] := '{}';
  wrong text[] := '{}';
  others text[] := '{}';
  cells int := 0;
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  m := app.current_school_id();
  SELECT count(*) INTO tables
    FROM pg_class cl JOIN pg_namespace ns ON ns.oid = cl.relnamespace
   WHERE ns.nspname = 'public' AND cl.relkind = 'r' AND cl.relrowsecurity;

  FOREACH via IN ARRAY ARRAY['app_authenticated', 'authenticated'] LOOP
    FOR d IN SELECT * FROM (VALUES
        ('00000000-0000-4000-8000-000000000105', m, 'P in the roller school'),
        (admin_a,                               a, 'P at A')
      ) v(reader, school, label)
    LOOP
      probed := 0;
      copied := 0;
      -- Every table with row security, from the catalogue.
      FOR t IN
        SELECT cl.relname AS tbl,
               EXISTS (SELECT 1 FROM pg_attribute at WHERE at.attrelid = cl.oid AND at.attname = 'schoolId' AND NOT at.attisdropped) AS has_school
          FROM pg_class cl JOIN pg_namespace ns ON ns.oid = cl.relnamespace
         WHERE ns.nspname = 'public' AND cl.relkind = 'r' AND cl.relrowsecurity
         ORDER BY 1
      LOOP
        key_col := CASE WHEN t.tbl = 'Schools' THEN 'id' WHEN t.has_school THEN 'schoolId' END;
        -- A row to copy: one of the school's (or, without a "schoolId", any
        -- the administrator reads), read as its full administrator through
        -- the gateway's role, which reads the most.
        SET LOCAL ROLE app_authenticated;
        PERFORM set_config('request.jwt.claims', json_build_object('sub', d.reader)::text, true);
        PERFORM set_config('app.chosen_school_id', '', true);
        PERFORM set_config('request.headers', '', true);
        stashed := NULL;
        BEGIN
          IF key_col IS NULL THEN
            EXECUTE format('SELECT to_jsonb(x) FROM %I x LIMIT 1', t.tbl) INTO stashed;
          ELSE
            EXECUTE format('SELECT to_jsonb(x) FROM %I x WHERE x.%I = $1 LIMIT 1', t.tbl, key_col) INTO stashed USING d.school;
          END IF;
        EXCEPTION WHEN insufficient_privilege THEN stashed := NULL;
        END;
        EXECUTE format('SET LOCAL ROLE %I', via);
        SELECT string_agg(quote_ident(at.attname), ', ' ORDER BY at.attnum) INTO ins_cols
          FROM pg_attribute at
         WHERE at.attrelid = format('public.%I', t.tbl)::regclass AND at.attnum > 0 AND NOT at.attisdropped
           AND has_column_privilege(format('public.%I', t.tbl), at.attname, 'INSERT');
        SELECT quote_ident(at.attname) INTO upd_col
          FROM pg_attribute at
         WHERE at.attrelid = format('public.%I', t.tbl)::regclass AND at.attnum > 0 AND NOT at.attisdropped
           AND has_column_privilege(format('public.%I', t.tbl), at.attname, 'UPDATE')
         ORDER BY at.attnum LIMIT 1;
        school_ins := t.has_school AND has_column_privilege(format('public.%I', t.tbl), 'schoolId', 'INSERT');

        -- Now P, naming the school.
        PERFORM set_config('request.jwt.claims', json_build_object('sub', p)::text, true);
        PERFORM set_config('app.chosen_school_id', CASE via WHEN 'app_authenticated' THEN d.school::text ELSE '' END, true);
        PERFORM set_config('request.headers', CASE via WHEN 'authenticated' THEN json_build_object('x-school-id', d.school)::text ELSE '' END, true);
        IF app.current_school_id() IS DISTINCT FROM d.school OR app.current_user_id() IS NOT NULL THEN
          RAISE EXCEPTION 'huvudman 263a: P is not the reader in % as %', d.label, via;
        END IF;
        probed := probed + 1;
        IF stashed IS NOT NULL THEN copied := copied + 1; END IF;
        -- A copy of the row whole; a new row of the school, every other
        -- column its default (row security is asked before any NOT NULL);
        -- and every row the reader's USING lets an UPDATE and a DELETE meet.
        FOREACH cmd IN ARRAY ARRAY['insert a copy', 'insert a new row', 'update', 'delete'] LOOP
          CONTINUE WHEN cmd = 'insert a copy' AND stashed IS NULL;
          outcome := NULL;
          BEGIN
            IF cmd = 'insert a copy' THEN
              IF ins_cols IS NULL THEN
                outcome := 'denied';
              ELSE
                EXECUTE format('INSERT INTO %I (%s) SELECT %s FROM jsonb_populate_record(NULL::%I, $1)',
                               t.tbl, ins_cols, ins_cols, t.tbl) USING stashed;
                GET DIAGNOSTICS n = ROW_COUNT;
                outcome := CASE WHEN n = 1 THEN 'admitted' ELSE 'none' END;
              END IF;
            ELSIF cmd = 'insert a new row' THEN
              IF school_ins THEN
                EXECUTE format('INSERT INTO %I ("schoolId") VALUES ($1)', t.tbl) USING d.school;
              ELSE
                EXECUTE format('INSERT INTO %I DEFAULT VALUES', t.tbl);
              END IF;
              GET DIAGNOSTICS n = ROW_COUNT;
              outcome := CASE WHEN n = 1 THEN 'admitted' ELSE 'none' END;
            ELSIF cmd = 'update' THEN
              IF upd_col IS NULL THEN
                outcome := 'denied';
              ELSE
                EXECUTE format('UPDATE %I SET %s = %s', t.tbl, upd_col, upd_col);
                GET DIAGNOSTICS n = ROW_COUNT;
                outcome := CASE WHEN n = 0 THEN 'none' ELSE 'admitted' END;
              END IF;
            ELSE
              EXECUTE format('DELETE FROM %I', t.tbl);
              GET DIAGNOSTICS n = ROW_COUNT;
              outcome := CASE WHEN n = 0 THEN 'none' ELSE 'admitted' END;
            END IF;
            RAISE EXCEPTION USING ERRCODE = 'ZH263';
          EXCEPTION
            WHEN SQLSTATE 'ZH263' THEN NULL;
            WHEN unique_violation OR foreign_key_violation OR exclusion_violation OR check_violation OR not_null_violation THEN
              -- Past row security, which PostgreSQL checks before the
              -- table's constraints: the row reached them.
              outcome := 'admitted';
            WHEN insufficient_privilege THEN
              GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
              outcome := CASE WHEN msg LIKE '%row-level security%' THEN 'refused' ELSE 'denied' END;
            WHEN OTHERS THEN
              GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, msg = MESSAGE_TEXT;
              outcome := 'other ' || st;
          END;
          IF outcome LIKE 'other %' THEN
            others := others || format('%s %s %s', t.tbl, cmd, outcome);
          END IF;
          IF outcome = 'admitted' THEN
            wrong := wrong || format('%s as %s: %s %s was admitted', d.label, via, cmd, t.tbl);
          END IF;
          cells := cells + 1;
        END LOOP;
      END LOOP;
      -- Every table with row security is tried; the floors fail the section
      -- when a table, or a fixture row to copy, goes missing.
      IF probed <> tables OR tables < 114 THEN
        wrong := wrong || format('%s as %s: %s of %s tables with row security tried (at least 114)', d.label, via, probed, tables);
      END IF;
      floor_copies := CASE WHEN d.school = m THEN 95 ELSE 24 END;
      IF copied < floor_copies THEN
        wrong := wrong || format('%s as %s: only %s tables had a row to copy (at least %s)', d.label, via, copied, floor_copies);
      END IF;
      tried := tried || format('%s %s: %s tables, %s with a row to copy', via, d.label, probed, copied);
    END LOOP;
    SET LOCAL ROLE app_authenticated;
  END LOOP;
  PERFORM set_config('app.chosen_school_id', '', true);
  PERFORM set_config('request.headers', '', true);
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'huvudman 263a: % of % cells wrong: %', cardinality(wrong), cells, array_to_string(wrong, '; ');
  END IF;
  RAISE NOTICE 'huvudman 263a: % cells (%); refused by a trigger before row security: %', cells,
    array_to_string(tried, '; '), coalesce(nullif(array_to_string(others, ', '), ''), 'none');
END $$;
ROLLBACK;

BEGIN;
DO $$
DECLARE
  p constant text := 'fe000000-0000-4000-8000-000000000260';
  m uuid;
  pupil uuid;
  ikey uuid;
  src uuid;
  req uuid;
  feed uuid;
  h2 uuid;
  r record;
  refused text;
  ran text[] := '{}';
  wrong text[] := '{}';
BEGIN
  -- What the calls name, read as the roller school's full administrator.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  m := app.current_school_id();
  SELECT id INTO pupil FROM "Users" WHERE "schoolId" = m AND role = 'STUDENT' AND "isActive" ORDER BY "authId" LIMIT 1;
  SELECT id INTO ikey FROM "IntegrationApiKeys" WHERE "schoolId" = m ORDER BY "createdAt" LIMIT 1;
  SELECT id INTO src FROM "Ss12000Sources" WHERE "schoolId" = m ORDER BY "createdAt" LIMIT 1;
  SELECT id INTO req FROM "LeaveRequests" WHERE "schoolId" = m ORDER BY "createdAt" LIMIT 1;
  SELECT id INTO feed FROM "CalendarFeeds" WHERE "schoolId" = m ORDER BY "createdAt" LIMIT 1;
  SELECT "huvudmanId" INTO h2 FROM "HuvudmanSchoolRequests" WHERE "schoolId" = m LIMIT 1;
  IF pupil IS NULL OR ikey IS NULL OR src IS NULL OR h2 IS NULL THEN
    RAISE EXCEPTION 'huvudman 263b: the roller school lacks a pupil (%), a key (%), a source (%) or a question (%); fixtures did not run',
      pupil, ikey, src, h2;
  END IF;

  PERFORM set_config('request.jwt.claims', json_build_object('sub', p)::text, true);
  PERFORM set_config('app.chosen_school_id', m::text, true);
  IF app.current_school_id() IS DISTINCT FROM m OR app.current_user_id() IS NOT NULL THEN
    RAISE EXCEPTION 'huvudman 263b: P is not the reader in the roller school';
  END IF;

  -- Two refuse in their answer: a feed for nobody, and a referral that
  -- updates no request.
  IF app.calendar_feed_create(pupil, repeat('f', 64), 'sv') ->> 'refused' IS DISTINCT FROM 'NO_PRINCIPAL'
     OR app.calendar_feed_create(NULL, repeat('e', 64), 'sv') ->> 'refused' IS DISTINCT FROM 'NO_PRINCIPAL' THEN
    wrong := wrong || format('calendar_feed_create answered the reader %s', app.calendar_feed_create(NULL, repeat('d', 64), 'sv'));
  END IF;
  IF req IS NOT NULL AND app.leave_request_refer(req) THEN
    wrong := wrong || 'leave_request_refer referred a request for the reader'::text;
  END IF;

  FOR r IN SELECT * FROM (VALUES
      ('claim_device_push_token',            'SELECT app.claim_device_push_token(''ExponentPushToken[rls263]'', ''IOS'', ''sv'')'),
      ('integration_key_set_webhook_secret', format('SELECT app.integration_key_set_webhook_secret(%L::uuid, %L::bytea, %L::bytea, %L::bytea, %L)',
                                                    ikey, '\x00', '\x00', '\x00', 'k1')),
      ('ss12000_set_source_secret',          format('SELECT app.ss12000_set_source_secret(%L::uuid, %L::"Ss12000SecretKind", %L::bytea, %L::bytea, %L::bytea, %L)',
                                                    src, (SELECT enumlabel FROM pg_enum WHERE enumtypid = '"Ss12000SecretKind"'::regtype ORDER BY enumsortorder LIMIT 1),
                                                    '\x00', '\x00', '\x00', 'k1')),
      ('ss12000_clear_source_secrets',       format('SELECT app.ss12000_clear_source_secrets(%L::uuid, NULL)', src)),
      ('school_accepts_huvudman',            format('SELECT app.school_accepts_huvudman(%L::uuid)', h2)),
      ('school_declines_huvudman',           format('SELECT app.school_declines_huvudman(%L::uuid)', h2)),
      ('school_leaves_huvudman',             'SELECT app.school_leaves_huvudman()')
    ) v(fn, stmt)
  LOOP
    refused := NULL;
    BEGIN
      EXECUTE r.stmt;
      RAISE EXCEPTION USING ERRCODE = 'ZH263';
    EXCEPTION
      WHEN SQLSTATE 'ZH263' THEN refused := NULL;
      WHEN OTHERS THEN GET STACKED DIAGNOSTICS refused = RETURNED_SQLSTATE;
    END;
    IF refused IS NULL THEN
      wrong := wrong || format('%s ran for the reader', r.fn);
    END IF;
    ran := ran || format('%s %s', r.fn, coalesce(refused, 'ran'));
  END LOOP;

  -- Those that answer a caller with no row by doing nothing.
  IF (SELECT count(*) FROM app.leave_requests_tell_new_mentors()) <> 0 THEN
    wrong := wrong || 'leave_requests_tell_new_mentors told mentors for the reader'::text;
  END IF;
  IF feed IS NOT NULL THEN
    BEGIN
      PERFORM app.calendar_feed_revoke(feed);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
    PERFORM set_config('app.chosen_school_id', '', true);
    IF (SELECT "revokedAt" FROM "CalendarFeeds" WHERE id = feed) IS NOT NULL THEN
      wrong := wrong || 'calendar_feed_revoke revoked the school''s feed for the reader'::text;
    END IF;
  END IF;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  PERFORM set_config('app.chosen_school_id', '', true);
  IF EXISTS (SELECT 1 FROM "HuvudmanSchoolRequests" WHERE "schoolId" = m AND "huvudmanId" = h2) IS DISTINCT FROM true
     OR NOT EXISTS (SELECT 1 FROM "HuvudmanSchools" WHERE "schoolId" = m) THEN
    wrong := wrong || 'the reader changed the roller school''s huvudman'::text;
  END IF;
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'huvudman 263b: %', array_to_string(wrong, '; ');
  END IF;
  RAISE NOTICE 'huvudman 263b: %', array_to_string(ran, ', ');
END $$;
ROLLBACK;

-- 263c: every function either API role may run that may write (VOLATILE, in
-- app and public, triggers aside, from the catalogue), called as P naming
-- the roller school, through the setting and the header: once with every
-- argument NULL and once with the reader's school for every uuid. Each call
-- runs in a subtransaction that is rolled back after it, and either refuses
-- (an error) or returns; one that returns has written nothing, by the
-- transaction's own counters of rows inserted, updated and deleted
-- (pg_stat_xact_all_tables), or is one of the gateway's jobs below and
-- writes no more than the same call writes with no principal at all. The
-- jobs (gallring, the job runner, push receipts, the candidates' sweep,
-- SS12000 housekeeping and delivery) ask for no principal and no route
-- calls them: the reader gets nothing through them that an empty session
-- would not. They are named rather than inferred from the writes, since
-- which of them write depends on the arguments a call happens to get; a
-- function that writes for the reader and is not named fails, and so does
-- a name the catalogue no longer has. app.personal_data_read writes the
-- reader's own read log, by design (266). The counts are printed, with
-- floors.
BEGIN;
DO $$
DECLARE
  p constant text := 'fe000000-0000-4000-8000-000000000260';
  m uuid;
  via text;
  f record;
  variant int;
  args text;
  call text;
  before bigint;
  delta bigint;
  delta0 bigint;
  outcome text;
  called int;
  refused int;
  floor_calls int;
  counted bigint;
  jobs text[] := '{}';
  ran text[] := '{}';
  wrong text[] := '{}';
  writes_by_design constant text[] := ARRAY['app.personal_data_read'];
  job_functions constant text[] := ARRAY[
    'app.gallring_begin', 'app.gallring_claim_person', 'app.gallring_departed_due', 'app.gallring_finish',
    'app.gallring_pseudonymise', 'app.gallring_purge',
    'app.job_claim_finished', 'app.job_claim_nightly', 'app.job_run_settled',
    'app.push_due_receipts', 'app.push_receipts_settled', 'app.push_settle',
    'app.schedule_candidates_sweep',
    'app.ss12000_due_notifications', 'app.ss12000_due_sources', 'app.ss12000_housekeeping',
    'app.ss12000_notification_settled', 'app.ss12000_provider_housekeeping'];
  gone text;
BEGIN
  SELECT string_agg(j, ', ') INTO gone FROM unnest(job_functions) j
   WHERE NOT EXISTS (SELECT 1 FROM pg_proc p2 JOIN pg_namespace n ON n.oid = p2.pronamespace
                      WHERE n.nspname || '.' || p2.proname = j AND p2.provolatile = 'v'
                        AND has_function_privilege('app_authenticated', p2.oid, 'EXECUTE'));
  IF gone IS NOT NULL THEN
    wrong := wrong || format('the jobs named here are no longer in the catalogue as the API''s: %s', gone);
  END IF;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  m := app.current_school_id();
  FOREACH via IN ARRAY ARRAY['app_authenticated', 'authenticated'] LOOP
    EXECUTE format('SET LOCAL ROLE %I', via);
    called := 0;
    refused := 0;
    FOR f IN
      SELECT p2.oid, n.nspname || '.' || p2.proname AS name, p2.proargtypes::oid[] AS types
        FROM pg_proc p2 JOIN pg_namespace n ON n.oid = p2.pronamespace
       WHERE n.nspname IN ('app', 'public') AND p2.prokind = 'f' AND p2.provolatile = 'v'
         AND p2.prorettype <> 'trigger'::regtype
         AND has_function_privilege(via, p2.oid, 'EXECUTE')
       ORDER BY 2, p2.oid
    LOOP
      FOREACH variant IN ARRAY ARRAY[1, 2] LOOP
        SELECT coalesce(string_agg(
                 CASE WHEN variant = 1 THEN 'NULL::' || format_type(ty.oid, NULL)
                      WHEN ty.oid = 'uuid'::regtype THEN quote_literal(m) || '::uuid'
                      WHEN ty.oid = 'uuid[]'::regtype THEN 'ARRAY[' || quote_literal(m) || ']::uuid[]'
                      WHEN ty.oid = 'text'::regtype THEN '''rls263c'''
                      WHEN ty.oid IN ('integer'::regtype, 'bigint'::regtype, 'smallint'::regtype) THEN '1'
                      WHEN ty.oid = 'boolean'::regtype THEN 'true'
                      WHEN ty.oid = 'date'::regtype THEN 'current_date'
                      WHEN ty.oid = 'timestamp with time zone'::regtype THEN 'now()'
                      WHEN ty.oid = 'jsonb'::regtype THEN '''{}''::jsonb'
                      WHEN ty.oid = 'bytea'::regtype THEN '''\x00''::bytea'
                      WHEN ty.typtype = 'e' THEN quote_literal((SELECT e.enumlabel FROM pg_enum e WHERE e.enumtypid = ty.oid ORDER BY e.enumsortorder LIMIT 1)) || '::' || format_type(ty.oid, NULL)
                      ELSE 'NULL::' || format_type(ty.oid, NULL) END,
                 ', ' ORDER BY a.ord), '')
          INTO args
          FROM unnest(f.types) WITH ORDINALITY a(t, ord) JOIN pg_type ty ON ty.oid = a.t;
        call := format('SELECT count(*) FROM %s(%s) x', f.name, args);
        -- As P, naming the school as each role names it; then, for a call
        -- that wrote, as nobody.
        FOREACH outcome IN ARRAY ARRAY['reader', 'nobody'] LOOP
          EXIT WHEN outcome = 'nobody' AND (delta IS NULL OR delta = 0 OR f.name = ANY (writes_by_design));
          IF outcome = 'reader' THEN
            delta := NULL;
            PERFORM set_config('request.jwt.claims', json_build_object('sub', p)::text, true);
            PERFORM set_config('app.chosen_school_id', CASE via WHEN 'app_authenticated' THEN m::text ELSE '' END, true);
            PERFORM set_config('request.headers', CASE via WHEN 'authenticated' THEN json_build_object('x-school-id', m)::text ELSE '' END, true);
          ELSE
            delta0 := NULL;
            PERFORM set_config('request.jwt.claims', '', true);
            PERFORM set_config('app.chosen_school_id', '', true);
            PERFORM set_config('request.headers', '', true);
          END IF;
          BEGIN
            SELECT coalesce(sum(n_tup_ins + n_tup_upd + n_tup_del), 0) INTO before FROM pg_stat_xact_all_tables;
            EXECUTE call INTO counted;
            IF outcome = 'reader' THEN
              SELECT coalesce(sum(n_tup_ins + n_tup_upd + n_tup_del), 0) - before INTO delta FROM pg_stat_xact_all_tables;
            ELSE
              SELECT coalesce(sum(n_tup_ins + n_tup_upd + n_tup_del), 0) - before INTO delta0 FROM pg_stat_xact_all_tables;
            END IF;
            RAISE EXCEPTION USING ERRCODE = 'ZH26C';
          EXCEPTION
            WHEN SQLSTATE 'ZH26C' THEN NULL;
            WHEN OTHERS THEN
              IF outcome = 'reader' THEN refused := refused + 1; END IF;
          END;
          -- Whatever a call set, the next starts from its principal alone.
          PERFORM set_config(g, '', true)
             FROM unnest(ARRAY['app.service_school_id', 'app.service_huvudman_key_id', 'app.service_key_id', 'app.sync_school_id',
                               'app.service_key_lookup', 'app.login_join']) g;
        END LOOP;
        IF delta > 0 AND NOT f.name = ANY (writes_by_design) THEN
          IF NOT f.name = ANY (job_functions) THEN
            wrong := wrong || format('%s as %s wrote %s rows for the reader, and is no job named here', call, via, delta);
          ELSIF delta0 IS NOT NULL AND delta0 >= delta THEN
            jobs := jobs || format('%s (%s rows, as many with no principal)', f.name, delta);
          ELSE
            wrong := wrong || format('%s as %s wrote %s rows for the reader, %s with no principal', call, via, delta, coalesce(delta0::text, 'an error'));
          END IF;
        END IF;
        called := called + 1;
      END LOOP;
    END LOOP;
    floor_calls := CASE via WHEN 'app_authenticated' THEN 2 * 54 ELSE 2 * 12 END;
    IF called < floor_calls THEN
      wrong := wrong || format('as %s only %s calls were made (at least %s)', via, called, floor_calls);
    END IF;
    ran := ran || format('%s: %s calls of %s functions, %s refused', via, called, called / 2, refused);
    SET LOCAL ROLE app_authenticated;
  END LOOP;
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM set_config('app.chosen_school_id', '', true);
  PERFORM set_config('request.headers', '', true);
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'huvudman 263c: %', array_to_string(wrong, '; ');
  END IF;
  RAISE NOTICE 'huvudman 263c: %; the jobs'' writes, the same with no principal: %', array_to_string(ran, '; '),
    coalesce(nullif(array_to_string(jobs, ', '), ''), 'none');
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 264: en förfalskad header ger ingen läsare (20261212090000).
--
-- Through PostgREST's role and its header alone, as a client would forge
-- it: every helper, and every table with row security read whole.
--
--   264a  no principal, and no row in any table but the huvudman's own,
--         for a school the login has neither a row nor a membership at
--         (the läslogg school), a school its huvudman only asked for (D), a
--         deactivated membership (X naming A), a member of a huvudman that
--         does not own the school (Q naming the roller school), and a school
--         whose ownership ended in this transaction (C, which left);
--   264b  a school where the login has a row of another role: L naming A is
--         the teacher there, and reads what a teacher at A reads (…0244
--         naming A), not what the huvudman's reader would.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls264_a', :'school_a', true);
DO $$
DECLARE
  a uuid := current_setting('app.test_rls264_a')::uuid;
  m uuid;
  c uuid;
  d uuid;
  ll uuid;
  cs record;
  t record;
  got record;
  n bigint;
  twin_n bigint;
  wrong text[] := '{}';
  cells int := 0;
  huvudmans constant text[] := ARRAY['Huvudmen', 'HuvudmanMembers', 'HuvudmanSchools', 'HuvudmanSchoolRequests',
                                     'HuvudmanSchoolEvents', 'HuvudmanApiKeys'];
  own_rows constant text[] := ARRAY['Notifications', 'NotificationOptOuts', 'PushDevices', 'CalendarFeeds',
                                    'ScheduleCandidateRuns', 'ScheduleCandidates', 'PersonalDataAccess', 'Users'];
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  m := app.current_school_id();
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000266')::text, true);
  d := app.current_school_id();
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000121')::text, true);
  ll := app.current_school_id();
  -- C leaves its huvudman, in this transaction: the reader is gone at the
  -- next statement.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000269')::text, true);
  c := app.current_school_id();
  PERFORM app.school_leaves_huvudman();
  IF m IS NULL OR d IS NULL OR ll IS NULL OR c IS NULL OR ll IN (a, m, c, d) THEN
    RAISE EXCEPTION 'huvudman 264: schools m %, d %, läslogg %, c %; fixtures did not run', m, d, ll, c;
  END IF;

  SET LOCAL ROLE authenticated;
  PERFORM set_config('app.chosen_school_id', '', true);
  FOR cs IN
    SELECT * FROM (VALUES
      ('fe000000-0000-4000-8000-000000000260', ll, NULL::uuid, NULL::text, '264a P names a school it has nothing at'),
      ('fe000000-0000-4000-8000-000000000260', d,  NULL,       NULL,       '264a P names D, only asked for'),
      ('fe000000-0000-4000-8000-000000000262', a,  NULL,       NULL,       '264a X, deactivated, names A'),
      ('fe000000-0000-4000-8000-000000000263', m,  NULL,       NULL,       '264a Q names the school H2 asked for'),
      ('fe000000-0000-4000-8000-000000000260', c,  NULL,       NULL,       '264a P names C, which left'),
      ('fe000000-0000-4000-8000-000000000264', a,  a,          'fe000000-0000-4000-8000-000000000244', '264b L names A, a teacher there')
    ) v(sub, named, school, twin, label)
  LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', cs.sub, 'role', 'authenticated')::text, true);
    PERFORM set_config('request.headers', json_build_object('x-school-id', cs.named, 'accept', '*/*')::text, true);
    SELECT app.current_user_id() AS id, app.current_school_id() AS school, app.current_user_role()::text AS role,
           app.current_user_may('PERSONAL', false) AS may_read, app.current_user_decides() AS decides
      INTO got;
    IF cs.school IS NULL AND (got.id IS NOT NULL OR got.school IS NOT NULL OR got.role IS NOT NULL OR got.may_read OR got.decides) THEN
      RAISE EXCEPTION 'huvudman %: resolved to %', cs.label, row_to_json(got);
    END IF;
    IF cs.school IS NOT NULL AND (got.school IS DISTINCT FROM cs.school OR got.role IS DISTINCT FROM 'TEACHER'
                                  OR got.id IS NULL OR got.may_read) THEN
      RAISE EXCEPTION 'huvudman %: resolved to %, not the teacher''s own row', cs.label, row_to_json(got);
    END IF;
    FOR t IN
      SELECT cl.relname AS tbl FROM pg_class cl JOIN pg_namespace ns ON ns.oid = cl.relnamespace
       WHERE ns.nspname = 'public' AND cl.relkind = 'r' AND cl.relrowsecurity ORDER BY 1
    LOOP
      PERFORM set_config('request.jwt.claims', json_build_object('sub', cs.sub, 'role', 'authenticated')::text, true);
      PERFORM set_config('request.headers', json_build_object('x-school-id', cs.named)::text, true);
      BEGIN
        EXECUTE format('SELECT count(*) FROM %I', t.tbl) INTO n;
      EXCEPTION WHEN insufficient_privilege THEN n := -1;
      END;
      cells := cells + 1;
      IF cs.school IS NULL THEN
        IF n > 0 AND NOT t.tbl = ANY (huvudmans) THEN
          wrong := wrong || format('%s reads %s rows of %s', cs.label, n, t.tbl);
        END IF;
        CONTINUE;
      END IF;
      PERFORM set_config('request.jwt.claims', json_build_object('sub', cs.twin, 'role', 'authenticated')::text, true);
      BEGIN
        EXECUTE format('SELECT count(*) FROM %I', t.tbl) INTO twin_n;
      EXCEPTION WHEN insufficient_privilege THEN twin_n := -1;
      END;
      IF t.tbl = ANY (own_rows) THEN
        IF (n = -1) IS DISTINCT FROM (twin_n = -1) THEN
          wrong := wrong || format('%s: %s answers %s, the teacher %s', cs.label, t.tbl, n, twin_n);
        END IF;
      ELSIF n IS DISTINCT FROM twin_n THEN
        wrong := wrong || format('%s sees %s rows of %s, a teacher at A %s', cs.label, n, t.tbl, twin_n);
      END IF;
    END LOOP;
  END LOOP;
  SET LOCAL ROLE app_authenticated;
  PERFORM set_config('request.headers', '', true);
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'huvudman 264: % of % cells wrong: %', cardinality(wrong), cells, array_to_string(wrong, '; ');
  END IF;
  RAISE NOTICE 'huvudman 264: % cells', cells;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 265: huvudmannens egna tabeller, och vem som frågar, svarar och
-- avslutar (20261212090000).
--
--   265a  reads: a member reads their huvudman, its members, schools,
--         questions and history, and nobody else's; only the
--         kommunadministratör reads the keys; a deactivated member reads
--         nothing; a school's administrators read their own school's
--         ownership, questions and history, the names of who owns or asks;
--         its deciders (rektor or full, as the gateway's Dataskydd), through
--         the three functions, the owner's readers and keys and the school's
--         history with its huvudmän; its läsare does not, nor does anybody
--         else at the school: its teacher, pupil and guardian read none of
--         the six;
--   265b  the kommunadministratör writes members (never a login, never
--         another huvudman's) and keys (read scopes only; a revoked key
--         stays revoked); a planner writes neither; the login only through
--         app.huvudman_member_takes_login, and only for the
--         kommunadministratör's own huvudman;
--   265c  the questions: by slug, once; HM409 for the huvudman's own school
--         and for a school with another huvudman, HM404 for no school, HM403
--         for anybody but a kommunadministratör of the huvudman;
--   265d  the answers: the school's decider says yes (the huvudman owns the
--         school from the next statement, and the question is gone), no, or
--         leaves; nobody else at the school may, the huvudman's reader
--         included; a yes to a second huvudman is HM409; the
--         kommunadministratör withdraws and lets go. Every act is in the
--         history, by its side.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls265_a', :'school_a', true),
       set_config('app.test_rls265_b', :'school_b', true);
DO $$
DECLARE
  a uuid := current_setting('app.test_rls265_a')::uuid;
  b uuid := current_setting('app.test_rls265_b')::uuid;
  m uuid;
  c uuid;
  d uuid;
  ll uuid;
  h uuid;
  h2 uuid;
  newbie uuid;
  qid uuid;
  key uuid;
  r record;
  st text;
  n bigint;
  wrong text[] := '{}';
  k constant text := 'fe000000-0000-4000-8000-000000000261';
  p constant text := 'fe000000-0000-4000-8000-000000000260';
  k2 constant text := 'fe000000-0000-4000-8000-000000000268';

  -- The outcome of a statement: 'ok' and its row count, or the SQLSTATE.
  outcome text;
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  m := app.current_school_id();
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000269')::text, true);
  c := app.current_school_id();
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000266')::text, true);
  d := app.current_school_id();
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000121')::text, true);
  ll := app.current_school_id();

  -- 265a, as each reader with nothing named.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k)::text, true);
  SELECT id INTO h FROM "Huvudmen";
  FOR r IN SELECT * FROM (VALUES
      -- sub, Huvudmen, members, schools, questions, history, keys, case
      (k,                                       1, 6, 3, 2, 8, 2, 'K, H''s kommunadministratör'),
      (p,                                       1, 6, 3, 2, 8, 0, 'P, H''s planner'),
      ('fe000000-0000-4000-8000-000000000262',  0, 0, 0, 0, 0, 0, 'X, deactivated'),
      ('fe000000-0000-4000-8000-000000000263',  1, 2, 0, 1, 1, 0, 'Q, H2''s planner'),
      (k2,                                      1, 2, 0, 1, 1, 1, 'K2, H2''s kommunadministratör'),
      ('00000000-0000-4000-8000-000000000105',  2, 0, 1, 1, 3, 0, 'the roller school''s full administrator'),
      ('00000000-0000-4000-8000-000000000115',  2, 0, 1, 1, 3, 0, 'the roller school''s läsare'),
      ('fe000000-0000-4000-8000-000000000266',  1, 0, 0, 1, 1, 0, 'D''s full administrator'),
      ('00000000-0000-4000-8000-000000000121',  0, 0, 0, 0, 0, 0, 'the läslogg school''s administrator'),
      -- Nobody at an owned school but its administrators reads its huvudman.
      ('00000000-0000-4000-8000-000000000111',  0, 0, 0, 0, 0, 0, 'a teacher of the roller school'),
      ('00000000-0000-4000-8000-000000000112',  0, 0, 0, 0, 0, 0, 'a pupil of the roller school'),
      ('00000000-0000-4000-8000-000000000113',  0, 0, 0, 0, 0, 0, 'a guardian of the roller school')
    ) v(sub, huvudmen, members, schools, questions, history, keys, label)
  LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', r.sub)::text, true);
    IF (SELECT count(*) FROM "Huvudmen") <> r.huvudmen OR (SELECT count(*) FROM "HuvudmanMembers") <> r.members
       OR (SELECT count(*) FROM "HuvudmanSchools") <> r.schools OR (SELECT count(*) FROM "HuvudmanSchoolRequests") <> r.questions
       OR (SELECT count(*) FROM "HuvudmanSchoolEvents") <> r.history OR (SELECT count(*) FROM "HuvudmanApiKeys") <> r.keys THEN
      wrong := wrong || format('265a %s reads %s/%s/%s/%s/%s/%s, expected %s/%s/%s/%s/%s/%s', r.label,
        (SELECT count(*) FROM "Huvudmen"), (SELECT count(*) FROM "HuvudmanMembers"), (SELECT count(*) FROM "HuvudmanSchools"),
        (SELECT count(*) FROM "HuvudmanSchoolRequests"), (SELECT count(*) FROM "HuvudmanSchoolEvents"), (SELECT count(*) FROM "HuvudmanApiKeys"),
        r.huvudmen, r.members, r.schools, r.questions, r.history, r.keys);
    END IF;
  END LOOP;
  -- The owner's readers and keys, for the school's deciders only.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  IF (SELECT count(*) FROM app.school_huvudman_readers()) <> 6 OR (SELECT count(*) FROM app.school_huvudman_keys()) <> 2
     OR EXISTS (SELECT 1 FROM app.school_huvudman_readers() WHERE first_name IS NULL OR role IS NULL) THEN
    wrong := wrong || format('265a the roller school''s rektor reads %s readers and %s keys of its huvudman',
      (SELECT count(*) FROM app.school_huvudman_readers()), (SELECT count(*) FROM app.school_huvudman_keys()));
  END IF;
  -- Who of them has a row of their own here: G, deactivated; nobody else.
  IF (SELECT string_agg(last_name || ':' || coalesce(own_row, '-'), ',' ORDER BY last_name)
        FROM app.school_huvudman_readers() WHERE own_row IS NOT NULL) IS DISTINCT FROM 'Vårdnadshavare:INACTIVE' THEN
    wrong := wrong || format('265a the readers'' own rows in the roller school are %s',
      (SELECT json_agg(x) FROM app.school_huvudman_readers() x));
  END IF;
  IF (SELECT count(*) FROM app.school_huvudman_history(100)) <> 3
     OR EXISTS (SELECT 1 FROM app.school_huvudman_history(100) WHERE huvudman_name IS NULL) THEN
    wrong := wrong || format('265a the roller school''s history with its huvudmän: %s',
      (SELECT json_agg(x) FROM app.school_huvudman_history(100) x));
  END IF;
  -- The huvudman's side: its schools with their names, and its history.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p)::text, true);
  IF (SELECT string_agg(state || ':' || CASE WHEN school_id = a THEN 'A' ELSE slug END, ',' ORDER BY state, CASE WHEN school_id = a THEN 'A' ELSE slug END)
        FROM app.huvudman_schools(h))
       IS DISTINCT FROM 'OWNED:A,OWNED:rls-huvudman-c,OWNED:rls-roller-school,REQUESTED:rls-fixture-school,REQUESTED:rls-huvudman-d'
     OR (SELECT count(*) FROM app.huvudman_history(h, 100)) <> 8
     OR (SELECT count(*) FROM app.huvudman_history(h, 1)) <> 1 THEN
    wrong := wrong || format('265a P reads H''s schools %s and %s events',
      (SELECT string_agg(state || ':' || slug, ',') FROM app.huvudman_schools(h)), (SELECT count(*) FROM app.huvudman_history(h, 100)));
  END IF;
  FOREACH st IN ARRAY ARRAY['fe000000-0000-4000-8000-000000000263', 'fe000000-0000-4000-8000-000000000262',
                             '00000000-0000-4000-8000-000000000105'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', st)::text, true);
    IF EXISTS (SELECT 1 FROM app.huvudman_schools(h)) OR EXISTS (SELECT 1 FROM app.huvudman_history(h, 100)) THEN
      wrong := wrong || format('265a %s, no member of H, reads H''s schools or history', st);
    END IF;
  END LOOP;
  FOREACH st IN ARRAY ARRAY['fe000000-0000-4000-8000-000000000266', '00000000-0000-4000-8000-000000000121',
                             '00000000-0000-4000-8000-000000000112', '00000000-0000-4000-8000-000000000115', k] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', st)::text, true);
    IF EXISTS (SELECT 1 FROM app.school_huvudman_readers()) OR EXISTS (SELECT 1 FROM app.school_huvudman_keys())
       OR (st = '00000000-0000-4000-8000-000000000115' AND EXISTS (SELECT 1 FROM app.school_huvudman_history(100))) THEN
      wrong := wrong || format('265a %s reads a huvudman''s readers or keys of a school it does not decide for, or that has none', st);
    END IF;
  END LOOP;

  -- 265b, the kommunadministratör's writes.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k2)::text, true);
  SELECT id INTO h2 FROM "Huvudmen";
  SELECT id INTO qid FROM "HuvudmanMembers" WHERE "authId" = 'fe000000-0000-4000-8000-000000000263';
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k)::text, true);
  SELECT id INTO newbie FROM "HuvudmanMembers" WHERE "authId" IS NULL;
  IF h IS NULL OR h2 IS NULL OR newbie IS NULL OR qid IS NULL OR h = h2 THEN
    RAISE EXCEPTION 'huvudman 265: H %, H2 %, the newcomer %, Q %; fixtures did not run', h, h2, newbie, qid;
  END IF;
  FOR r IN SELECT * FROM (VALUES
      (k,  format('INSERT INTO "HuvudmanMembers" ("huvudmanId", email, "firstName", "lastName", role) VALUES (%L, ''rls265-new@example.invalid'', ''Ny'', ''Planerare'', ''PLANERARE'')', h), 'ok 1', 'K adds a planner to H'),
      (k,  format('INSERT INTO "HuvudmanMembers" ("huvudmanId", email, "firstName", "lastName", role) VALUES (%L, ''rls265-h2@example.invalid'', ''Ny'', ''Planerare'', ''PLANERARE'')', h2), '42501', 'K adds a planner to H2'),
      (k,  format('INSERT INTO "HuvudmanMembers" ("huvudmanId", "authId", email, "firstName", "lastName", role, "invitedAt") VALUES (%L, gen_random_uuid(), ''rls265-login@example.invalid'', ''Ny'', ''Login'', ''PLANERARE'', now())', h), '42501', 'K adds a member with a login'),
      (k,  format('UPDATE "HuvudmanMembers" SET role = ''KOMMUNADMINISTRATOR'' WHERE id = %L', newbie), 'ok 1', 'K makes the newcomer a kommunadministratör'),
      (k,  format('UPDATE "HuvudmanMembers" SET "isActive" = false WHERE id = %L', qid), 'ok 0', 'K deactivates H2''s planner'),
      (k,  format('UPDATE "HuvudmanMembers" SET "authId" = gen_random_uuid() WHERE id = %L', newbie), '42501', 'K hands a login by hand'),
      (k,  format('UPDATE "HuvudmanMembers" SET email = ''rls265-moved@example.invalid'' WHERE id = %L', newbie), '42501', 'K moves an address'),
      (k,  format('DELETE FROM "HuvudmanMembers" WHERE id = %L', newbie), '42501', 'K deletes a member'),
      (p,  format('INSERT INTO "HuvudmanMembers" ("huvudmanId", email, "firstName", "lastName", role) VALUES (%L, ''rls265-p@example.invalid'', ''Ny'', ''Planerare'', ''PLANERARE'')', h), '42501', 'P adds a member'),
      (p,  format('UPDATE "HuvudmanMembers" SET "isActive" = false WHERE "huvudmanId" = %L', h), 'ok 0', 'P deactivates H''s members'),
      (p,  format('SELECT app.huvudman_member_takes_login(%L, gen_random_uuid())', newbie), 'HM403', 'P hands the newcomer a login'),
      (k,  format('SELECT app.huvudman_member_takes_login(%L, gen_random_uuid())', qid), 'HM403', 'K hands H2''s planner a login'),
      (k,  format('SELECT app.huvudman_member_takes_login(%L, NULL)', newbie), 'HM400', 'K hands the newcomer no login'),
      (k,  format('SELECT app.huvudman_member_takes_login(%L, %L)', newbie, p), '23505', 'K hands the newcomer P''s login, which H''s member holds'),
      (k,  format('SELECT app.huvudman_member_takes_login(%L, ''fe000000-0000-4000-8000-000000000270'')', newbie), 'ok 1', 'K hands the newcomer a login'),
      (k,  format('INSERT INTO "HuvudmanApiKeys" ("huvudmanId", name, "keyHash", scopes) VALUES (%L, ''rls265'', repeat(''1'', 64), ARRAY[''persons.read''])', h), 'ok 1', 'K makes a key'),
      (k,  format('INSERT INTO "HuvudmanApiKeys" ("huvudmanId", name, "keyHash", scopes) VALUES (%L, ''rls265'', repeat(''2'', 64), ARRAY[''attendances.read''])', h), '23514', 'K makes a key that reads attendance'),
      (k,  format('INSERT INTO "HuvudmanApiKeys" ("huvudmanId", name, "keyHash", scopes) VALUES (%L, ''rls265'', repeat(''3'', 64), ARRAY[''subscriptions.write''])', h), '23514', 'K makes a key that subscribes'),
      (k,  format('INSERT INTO "HuvudmanApiKeys" ("huvudmanId", name, "keyHash", scopes) VALUES (%L, ''rls265'', repeat(''4'', 64), ARRAY[''persons.read''])', h2), '42501', 'K makes H2 a key'),
      (k,  format('INSERT INTO "HuvudmanApiKeys" ("huvudmanId", name, "keyHash", scopes, "revokedAt") VALUES (%L, ''rls265'', repeat(''5'', 64), ARRAY[''persons.read''], now())', h), '42501', 'K makes a key born revoked'),
      (k,  'UPDATE "HuvudmanApiKeys" SET "revokedAt" = now() WHERE name = ''RLS H nyckel''', 'ok 1', 'K revokes H''s key'),
      (k,  'UPDATE "HuvudmanApiKeys" SET "revokedAt" = NULL WHERE name = ''RLS H återkallad''', 'HM409', 'K brings a revoked key back'),
      (k,  'UPDATE "HuvudmanApiKeys" SET name = ''omdöpt'' WHERE name = ''RLS H återkallad''', '42501', 'K renames a key'),
      (k2, 'UPDATE "HuvudmanApiKeys" SET "revokedAt" = now() WHERE name = ''rls265''', 'ok 0', 'K2 revokes H''s new key'),
      (p,  format('INSERT INTO "HuvudmanApiKeys" ("huvudmanId", name, "keyHash", scopes) VALUES (%L, ''rls265p'', repeat(''6'', 64), ARRAY[''persons.read''])', h), '42501', 'P makes a key'),
      (k,  format('INSERT INTO "HuvudmanSchools" ("schoolId", "huvudmanId") VALUES (%L, %L)', b, h), '42501', 'K owns B by hand'),
      (k,  format('INSERT INTO "HuvudmanSchoolEvents" ("huvudmanId", "schoolId", kind) VALUES (%L, %L, ''JOINED'')', h, b), '42501', 'K writes the history by hand'),
      ('00000000-0000-4000-8000-000000000105', format('DELETE FROM "HuvudmanSchools" WHERE "schoolId" = %L', m), '42501', 'the roller school''s full administrator ends it by hand')
    ) v(sub, stmt, expected, label)
  LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', r.sub)::text, true);
    BEGIN
      EXECUTE r.stmt;
      GET DIAGNOSTICS n = ROW_COUNT;
      outcome := 'ok ' || n;
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS outcome = RETURNED_SQLSTATE;
    END;
    -- A function's SELECT counts its one row.
    IF outcome IS DISTINCT FROM r.expected THEN
      wrong := wrong || format('265b %s: %s, expected %s', r.label, outcome, r.expected);
    END IF;
  END LOOP;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k)::text, true);
  IF (SELECT "authId"::text || '/' || ("invitedAt" IS NOT NULL)::text FROM "HuvudmanMembers" WHERE id = newbie)
     IS DISTINCT FROM 'fe000000-0000-4000-8000-000000000270/true' THEN
    wrong := wrong || '265b the newcomer''s login is not the one handed, or not stamped'::text;
  END IF;

  -- 265c, the questions.
  FOR r IN SELECT * FROM (VALUES
      (k,  h,  'rls-huvudman-d',     'ok',    'K asks again for D'),
      (k,  h,  'rls-roller-school',  'HM409', 'K asks for the roller school, which H owns'),
      (k,  h,  'rls-no-such-school', 'HM404', 'K asks for no school'),
      (k,  h2, 'rls-laslogg-school', 'HM403', 'K asks for H2'),
      (p,  h,  'rls-laslogg-school', 'HM403', 'P asks'),
      (k2, h2, 'rls-roller-school',  'HM409', 'K2 asks for a school H owns'),
      (k,  h,  'rls-laslogg-school', 'ok',    'K asks for the läslogg school')
    ) v(sub, huvudman, slug, expected, label)
  LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', r.sub)::text, true);
    BEGIN
      PERFORM app.huvudman_request_school(r.huvudman, r.slug);
      outcome := 'ok';
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS outcome = RETURNED_SQLSTATE;
    END;
    IF outcome IS DISTINCT FROM r.expected THEN
      wrong := wrong || format('265c %s: %s, expected %s', r.label, outcome, r.expected);
    END IF;
  END LOOP;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k)::text, true);
  IF (SELECT count(*) FROM "HuvudmanSchoolRequests" WHERE "schoolId" = d) <> 1
     OR (SELECT count(*) FROM "HuvudmanSchoolEvents" WHERE "schoolId" = d AND kind = 'REQUESTED') <> 1
     OR (SELECT count(*) FROM "HuvudmanSchoolRequests" WHERE "schoolId" = ll) <> 1
     OR (SELECT count(*) FROM "HuvudmanSchoolEvents" WHERE "schoolId" = ll AND kind = 'REQUESTED' AND "byMemberId" IS NOT NULL) <> 1 THEN
    wrong := wrong || '265c a question was not asked once, or not written in the history by its member'::text;
  END IF;

  -- 265d, the answers.
  FOR r IN SELECT * FROM (VALUES
      ('fe000000-0000-4000-8000-000000000267', format('SELECT app.school_accepts_huvudman(%L)', h),  'HM403', 'D''s schemaläggare says yes'),
      ('00000000-0000-4000-8000-000000000115', format('SELECT app.school_declines_huvudman(%L)', h2), 'HM403', 'the roller school''s läsare says no'),
      ('00000000-0000-4000-8000-000000000115', 'SELECT app.school_leaves_huvudman()',                  'HM403', 'the roller school''s läsare leaves'),
      ('00000000-0000-4000-8000-000000000105', format('SELECT app.school_accepts_huvudman(%L)', h2), 'HM409', 'the roller school says yes to a second huvudman'),
      ('00000000-0000-4000-8000-000000000105', format('SELECT app.school_declines_huvudman(%L)', h2), 'ok',    'the roller school says no to H2'),
      ('00000000-0000-4000-8000-000000000105', format('SELECT app.school_declines_huvudman(%L)', h2), 'HM404', 'the roller school says no again'),
      ('fe000000-0000-4000-8000-000000000266', format('SELECT app.school_accepts_huvudman(%L)', h),  'ok',    'D says yes to H'),
      ('fe000000-0000-4000-8000-000000000266', format('SELECT app.school_accepts_huvudman(%L)', h),  'HM404', 'D says yes again'),
      (k,                                      format('SELECT app.huvudman_withdraw_request(%L, %L)', h, b), 'ok', 'K withdraws the question to B'),
      (k,                                      format('SELECT app.huvudman_withdraw_request(%L, %L)', h, b), 'HM404', 'K withdraws it again'),
      (p,                                      format('SELECT app.huvudman_release_school(%L, %L)', h, a), 'HM403', 'P lets A go'),
      (k,                                      format('SELECT app.huvudman_release_school(%L, %L)', h, a), 'ok',    'K lets A go'),
      (k,                                      format('SELECT app.huvudman_release_school(%L, %L)', h, a), 'HM404', 'K lets A go again'),
      ('fe000000-0000-4000-8000-000000000269', 'SELECT app.school_leaves_huvudman()',                  'ok',    'C leaves H'),
      ('fe000000-0000-4000-8000-000000000269', 'SELECT app.school_leaves_huvudman()',                  'HM404', 'C leaves again')
    ) v(sub, stmt, expected, label)
  LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', r.sub)::text, true);
    PERFORM set_config('app.chosen_school_id', '', true);
    BEGIN
      EXECUTE r.stmt;
      outcome := 'ok';
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS outcome = RETURNED_SQLSTATE;
    END;
    IF outcome IS DISTINCT FROM r.expected THEN
      wrong := wrong || format('265d %s: %s, expected %s', r.label, outcome, r.expected);
    END IF;
  END LOOP;
  -- The huvudman's reader says nothing for the school either.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p)::text, true);
  PERFORM set_config('app.chosen_school_id', m::text, true);
  BEGIN
    PERFORM app.school_leaves_huvudman();
    wrong := wrong || '265d H''s reader made the roller school leave H'::text;
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  -- What the answers did, from the next statement: P reads D, and not A or C.
  PERFORM set_config('app.chosen_school_id', d::text, true);
  IF app.current_school_id() IS DISTINCT FROM d THEN
    wrong := wrong || '265d D said yes, and P does not read it'::text;
  END IF;
  PERFORM set_config('app.chosen_school_id', a::text, true);
  IF app.current_school_id() IS NOT NULL THEN
    wrong := wrong || '265d H let A go, and P still reads it'::text;
  END IF;
  PERFORM set_config('app.chosen_school_id', c::text, true);
  IF app.current_school_id() IS NOT NULL THEN
    wrong := wrong || '265d C left H, and P still reads it'::text;
  END IF;
  PERFORM set_config('app.chosen_school_id', '', true);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', k)::text, true);
  IF (SELECT string_agg(kind::text || ':' || CASE WHEN "byUserId" IS NOT NULL THEN 'school' WHEN "byMemberId" IS NOT NULL THEN 'huvudman' ELSE '-' END,
                        ',' ORDER BY "schoolId", at, id)
        FROM "HuvudmanSchoolEvents" WHERE kind IN ('JOINED', 'WITHDRAWN', 'RELEASED', 'LEFT') AND at > now() - interval '1 hour'
         AND "schoolId" IN (b, d, a, c) AND at >= transaction_timestamp())
     IS DISTINCT FROM (SELECT string_agg(e, ',' ORDER BY s, o)
                         FROM (VALUES (b, 1, 'WITHDRAWN:huvudman'), (d, 1, 'JOINED:school'), (a, 1, 'RELEASED:huvudman'), (c, 1, 'LEFT:school')) v(s, o, e)) THEN
    wrong := wrong || format('265d the history says %s',
      (SELECT string_agg(kind::text || '@' || "schoolId", ',') FROM "HuvudmanSchoolEvents" WHERE at >= transaction_timestamp()));
  END IF;
  IF EXISTS (SELECT 1 FROM "HuvudmanSchoolRequests" WHERE "schoolId" IN (b, d)) THEN
    wrong := wrong || '265d an answered or withdrawn question is still asked'::text;
  END IF;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  IF (SELECT count(*) FROM "HuvudmanSchoolEvents" WHERE kind = 'DECLINED' AND "byUserId" IS NOT NULL) <> 1 THEN
    wrong := wrong || '265d the roller school''s no is not in its history'::text;
  END IF;

  PERFORM set_config('request.jwt.claims', '', true);
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'huvudman 265: %', array_to_string(wrong, '; ');
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 266: läsloggen namnger huvudmannens läsare och nyckel
-- (20261212090100).
--
--   266a  P's read in the roller school is written in the school's own log:
--         the member, no Users row, the administrator's role, the client's
--         channel; the same read within the quarter-hour adds nothing;
--   266b  H's key, opened for the roller school, reads as an integration:
--         the key, no school key, no role; opening it for a school H does
--         not own (B), with the revoked key or with H2's key is HM403 with
--         nothing set, and a key set beside the school by hand (as a broken
--         gateway would) is PD403, for H2's key and for the revoked one;
--   266c  the school's decider reads the names of both in its log
--         (app.access_log_huvudman_names); the läsare and the reader do not;
--   266d  once the school has left the huvudman, P reads nothing there, and
--         its read is refused for having no reader (PD403); the names in
--         the school's log stay;
--   266e  P's read is P's own in the log: the school's administrator's read
--         of the same pupil a moment before leaves P's to be written;
--   266f  H's key beside the school's own key, by hand, is PD403;
--   266g  the decider of D, which H only asked for, reads no names of H's;
--   266h  the four arms where the service principal writes: H's key,
--         opened for the roller school, updates no Users or
--         GuardianStudents row and inserts no GuardianStudents or
--         StudentGroups row (20261212090300); the school's own principal
--         passes each. Nor does it write, read an address or take the
--         school's catch-up lock through app.leave_requests_tell_new_mentors(),
--         which the school's own principal takes;
--   266i  the read log's quarter-hour is each reader's and each key's own:
--         K's read of a pupil P read a moment before is written, and so is
--         a second key of H's after the first;
--   266j  the source's secrets are refused the reader and the läsare, and
--         the delivery job's context is neither the reader's nor a
--         huvudman's key's, set without a school (20261212090300);
--   266k  from the catalogue: every SECURITY DEFINER function that may
--         write and asks app.current_service_school_id() either refuses a
--         huvudman's key or is named here with why.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  p constant text := 'fe000000-0000-4000-8000-000000000260';
  m uuid;
  b uuid;
  d_school uuid;
  pupil uuid;
  pupil2 uuid;
  member uuid;
  hkey uuid;
  ikey uuid;
  revoked uuid;
  h2key uuid;
  got record;
  w record;
  via text;
  cols text;
  pupil3 uuid;
  hkey2 uuid;
  counted bigint;
  got_n bigint;
  outcome text;
  msg text;
  n int;
  st text;
  wrong text[] := '{}';
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  m := app.current_school_id();
  SELECT id INTO pupil FROM "Users" WHERE "schoolId" = m AND role = 'STUDENT' AND "isActive" ORDER BY "authId" LIMIT 1;
  SELECT id INTO pupil2 FROM "Users" WHERE "schoolId" = m AND role = 'STUDENT' AND "isActive" AND id <> pupil ORDER BY "authId" LIMIT 1;
  SELECT id INTO pupil3 FROM "Users" WHERE "schoolId" = m AND role = 'STUDENT' AND "isActive" AND id NOT IN (pupil, pupil2) ORDER BY "authId" LIMIT 1;
  SELECT id INTO ikey FROM "IntegrationApiKeys" WHERE name = 'Roller nyckel';
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000266')::text, true);
  d_school := app.current_school_id();
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000261')::text, true);
  SELECT id INTO hkey FROM "HuvudmanApiKeys" WHERE name = 'RLS H nyckel';
  SELECT id INTO revoked FROM "HuvudmanApiKeys" WHERE name = 'RLS H återkallad';
  SELECT school_id INTO b FROM app.huvudman_schools((SELECT "huvudmanId" FROM "HuvudmanApiKeys" WHERE id = hkey))
   WHERE slug = 'rls-fixture-school' AND state = 'REQUESTED';
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000268')::text, true);
  SELECT id INTO h2key FROM "HuvudmanApiKeys" WHERE name = 'RLS H2 nyckel';
  IF pupil IS NULL OR pupil2 IS NULL OR pupil3 IS NULL OR hkey IS NULL OR revoked IS NULL OR h2key IS NULL OR ikey IS NULL OR b IS NULL OR d_school IS NULL THEN
    RAISE EXCEPTION 'huvudman 266: pupils % % %, keys % % % %, schools % %; fixtures did not run',
      pupil, pupil2, pupil3, hkey, revoked, h2key, ikey, b, d_school;
  END IF;

  -- 266a
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p)::text, true);
  PERFORM set_config('app.chosen_school_id', m::text, true);
  SELECT member_id INTO member FROM app.huvudman_reader();
  IF app.personal_data_read('PEOPLE', 'WEB', ARRAY[pupil]) <> 1 THEN
    wrong := wrong || '266a P''s read wrote no row'::text;
  END IF;
  IF app.personal_data_read('PEOPLE', 'WEB', ARRAY[pupil]) <> 0 THEN
    wrong := wrong || '266a P''s second read within the quarter-hour wrote a row'::text;
  END IF;
  IF app.personal_data_read('ROSTER', 'APP', ARRAY[pupil]) <> 1 THEN
    wrong := wrong || '266a P''s read of another kind wrote no row'::text;
  END IF;

  -- 266b, as the service: no claims.
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM set_config('app.chosen_school_id', '', true);
  FOR got IN SELECT * FROM (VALUES
      (hkey, b, 'a school H only asked for (B)'),
      (hkey, NULL::uuid, 'no school'),
      (revoked, m, 'the revoked key'),
      (h2key, m, 'H2''s key')
    ) v(k, s, label)
  LOOP
    BEGIN
      PERFORM app.huvudman_key_opens_school(got.k, got.s);
      wrong := wrong || format('266b opening %s was allowed', got.label);
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE;
      IF st <> 'HM403' THEN wrong := wrong || format('266b opening %s: %s, not HM403', got.label, st); END IF;
    END;
    IF app.current_service_school_id() IS NOT NULL OR nullif(current_setting('app.service_huvudman_key_id', true), '') IS NOT NULL THEN
      wrong := wrong || format('266b opening %s set the principal', got.label);
    END IF;
  END LOOP;
  -- By hand, beside the school: refused by the read log.
  FOREACH st IN ARRAY ARRAY[h2key::text, revoked::text] LOOP
    PERFORM set_config('app.service_school_id', m::text, true);
    PERFORM set_config('app.service_huvudman_key_id', st, true);
    BEGIN
      PERFORM app.personal_data_read('PEOPLE', NULL, ARRAY[pupil]);
      wrong := wrong || format('266b a read with the key %s by hand was written', st);
    EXCEPTION WHEN SQLSTATE 'PD403' THEN NULL;
    END;
  END LOOP;
  -- 266f: H's key beside the school's own.
  PERFORM set_config('app.service_school_id', m::text, true);
  PERFORM set_config('app.service_key_id', ikey::text, true);
  PERFORM set_config('app.service_huvudman_key_id', hkey::text, true);
  BEGIN
    PERFORM app.personal_data_read('PEOPLE', NULL, ARRAY[pupil]);
    wrong := wrong || '266f a read with H''s key beside the school''s own was written'::text;
  EXCEPTION WHEN SQLSTATE 'PD403' THEN NULL;
  END;
  PERFORM set_config('app.service_key_id', '', true);
  PERFORM set_config('app.service_school_id', '', true);
  PERFORM set_config('app.service_huvudman_key_id', '', true);
  PERFORM app.huvudman_key_opens_school(hkey, m);
  IF app.current_service_school_id() IS DISTINCT FROM m OR nullif(current_setting('app.service_huvudman_key_id', true), '')::uuid IS DISTINCT FROM hkey THEN
    wrong := wrong || '266b H''s key did not open the roller school'::text;
  END IF;
  IF app.personal_data_read('PEOPLE', NULL, ARRAY[pupil]) <> 1 OR app.personal_data_read('PEOPLE', NULL, ARRAY[pupil]) <> 0 THEN
    wrong := wrong || '266b the key''s read wrote no row, or two'::text;
  END IF;
  PERFORM set_config('app.service_school_id', '', true);
  PERFORM set_config('app.service_huvudman_key_id', '', true);

  -- What was written, and 266c, as the school's decider.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  SELECT count(*) FILTER (WHERE "huvudmanMemberId" = member AND "actorId" IS NULL AND "actorRole" = 'SCHOOL_ADMIN'
                            AND "apiKeyId" IS NULL AND "huvudmanApiKeyId" IS NULL AND channel IN ('WEB', 'APP')) AS readers,
         count(*) FILTER (WHERE "huvudmanApiKeyId" = hkey AND "apiKeyId" IS NULL AND "actorId" IS NULL AND "actorRole" IS NULL
                            AND "huvudmanMemberId" IS NULL AND channel = 'INTEGRATION') AS keys,
         count(*) AS total
    INTO got FROM "PersonalDataAccess" WHERE at >= transaction_timestamp() AND "schoolId" = m;
  IF got.readers <> 2 OR got.keys <> 1 OR got.total <> 3 THEN
    wrong := wrong || format('266a/b the log holds %s rows of the reader and %s of the key, of %s', got.readers, got.keys, got.total);
  END IF;
  IF (SELECT string_agg(kind || ':' || name || ':' || huvudman_name, ',' ORDER BY kind)
        FROM app.access_log_huvudman_names(ARRAY[member, gen_random_uuid()], ARRAY[hkey, h2key]))
     IS DISTINCT FROM 'KEY:RLS H nyckel:RLS Kommun,MEMBER:Huvudman Planerare:RLS Kommun' THEN
    wrong := wrong || format('266c the decider reads the names %s',
      (SELECT json_agg(x) FROM app.access_log_huvudman_names(ARRAY[member], ARRAY[hkey, h2key]) x));
  END IF;
  FOREACH st IN ARRAY ARRAY['00000000-0000-4000-8000-000000000115', p] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', st)::text, true);
    PERFORM set_config('app.chosen_school_id', m::text, true);
    IF EXISTS (SELECT 1 FROM app.access_log_huvudman_names(ARRAY[member], ARRAY[hkey])) THEN
      wrong := wrong || format('266c %s, who does not decide, reads the names', st);
    END IF;
  END LOOP;
  PERFORM set_config('app.chosen_school_id', '', true);

  -- 266g
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000266')::text, true);
  IF app.current_school_id() IS DISTINCT FROM d_school OR NOT app.current_user_decides() THEN
    wrong := wrong || '266g D''s rektor is not D''s decider'::text;
  ELSIF EXISTS (SELECT 1 FROM app.access_log_huvudman_names(ARRAY[member], ARRAY[hkey])) THEN
    wrong := wrong || '266g D''s decider reads the names of a huvudman that never owned D'::text;
  END IF;

  -- 266e: the school's administrator reads pupil2, then P does.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  IF app.personal_data_read('PEOPLE', 'WEB', ARRAY[pupil2]) <> 1 THEN
    wrong := wrong || '266e the administrator''s read wrote no row'::text;
  END IF;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p)::text, true);
  PERFORM set_config('app.chosen_school_id', m::text, true);
  IF app.personal_data_read('PEOPLE', 'WEB', ARRAY[pupil2]) <> 1 THEN
    wrong := wrong || '266e P''s read was taken for the administrator''s'::text;
  END IF;
  PERFORM set_config('app.chosen_school_id', '', true);

  -- 266h, as the service: the school's own principal, then H's key.
  PERFORM set_config('request.jwt.claims', '', true);
  FOREACH via IN ARRAY ARRAY['school', 'key'] LOOP
    PERFORM set_config('app.service_school_id', '', true);
    PERFORM set_config('app.service_huvudman_key_id', '', true);
    IF via = 'key' THEN
      PERFORM app.huvudman_key_opens_school(hkey, m);
    ELSE
      PERFORM set_config('app.service_school_id', m::text, true);
    END IF;
    FOR w IN SELECT * FROM (VALUES ('Users', 'update', 'firstName'), ('GuardianStudents', 'update', 'origin'),
                                   ('GuardianStudents', 'insert', NULL), ('StudentGroups', 'insert', NULL)) v(tbl, cmd, col) LOOP
      outcome := NULL;
      BEGIN
        IF w.cmd = 'update' THEN
          EXECUTE format('UPDATE %I SET %I = %I WHERE "schoolId" = $1', w.tbl, w.col, w.col) USING m;
        ELSE
          SELECT string_agg(quote_ident(at.attname), ', ' ORDER BY at.attnum) INTO cols
            FROM pg_attribute at
           WHERE at.attrelid = format('public.%I', w.tbl)::regclass AND at.attnum > 0 AND NOT at.attisdropped
             AND at.attname <> 'id' AND has_column_privilege(format('public.%I', w.tbl), at.attname, 'INSERT');
          EXECUTE format('INSERT INTO %I (%s) SELECT %s FROM %I x WHERE x."schoolId" = $1 LIMIT 1', w.tbl, cols, cols, w.tbl) USING m;
        END IF;
        GET DIAGNOSTICS n = ROW_COUNT;
        outcome := CASE WHEN n > 0 THEN 'admitted' ELSE 'none' END;
        RAISE EXCEPTION USING ERRCODE = 'ZH266';
      EXCEPTION
        WHEN SQLSTATE 'ZH266' THEN NULL;
        WHEN unique_violation OR foreign_key_violation OR exclusion_violation OR check_violation OR not_null_violation THEN
          outcome := 'admitted';  -- past row security
        WHEN insufficient_privilege THEN
          GET STACKED DIAGNOSTICS msg = MESSAGE_TEXT;
          outcome := CASE WHEN msg LIKE '%row-level security%' THEN 'refused' ELSE 'denied: ' || msg END;
      END;
      IF via = 'key' AND outcome NOT IN ('refused', 'none') THEN
        wrong := wrong || format('266h H''s key: %s %s was %s', w.cmd, w.tbl, outcome);
      ELSIF via = 'school' AND outcome IS DISTINCT FROM 'admitted' THEN
        wrong := wrong || format('266h the school''s own principal: %s %s was %s', w.cmd, w.tbl, outcome);
      END IF;
    END LOOP;
  END LOOP;
  PERFORM set_config('app.service_school_id', '', true);
  PERFORM set_config('app.service_huvudman_key_id', '', true);
  -- 266h: the mentors' notices, which took any service principal. A
  -- principal the function takes is a school it catches up, under the
  -- school's advisory lock, whether or not anybody is owed a notice there:
  -- H's key takes no lock, writes nothing and tells nobody; the school's own
  -- principal, after it, takes the lock (the control; a lock the key took
  -- would already be held).
  outcome := NULL;
  FOREACH via IN ARRAY ARRAY['key', 'school'] LOOP
    IF via = 'key' THEN
      PERFORM app.huvudman_key_opens_school(hkey, m);
    ELSE
      PERFORM set_config('app.service_school_id', m::text, true);
    END IF;
    SELECT count(*) INTO n FROM pg_locks WHERE locktype = 'advisory' AND pid = pg_backend_pid();
    SELECT coalesce(sum(n_tup_ins + n_tup_upd + n_tup_del), 0) INTO counted FROM pg_stat_xact_all_tables;
    SELECT count(*) INTO got_n FROM app.leave_requests_tell_new_mentors();
    IF via = 'key' AND got_n <> 0 THEN
      wrong := wrong || '266h H''s key reads the new mentors'' addresses'::text;
    END IF;
    IF via = 'key' AND (SELECT coalesce(sum(n_tup_ins + n_tup_upd + n_tup_del), 0) FROM pg_stat_xact_all_tables) <> counted THEN
      wrong := wrong || '266h H''s key wrote the new mentors'' notices'::text;
    END IF;
    IF via = 'key' AND (SELECT count(*) FROM pg_locks WHERE locktype = 'advisory' AND pid = pg_backend_pid()) <> n THEN
      wrong := wrong || '266h the mentors'' catch-up took H''s key for the school''s principal (it locked the school)'::text;
      outcome := 'locked';
    ELSIF via = 'school' AND outcome IS DISTINCT FROM 'locked'
          AND (SELECT count(*) FROM pg_locks WHERE locktype = 'advisory' AND pid = pg_backend_pid()) <= n THEN
      wrong := wrong || '266h the school''s own principal took no catch-up lock: the key''s check above proves nothing'::text;
    END IF;
    PERFORM set_config('app.service_school_id', '', true);
    PERFORM set_config('app.service_huvudman_key_id', '', true);
  END LOOP;

  -- 266i: P reads pupil3, then K does; then H's key, then a second key of H's.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p)::text, true);
  PERFORM set_config('app.chosen_school_id', m::text, true);
  IF app.personal_data_read('PEOPLE', 'WEB', ARRAY[pupil3]) <> 1 THEN wrong := wrong || '266i P''s read of pupil3 wrote no row'::text; END IF;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000261')::text, true);
  IF app.personal_data_read('PEOPLE', 'WEB', ARRAY[pupil3]) <> 1 THEN
    wrong := wrong || '266i K''s read was taken for P''s, a moment before'::text;
  END IF;
  PERFORM set_config('app.chosen_school_id', '', true);
  -- K makes a second key of H's.
  INSERT INTO "HuvudmanApiKeys" ("huvudmanId", name, "keyHash", scopes, "createdById")
  SELECT "huvudmanId", 'RLS H nyckel 2', encode(sha256(convert_to('sh_' || repeat('e', 48), 'UTF8')), 'hex'), ARRAY['persons.read'], id
    FROM "HuvudmanMembers" WHERE "authId" = 'fe000000-0000-4000-8000-000000000261'
  RETURNING id INTO hkey2;
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM app.huvudman_key_opens_school(hkey, m);
  PERFORM app.personal_data_read('PEOPLE', NULL, ARRAY[pupil3]);
  PERFORM set_config('app.service_school_id', '', true);
  PERFORM set_config('app.service_huvudman_key_id', '', true);
  PERFORM app.huvudman_key_opens_school(hkey2, m);
  IF app.personal_data_read('PEOPLE', NULL, ARRAY[pupil3]) <> 1 THEN
    wrong := wrong || '266i the second key''s read was taken for the first key''s'::text;
  END IF;
  PERFORM set_config('app.service_school_id', '', true);
  PERFORM set_config('app.service_huvudman_key_id', '', true);

  -- 266j
  FOREACH st IN ARRAY ARRAY[p, '00000000-0000-4000-8000-000000000115'] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', st)::text, true);
    PERFORM set_config('app.chosen_school_id', m::text, true);
    BEGIN
      PERFORM * FROM app.ss12000_source_secrets(gen_random_uuid());
      wrong := wrong || format('266j %s may read a source''s secrets', st);
    EXCEPTION WHEN SQLSTATE 'SS403' THEN NULL;
    END;
  END LOOP;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  BEGIN
    PERFORM * FROM app.ss12000_source_secrets(gen_random_uuid());
  EXCEPTION WHEN SQLSTATE 'SS403' THEN
    wrong := wrong || '266j the roller school''s full administrator may not read its sources'' secrets'::text;
  END;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p)::text, true);
  IF app.ss12000_is_delivery_context() THEN
    wrong := wrong || '266j the reader''s claims are taken for the delivery job'::text;
  END IF;
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM set_config('app.chosen_school_id', '', true);
  IF NOT app.ss12000_is_delivery_context() THEN
    wrong := wrong || '266j an empty transaction is no longer the delivery job''s'::text;
  END IF;
  -- A huvudman's key set alone, no school opened (a broken gateway would).
  PERFORM set_config('app.service_huvudman_key_id', hkey::text, true);
  IF app.ss12000_is_delivery_context() THEN
    wrong := wrong || '266j a huvudman''s key set without a school is taken for the delivery job'::text;
  END IF;
  PERFORM set_config('app.service_huvudman_key_id', '', true);

  -- 266k
  SELECT string_agg(n.nspname || '.' || p2.proname, ', ' ORDER BY 1) INTO cols
    FROM pg_proc p2 JOIN pg_namespace n ON n.oid = p2.pronamespace
   WHERE n.nspname IN ('app', 'public', 'sign_in') AND p2.prosecdef AND p2.provolatile = 'v'
     AND p2.prosrc ~ 'current_service_school_id\(\)'
     AND p2.prosrc !~ 'current_service_huvudman_key_id\(\)'
     AND (n.nspname, p2.proname) NOT IN (
       -- Triggers: they run on a write, and the four arms where the service
       -- principal writes refuse a huvudman's key (266h).
       ('app', 'ss12000_ids_are_written_by_an_admin'),
       ('app', 'ss12000_subscription_writes_are_narrow'),
       ('app', 'staffing_policies_sharing_is_decided'),
       ('app', 'teacher_work_rules_day_is_planned'),
       ('app', 'users_administrators_are_decided'),
       ('app', 'users_class_moves_are_narrow')
     );
  IF cols IS NOT NULL THEN
    wrong := wrong || format('266k these may write for any service principal, a huvudman''s key too: %s', cols);
  END IF;

  -- 266d
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  PERFORM set_config('app.chosen_school_id', '', true);
  PERFORM app.school_leaves_huvudman();
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p)::text, true);
  PERFORM set_config('app.chosen_school_id', m::text, true);
  IF app.current_school_id() IS NOT NULL OR (SELECT count(*) FROM "Users") <> 0 THEN
    wrong := wrong || '266d P reads the roller school after it left'::text;
  END IF;
  BEGIN
    PERFORM app.personal_data_read('PEOPLE', 'WEB', ARRAY[pupil]);
    wrong := wrong || '266d P''s read after the school left was written'::text;
  EXCEPTION WHEN SQLSTATE 'PD403' THEN NULL;
  END;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  PERFORM set_config('app.chosen_school_id', '', true);
  IF (SELECT count(*) FROM app.access_log_huvudman_names(ARRAY[member], ARRAY[hkey])) <> 2 THEN
    wrong := wrong || '266d the names left the log with the huvudman'::text;
  END IF;
  PERFORM set_config('request.jwt.claims', '', true);
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'huvudman 266: %', array_to_string(wrong, '; ');
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 267: huvudmannens nyckel, uppslaget och tjänsteprincipalen
-- (20261212090000).
--
--   267a  the key lookup reads the live keys of every huvudman and nothing
--         revoked, stamps lastUsedAt and nothing else (SS403), and touches
--         no revoked key; without the lookup, and with nobody signed in, no
--         key is read;
--   267b  the key's schools, by id: H's three for H's key, none for the
--         revoked one, H2's key, or no key;
--   267c  a school opened for H's key is that school's service principal and
--         no more: the seven tables the service reads answer exactly what
--         they answer for the school's own principal;
--   267d  the database holds the key to its huvudman's schools without the
--         gateway (20261212090300): with the two settings written by hand,
--         app.current_service_school_id() is the school for H's key at a
--         school H owns, and NULL, with no Users row read, at B (which H only
--         asked for), with the revoked key and with H2's key; with no key it
--         is the setting, as for the school's own principal.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls267_a', :'school_a', true);
DO $$
DECLARE
  a uuid := current_setting('app.test_rls267_a')::uuid;
  m uuid;
  c uuid;
  hkey uuid;
  revoked uuid;
  h2key uuid;
  b uuid;
  r record;
  t text;
  expected uuid[];
  want_owner text;
  n bigint;
  own bigint;
  st text;
  wrong text[] := '{}';
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  m := app.current_school_id();
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000269')::text, true);
  c := app.current_school_id();
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000261')::text, true);
  SELECT id INTO hkey FROM "HuvudmanApiKeys" WHERE name = 'RLS H nyckel';
  SELECT id INTO revoked FROM "HuvudmanApiKeys" WHERE name = 'RLS H återkallad';
  SELECT school_id INTO b FROM app.huvudman_schools((SELECT "huvudmanId" FROM "HuvudmanApiKeys" WHERE id = hkey))
   WHERE slug = 'rls-fixture-school' AND state = 'REQUESTED';
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000268')::text, true);
  SELECT id INTO h2key FROM "HuvudmanApiKeys" WHERE name = 'RLS H2 nyckel';
  IF b IS NULL THEN RAISE EXCEPTION 'huvudman 267: B is not among H''s questions; fixtures did not run'; END IF;

  -- 267a
  PERFORM set_config('request.jwt.claims', '', true);
  IF (SELECT count(*) FROM "HuvudmanApiKeys") <> 0 THEN
    wrong := wrong || '267a nobody reads a key'::text;
  END IF;
  PERFORM set_config('app.service_key_lookup', 'on', true);
  IF (SELECT array_agg(name ORDER BY name) FROM "HuvudmanApiKeys") IS DISTINCT FROM ARRAY['RLS H nyckel', 'RLS H2 nyckel'] THEN
    wrong := wrong || format('267a the lookup reads %s', (SELECT array_agg(name ORDER BY name) FROM "HuvudmanApiKeys"));
  END IF;
  UPDATE "HuvudmanApiKeys" SET "lastUsedAt" = now() WHERE id = hkey;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN wrong := wrong || '267a the lookup did not stamp the key'::text; END IF;
  UPDATE "HuvudmanApiKeys" SET "lastUsedAt" = now() WHERE id = revoked;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 0 THEN wrong := wrong || '267a the lookup stamped a revoked key'::text; END IF;
  BEGIN
    UPDATE "HuvudmanApiKeys" SET "revokedAt" = now() WHERE id = hkey;
    wrong := wrong || '267a the lookup revoked a key'::text;
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE;
    IF st NOT IN ('SS403', '42501') THEN wrong := wrong || format('267a the lookup''s revocation: %s', st); END IF;
  END;
  PERFORM set_config('app.service_key_lookup', '', true);

  -- 267b
  FOR t IN SELECT unnest(ARRAY[hkey::text, revoked::text, h2key::text, '']) LOOP
    PERFORM set_config('app.service_huvudman_key_id', t, true);
    expected := '{}';
    IF t = hkey::text THEN
      expected := (SELECT array_agg(s ORDER BY s) FROM unnest(ARRAY[a, m, c]) s);
    END IF;
    -- In the function's own order, which is by id.
    IF (SELECT coalesce(array_agg(school_id), '{}') FROM app.huvudman_key_schools()) IS DISTINCT FROM expected THEN
      wrong := wrong || format('267b the key %s reads the schools %s', t, (SELECT array_agg(school_id) FROM app.huvudman_key_schools()));
    END IF;
    want_owner := CASE WHEN t = hkey::text THEN 'RLS Kommun/2121000001/0884'
                       WHEN t = h2key::text THEN 'RLS Annan huvudman/2121000002/-' ELSE '' END;
    IF (SELECT coalesce(string_agg(name || '/' || coalesce(organisation_number, '-') || '/' || coalesce(municipality_code, '-'), ','), '')
          FROM app.huvudman_key_owner()) IS DISTINCT FROM want_owner THEN
      wrong := wrong || format('267b the key %s is of the huvudman %s', t, (SELECT json_agg(x) FROM app.huvudman_key_owner() x));
    END IF;
  END LOOP;
  PERFORM set_config('app.service_huvudman_key_id', '', true);

  -- 267c
  FOREACH t IN ARRAY ARRAY['Schools', 'AcademicYears', 'MasterLessons', 'CalendarLessons', 'Users', 'StudentGroups', 'GuardianStudents'] LOOP
    PERFORM set_config('app.service_school_id', m::text, true);
    EXECUTE format('SELECT count(*) FROM %I', t) INTO own;
    PERFORM set_config('app.service_school_id', '', true);
    PERFORM app.huvudman_key_opens_school(hkey, m);
    EXECUTE format('SELECT count(*) FROM %I', t) INTO n;
    PERFORM set_config('app.service_school_id', '', true);
    PERFORM set_config('app.service_huvudman_key_id', '', true);
    IF n IS DISTINCT FROM own OR own = 0 THEN
      wrong := wrong || format('267c %s: %s rows for H''s key, %s for the school''s own principal', t, n, own);
    END IF;
  END LOOP;

  -- 267d, by hand: no app.huvudman_key_opens_school.
  FOR r IN SELECT * FROM (VALUES
      (m, hkey::text, m, 'H''s key at the roller school'),
      (a, hkey::text, a, 'H''s key at A'),
      (b, hkey::text, NULL::uuid, 'H''s key at B, only asked for'),
      (m, revoked::text, NULL::uuid, 'the revoked key at the roller school'),
      (m, h2key::text, NULL::uuid, 'H2''s key at the roller school'),
      (b, '', b, 'no key at B: the school''s own principal')
    ) v(school, k, expected, label)
  LOOP
    PERFORM set_config('app.service_school_id', r.school::text, true);
    PERFORM set_config('app.service_huvudman_key_id', r.k, true);
    IF app.current_service_school_id() IS DISTINCT FROM r.expected THEN
      wrong := wrong || format('267d %s is the school %s', r.label, app.current_service_school_id());
    END IF;
    SELECT count(*) INTO n FROM "Users";
    IF (r.expected IS NULL) <> (n = 0) THEN
      wrong := wrong || format('267d %s reads %s Users rows', r.label, n);
    END IF;
  END LOOP;
  PERFORM set_config('app.service_school_id', '', true);
  PERFORM set_config('app.service_huvudman_key_id', '', true);
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'huvudman 267: %', array_to_string(wrong, '; ');
  END IF;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 268: kroken dömer huvudmannens skolor, var och en för sig
-- (20261212090000).
--
-- As supabase_auth_admin, like section 243. H owns A (no school-account
-- row), the roller school (Entra, optional for staff) and C (Entra, required
-- for staff):
--
--   268a  sign_in.rules: P's three schools as the reader's, staff, after
--         every own row ('infinity'); L's own row at A first and the
--         reader's rows at all three, A's too; G's deactivated own row in
--         the roller school and the reader's three;
--   268b  P by password: the claims, with {reader:C: sso_required}; L and G
--         the same, their own rows judged first and open;
--   268c  P by school account with C's tenant: the reader closed at A and
--         in the roller school (A has no school account; the roller school's
--         tenant is another), open at C;
--   268d  Q, whose huvudman owns nothing, and a login with one row: exactly
--         the claims Auth signed;
--   268e  P with an active guardian row at C (which requires a school
--         account of staff only) by password: C closed to the reader alone,
--         {reader:C: sso_required}; under those claims P naming C is the
--         guardian there, and once C deactivates the row, P naming C is no
--         principal at all: not the reader that was never let in;
--   268f  X, whose membership is inactive, by password: its schools are
--         judged all the same, {reader:C: sso_required}; once the
--         membership is made active, X naming C is no principal and X
--         naming A is the reader;
--   268g  P, when the one school H owns requires a school account of staff:
--         by password the token is refused (sso_required), by school account
--         issued.
-- ---------------------------------------------------------------------------

BEGIN;
SELECT set_config('app.test_rls268_a', :'school_a', true);
DO $$
DECLARE
  a constant text := current_setting('app.test_rls268_a');
  now_s bigint := extract(epoch FROM now())::bigint;
  c_tenant constant text := '7b0c2a9e-3c1d-4e5f-8a6b-0c1d2e3f4a5d';
  p constant text := 'fe000000-0000-4000-8000-000000000260';
  l constant text := 'fe000000-0000-4000-8000-000000000264';
  g constant text := 'fe000000-0000-4000-8000-000000000265';
  m text;
  c text;
  r record;
  claims jsonb;
  got jsonb;
  expected jsonb;
  cases int := 0;
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  m := app.current_school_id()::text;
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000269')::text, true);
  c := app.current_school_id()::text;
  PERFORM set_config('request.jwt.claims', '', true);
  SET LOCAL ROLE supabase_auth_admin;
  IF current_user <> 'supabase_auth_admin' THEN RAISE EXCEPTION 'huvudman 268: running as %', current_user; END IF;

  -- 268a
  IF (SELECT array_agg("schoolId"::text || '/' || "role"::text || '/' || ("loginSince" = 'infinity')::text || '/' || "isActive"::text
                       || '/' || "huvudmanReader"::text ORDER BY "loginSince", "schoolId")
        FROM sign_in.rules(p::uuid)) IS DISTINCT FROM
     (SELECT array_agg(s || '/SCHOOL_ADMIN/true/true/true' ORDER BY s) FROM unnest(ARRAY[a, m, c]) s) THEN
    RAISE EXCEPTION 'huvudman 268a: P''s rules are %', (SELECT json_agg(x) FROM sign_in.rules(p::uuid) x);
  END IF;
  IF (SELECT array_agg("schoolId"::text || '/' || "role"::text || '/' || "huvudmanReader"::text ORDER BY "loginSince", "schoolId")
        FROM sign_in.rules(l::uuid))
     IS DISTINCT FROM ARRAY[a || '/TEACHER/false'] || (SELECT array_agg(s || '/SCHOOL_ADMIN/true' ORDER BY s) FROM unnest(ARRAY[a, m, c]) s) THEN
    RAISE EXCEPTION 'huvudman 268a: L''s rules are %', (SELECT json_agg(x) FROM sign_in.rules(l::uuid) x);
  END IF;
  IF (SELECT count(*) FROM sign_in.rules(g::uuid) WHERE "schoolId"::text = m) <> 2
     OR (SELECT count(*) FROM sign_in.rules(g::uuid) WHERE "schoolId"::text = m AND "role" = 'GUARDIAN' AND NOT "isActive" AND NOT "huvudmanReader") <> 1
     OR (SELECT count(*) FROM sign_in.rules(g::uuid) WHERE "huvudmanReader") <> 3
     OR (SELECT count(*) FROM sign_in.rules(g::uuid)) <> 4 THEN
    RAISE EXCEPTION 'huvudman 268a: G''s rules are %', (SELECT json_agg(x) FROM sign_in.rules(g::uuid) x);
  END IF;

  FOR r IN SELECT * FROM (VALUES
      ('268b P by password',                      p, 'password', '["password"]'::jsonb, jsonb_build_object('reader:' || c, 'sso_required'), NULL::text[], false),
      ('268b P refreshed',                        p, 'token_refresh', '["password"]', jsonb_build_object('reader:' || c, 'sso_required'), NULL, false),
      ('268b L by password',                      l, 'password', '["password"]', jsonb_build_object('reader:' || c, 'sso_required'), NULL, false),
      ('268b G by password',                      g, 'password', '["password"]', jsonb_build_object('reader:' || c, 'sso_required'), NULL, false),
      ('268d Q, whose huvudman owns nothing',     'fe000000-0000-4000-8000-000000000263', 'password', '["password"]', NULL, NULL, false),
      ('268d a login with one row',               '00000000-0000-4000-8000-000000000105', 'password', '["password"]', NULL, NULL, false),
      ('268c P by school account, C''s tenant',   p, 'oauth', '["oauth"]', NULL, ARRAY['reader:' || a, 'reader:' || m], true)
    ) AS v(label, sub, method, amr, closed, closed_keys, needs_identity)
  LOOP
    IF r.needs_identity THEN
      INSERT INTO auth.identities (provider_id, user_id, identity_data, provider)
      VALUES ('rls268-entra', r.sub::uuid,
              jsonb_build_object('iss', 'https://login.microsoftonline.com/' || c_tenant || '/v2.0', 'sub', 'rls268-entra',
                                 'custom_claims', jsonb_build_object('tid', c_tenant)),
              'azure');
    END IF;
    claims := jsonb_build_object(
      'aud', 'authenticated', 'sub', r.sub, 'role', 'authenticated', 'email', 'rls268@example.invalid',
      'session_id', gen_random_uuid(), 'aal', 'aal1', 'is_anonymous', false,
      'app_metadata', jsonb_build_object('provider', 'email'), 'user_metadata', '{}'::jsonb,
      'amr', (SELECT jsonb_agg(jsonb_build_object('method', e #>> '{}', 'timestamp', now_s - 60)) FROM jsonb_array_elements(r.amr) e));
    got := sign_in.custom_access_token_hook(jsonb_build_object('user_id', r.sub, 'claims', claims, 'authentication_method', r.method));
    expected := CASE WHEN r.closed IS NULL THEN jsonb_build_object('claims', claims)
                     ELSE jsonb_build_object('claims', claims || jsonb_build_object('rastra_closed_schools', r.closed)) END;
    IF r.closed_keys IS NOT NULL THEN
      IF got ? 'error' OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(got #> '{claims,rastra_closed_schools}') k)
                           IS DISTINCT FROM (SELECT array_agg(k ORDER BY k) FROM unnest(r.closed_keys) k) THEN
        RAISE EXCEPTION 'huvudman %: gave %, expected % closed', r.label, got, r.closed_keys;
      END IF;
    ELSIF got IS DISTINCT FROM expected THEN
      RAISE EXCEPTION 'huvudman %: gave %, expected %', r.label, got, expected;
    END IF;
    cases := cases + 1;
  END LOOP;
  IF cases <> 7 THEN RAISE EXCEPTION 'huvudman 268: only % cases ran', cases; END IF;
  SET LOCAL ROLE app_authenticated;
END $$;
ROLLBACK;

-- 268e and 268f: a verdict of the token's, and a row or membership changed
-- during the token's life.
BEGIN;
SELECT set_config('app.test_rls268_a', :'school_a', true);
DO $$
DECLARE
  a constant text := current_setting('app.test_rls268_a');
  now_s bigint := extract(epoch FROM now())::bigint;
  p constant text := 'fe000000-0000-4000-8000-000000000260';
  x constant text := 'fe000000-0000-4000-8000-000000000262';
  c text;
  guardian uuid := gen_random_uuid();
  r record;
  claims jsonb;
  got jsonb;
  n int;
  wrong text[] := '{}';
BEGIN
  -- C's rektor gives P's login a guardian row at C, as an invitation does.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000269')::text, true);
  c := app.current_school_id()::text;
  PERFORM set_config('app.login_join', guardian::text, true);
  INSERT INTO "Users" (id, "schoolId", email, "firstName", "lastName", role, "authId", "invitedAt", "updatedAt")
  VALUES (guardian, c::uuid, 'hm-p-c-guardian@example.invalid', 'Huvudman', 'Förälder', 'GUARDIAN', p::uuid, now(), now());
  PERFORM set_config('app.login_join', '', true);
  PERFORM set_config('request.jwt.claims', '', true);

  FOR r IN SELECT * FROM (VALUES ('268e', p), ('268f', x)) v(label, sub) LOOP
    claims := jsonb_build_object(
      'aud', 'authenticated', 'sub', r.sub, 'role', 'authenticated', 'email', 'rls268@example.invalid',
      'session_id', gen_random_uuid(), 'aal', 'aal1', 'is_anonymous', false,
      'app_metadata', jsonb_build_object('provider', 'email'), 'user_metadata', '{}'::jsonb,
      'amr', jsonb_build_array(jsonb_build_object('method', 'password', 'timestamp', now_s - 60)));
    SET LOCAL ROLE supabase_auth_admin;
    got := sign_in.custom_access_token_hook(jsonb_build_object('user_id', r.sub, 'claims', claims, 'authentication_method', 'password'));
    SET LOCAL ROLE app_authenticated;
    IF got IS DISTINCT FROM jsonb_build_object('claims', claims || jsonb_build_object('rastra_closed_schools', jsonb_build_object('reader:' || c, 'sso_required'))) THEN
      wrong := wrong || format('%s by password: %s', r.label, got);
    END IF;
    PERFORM set_config('app.test_rls268_' || replace(r.label, '268', ''), (got -> 'claims')::text, true);
  END LOOP;

  -- 268e: under P's token, P naming C is the guardian there.
  PERFORM set_config('request.jwt.claims', current_setting('app.test_rls268_e'), true);
  PERFORM set_config('app.chosen_school_id', c, true);
  IF app.current_school_id()::text IS DISTINCT FROM c OR app.current_user_role() IS DISTINCT FROM 'GUARDIAN'
     OR app.current_user_id() IS DISTINCT FROM guardian OR EXISTS (SELECT 1 FROM app.huvudman_reader()) THEN
    wrong := wrong || format('268e P naming C is %s %s, not the guardian', app.current_school_id(), app.current_user_role());
  END IF;
  -- C deactivates the row; P's token is unchanged.
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000269')::text, true);
  PERFORM set_config('app.chosen_school_id', '', true);
  UPDATE "Users" SET "isActive" = false WHERE id = guardian;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN wrong := wrong || '268e C''s rektor could not deactivate the row'::text; END IF;
  PERFORM set_config('request.jwt.claims', current_setting('app.test_rls268_e'), true);
  PERFORM set_config('app.chosen_school_id', c, true);
  IF app.current_school_id() IS NOT NULL OR app.current_user_role() IS NOT NULL
     OR app.current_user_may('PERSONAL', false) OR EXISTS (SELECT 1 FROM app.huvudman_reader()) THEN
    wrong := wrong || format('268e P naming C after the row went is %s %s: the reader the token never let in', app.current_school_id(), app.current_user_role());
  END IF;

  -- 268f: X's membership is made active during the token's life.
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM set_config('app.chosen_school_id', '', true);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000261')::text, true);
  UPDATE "HuvudmanMembers" SET "isActive" = true WHERE "authId" = x::uuid;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 1 THEN wrong := wrong || '268f the kommunadministratör could not make X active'::text; END IF;
  PERFORM set_config('request.jwt.claims', current_setting('app.test_rls268_f'), true);
  PERFORM set_config('app.chosen_school_id', c, true);
  IF app.current_school_id() IS NOT NULL OR EXISTS (SELECT 1 FROM app.huvudman_reader()) THEN
    wrong := wrong || '268f X naming C, which the token closed to the reader, reads it'::text;
  END IF;
  PERFORM set_config('app.chosen_school_id', a, true);
  IF app.current_school_id()::text IS DISTINCT FROM a OR NOT EXISTS (SELECT 1 FROM app.huvudman_reader()) THEN
    wrong := wrong || '268f X naming A, which the token let the reader into, is not the reader'::text;
  END IF;
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM set_config('app.chosen_school_id', '', true);
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'huvudman 268: %', array_to_string(wrong, '; ');
  END IF;
END $$;
ROLLBACK;

-- 268g: H owns C alone.
BEGIN;
SELECT set_config('app.test_rls268_a', :'school_a', true);
DO $$
DECLARE
  now_s bigint := extract(epoch FROM now())::bigint;
  c_tenant constant text := '7b0c2a9e-3c1d-4e5f-8a6b-0c1d2e3f4a5d';
  p constant text := 'fe000000-0000-4000-8000-000000000260';
  c uuid;
  claims jsonb;
  got jsonb;
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000261')::text, true);
  FOR c IN SELECT school_id FROM app.huvudman_schools((SELECT "huvudmanId" FROM "HuvudmanMembers" WHERE "authId" = p::uuid))
            WHERE state = 'OWNED' AND slug <> 'rls-huvudman-c' LOOP
    PERFORM app.huvudman_release_school((SELECT "huvudmanId" FROM "HuvudmanMembers" WHERE "authId" = p::uuid), c);
  END LOOP;
  PERFORM set_config('request.jwt.claims', '', true);
  claims := jsonb_build_object(
    'aud', 'authenticated', 'sub', p, 'role', 'authenticated', 'email', 'rls268@example.invalid',
    'session_id', gen_random_uuid(), 'aal', 'aal1', 'is_anonymous', false,
    'app_metadata', jsonb_build_object('provider', 'email'), 'user_metadata', '{}'::jsonb,
    'amr', jsonb_build_array(jsonb_build_object('method', 'password', 'timestamp', now_s - 60)));
  SET LOCAL ROLE supabase_auth_admin;
  IF (SELECT count(*) FROM sign_in.rules(p::uuid)) <> 1 THEN
    RAISE EXCEPTION 'huvudman 268g: P''s rules are %', (SELECT json_agg(x) FROM sign_in.rules(p::uuid) x);
  END IF;
  got := sign_in.custom_access_token_hook(jsonb_build_object('user_id', p, 'claims', claims, 'authentication_method', 'password'));
  IF got IS DISTINCT FROM jsonb_build_object('error', jsonb_build_object('http_code', 403, 'message', 'sso_required')) THEN
    RAISE EXCEPTION 'huvudman 268g: P by password, with only C, gave %', got;
  END IF;
  INSERT INTO auth.identities (provider_id, user_id, identity_data, provider)
  VALUES ('rls268g-entra', p::uuid,
          jsonb_build_object('iss', 'https://login.microsoftonline.com/' || c_tenant || '/v2.0', 'sub', 'rls268g-entra',
                             'custom_claims', jsonb_build_object('tid', c_tenant)),
          'azure');
  claims := jsonb_set(claims, '{amr}', jsonb_build_array(jsonb_build_object('method', 'oauth', 'timestamp', now_s - 60)));
  got := sign_in.custom_access_token_hook(jsonb_build_object('user_id', p, 'claims', claims, 'authentication_method', 'oauth'));
  IF got IS DISTINCT FROM jsonb_build_object('claims', claims) THEN
    RAISE EXCEPTION 'huvudman 268g: P by school account, with only C, gave %', got;
  END IF;
  SET LOCAL ROLE app_authenticated;
END $$;
ROLLBACK;

-- ---------------------------------------------------------------------------
-- Section 268, continued: en medlems inloggning hålls, och skolans sida av
-- huvudmannen är beslutsfattarens (20261212090000). In 268 because 260–268
-- are this phase's.
--
--   268h  app.login_is_held_elsewhere counts a membership: L's login, held
--         by L's row at A and by L's membership, is held beside the row;
--         P's, held by the membership alone, is held with no row named;
--   268i  gallring leaves a login a membership holds: with the gallring
--         school's departed pupil's login handed to a member of H,
--         app.gallring_claim_person answers invited = false;
--   268j  what the school reads of its huvudman (its readers, keys and
--         history) is its deciders': the roller school's rektor reads them,
--         its läsare and P, the huvudman's reader there, read nothing.
-- ---------------------------------------------------------------------------

BEGIN;
DO $$
DECLARE
  l constant text := 'fe000000-0000-4000-8000-000000000264';
  p constant text := 'fe000000-0000-4000-8000-000000000260';
  l_row uuid;
  m uuid;
  sub text;
  wrong text[] := '{}';
BEGIN
  -- 268h
  PERFORM set_config('request.jwt.claims', json_build_object('sub', l)::text, true);
  l_row := app.current_user_id();
  PERFORM set_config('request.jwt.claims', '', true);
  IF l_row IS NULL THEN RAISE EXCEPTION 'huvudman 268h: L has no row at A'; END IF;
  IF NOT app.login_is_held_elsewhere(l::uuid, l_row) THEN
    wrong := wrong || '268h L''s login, which L''s membership holds, was taken for the row''s alone'::text;
  END IF;
  IF NOT app.login_is_held_elsewhere(p::uuid, NULL) THEN
    wrong := wrong || '268h P''s login, which only a membership holds, was taken for nobody''s'::text;
  END IF;

  -- 268j
  PERFORM set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000105')::text, true);
  m := app.current_school_id();
  IF (SELECT count(*) FROM app.school_huvudman_keys()) <> 2 OR (SELECT count(*) FROM app.school_huvudman_readers()) = 0
     OR (SELECT count(*) FROM app.school_huvudman_history(50)) = 0 THEN
    wrong := wrong || '268j the roller school''s rektor does not read its huvudman'::text;
  END IF;
  FOREACH sub IN ARRAY ARRAY['00000000-0000-4000-8000-000000000115', p] LOOP
    PERFORM set_config('request.jwt.claims', json_build_object('sub', sub)::text, true);
    PERFORM set_config('app.chosen_school_id', m::text, true);
    IF app.current_school_id() IS DISTINCT FROM m THEN
      wrong := wrong || format('268j %s is not in the roller school', sub);
    ELSIF EXISTS (SELECT 1 FROM app.school_huvudman_keys()) OR EXISTS (SELECT 1 FROM app.school_huvudman_readers())
          OR EXISTS (SELECT 1 FROM app.school_huvudman_history(50)) THEN
      wrong := wrong || format('268j %s, who does not decide, reads the school''s huvudman', sub);
    END IF;
  END LOOP;
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM set_config('app.chosen_school_id', '', true);
  IF cardinality(wrong) > 0 THEN
    RAISE EXCEPTION 'huvudman 268h/j: %', array_to_string(wrong, '; ');
  END IF;
END $$;
ROLLBACK;

-- 268i, after 242c.
BEGIN;
SELECT set_config('request.jwt.claims', json_build_object('sub', '00000000-0000-4000-8000-000000000081')::text, true);
DO $$
BEGIN
  PERFORM set_config('app.test_rls268i_school', app.current_school_id()::text, true);
  PERFORM set_config('app.test_rls268i_pupil', (SELECT id::text FROM "Users" WHERE "authId" = '00000000-0000-4000-8000-000000000085'), true);
  IF current_setting('app.test_rls268i_pupil', true) IS NULL THEN
    RAISE EXCEPTION 'huvudman 268i: the gallring school''s departed pupil is not in the fixtures';
  END IF;
END $$;
SELECT set_config('request.jwt.claims', json_build_object('sub', 'fe000000-0000-4000-8000-000000000261')::text, true);
DO $$
DECLARE
  h uuid := (SELECT "huvudmanId" FROM "HuvudmanMembers" WHERE "authId" = 'fe000000-0000-4000-8000-000000000261');
  member uuid;
BEGIN
  -- H's kommunadministratör invites the pupil's address, and the member
  -- takes the login the address has, as the gateway's invitation does.
  INSERT INTO "HuvudmanMembers" ("huvudmanId", email, "firstName", "lastName", role, "updatedAt")
  VALUES (h, 'hm-268i@example.invalid', 'Huvudman', 'Elev', 'PLANERARE', now())
  RETURNING id INTO member;
  PERFORM app.huvudman_member_takes_login(member, '00000000-0000-4000-8000-000000000085');
END $$;
SELECT set_config('request.jwt.claims', '', true);
DO $$
DECLARE
  run uuid := app.gallring_begin(current_setting('app.test_rls268i_school')::uuid, clock_timestamp());
  c record;
BEGIN
  SELECT * INTO c FROM app.gallring_claim_person(run, current_setting('app.test_rls268i_pupil')::uuid);
  IF c.auth_id IS DISTINCT FROM '00000000-0000-4000-8000-000000000085' OR c.invited IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'huvudman 268i: the departed pupil whose login a membership holds was claimed as % %', c.auth_id, c.invited;
  END IF;
END $$;
ROLLBACK;
